// All 1330 Thirukkurals by Thiruvalluvar (public domain)
// Tamil verse, transliteration, and English meaning
export const kurals = [
  { number: 1, tamil: "அகர முதல எழுத்தெல்லாம் ஆதி\nபகவன் முதற்றே உலகு.", transliteration: "Akara Mudhala Ezhuththellaam Aadhi / Pakavan Mudhatre Ulaku", english: "As the letter A is the first of all letters, so the eternal God is first in the world" },
  { number: 2, tamil: "கற்றதனால் ஆய பயனென்கொல் வாலறிவன்\nநற்றாள் தொழாஅர் எனின்.", transliteration: "Katradhanaal Aaya Payanenkol Vaalarivan / Natraal Thozhaaar Enin", english: "What Profit have those derived from learning, who worship not the good feet of Him who is possessed of pure knowledge ?" },
  { number: 3, tamil: "மலர்மிசை ஏகினான் மாணடி சேர்ந்தார்\nநிலமிசை நீடுவாழ் வார்.", transliteration: "Malarmisai Ekinaan Maanati Serndhaar / Nilamisai Neetuvaazh Vaar", english: "They who are united to the glorious feet of Him who passes swiftly over the flower of the mind, shall flourish long above all worlds" },
  { number: 4, tamil: "வேண்டுதல் வேண்டாமை இலானடி சேர்ந்தார்க்கு\nயாண்டும் இடும்பை இல.", transliteration: "Ventudhal Ventaamai Ilaanati Serndhaarkku / Yaantum Itumpai Ila", english: "To those who meditate the feet of Him who is void of desire or aversion, evil shall never come" },
  { number: 5, tamil: "இருள்சேர் இருவினையும் சேரா இறைவன்\nபொருள்சேர் புகழ்புரிந்தார் மாட்டு.", transliteration: "Irulser Iruvinaiyum Seraa Iraivan / Porulser Pukazhpurindhaar Maattu", english: "The two-fold deeds that spring from darkness shall not adhere to those who delight in the true praise of God" },
  { number: 6, tamil: "பொறிவாயில் ஐந்தவித்தான் பொய்தீர் ஒழுக்க\nநெறிநின்றார் நீடுவாழ் வார்.", transliteration: "Porivaayil Aindhaviththaan Poidheer Ozhukka / Nerinindraar Neetuvaazh Vaar", english: "Those shall long proposer who abide in the faultless way of Him who has destroyed the five desires of the senses" },
  { number: 7, tamil: "தனக்குவமை இல்லாதான் தாள்சேர்ந்தார்க் கல்லால்\nமனக்கவலை மாற்றல் அரிது.", transliteration: "Thanakkuvamai Illaadhaan Thaalserndhaark Kallaal / Manakkavalai Maatral Aridhu", english: "Anxiety of mind cannot be removed, except from those who are united to the feet of Him who is incomparable" },
  { number: 8, tamil: "அறவாழி அந்தணன் தாள்சேர்ந்தார்க் கல்லால்\nபிறவாழி நீந்தல் அரிது.", transliteration: "Aravaazhi Andhanan Thaalserndhaark Kallaal / Piravaazhi Neendhal Aridhu", english: "None can swim the sea of vice, but those who are united to the feet of that gracious Being who is a sea of virtue" },
  { number: 9, tamil: "கோளில் பொறியின் குணமிலவே எண்குணத்தான்\nதாளை வணங்காத் தலை.", transliteration: "Kolil Poriyin Kunamilave Enkunaththaan / Thaalai Vanangaath Thalai", english: "The head that worships not the feet of Him who is possessed of eight attributes, is as useless as a sense without the power of sensation" },
  { number: 10, tamil: "பிறவிப் பெருங்கடல் நீந்துவர் நீந்தார்\nஇறைவன் அடிசேரா தார்.", transliteration: "Piravip Perungatal Neendhuvar Neendhaar / Iraivan Atiseraa Thaar", english: "None can swim the great sea of births but those who are united to the feet of God" },
  { number: 11, tamil: "வான்நின்று உலகம் வழங்கி வருதலால்\nதான்அமிழ்தம் என்றுணரற் பாற்று.", transliteration: "Vaannindru Ulakam Vazhangi Varudhalaal / Thaanamizhdham Endrunarar Paatru", english: "By the continuance of rain the world is preserved in existence; it is therefore worthy to be called ambrosia" },
  { number: 12, tamil: "துப்பார்க்குத் துப்பாய துப்பாக்கித் துப்பார்க்குத்\nதுப்பாய தூஉம் மழை.", transliteration: "Thuppaarkkuth Thuppaaya Thuppaakkith Thuppaarkkuth / Thuppaaya Thooum Mazhai", english: "Rain produces good food, and is itself food" },
  { number: 13, tamil: "விண்இன்று பொய்ப்பின் விரிநீர் வியனுலகத்து\nஉள்நின்று உடற்றும் பசி.", transliteration: "Vinindru Poippin Virineer Viyanulakaththu / Ulnindru Utatrum Pasi", english: "If the cloud, withholding rain, deceive (our hopes) hunger will long distress the sea-girt spacious world" },
  { number: 14, tamil: "ஏரின் உழாஅர் உழவர் புயல்என்னும்\nவாரி வளங்குன்றிக் கால்.", transliteration: "Erin Uzhaaar Uzhavar Puyalennum / Vaari Valangundrik Kaal", english: "If the abundance of wealth imparting rain diminish, the labour of the plough must cease" },
  { number: 15, tamil: "கெடுப்பதூஉம் கெட்டார்க்குச் சார்வாய்மற் றாங்கே\nஎடுப்பதூஉம் எல்லாம் மழை.", transliteration: "Ketuppadhooum Kettaarkkuch Chaarvaaimar Raange / Etuppadhooum Ellaam Mazhai", english: "Rain by its absence ruins men; and by its existence restores them to fortune" },
  { number: 16, tamil: "விசும்பின் துளிவீழின் அல்லால்மற் றாங்கே\nபசும்புல் தலைகாண்பு அரிது.", transliteration: "Visumpin Thuliveezhin Allaalmar Raange / Pasumpul Thalaikaanpu Aridhu", english: "If no drop falls from the clouds, not even the green blade of grass will be seen" },
  { number: 17, tamil: "நெடுங்கடலும் தன்நீர்மை குன்றும் தடிந்தெழிலி\nதான்நல்கா தாகி விடின்.", transliteration: "Netungatalum Thanneermai Kundrum Thatindhezhili / Thaannalkaa Thaaki Vitin", english: "Even the wealth of the wide sea will be diminished, if the cloud that has drawn (its waters) up gives them not back again (in rain)" },
  { number: 18, tamil: "சிறப்பொடு பூசனை செல்லாது வானம்\nவறக்குமேல் வானோர்க்கும் ஈண்டு.", transliteration: "Sirappotu Poosanai Sellaadhu Vaanam / Varakkumel Vaanorkkum Eentu", english: "If the heaven dry up, neither yearly festivals, nor daily worship will be offered in this world, to the celestials" },
  { number: 19, tamil: "தானம் தவம்இரண்டும் தங்கா வியன்உலகம்\nவானம் வழங்கா தெனின்.", transliteration: "Thaanam Thavamirantum Thangaa Viyanulakam / Vaanam Vazhangaa Thenin", english: "If rain fall not, penance and alms-deeds will not dwell within this spacious world" },
  { number: 20, tamil: "நீர்இன்று அமையாது உலகெனின் யார்யார்க்கும்\nவான்இன்று அமையாது ஒழுக்கு.", transliteration: "Neerindru Amaiyaadhu Ulakenin Yaaryaarkkum / Vaanindru Amaiyaadhu Ozhukku", english: "If it be said that the duties of life cannot be discharged by any person without water, so without rain there cannot be the flowing of water" },
  { number: 21, tamil: "ஒழுக்கத்து நீத்தார் பெருமை விழுப்பத்து\nவேண்டும் பனுவல் துணிவு.", transliteration: "Ozhukkaththu Neeththaar Perumai Vizhuppaththu / Ventum Panuval Thunivu", english: "The end and aim of all treatise is to extol beyond all other excellence, the greatness of those who, while abiding in the rule of conduct peculiar to their state, have abandoned all desire" },
  { number: 22, tamil: "துறந்தார் பெருமை துணைக்கூறின் வையத்து\nஇறந்தாரை எண்ணிக்கொண் டற்று.", transliteration: "Thurandhaar Perumai Thunaikkoorin Vaiyaththu / Irandhaarai Ennikkon Tatru", english: "To describe the measure of the greatness of those who have forsaken the two-fold desires, is like counting the dead" },
  { number: 23, tamil: "இருமை வகைதெரிந்து ஈண்டுஅறம் பூண்டார்\nபெருமை பிறங்கிற்று உலகு.", transliteration: "Irumai Vakaidherindhu Eentuaram Poontaar / Perumai Pirangitru Ulaku", english: "The greatness of those who have discovered the properties of both states of being, and renounced the world, shines forth on earth (beyond all others)" },
  { number: 24, tamil: "உரனென்னும் தோட்டியான் ஓரைந்தும் காப்பான்\nவரனென்னும் வைப்பிற்கோர் வித்து.", transliteration: "Uranennum Thottiyaan Oraindhum Kaappaan / Varanennum Vaippirkor Viththu", english: "He who guides his five senses by the hook of wisdom will be a seed in the world of heaven" },
  { number: 25, tamil: "ஐந்தவித்தான் ஆற்றல் அகல்விசும்பு ளார்கோமான்\nஇந்திரனே சாலுங் கரி.", transliteration: "Aindhaviththaan Aatral Akalvisumpu Laarkomaan / Indhirane Saalung Kari", english: "Indra, the king of the inhabitants of the spacious heaven, is himself, a sufficient proof of the strength of him who has subdued his five senses" },
  { number: 26, tamil: "செயற்கரிய செய்வார் பெரியர் சிறியர்\nசெயற்கரிய செய்கலா தார்.", transliteration: "Seyarkariya Seyvaar Periyar Siriyar / Seyarkariya Seykalaa Thaar", english: "The great will do those things which is difficult to be done; but the mean cannot do them" },
  { number: 27, tamil: "சுவைஒளி ஊறுஓசை நாற்றமென ஐந்தின்\nவகைதெரிவான் கட்டே உலகு.", transliteration: "Suvaioli Ooruosai Naatramendru Aindhin / Vakaidherivaan Katte Ulaku", english: "The world is within the knowledge of him who knows the properties of taste, sight, touch, hearing and smell" },
  { number: 28, tamil: "நிறைமொழி மாந்தர் பெருமை நிலத்து\nமறைமொழி காட்டி விடும்.", transliteration: "Niraimozhi Maandhar Perumai Nilaththu / Maraimozhi Kaatti Vitum", english: "The hidden words of the men whose words are full of effect, will shew their greatness to the world" },
  { number: 29, tamil: "குணமென்னும் குன்றேறி நின்றார் வெகுளி\nகணமேயும் காத்தல் அரிது.", transliteration: "Kunamennum Kundreri Nindraar Vekuli / Kanameyum Kaaththal Aridhu", english: "The anger of those who have ascended the mountain of goodness, though it continue but for a moment, cannot be resisted" },
  { number: 30, tamil: "அந்தணர் என்போர் அறவோர்மற் றெவ்வுயிர்க்கும்\nசெந்தண்மை பூண்டொழுக லான்.", transliteration: "Andhanar Enpor Aravormar Revvuyir / Kkum Sendhanmai Poontozhuka Laan", english: "The virtuous are truly called Anthanar; because in their conduct towards all creatures they are clothed in kindness" },
  { number: 31, tamil: "சிறப்புஈனும் செல்வமும் ஈனும் அறத்தினூஉங்கு\nஆக்கம் எவனோ உயிர்க்கு.", transliteration: "Sirappu Eenum Selvamum Eenum / Araththinooungu Aakkam Evano Uyirkku", english: "Virtue will confer heaven and wealth; what greater source of happiness can man possess ?" },
  { number: 32, tamil: "அறத்தினூஉங்கு ஆக்கமும் இல்லை அதனை\nமறத்தலின் ஊங்கில்லை கேடு.", transliteration: "Araththinooungu Aakkamum Illai Adhanai / Maraththalin Oongillai Ketu", english: "There can be no greater source of good than (the practice of) virtue; there can be no greater source of evil than the forgetfulness of it" },
  { number: 33, tamil: "ஒல்லும் வகையான் அறவினை ஓவாதே\nசெல்லும்வாய் எல்லாஞ் செயல்.", transliteration: "Ollum Vakaiyaan Aravinai Ovaadhe / Sellumvaai Ellaanj Cheyal", english: "As much as possible, in every way, incessantly practise virtue" },
  { number: 34, tamil: "மனத்துக்கண் மாசிலன் ஆதல் அனைத்தறன்\nஆகுல நீர பிற.", transliteration: "Manaththukkan Maasilan Aadhal Anaiththu / Aran Aakula Neera Pira", english: "Let him who does virtuous deeds be of spotless mind; to that extent is virtue; all else is vain show" },
  { number: 35, tamil: "அழுக்காறு அவாவெகுளி இன்னாச்சொல் நான்கும்\nஇழுக்கா இயன்றது அறம்.", transliteration: "Azhukkaaru Avaavekuli Innaachchol Naankum / Izhukkaa Iyandradhu Aram", english: "That conduct is virtue which is free from these four things, viz, malice, desire, anger and bitter speech" },
  { number: 36, tamil: "அன்றறிவாம் என்னாது அறஞ்செய்க மற்றது\nபொன்றுங்கால் பொன்றாத் துணை.", transliteration: "Andrarivaam Ennaadhu Aranjeyka Matradhu / Pondrungaal Pondraath Thunai", english: "Defer not virtue to another day; receive her now; and at the dying hour she will be your undying friend" },
  { number: 37, tamil: "அறத்தாறு இதுவென வேண்டா சிவிகை\nபொறுத்தானோடு ஊர்ந்தான் இடை.", transliteration: "Araththaaru Ithuvena Ventaa Sivikai / Poruththaanotu Oorndhaan Itai", english: "The fruit of virtue need not be described in books; it may be inferred from seeing the bearer of a palanquin and the rider therein" },
  { number: 38, tamil: "வீழ்நாள் படாஅமை நன்றாற்றின் அஃதொருவன்\nவாழ்நாள் வழியடைக்கும் கல்.", transliteration: "Veezhnaal Pataaamai Nandraatrin Aqdhoruvan / Vaazhnaal Vazhiyataikkum Kal", english: "If one allows no day to pass without some good being done, his conduct will be a stone to block up the passage to other births" },
  { number: 39, tamil: "அறத்தான் வருவதே இன்பம் மற்றெல்லாம்\nபுறத்த புகழும் இல.", transliteration: "Araththaan Varuvadhe Inpam Mar / Rellaam Puraththa Pukazhum Ila", english: "Only that pleasure which flows from domestic virtue is pleasure; all else is not pleasure, and it is without praise" },
  { number: 40, tamil: "செயற்பால தோரும் அறனே ஒருவற்கு\nஉயற்பால தோரும் பழி.", transliteration: "Seyarpaala Thorum Arane Oruvarku / Uyarpaala Thorum Pazhi", english: "That is virtue which each ought to do, and that is vice which each should shun" },
  { number: 41, tamil: "இல்வாழ்வான் என்பான் இயல்புடைய மூவர்க்கும்\nநல்லாற்றின் நின்ற துணை.", transliteration: "Ilvaazhvaan Enpaan Iyalputaiya Moovarkkum / Nallaatrin Nindra Thunai", english: "He will be called a (true) householder, who is a firm support to the virtuous of the three orders in" },
  { number: 42, tamil: "துறந்தார்க்கும் துவ்வாதவர்க்கும் இறந்தார்க்கும்\nஇல்வாழ்வான் என்பான் துணை.", transliteration: "Thurandhaarkkum Thuvvaa Dhavarkkum Irandhaarkkum / Ilvaazhvaan Enpaan Thunai", english: "He will be said to flourish in domestic virtue who aids the forsaken, the poor, and the dead" },
  { number: 43, tamil: "தென்புலத்தார் தெய்வம் விருந்தொக்கல் தானென்றாங்கு\nஐம்புலத்தாறு ஓம்பல் தலை.", transliteration: "Thenpulaththaar Theyvam Virundhokkal Thaanendraangu / Aimpulaththaaru Ompal Thalai", english: "The chief (duty of the householder) is to preserve the five-fold rule (of conduct) towards the manes, the Gods, his guests, his relations and himself" },
  { number: 44, tamil: "பழியஞ்சிப் பாத்தூண் உடைத்தாயின் வாழ்க்கை\nவழியெஞ்சல் எஞ்ஞான்றும் இல்.", transliteration: "Pazhiyanjip Paaththoon Utaiththaayin Vaazhkkai / Vazhiyenjal Egngnaandrum Il", english: "His descendants shall never fail who, living in the domestic state, fears vice (in the acquisition of property) and shares his food (with others)" },
  { number: 45, tamil: "அன்பும் அறனும் உடைத்தாயின் இல்வாழ்க்கை\nபண்பும் பயனும் அது.", transliteration: "Anpum Aranum Utaiththaayin Ilvaazhkkai / Panpum Payanum Adhu", english: "If the married life possess love and virtue, these will be both its duty and reward" },
  { number: 46, tamil: "அறத்தாற்றின் இல்வாழ்க்கை ஆற்றின் புறத்தாற்றில்\nபோஒய்ப் பெறுவ தெவன்?", transliteration: "Araththaatrin Ilvaazhkkai Aatrin Puraththaatril / Pooip Peruva Thevan?", english: "What will he who lives virtuously in the domestic state gain by going into the other, (ascetic) state ?" },
  { number: 47, tamil: "இயல்பினான் இல்வாழ்க்கை வாழ்பவன் என்பான்\nமுயல்வாருள் எல்லாம் தலை.", transliteration: "Iyalpinaan Ilvaazhkkai Vaazhpavan Enpaan / Muyalvaarul Ellaam Thalai", english: "Among all those who labour (for future happiness) he is greatest who lives well in the household state" },
  { number: 48, tamil: "ஆற்றின் ஒழுக்கி அறனிழுக்கா இல்வாழ்க்கை\nநோற்பாரின் நோன்மை உடைத்து.", transliteration: "Aatrin Ozhukki Aranizhukkaa Ilvaazhkkai / Norpaarin Nonmai Utaiththu", english: "The householder who, not swerving from virtue, helps the ascetic in his way, endures more than those who endure penance" },
  { number: 49, tamil: "அறனெனப் பட்டதே இல்வாழ்க்கை அஃதும்\nபிறன்பழிப்ப தில்லாயின் நன்று.", transliteration: "Aran Enap Pattadhe Ilvaazhkkai / Aqdhum Piranpazhippa Thillaayin Nandru", english: "The marriage state is truly called virtue The other state is also good, if others do not reproach it" },
  { number: 50, tamil: "வையத்துள் வாழ்வாங்கு வாழ்பவன் வான்உறையும்\nதெய்வத்துள் வைக்கப் படும்.", transliteration: "Vaiyaththul Vaazhvaangu Vaazhpavan Vaanu�ryum / Theyvaththul Vaikkap Patum", english: "He who on earth has lived in the conjugal state as he should live, will be placed among the Gods who dwell in heaven" },
  { number: 51, tamil: "மனைக்தக்க மாண்புடையள் ஆகித்தற் கொண்டான்\nவளத்தக்காள் வாழ்க்கைத் துணை.", transliteration: "Manaikdhakka Maanputaiyal Aakiththar Kontaan / Valaththakkaal Vaazhkkaith Thunai", english: "She who has the excellence of home virtues, and can expend within the means of her husband, is a help in the domestic state" },
  { number: 52, tamil: "மனைமாட்சி இல்லாள்கண் இல்லாயின் வாழ்க்கை\nஎனைமாட்சித் தாயினும் இல்.", transliteration: "Manaimaatchi Illaalkan Illaayin Vaazhkkai / Enaimaatchith Thaayinum Il", english: "If the wife be devoid of domestic excellence, whatever (other) greatness be possessed, the conjugal state, is nothing" },
  { number: 53, tamil: "இல்லதென் இல்லவள் மாண்பானால் உள்ளதென்\nஇல்லவள் மாணாக் கடை?", transliteration: "Illadhen Illaval Maanpaanaal Ulladhen / Illaval Maanaak Katai?", english: "If his wife be eminent (in virtue), what does (that man) not possess ? If she be without excellence, what does (he) possess ?" },
  { number: 54, tamil: "பெண்ணின் பெருந்தக்க யாவுள கற்பென்னும்\nதிண்மைஉண் டாகப் பெறின்.", transliteration: "Pennin Perundhakka Yaavula Karpennum / Thinmaiun Taakap Perin", english: "What is more excellent than a wife, if she possess the stability of chastity ?" },
  { number: 55, tamil: "தெய்வம் தொழாஅள் கொழுநன் தொழுதெழுவாள்\nபெய்யெனப் பெய்யும் மழை.", transliteration: "Theyvam Thozhaaal Kozhunan Thozhudhezhuvaal / Peyyenap Peyyum Mazhai", english: "If she, who does not worship God, but who rising worships her husband, say, \"let it rain,\" it will rain" },
  { number: 56, tamil: "தற்காத்துத் தற்கொண்டாற் பேணித் தகைசான்ற\nசொற்காத்துச் சோர்விலாள் பெண்.", transliteration: "Tharkaaththuth Tharkontaar Penith Thakaisaandra / Sorkaaththuch Chorvilaal Pen", english: "She is a wife who unweariedly guards herself, takes care of her husband, and preserves an unsullied fame" },
  { number: 57, tamil: "சிறைகாக்கும் காப்பெவன் செய்யும் மகளிர்\nநிறைகாக்கும் காப்பே தலை.", transliteration: "Siraikaakkum Kaappevan Seyyum Makalir / Niraikaakkum Kaappe Thalai", english: "What avails the guard of a prison ? The chief guard of a woman is her chastity" },
  { number: 58, tamil: "பெற்றாற் பெறின்பெறுவர் பெண்டிர் பெருஞ்சிறப்புப்\nபுத்தேளிர் வாழும் உலகு.", transliteration: "Petraar Perinperuvar Pentir Perunjirappup / Puththelir Vaazhum Ulaku", english: "If women shew reverence to their husbands, they will obtain great excellence in the world where the gods flourish" },
  { number: 59, tamil: "புகழ்புரிந்த இல்லிலோர்க்கு இல்லை இகழ்வார்முன்\nஏறுபோல் பீடு நடை.", transliteration: "Pukazhpurindha Illilorkku Illai Ikazhvaarmun / Erupol Peetu Natai", english: "The man whose wife seeks not the praise (of chastity) cannot walk with lion-like stately step, before those who revile them" },
  { number: 60, tamil: "மங்கலம் என்ப மனைமாட்சி மற்று அதன்\nநன்கலம் நன்மக்கட் பேறு.", transliteration: "Mangalam Enpa Manaimaatchi Matru / Adhan Nankalam Nanmakkat Peru", english: "The excellence of a wife is the good of her husband; and good children are the jewels of that goodness" },
  { number: 61, tamil: "பெறுமவற்றுள் யாமறிவது இல்லை அறிவறிந்த\nமக்கட்பேறு அல்ல பிற.", transliteration: "Perumavatrul Yaamarivadhu Illai Arivarindha / Makkatperu Alla Pira", english: "Among all the benefits that may be acquired, we know no greater benefit than the acquisition of intelligent children" },
  { number: 62, tamil: "எழுபிறப்பும் தீயவை தீண்டா பழிபிறங்காப்\nபண்புடை மக்கட் பெறின்.", transliteration: "Ezhupirappum Theeyavai Theentaa Pazhipirangaap / Panputai Makkat Perin", english: "The evils of the seven births shall not touch those who abtain children of a good disposition, free from vice" },
  { number: 63, tamil: "தம்பொருள் என்பதம் மக்கள் அவர்பொருள்\nதம்தம் வினையான் வரும்.", transliteration: "Thamporul Enpadham Makkal Avarporul / Thamdham Vinaiyaan Varum", english: "Men will call their sons their wealth, because it flows to them through the deeds which they (sons) perform on their behalf" },
  { number: 64, tamil: "அமிழ்தினும் ஆற்ற இனிதேதம் மக்கள்\nசிறுகை அளாவிய கூழ்.", transliteration: "Amizhdhinum Aatra Inidhedham Makkal / Sirukai Alaaviya Koozh", english: "The rice in which the little hand of their children has dabbled will be far sweeter (to the parent) than ambrosia" },
  { number: 65, tamil: "மக்கள்மெய் தீண்டல் உடற்கின்பம் மற்றுஅவர்\nசொற்கேட்டல் இன்பம் செவிக்கு.", transliteration: "Makkalmey Theental Utarkinpam Matru / Avar Sorkettal Inpam Sevikku", english: "The touch of children gives pleasure to the body, and the hearing of their words, pleasure to the ear" },
  { number: 66, tamil: "குழல்இனிது யாழ்இனிது என்பதம் மக்கள்\nமழலைச்சொல் கேளா தவர்.", transliteration: "Kuzhal Inidhu Yaazhinidhu Enpadham / Makkal Mazhalaichchol Kelaa Thavar", english: "\"The pipe is sweet, the lute is sweet,\" say those who have not heard the prattle of their own children" },
  { number: 67, tamil: "தந்தை மகற்காற்றும் நன்றி அவையத்து\nமுந்தி இருப்பச் செயல்.", transliteration: "Thandhai Makarkaatrum Nandri Avaiyaththu / Mundhi Iruppach Cheyal", english: "The benefit which a father should confer on his son is to give him precedence in the assembly of the learned" },
  { number: 68, tamil: "தம்மின்தம் மக்கள் அறிவுடைமை மாநிலத்து\nமன்னுயிர்க் கெல்லாம் இனிது.", transliteration: "Thammindham Makkal Arivutaimai Maanilaththu / Mannuyirk Kellaam Inidhu", english: "That their children should possess knowledge is more pleasing to all men of this great earth than to themselves" },
  { number: 69, tamil: "ஈன்ற பொழுதின் பெரிதுவக்கும் தன்மகனைச்\nசான்றோன் எனக்கேட்ட தாய்.", transliteration: "Eendra Pozhudhin Peridhuvakkum Thanmakanaich / Chaandron Enakketta Thaai", english: "The mother who hears her son called \"a wise man\" will rejoice more than she did at his birth" },
  { number: 70, tamil: "மகன்தந்தைக்கு ஆற்றும் உதவி இவன்தந்தை\nஎன்நோற்றான் கொல் எனும் சொல்.", transliteration: "Makandhandhaikku Aatrum Udhavi Ivandhandhai / Ennotraan Kol Enum Sol", english: "(So to act) that it may be said \"by what great penance did his father beget him,\" is the benefit which a son should render to his father" },
  { number: 71, tamil: "அன்பிற்கும் உண்டோ அடைக்குந்தாழ் ஆர்வலர்\nபுன்கணீர் பூசல் தரும்.", transliteration: "Anpirkum Unto Ataikkundhaazh Aarvalar / Punkaneer Poosal Tharum", english: "Is there any fastening that can shut in love ? Tears of the affectionate will publish the love that is within" },
  { number: 72, tamil: "அன்பிலார் எல்லாம் தமக்குரியர் அன்புடையார்\nஎன்பும் உரியர் பிறர்க்கு.", transliteration: "Anpilaar Ellaam Thamakkuriyar Anputaiyaar / Enpum Uriyar Pirarkku", english: "Those who are destitute of love appropriate all they have to themselves; but those who possess love consider even their bones to belong to others" },
  { number: 73, tamil: "அன்போடு இயைந்த வழக்கென்ப ஆருயிர்க்கு\nஎன்போடு இயைந்த தொடர்பு.", transliteration: "Anpotu Iyaindha Vazhakkenpa Aaruyirkku / Enpotu Iyaindha Thotarpu", english: "They say that the union of soul and body in man is the fruit of the union of love and virtue (in a former birth)" },
  { number: 74, tamil: "அன்புஈனும் ஆர்வம் உடைமை அதுஈனும்\nநண்பு என்னும் நாடாச் சிறப்பு.", transliteration: "Anpu Eenum Aarvam Utaimai / Adhueenum Nanpu Ennum Naataach", english: "Love begets desire: and that (desire) begets the immeasureable excellence of friendship" },
  { number: 75, tamil: "அன்புற்று அமர்ந்த வழக்கென்ப வையகத்து\nஇன்புற்றார் எய்தும் சிறப்பு.", transliteration: "Anputru Amarndha Vazhakkenpa Vaiyakaththu / Inputraar Eydhum Sirappu", english: "These are the fruits of tranquil life of love" },
  { number: 76, tamil: "அறத்திற்கே அன்புசார் பென்ப அறியார்\nமறத்திற்கும் அஃதே துணை.", transliteration: "Araththirke Anpusaar Penpa Ariyaar / Maraththirkum Aqdhe Thunai", english: "The ignorant say that love is an ally to virtue only, but it is also a help to get out of vice" },
  { number: 77, tamil: "என்பி லதனை வெயில்போலக் காயுமே\nஅன்பி லதனை அறம்.", transliteration: "Enpi Ladhanai Veyilpolak Kaayume / Anpi Ladhanai Aram", english: "Virtue will burn up the soul which is without love, even as the sun burns up the creature which is without bone, ie worms" },
  { number: 78, tamil: "அன்பகத் தில்லா உயிர்வாழ்க்கை வன்பாற்கண்\nவற்றல் மரந்தளிர்த் தற்று.", transliteration: "Anpakath Thillaa Uyirvaazhkkai Vanpaarkan / Vatral Marandhalirth Thatru", english: "The domestic state of that man whose mind is without love is like the flourishing of a withered tree upon the parched desert" },
  { number: 79, tamil: "புறத்துறுப் பெல்லாம் எவன்செய்யும் யாக்கை\nஅகத்துறுப்பு அன்பி லவர்க்கு.", transliteration: "Puraththurup Pellaam Evanseyyum Yaakkai / Akaththuruppu Anpi Lavarkku", english: "Of what avail are all the external members (of the body) to those who are destitute of love, the internal member" },
  { number: 80, tamil: "அன்பின் வழியது உயிர்நிலை அஃதிலார்க்கு\nஎன்புதோல் போர்த்த உடம்பு.", transliteration: "Anpin Vazhiyadhu Uyirnilai Aqdhilaarkku / Enpudhol Porththa Utampu", english: "That body alone which is inspired with love contains a living soul: if void of it, (the body) is bone overlaid with skin" },
  { number: 81, tamil: "இருந்தோம்பி இல்வாழ்வ தெல்லாம் விருந்தோம்பி\nவேளாண்மை செய்தற் பொருட்டு.", transliteration: "Irundhompi Ilvaazhva Thellaam Virundhompi / Velaanmai Seydhar Poruttu", english: "The whole design of living in the domestic state and laying up (property) is (to be able) to exercise the benevolence of hospitality" },
  { number: 82, tamil: "விருந்து புறத்ததாத் தானுண்டல் சாவா\nமருந்தெனினும் வேண் டற்பாற் றன்று.", transliteration: "Virundhu Puraththadhaath Thaanuntal Saavaa / Marundheninum Ventarpaar Randru", english: "It is not fit that one should wish his guests to be outside (his house) even though he were eating the food of immortality" },
  { number: 83, tamil: "வருவிருந்து வைகலும் ஓம்புவான் வாழ்க்கை\nபருவந்து பாழ்படுதல் இன்று.", transliteration: "Varuvirundhu Vaikalum Ompuvaan Vaazhkkai / Paruvandhu Paazhpatudhal Indru", english: "The domestic life of the man that daily entertains the guests who come to him shall not be laid waste by poverty" },
  { number: 84, tamil: "அகனமர்ந்து செய்யாள் உறையும் முகனமர்ந்து\nநல்விருந்து ஓம்புவான் இல்.", transliteration: "Akanamarndhu Seyyaal Uraiyum Mukanamarndhu / Nalvirundhu Ompuvaan Il", english: "Lakshmi with joyous mind shall dwell in the house of that man who, with cheerful countenance, entertains the good as guests" },
  { number: 85, tamil: "வித்தும் இடல்வேண்டும் கொல்லோ விருந்தோம்பி\nமிச்சில் மிசைவான் புலம்.", transliteration: "Viththum Italventum Kollo Virundhompi / Michchil Misaivaan Pulam", english: "Is it necessary to sow the field of the man who, having feasted his guests, eats what may remain ?" },
  { number: 86, tamil: "செல்விருந்து ஓம்பி வருவிருந்து பார்த்திருப்பான்\nநல்வருந்து வானத் தவர்க்கு.", transliteration: "Selvirundhu Ompi Varuvirundhu Paarththiruppaan / Nalvarundhu Vaanath Thavarkku", english: "He who, having entertained the guests that have come, looks out for others who may yet come, will be a welcome guest to the inhabitants of heaven" },
  { number: 87, tamil: "இனைத்துணைத் தென்பதொன் றில்லை விருந்தின்\nதுணைத்துணை வேள்விப் பயன்.", transliteration: "Inaiththunaith Thenpadhon Rillai Virundhin / Thunaiththunai Velvip Payan", english: "The advantages of benevolence cannot be measured; the measure (of the virtue) of the guests (entertained) is the only measure" },
  { number: 88, tamil: "பரிந்தோம்பிப் பற்றற்றேம் என்பர் விருந்தோம்பி\nவேள்வி தலைப்படா தார்.", transliteration: "Parindhompip Patratrem Enpar Virundhompi / Velvi Thalaippataa Thaar", english: "Those who have taken no part in the benevolence of hospitality shall (at length lament) saying, \"we have laboured and laid up wealth and are now without support.\"" },
  { number: 89, tamil: "உடைமையுள் இன்மை விருந்தோம்பல் ஓம்பா\nமடமை மடவார்கண் உண்டு.", transliteration: "Utaimaiyul Inmai Virundhompal Ompaa / Matamai Matavaarkan Untu", english: "That stupidity which excercises no hospitality is poverty in the midst of wealth It is the property of the stupid" },
  { number: 90, tamil: "மோப்பக் குழையும் அனிச்சம் முகந்திரிந்து\nநோக்கக் குநழ்யும் விருந்து.", transliteration: "Moppak Kuzhaiyum Anichcham Mukandhirindhu / Nokkak Kuzhaiyum Virundhu", english: "As the Anicham flower fades in smelling, so fades the guest when the face is turned away" },
  { number: 91, tamil: "இன்சொலால் ஈரம் அளைஇப் படிறுஇலவாம்\nசெம்பொருள் கண்டார்வாய்ச் சொல்.", transliteration: "Insolaal Eeram Alaiip Patiruilavaam / Semporul Kantaarvaaich Chol", english: "Sweet words are those which imbued with love and free from deceit flow from the mouth of the virtuous" },
  { number: 92, tamil: "அகன்அமர்ந்து ஈதலின் நன்றே முகனமர்ந்து\nஇன்சொலன் ஆகப் பெறின்.", transliteration: "Akanamarndhu Eedhalin Nandre Mukanamarndhu / Insolan Aakap Perin", english: "Sweet speech, with a cheerful countenance is better than a gift made with a joyous mind" },
  { number: 93, tamil: "முகத்தான் அமர்ந்து இனிதுநோக்கி அகத்தானாம்\nஇன்சொ லினதே அறம்.", transliteration: "Mukaththaan Amarndhuinidhu Nokki Akaththaanaam / Inso Linadhe Aram", english: "Sweet speech, flowing from the heart (uttered) with a cheerful countenance and a sweet look, is true virtue" },
  { number: 94, tamil: "துன்புறூஉம் துவ்வாமை இல்லாகும் யார்மாட்டும்\nஇன்புறூஉம் இன்சொ லவர்க்கு.", transliteration: "Thunpurooum Thuvvaamai Illaakum Yaarmaattum / Inpurooum Inso Lavarkku", english: "Sorrow-increasing poverty shall not come upon those who use towards all, pleasure-increasing sweetness of speech" },
  { number: 95, tamil: "பணிவுடையன் இன்சொலன் ஆதல் ஒருவற்கு\nஅணியல்ல மற்றுப் பிற.", transliteration: "Panivutaiyan Insolan Aadhal Oruvarku / Aniyalla Matrup Pira", english: "Humility and sweetness of speech are the ornaments of man; all others are not (ornaments)" },
  { number: 96, tamil: "அல்லவை தேய அறம்பெருகும் நல்லவை\nநாடி இனிய சொலின்", transliteration: "Allavai Theya Aramperukum Nallavai / Naati Iniya Solin", english: "If a man, while seeking to speak usefully, speaks also sweetly, his sins will diminish and his virtue increase" },
  { number: 97, tamil: "நயன்ஈன்று நன்றி பயக்கும் பயன்ஈன்று\nபண்பின் தலைப்பிரியாச் சொல்.", transliteration: "Nayan Eendru Nandri Payakkum / Payaneendru Panpin Thalaippiriyaach Chol", english: "That speech which, while imparting benefits ceases not to please, will yield righteousness (for this world) and merit (for the next world)" },
  { number: 98, tamil: "சிறுமையுவு நீங்கிய இன்சொல் மறுமையும்\nஇம்மையும் இன்பம் தரும்.", transliteration: "Sirumaiyul Neengiya Insol Marumaiyum / Immaiyum Inpam Tharum", english: "Sweet speech, free from harm to others, will give pleasure both in this world and in the next" },
  { number: 99, tamil: "இன்சொல் இனிதீன்றல் காண்பான் எவன்கொலோ\nவன்சொல் வழங்கு வது?", transliteration: "Insol Inidheendral Kaanpaan Evankolo / Vansol Vazhangu Vadhu?", english: "Why does he use harsh words, who sees the pleasure which sweet speech yields ?" },
  { number: 100, tamil: "இனிய உளவாக இன்னாத கூறல்\nகனிஇருப்பக் காய்கவர்ந் தற்று.", transliteration: "Iniya Ulavaaka Innaadha Kooral / Kaniiruppak Kaaikavarn Thatru", english: "To say disagreeable things when agreeable are at hand is like eating unripe fruit when there is ripe" },
  { number: 101, tamil: "செய்யாமல் செய்த உதவிக்கு வையகமும்\nவானகமும் ஆற்றல் அரிது.", transliteration: "Seyyaamal Seydha Udhavikku Vaiyakamum / Vaanakamum Aatral Aridhu", english: "(The gift of) heaven and earth is not an equivalent for a benefit which is conferred where none had been received" },
  { number: 102, tamil: "காலத்தி னாற்செய்த நன்றி சிறிதெனினும்\nஞாலத்தின் மாணப் பெரிது.", transliteration: "Kaalaththi Naarseydha Nandri Siridheninum / Gnaalaththin Maanap Peridhu", english: "A favour conferred in the time of need, though it be small (in itself), is (in value) much larger than the world" },
  { number: 103, tamil: "பயன்தூக்கார் செய்த உதவி நயன்தூக்கின்\nநன்மை கடலின் பெரிது.", transliteration: "Payandhookkaar Seydha Udhavi Nayandhookkin / Nanmai Katalin Peridhu", english: "If we weigh the excellence of a benefit which is conferred without weighing the return, it is larger than the sea" },
  { number: 104, tamil: "தினைத்துணை நன்றி செயினும் பனைத்துணையாக்\nகொள்வர் பயன்தெரி வார்.", transliteration: "Thinaiththunai Nandri Seyinum Panaiththunaiyaak / Kolvar Payandheri Vaar", english: "Though the benefit conferred be as small as a millet seed, those who know its advantage will consider it as large as a palmyra fruit" },
  { number: 105, tamil: "உதவி வரைத்தன்று உதவி உதவி\nசெயப்பட்டார் சால்பின் வரைத்து.", transliteration: "Udhavi Varaiththandru Udhavi Udhavi / Seyappattaar Saalpin Varaiththu", english: "The benefit itself is not the measure of the benefit; the worth of those who have received it is its measure" },
  { number: 106, tamil: "மறவற்க மாசற்றார் கேண்மை துறவற்க\nதுன்பத்துள் துப்பாயார் நட்பு.", transliteration: "Maravarka Maasatraar Kenmai Thuravarka / Thunpaththul Thuppaayaar Natpu", english: "Forsake not the friendship of those who have been your staff in adversity Forget not be benevolence of the blameless" },
  { number: 107, tamil: "எழுமை எழுபிறப்பும் உள்ளுவர் தங்கண்\nவிழுமந் துடைத்தவர் நட்பு.", transliteration: "Ezhumai Ezhupirappum Ulluvar Thangan / Vizhuman Thutaiththavar Natpu", english: "(The wise) will remember throughout their seven-fold births the love of those who have wiped away their affliction" },
  { number: 108, tamil: "நன்றி மறப்பது நன்றன்று நன்றல்லது\nஅன்றே மறப்பது நன்று.", transliteration: "Nandri Marappadhu Nandrandru Nandralladhu / Andre Marappadhu Nandru", english: "It is not good to forget a benefit; it is good to forget an injury even in the very moment (in which it is inflicted)" },
  { number: 109, tamil: "கொன்றன்ன இன்னா செயினும் அவர்செய்த\nஒன்றுநன்று உள்ளக் கெடும்.", transliteration: "Kondranna Innaa Seyinum Avarseydha / Ondrunandru Ullak Ketum", english: "Though one inflict an injury great as murder, it will perish before the thought of one benefit (formerly) conferred" },
  { number: 110, tamil: "எந்நன்றி கொன்றார்க்கும் உய்வுண்டாம் உய்வில்லை\nசெய்ந்நன்றி கொன்ற மகற்கு.", transliteration: "Ennandri Kondraarkkum Uyvuntaam Uyvillai / Seynnandri Kondra Makarku", english: "He who has killed every virtue may yet escape; there is no escape for him who has killed a benefit" },
  { number: 111, tamil: "தகுதி எனவொன்று நன்றே பகுதியால்\nபாற்பட்டு ஒழுகப் பெறின்.", transliteration: "Thakudhi Enavondru Nandre Pakudhiyaal / Paarpattu Ozhukap Perin", english: "That equity which consists in acting with equal regard to each of (the three) divisions of men [enemies, strangers and friends] is a pre-eminent virtue" },
  { number: 112, tamil: "செப்பம் உடையவன் ஆக்கஞ் சிதைவின்றி\nஎச்சத்திற் கேமாப்பு உடைத்து.", transliteration: "Seppam Utaiyavan Aakkanj Chidhaivindri / Echchaththir Kemaappu Utaiththu", english: "The wealth of the man of rectitude will not perish, but will bring happiness also to his posterity" },
  { number: 113, tamil: "நன்றே தரினும் நடுவிகந்தாம் ஆக்கத்தை\nஅன்றே யொழிய விடல்.", transliteration: "Nandre Tharinum Natuvikandhaam Aakkaththai / Andre Yozhiya Vital", english: "Forsake in the very moment (of acquisition) that gain which, though it should bring advantage, is without equity" },
  { number: 114, tamil: "தக்கார் தகவிலர் என்பது அவரவர்\nஎச்சத்தாற் காணப்ப படும்.", transliteration: "Thakkaar Thakavilar Enpadhu Avaravar / Echchaththaar Kaanap Patum", english: "The worthy and unworthy may be known by the existence or otherwise of good offsprings" },
  { number: 115, tamil: "கேடும் பெருக்கமும் இல்லல்ல நெஞ்சத்துக்\nகோடாமை சான்றோர்க் கணி.", transliteration: "Ketum Perukkamum Illalla Nenjaththuk / Kotaamai Saandrork Kani", english: "Loss and gain come not without cause; it is the ornament of the wise to preserve evenness of mind (under both)" },
  { number: 116, tamil: "கெடுவல்யான் என்பது அறிகதன் நெஞ்சம்\nநடுவொரீஇ அல்ல செயின்.", transliteration: "Ketuvalyaan Enpadhu Arikadhan Nenjam / Natuvoreei Alla Seyin", english: "Let him whose mind departing from equity commits sin well consider thus within himself, \"I shall perish.\"" },
  { number: 117, tamil: "கெடுவாக வையாது உலகம் நடுவாக\nநன்றிக்கண் தங்கியான் தாழ்வு.", transliteration: "Ketuvaaka Vaiyaadhu Ulakam Natuvaaka / Nandrikkan Thangiyaan Thaazhvu", english: "The great will not regard as poverty the low estate of that man who dwells in the virtue of equity" },
  { number: 118, tamil: "சமன்செய்து சீர்தூக்குங் கோல்போல் அமைந்தொருபால்\nகோடாமை சான்றோர்க் கணி.", transliteration: "Samanseydhu Seerdhookkung Kolpol Amaindhorupaal / Kotaamai Saandrork Kani", english: "To incline to neither side, but to rest impartial as the even-fixed scale is the ornament of the wise" },
  { number: 119, tamil: "சொற்கோட்டம் இல்லது செப்பம் ஒருதலையா\nஉட்கோட்டம் இன்மை பெறின்.", transliteration: "Sorkottam Illadhu Seppam Orudhalaiyaa / Utkottam Inmai Perin", english: "Freedom from obliquity of speech is rectitude, if there be (corresponding) freedom from bias of mind" },
  { number: 120, tamil: "வாணிகம் செய்வார்க்கு வாணிகம் பேணிப்\nபிறவும் தமபோல் செயின்.", transliteration: "Vaanikam Seyvaarkku Vaanikam Penip / Piravum Thamapol Seyin", english: "The true merchandize of merchants is to guard and do by the things of others as they do by their own" },
  { number: 121, tamil: "அடக்கம் அமரருள் உய்க்கும் அடங்காமை\nஆரிருள் உய்த்து விடும்.", transliteration: "Atakkam Amararul Uykkum Atangaamai / Aarirul Uyththu Vitum", english: "Self-control will place (a man) among the Gods; the want of it will drive (him) into the thickest darkness (of hell)" },
  { number: 122, tamil: "காக்க பொருளா அடக்கத்தை ஆக்கம்\nஅதனினூஉங் கில்லை உயிர்க்கு.", transliteration: "Kaakka Porulaa Atakkaththai Aakkam / Adhaninooung Killai Uyirkku", english: "Let self-control be guarded as a treasure; there is no greater source of good for man than that" },
  { number: 123, tamil: "செறிவறிந்து சீர்மை பயக்கும் அறிவறிந்து\nஆற்றின் அடங்கப் பெறின்.", transliteration: "Serivarindhu Seermai Payakkum Arivarindhu / Aatrin Atangap Perin", english: "Knowing that self-control is knowledge, if a man should control himself, in the prescribed course, such self-control will bring him distinction among the wise" },
  { number: 124, tamil: "நிலையின் திரியாது அடங்கியான் தோற்றம்\nமலையினும் மாணப் பெரிது.", transliteration: "Nilaiyin Thiriyaadhu Atangiyaan Thotram / Malaiyinum Maanap Peridhu", english: "More lofty than a mountain will be the greatness of that man who without swerving from his domestic state, controls himself" },
  { number: 125, tamil: "எல்லார்க்கும் நன்றாம் பணிதல் அவருள்ளும்\nசெல்வர்க்கே செல்வம் தகைத்து.", transliteration: "Ellaarkkum Nandraam Panidhal Avarullum / Selvarkke Selvam Thakaiththu", english: "Humility is good in all; but especially in the rich it is (the excellence of) higher riches" },
  { number: 126, tamil: "ஒருமையுள் ஆமைபோல் ஐந்தடக்கல் ஆற்றின்\nஎழுமையும் ஏமாப் புடைத்து.", transliteration: "Orumaiyul Aamaipol Aindhatakkal Aatrin / Ezhumaiyum Emaap Putaiththu", english: "Should one throughout a single birth, like a tortoise keep in his five senses, the fruit of it will prove a safe-guard to him throughout the seven-fold births." },
  { number: 127, tamil: "யாகாவா ராயினும் நாகாக்க காவாக்கால்\nசோகாப்பர் சொல்லிழுக்குப் பட்டு.", transliteration: "Yaakaavaa Raayinum Naakaakka Kaavaakkaal / Sokaappar Sollizhukkup Pattu", english: "Whatever besides you leave unguarded, guard your tongue; otherwise errors of speech and the consequent misery will ensue" },
  { number: 128, tamil: "ஒன்றானுந் தீச்சொல் பொருட்பயன் உண்டாயின்\nநன்றாகா தாகி விடும்.", transliteration: "Ondraanun Theechchol Porutpayan Untaayin / Nandraakaa Thaaki Vitum", english: "If a man's speech be productive of a single evil, all the good by him will be turned into evil" },
  { number: 129, tamil: "தீயினாற் சுட்டபுண் உள்ளாறும் ஆறாதே\nநாவினாற் சுட்ட வடு.", transliteration: "Theeyinaar Suttapun Ullaarum Aaraadhe / Naavinaar Sutta Vatu", english: "The wound which has been burnt in by fire may heal, but a wound burnt in by the tongue will never heal" },
  { number: 130, tamil: "கதங்காத்துக் கற்றடங்கல் ஆற்றுவான் செவ்வி\nஅறம்பார்க்கும் ஆற்றின் நுழைந்து.", transliteration: "Kadhangaaththuk Katratangal Aatruvaan Sevvi / Arampaarkkum Aatrin Nuzhaindhu", english: "Virtue, seeking for an opportunity, will come into the path of that man who, possessed of learning and self-control, guards himself against anger" },
  { number: 131, tamil: "ஒழுக்கம் விழுப்பந் தரலான் ஒழுக்கம்\nஉயிரினும் ஓம்பப் படும்.", transliteration: "Ozhukkam Vizhuppan Tharalaan Ozhukkam / Uyirinum Ompap Patum", english: "Propriety of conduct leads to eminence, it should therefore be preserved more carefully than life" },
  { number: 132, tamil: "பரிந்தோம்பிக் காக்க ஒழுக்கம் தெரிந்தோம்பித்\nதேரினும் அஃதே துணை.", transliteration: "Parindhompik Kaakka Ozhukkam Therindhompith / Therinum Aqdhe Thunai", english: "Let propriety of conduct be laboriously preserved and guarded; though one know and practise and excel in many virtues, that will be an eminent aid" },
  { number: 133, tamil: "ஒழுக்கம் உடைமை குடிமை இழுக்கம்\nஇழிந்த பிறப்பாய் விடும்.", transliteration: "Ozhukkam Utaimai Kutimai Izhukkam / Izhindha Pirappaai Vitum", english: "Propriety of conduct is true greatness of birth, and impropriety will sink into a mean birth" },
  { number: 134, tamil: "மறப்பினும் ஓத்துக் கொளலாகும் பார்ப்பான்\nபிறப்பொழுக்கங் குன்றக் கெடும்.", transliteration: "Marappinum Oththuk Kolalaakum Paarppaan / Pirappozhukkang Kundrak Ketum", english: "A Brahman though he should forget the Vedas may recover it by reading; but, if he fail in propriety of conduct even his high birth will be destroyed" },
  { number: 135, tamil: "அழுக்கா றுடையான்கண் ஆக்கம்போன்று இல்லை\nஒழுக்க மிலான்கண் உயர்வு.", transliteration: "Azhukkaa Rutaiyaankan Aakkampondru Illai / Ozhukka Milaankan Uyarvu", english: "Just as the envious man will be without wealth, so will the man of destitute of propriety of conduct be without greatness" },
  { number: 136, tamil: "ஒழுக்கத்தின் ஒல்கார் உரவோர் இழுக்கத்தின்\nஏதம் படுபாக் கறிந்து.", transliteration: "Ozhukkaththin Olkaar Uravor Izhukkaththin / Edham Patupaak Karindhu", english: "Those firm in mind will not slacken in their observance of the proprieties of life, knowing, as they do, the misery that flows from the transgression from them" },
  { number: 137, tamil: "ஒழுக்கத்தின் எய்துவர் மேன்மை இழுக்கத்தின்\nஎய்துவர் எய்தாப் பழி.", transliteration: "Ozhukkaththin Eydhuvar Menmai Izhukkaththin / Eydhuvar Eydhaap Pazhi", english: "From propriety of conduct men obtain greatness; from impropriety comes insufferable disgrace" },
  { number: 138, tamil: "நன்றிக்கு வித்தாகும் நல்லொழுக்கம் தீயொழுக்கம்\nஎன்றும் இடும்பை தரும்.", transliteration: "Nandrikku Viththaakum Nallozhukkam Theeyozhukkam / Endrum Itumpai Tharum", english: "Propriety of conduct is the seed of virtue; impropriety will ever cause sorrow" },
  { number: 139, tamil: "ஒழுக்க முடையவர்க்கு ஒல்லாவே தீய\nவழுக்கியும் வாயாற் சொலல்.", transliteration: "Ozhukka Mutaiyavarkku Ollaave Theeya / Vazhukkiyum Vaayaar Solal", english: "Those who study propriety of conduct will not speak evil, even forgetfully" },
  { number: 140, tamil: "உலகத்தோடு ஒட்ட ஒழுகல் பலகற்றும்\nகல்லார் அறிவிலா தார்", transliteration: "Ulakaththotu Otta Ozhukal Palakatrum / Kallaar Arivilaa Thaar", english: "Those who know not how to act agreeably to the world, though they have learnt many things, are still ignorant" },
  { number: 141, tamil: "பிறன்பொருளாள் பெட்டொழுகும் பேதைமை ஞாலத்து\nஅறம்பொருள் கண்டார்கண் இல்.", transliteration: "Piranporulaal Pettozhukum Pedhaimai Gnaalaththu / Aramporul Kantaarkan Il", english: "The folly of desiring her who is the property of another will not be found in those who know (the attributes of) virtue and (the rights of) property" },
  { number: 142, tamil: "அறன்கடை நின்றாருள் எல்லாம் பிறன்கடை\nநின்றாரின் பேதையார் இல்.", transliteration: "Arankatai Nindraarul Ellaam Pirankatai / Nindraarin Pedhaiyaar Il", english: "Among all those who stand on the outside of virtue, there are no greater fools than those who stand outside their neighbour's door" },
  { number: 143, tamil: "விளிந்தாரின் வேறல்லர் மன்ற தெளிந்தாரில்\nதீமை புரிந்து ஒழுகு வார்.", transliteration: "Vilindhaarin Verallar Mandra Thelindhaaril / Theemai Purindhu Ozhuku Vaar", english: "Certainly they are no better than dead men who desire evil towards the wife of those who" },
  { number: 144, tamil: "எனைத்துணையர் ஆயினும் என்னாம் தினைத்துணையும்\nதேரான் பிறனில் புகல்.", transliteration: "Enaiththunaiyar Aayinum Ennaam Thinaiththunaiyum / Theraan Piranil Pukal", english: "However great one may be, what does it avail if, without at all considering his guilt, he goes unto the wife of another ?" },
  { number: 145, tamil: "எளிதென இல்லிறப்பான் எய்துமெஞ் ஞான்றும்\nவிளியாது நிற்கும் பழி.", transliteration: "Elidhena Illirappaan Eydhumenj Gnaandrum / Viliyaadhu Nirkum Pazhi", english: "He who thinks lightly of going into the wife of another acquires guilt that will abide with him imperishably and for ever" },
  { number: 146, tamil: "பகைபாவம் அச்சம் பழியென நான்கும்\nஇகவாவாம் இல்லிறப்பான் கண்.", transliteration: "Pakaipaavam Achcham Pazhiyena Naankum / Ikavaavaam Illirappaan Kan", english: "Hatred, sin, fear, disgrace; these four will never leave him who goes in to his neighbour's wife" },
  { number: 147, tamil: "அறனியலான் இல்வாழ்வான் என்பான் பிறனியலாள்\nபெண்மை நயவா தவன்.", transliteration: "Araniyalaan Ilvaazhvaan Enpaan Piraniyalaal / Penmai Nayavaa Thavan", english: "He who desires not the womanhood of her who should walk according to the will of another will be praised as a virtuous house-holder" },
  { number: 148, tamil: "பிறன்மனை நோக்காத பேராண்மை சான்றோர்க்கு\nஅறனொன்றோ ஆன்ற வொழுக்கு.", transliteration: "Piranmanai Nokkaadha Peraanmai Saandrorkku / Aranondro Aandra Vozhukku", english: "That noble manliness which looks not at the wife of another is the virtue and dignity of the great" },
  { number: 149, tamil: "நலக்குரியார் யாரெனின் நாமநீர் வைப்பின்\nபிறர்க்குரியாள் தோள்தோயா தார்.", transliteration: "Nalakkuriyaar Yaarenin Naamaneer Vaippin / Pirarkkuriyaal Tholdhoyaa Thaar", english: "Is it asked, \"who are those who shall obtain good in this world surrounded by the terror-producing sea ?\" Those who touch not the shoulder of her who belongs to another" },
  { number: 150, tamil: "அறன்வரையான் அல்ல செயினும் பிறன்வரையாள்\nபெண்மை நயவாமை நன்று.", transliteration: "Aranvaraiyaan Alla Seyinum Piranvaraiyaal / Penmai Nayavaamai Nandru", english: "Though a man perform no virtuous deeds and commit (every) vice, it will be well if he desire not the womanhood of her who is within the limit (of the house) of another" },
  { number: 151, tamil: "அகழ்வாரைத் தாங்கும் நிலம்போலத் தம்மை\nஇகழ்வார்ப் பொறுத்தல் தலை.", transliteration: "Akazhvaaraith Thaangum Nilampolath Thammai / Ikazhvaarp Poruththal Thalai", english: "To bear with those who revile us, just as the earth bears up those who dig it, is the first of virtues" },
  { number: 152, tamil: "பொறுத்தல் இறப்பினை என்றும் அதனை\nமறத்தல் அதனினும் நன்று.", transliteration: "Poruththal Irappinai Endrum Adhanai / Maraththal Adhaninum Nandru", english: "Bear with reproach even when you can retaliate; but to forget it will be still better than that" },
  { number: 153, tamil: "இன்மையுள் இன்மை விருந்தொரால் வன்மையுள்\nவன்மை மடவார்ப் பொறை.", transliteration: "Inmaiyul Inmai Virundhoraal Vanmaiyul / Vanmai Matavaarp Porai", english: "To neglect hospitality is poverty of poverty To bear with the ignorant is might of might" },
  { number: 154, tamil: "நிறையுடைமை நீங்காமை வேண்டின் பொற்யுடைமை\nபோற்றி யொழுகப் படும்.", transliteration: "Niraiyutaimai Neengaamai Ventin Poraiyutaimai / Potri Yozhukap Patum", english: "If you desire that greatness should never leave, you preserve in your conduct the exercise of patience" },
  { number: 155, tamil: "ஒறுத்தாரை ஒன்றாக வையாரே வைப்பர்\nபொறுத்தாரைப் பொன்போற் பொதிந்து.", transliteration: "Oruththaarai Ondraaka Vaiyaare Vaippar / Poruththaaraip Ponpor Podhindhu", english: "(The wise) will not at all esteem the resentful They will esteem the patient just as the gold which they lay up with care" },
  { number: 156, tamil: "ஒறுத்தார்க்கு ஒருநாளை இன்பம் பொறுத்தார்க்குப்\nபொன்றுந் துணையும் புகழ்.", transliteration: "Oruththaarkku Orunaalai Inpam Poruththaarkkup / Pondrun Thunaiyum Pukazh", english: "The pleasure of the resentful continues for a day The praise of the patient will continue until (the final destruction of) the world" },
  { number: 157, tamil: "திறனல்ல தற்பிறர் செய்யினும் நோநொந்து\nஅறனல்ல செய்யாமை நன்று.", transliteration: "Thiranalla Tharpirar Seyyinum Nonondhu / Aranalla Seyyaamai Nandru", english: "Though others inflict injuries on you, yet compassionating the evil (that will come upon them) it will be well not to do them anything contrary to virtue" },
  { number: 158, tamil: "மிகுதியான் மிக்கவை செய்தாரைத் தாந்தம்\nதகுதியான் வென்று விடல்.", transliteration: "Mikudhiyaan Mikkavai Seydhaaraith Thaandham / Thakudhiyaan Vendru Vital", english: "Let a man by patience overcome those who through pride commit excesses" },
  { number: 159, tamil: "துறந்தாரின் தூய்மை உடையர் இறந்தார்வாய்\nஇன்னாச்சொல் நோற்கிற் பவர்.", transliteration: "Thurandhaarin Thooimai Utaiyar Irandhaarvaai / Innaachchol Norkir Pavar", english: "Those who bear with the uncourteous speech of the insolent are as pure as the ascetics" },
  { number: 160, tamil: "உண்ணாது நோற்பார் பெரியர் பிறர்சொல்லும்\nஇன்னாச்சொல் நோற்பாரின் பின்.", transliteration: "Unnaadhu Norpaar Periyar Pirarsollum / Innaachchol Norpaarin Pin", english: "Those who endure abstinence from food are great, next to those who endure the uncourteous speech of others" },
  { number: 161, tamil: "ஒழுக்காறாக் கொள்க ஒருவன்தன் நெஞ்சத்து\nஅழுக்காறு இலாத இயல்பு.", transliteration: "Ozhukkaaraak Kolka Oruvandhan Nenjaththu / Azhukkaaru Ilaadha Iyalpu", english: "Let a man esteem that disposition which is free from envy in the same manner as propriety of conduct" },
  { number: 162, tamil: "விழுப்பேற்றின் அஃதொப்பது இல்லையார் மாட்டும்\nஅழுக்காற்றின் அன்மை பெறின்.", transliteration: "Vizhuppetrin Aqdhoppadhu Illaiyaar Maattum / Azhukkaatrin Anmai Perin", english: "Amongst all attainable excellences there is none equal to that of being free from envy towords others" },
  { number: 163, tamil: "அறன்ஆக்கம் வேண்டாதான் என்பான் பிறனாக்கம்\nபேணாது அழுக்கறுப் பான்.", transliteration: "Aranaakkam Ventaadhaan Enpaan Piranaakkam / Penaadhu Azhukkarup Paan", english: "Of him who instead of rejoicing in the wealth of others, envies it, it will be said \"he neither desires virtue not wealth.\"" },
  { number: 164, tamil: "அழுக்காற்றின் அல்லவை செய்யார் இழுக்காற்றின்\nஏதம் படுபாக்கு அறிந்து.", transliteration: "Azhukkaatrin Allavai Seyyaar Izhukkaatrin / Edham Patupaakku Arindhu", english: "(The wise) knowing the misery that comes from transgression will not through envy commit unrighteous deeds" },
  { number: 165, tamil: "அழுக்காறு உடையார்க்கு அதுசாலும் ஒன்னார்\nவழுக்காயும் கேடீன் பது.", transliteration: "Azhukkaaru Utaiyaarkku Adhusaalum Onnaar / Vazhukka�yum Keteen Padhu", english: "To those who cherish envy that is enough Though free from enemies that (envy) will bring destruction" },
  { number: 166, tamil: "கொடுப்பது அழுக்கறுப்பான் சுற்றம் உடுப்பதூஉம்\nஉண்பதூஉம் இன்றிக் கெடும்.", transliteration: "Kotuppadhu Azhukkaruppaan Sutram Utuppadhooum / Unpadhooum Indrik Ketum", english: "He who is envious at a gift (made to another) will with his relations utterly perish destitute of food and rainment" },
  { number: 167, tamil: "அவ்வித்து அழுக்காறு உடையானைச் செய்யவள்\nதவ்வையைக் காட்டி விடும்.", transliteration: "Avviththu Azhukkaaru Utaiyaanaich Cheyyaval / Thavvaiyaik Kaatti Vitum", english: "Lakshmi envying (the prosperity) of the envious man will depart and introduce him to her sister" },
  { number: 168, tamil: "அழுக்காறு எனஒரு பாவி திருச்செற்றுத்\nதீயுழி உய்த்து விடும்.", transliteration: "Azhukkaaru Enaoru Paavi Thiruchchetruth / Theeyuzhi Uyththu Vitum", english: "Envy will destroy (a man's) wealth (in his world) and drive him into the pit of fire (in the world to come.)" },
  { number: 169, tamil: "அவ்விய நெஞ்சத்தான் ஆக்கமும் செவ்வியான்\nகேடும் நினைக்கப் படும்.", transliteration: "Avviya Nenjaththaan Aakkamum Sevviyaan / Ketum Ninaikkap Patum", english: "The wealth of a man of envious mind and the poverty of the righteous will be pondered" },
  { number: 170, tamil: "அழுக்கற்று அகன்றாரும் இல்லை அஃதுஇல்லார்\nபெருக்கத்தில் தீர்ந்தாரும் இல்.", transliteration: "Azhukkatru Akandraarum Illai Aqdhuillaar / Perukkaththil Theerndhaarum Il", english: "Never have the envious become great; never have those who are free from envy been without greatness" },
  { number: 171, tamil: "நடுவின்றி நன்பொருள் வெஃகின் குடிபொன்றிக்\nகுற்றமும் ஆங்கே தரும்.", transliteration: "Natuvindri Nanporul Veqkin Kutipondrik / Kutramum Aange Tharum", english: "If a man departing from equity covet the property (of others), at that very time will his family be destroyed and guilt be incurred" },
  { number: 172, tamil: "படுபயன் வெஃகிப் பழிப்படுவ செய்யார்\nநடுவன்மை நாணு பவர்.", transliteration: "Patupayan Veqkip Pazhippatuva Seyyaar / Natuvanmai Naanu Pavar", english: "Those who blush at the want of equity will not commit disgraceful acts through desire of the profit that may be gained" },
  { number: 173, tamil: "சிற்றின்பம் வெஃகி அறனல்ல செய்யாரே\nமற்றின்பம் வேண்டு பவர்.", transliteration: "Sitrinpam Veqki Aranalla Seyyaare / Matrinpam Ventu Pavar", english: "Those who desire the higher pleasures (of heaven) will not act unjustly through desire of the trifling joy. (in this life.)" },
  { number: 174, tamil: "இலமென்று வெஃகுதல் செய்யார் புலம்வென்ற\nபுன்மையில் காட்சி யவர்.", transliteration: "Ilamendru Veqkudhal Seyyaar Pulamvendra / Punmaiyil Kaatchi Yavar", english: "The wise who have conquered their senses and are free from crime, will not covet (the things of others), with the thought \"we are destitute.\"" },
  { number: 175, tamil: "அஃகி அகன்ற அறிவென்னாம் யார்மாட்டும்\nவெஃகி வெறிய செயின்.", transliteration: "Aqki Akandra Arivennaam Yaarmaattum / Veqki Veriya Seyin", english: "What is the advantage of extensive and accurate knowledge if a man through covetousness act senselessly towards all ?" },
  { number: 176, tamil: "அருள்வெஃகி ஆற்றின்கண் நின்றான் பொருள்வெஃகிப்\nபொல்லாத சூழக் கெடும்.", transliteration: "Arulveqki Aatrinkan Nindraan Porulveqkip / Pollaadha Soozhak Ketum", english: "If he, who through desire of the virtue of kindness abides in the domestic state ie, the path in which it may be obtained, covet (the property of others) and think of evil methods (to obtain it), he will perish" },
  { number: 177, tamil: "வேண்டற்க வெஃகியாம் ஆக்கம் விளைவயின்\nமாண்டற் கரிதாம் பயன்.", transliteration: "Ventarka Veqkiyaam Aakkam Vilaivayin / Maantar Karidhaam Payan", english: "Desire not the gain of covetousness In the enjoyment of its fruits there is no glory" },
  { number: 178, tamil: "அஃகாமை செல்வத்திற்கு யாதெனின் வெஃகாமை\nவேண்டும் பிறன்கைப் பொருள்.", transliteration: "Aqkaamai Selvaththirku Yaadhenin Veqkaamai / Ventum Pirankaip Porul", english: "If it is weighed, \"what is the indestructibility of wealth,\" it is freedom from covetousness" },
  { number: 179, tamil: "அறனறிந்து வெஃகா அறிவுடையார்ச் சேரும்\nதிறன்அறிந் தாங்கே திரு.", transliteration: "Aranarindhu Veqkaa Arivutaiyaarch Cherum / Thiranarin Thaange Thiru", english: "Lakshmi, knowing the manner (in which she may approach) will immediately come to those wise men who, knowing that it is virtue, covet not the property of others" },
  { number: 180, tamil: "இறலீனும் எண்ணாது வெஃகின் விறல்ஈனும்\nவேண்டாமை என்னுஞ் செருக்கு.", transliteration: "Iraleenum Ennaadhu Veqkin Viraleenum / Ventaamai Ennunj Cherukku", english: "To covet (the wealth of another) regardless of consequences will bring destruction That greatness (of mind) which covets not will give victory" },
  { number: 181, tamil: "அறங்கூறான் அல்ல செயினும் ஒருவன்\nபுறங்கூறான் என்றல் இனிது.", transliteration: "Arangooraan Alla Seyinum Oruvan / Purangooraan Endral Inidhu", english: "Though one do not even speak of virtue and live in sin, it will be well if it be said of him \"he does not backbite.\"" },
  { number: 182, tamil: "அறனழீஇ அல்லவை செய்தலின் தீதே\nபுறனழீஇப் பொய்த்து நகை.", transliteration: "Aranazheei Allavai Seydhalin Theedhe / Puranazheeip Poiththu Nakai", english: "To smile deceitfully (in another's presence) after having reviled him to his destruction (behind his back) is a greater evil than the commission of (every other) sin and the destruction of (every) virtue" },
  { number: 183, tamil: "புறங்கூறிப் பொய்த்துயிர் வாழ்தலின் சாதல்\nஅறங்கூற்றும் ஆக்கத் தரும்.", transliteration: "Purangoorip Poiththuyir Vaazhdhalin Saadhal / Arangootrum Aakkath Tharum", english: "Death rather than life will confer upon the deceitful backbiter the profit which (the treatises on) virtue point out" },
  { number: 184, tamil: "கண்ணின்று கண்ணறச் சொல்லினும் சொல்லற்க\nமுன்னின்று பின்நோக்காச் சொல்.", transliteration: "Kannindru Kannarach Chollinum Sollarka / Munnindru Pinnokkaach Chol", english: "Though you speak without kindness before another's face speak not in his absence words which regard not the evil subsequently resulting from it" },
  { number: 185, tamil: "அறஞ்சொல்லும் நெஞ்சத்தான் அன்மை புறஞ்சொல்லும்\nபுன்மையாற் காணப் படும்.", transliteration: "Aranjollum Nenjaththaan Anmai Puranjollum / Punmaiyaar Kaanap Patum", english: "The emptiness of that man's mind who (merely) praises virtue will be seen from the meanness of reviling another behind his back" },
  { number: 186, tamil: "பிறன்பழி கூறுவான் தன்பழி யுள்ளும்\nதிறன்தெரிந்து கூறப் படும்.", transliteration: "Piranpazhi Kooruvaan Thanpazhi Yullum / Thirandherindhu Koorap Patum", english: "The character of the faults of that man who publishes abroad the faults of others will be sought out and published" },
  { number: 187, tamil: "பகச்சொல்லிக் கேளிர்ப் பிரிப்பர் நகச்சொல்லி\nநட்பாடல் தேற்றா தவர்.", transliteration: "Pakachchollik Kelirp Pirippar Nakachcholli / Natpaatal Thetraa Thavar", english: "Those who know not to live in friendship with amusing conversation will by back-biting estrange even their relatives" },
  { number: 188, tamil: "துன்னியார் குற்றமும் தூற்றும் மரபினார்\nஎன்னைகொல் ஏதிலார் மாட்டு.", transliteration: "Thunniyaar Kutramum Thootrum Marapinaar / Ennaikol Edhilaar Maattu", english: "What will those not do to strangers whose nature leads them to publish abroad the faults of their intimate friends ?" },
  { number: 189, tamil: "அறன்நோக்கி ஆற்றுங்கொல் வையம் புறன்நோக்கிப்\nபுன்சொல் உரைப்பான் பொறை.", transliteration: "Arannokki Aatrungol Vaiyam Purannokkip / Punsol Uraippaan Porai", english: "The world through charity supports the weight of those who reproach others observing their absence" },
  { number: 190, tamil: "ஏதிலார் குற்றம்போல் தங்குற்றங் காண்கிற்பின்\nதீதுண்டோ மன்னும் உயிர்க்கு.", transliteration: "Edhilaar Kutrampol Thangutrang Kaankirpin / Theedhunto Mannum Uyirkku", english: "If they observed their own faults as they observe the faults of others, would any evil happen to men ?" },
  { number: 191, tamil: "பல்லார் முனியப் பயனில சொல்லுவான்\nஎல்லாரும் எள்ளப் படும்.", transliteration: "Pallaar Muniyap Payanila Solluvaan / Ellaarum Ellap Patum", english: "He who to the disgust of many speaks useless things will be despised by all" },
  { number: 192, tamil: "பயனில பல்லார்முன் சொல்லல் நயனில\nநட்டார்கண் செய்தலிற் றீது.", transliteration: "Payanila Pallaarmun Sollal Nayanila / Nattaarkan Seydhalir Reedhu", english: "To speak useless things in the presence of many is a greater evil than to do unkind things towards friends" },
  { number: 193, tamil: "நயனிலன் என்பது சொல்லும் பயனில\nபாரித் துரைக்கும் உரை.", transliteration: "Nayanilan Enpadhu Sollum Payanila / Paarith Thuraikkum Urai", english: "That conversation in which a man utters forth useless things will say of him \"he is without virtue.\"" },
  { number: 194, tamil: "நயன்சாரா நன்மையின் நீக்கும் பயன்சாராப்\nபண்பில்சொல் பல்லா ரகத்து.", transliteration: "Nayansaaraa Nanmaiyin Neekkum Payansaaraap / Panpilsol Pallaa Rakaththu", english: "The words devoid of profit or pleasure which a man speaks will, being inconsistent with virtue," },
  { number: 195, tamil: "சீர்மை சிறப்பொடு நீங்கும் பயனில\nநீர்மை யுடையார் சொலின்.", transliteration: "Seermai Sirappotu Neengum Payanila / Neermai Yutaiyaar Solin", english: "If the good speak vain words their eminence and excellence will leave them" },
  { number: 196, tamil: "பயனில்சொல் பாராட்டு வானை மகன்எனல்\nமக்கட் பதடி யெனல்.", transliteration: "Payanil Sol Paaraattu Vaanai / Makanenal Makkat Padhati Yenal", english: "Call not him a man who parades forth his empty words Call him the chaff of men" },
  { number: 197, tamil: "நயனில சொல்லினுஞ் சொல்லுக சான்றோர்\nபயனில சொல்லாமை நன்று.", transliteration: "Nayanila Sollinunj Cholluka Saandror / Payanila Sollaamai Nandru", english: "Let the wise if they will, speak things without excellence; it will be well for them not to speak useless things" },
  { number: 198, tamil: "அரும்பயன் ஆயும் அறிவினார் சொல்லார்\nபெரும்பயன் இல்லாத சொல்.", transliteration: "Arumpayan Aayum Arivinaar Sollaar / Perumpayan Illaadha Sol", english: "The wise who seek after rare pleasures will not speak words that have not much weight in them" },
  { number: 199, tamil: "பொருள்தீர்ந்த பொச்சாந்துஞ் சொல்லார் மருள்தீர்ந்த\nமாசறு காட்சி யவர்.", transliteration: "Poruldheerndha Pochchaandhunj Chollaar Maruldheerndha / Maasaru Kaatchi Yavar", english: "Those wise men who are without faults and are freed from ignorance will not even forgetfully speak things that profit not" },
  { number: 200, tamil: "சொல்லுக சொல்லிற் பயனுடைய சொல்லற்க\nசொல்லிற் பயனிலாச் சொல்.", transliteration: "Solluka Sollir Payanutaiya Sollarka / Sollir Payanilaach Chol", english: "Speak what is useful, and speak not useless words" },
  { number: 201, tamil: "தீவினையார் அஞ்சார் விழுமியார் அஞ்சுவர்\nதீவினை என்னும் செருக்கு.", transliteration: "Theevinaiyaar Anjaar Vizhumiyaar Anjuvar / Theevinai Ennum Serukku", english: "Those who have experience of evil deeds will not fear, but the excellent will fear the pride of sin" },
  { number: 202, tamil: "தீயவை தீய பயத்தலால் தீயவை\nதீயினும் அஞ்சப் படும்.", transliteration: "Theeyavai Theeya Payaththalaal Theeyavai / Theeyinum Anjap Patum", english: "Because evil produces evil, therefore should evil be feared more than fire" },
  { number: 203, tamil: "அறிவினுள் எல்லாந் தலையென்ப தீய\nசெறுவார்க்கும் செய்யா விடல்.", transliteration: "Arivinul Ellaan Thalaiyenpa Theeya / Seruvaarkkum Seyyaa Vital", english: "So shalt thou wisdom's highest law, 'tis said, fulfil" },
  { number: 204, tamil: "மறந்தும் பிறன்கேடு சூழற்க சூழின்\nஅறஞ்சூழம் சூழ்ந்தவன் கேடு.", transliteration: "Marandhum Piranketu Soozharka Soozhin / Aranjoozham Soozhndhavan Ketu", english: "Even though forgetfulness meditate not the ruin of another Virtue will meditate the ruin of him who thus meditates" },
  { number: 205, tamil: "இலன்என்று தீயவை செய்யற்க செய்யின்\nஇலனாகும் மற்றும் பெயர்த்து.", transliteration: "Ilan Endru Theeyavai Seyyarka / Seyyin Ilanaakum Matrum Peyarththu", english: "Commit not evil, saying, \"I am poor\": if you do, you will become poorer still" },
  { number: 206, tamil: "தீப்பால தான்பிறர்கண் செய்யற்க நோய்ப்பால\nதன்னை அடல்வேண்டா தான்.", transliteration: "Theeppaala Thaanpirarkan Seyyarka Noippaala / Thannai Atalventaa Thaan", english: "Let him not do evil to others who desires not that sorrows should pursue him" },
  { number: 207, tamil: "எனைப்பகை யுற்றாரும் உய்வர் வினைப்பகை\nவீயாது பின்சென்று அடும்.", transliteration: "Enaippakai Yutraarum Uyvar Vinaippakai / Veeyaadhu Pinsendru Atum", english: "However great be the enmity men have incurred they may still live The enmity of sin will incessantly pursue and kill" },
  { number: 208, tamil: "தீயவை செய்தார் கெடுதல் நிழல்தன்னை\nவீயாது அஇஉறைந் தற்று.", transliteration: "Theeyavai Seydhaar Ketudhal Nizhaldhannai / Veeyaadhu Atiurain Thatru", english: "Destruction will dwell at the heels of those who commit evil even as their shadow that leaves them not" },
  { number: 209, tamil: "தன்னைத்தான் காதல னாயின் எனைத்தொன்றும்\nதுன்னற்க தீவினைப் பால்.", transliteration: "Thannaiththaan Kaadhala Naayin Enaiththondrum / Thunnarka Theevinaip Paal", english: "If a man love himself, let him not commit any sin however small" },
  { number: 210, tamil: "அருங்கேடன் என்பது அறிக மருங்கோடித்\nதீவினை செய்யான் எனின்.", transliteration: "Arungetan Enpadhu Arika Marungotith / Theevinai Seyyaan Enin", english: "Know ye that he is freed from destruction who commits no evil, going to neither side of the right path" },
  { number: 211, tamil: "கைம்மாறு வேண்டா கடப்பாடு மாரிமாட்டு\nஎன் ஆற்றுங் கொல்லோ உலகு.", transliteration: "Kaimmaaru Ventaa Katappaatu Maarimaattu / En Aatrung Kollo Ulaku", english: "Benevolence seeks not a return. What does the world give back to the clouds ?" },
  { number: 212, tamil: "தாளாற்றித் தந்த பொருளெல்லாம் தக்கார்க்கு\nவேளாண்மை செய்தற் பொருட்டு.", transliteration: "Thaalaatrith Thandha Porulellaam Thakkaarkku / Velaanmai Seydhar Poruttu", english: "All the wealth acquired with perseverance by the worthy is for the exercise of benevolence" },
  { number: 213, tamil: "புத்தே ளுலகத்தும் ஈண்டும் பெறலரிதே\nஒப்புரவின் நல்ல பிற.", transliteration: "Puththe Lulakaththum Eentum Peralaridhe / Oppuravin Nalla Pira", english: "It is difficult to obtain another good equal to benevolence either in this world or in that of the gods" },
  { number: 214, tamil: "ஒத்த தறவோன் உயிர்வாழ்வான் மற்றையான்\nசெத்தாருள் வைக்கப் படும்.", transliteration: "Oththa Tharavon Uyirvaazhvaan Matraiyaan / Seththaarul Vaikkap Patum", english: "He truly lives who knows (and discharges) the proper duties (of benevolence) He who knows them not will be reckoned among the dead" },
  { number: 215, tamil: "ஊருணி நீர்நிறைந் தற்றே உலகவாம்\nபேரறி வாளன் திரு.", transliteration: "Ooruni Neernirain Thatre Ulakavaam / Perari Vaalan Thiru", english: "The wealth of that man of eminent knowledge who desires to exercise the benevolence approved of by the world, is like the full waters of a city-tank" },
  { number: 216, tamil: "பயன்மரம் உள்ளூர்ப் பழுத்தற்றால் செல்வம்\nநயனுடை யான்கண் படின்.", transliteration: "Payanmaram Ulloorp Pazhuththatraal Selvam / Nayanutai Yaankan Patin", english: "The wealth of a man (possessed of the virtue) of benevolence is like the ripening of a fruitful tree in the midst of a town" },
  { number: 217, tamil: "மருந்தாகித் தப்பா மரத்தற்றால் செல்வம்\nபெருந்தகை யான்கண் படின்.", transliteration: "Marundhaakith Thappaa Maraththatraal Selvam / Perundhakai Yaankan Patin", english: "If wealth be in the possession of a man who has the great excellence (of benevolence), it is like a tree which as a medicine is an infallible cure for disease" },
  { number: 218, tamil: "இடனில் பருவத்தும் ஒப்புரவிற்கு ஒல்கார்\nகடனறி காட்சி யவர்.", transliteration: "Itanil Paruvaththum Oppuravirku Olkaar / Katanari Kaatchi Yavar", english: "The wise who know what is duty will not scant their benevolence even when they are without wealth" },
  { number: 219, tamil: "நயனுடையான் நல்கூர்ந்தா னாதல் செயும்நீர\nசெய்யாது அமைகலா வாறு.", transliteration: "Nayanutaiyaan Nalkoorndhaa Naadhal Seyumneera / Seyyaadhu Amaikalaa Vaaru", english: "The poverty of a benevolent man, is nothing but his inability to exercise the same" },
  { number: 220, tamil: "ஒப்புரவி னால்வரும் கேடெனின் அஃதொருவன்\nவிற்றுக்கோள் தக்க துடைத்து.", transliteration: "Oppuravi Naalvarum Ketenin Aqdhoruvan / Vitrukkol Thakka Thutaiththu", english: "If it be said that loss will result from benevolence, such loss is worth being procured even by the sale of one's self" },
  { number: 221, tamil: "வறியார்க்கொன்று ஈவதே ஈகைமற் றெல்லாம்\nகுறியெதிர்ப்பை நீர துடைத்து.", transliteration: "Variyaarkkondru Eevadhe Eekaimar Rellaam / Kuriyedhirppai Neera Thutaiththu", english: "To give to the destitute is true charity All other gifts have the nature of (what is done for) a measured return" },
  { number: 222, tamil: "நல்லாறு எனினும் கொளல்தீது மேலுலகம்\nஇல்லெனினும் ஈதலே நன்று.", transliteration: "Nallaaru Eninum Kolaldheedhu Melulakam / Illeninum Eedhale Nandru", english: "To beg is evil, even though it were said that it is a good path (to heaven) To give is good, even though it were said that those who do so cannot obtain heaven" },
  { number: 223, tamil: "இலனென்னும் எவ்வம் உரையாமை ஈதல்\nகுலனுடையான் கண்ணே யுள.", transliteration: "Ilanennum Evvam Uraiyaamai Eedhal / Kulanutaiyaan Kanne Yula", english: "(Even in a low state) not to adopt the mean expedient of saying \"I have nothing,\" but to give, is the characteristic of the mad of noble birth" },
  { number: 224, tamil: "இன்னாது இரக்கப் படுதல் இரந்தவர்\nஇன்முகங் காணும் அளவு.", transliteration: "Innaadhu Irakkap Patudhal Irandhavar / Inmukang Kaanum Alavu", english: "To see men begging from us in disagreeable, until we see their pleasant countenance" },
  { number: 225, tamil: "ஆற்றுவார் ஆற்றல் பசிஆற்றல் அப்பசியை\nமாற்றுவார் ஆற்றலின் பின்.", transliteration: "Aatruvaar Aatral Pasiaatral Appasiyai / Maatruvaar Aatralin Pin", english: "The power of those who perform penance is the power of enduring hunger It is inferior to the power of those who remove the hunger (of others)" },
  { number: 226, tamil: "அற்றார் அழிபசி தீர்த்தல் அஃதொருவன்\nபெற்றான் பொருள்வைப் புழி.", transliteration: "Atraar Azhipasi Theerththal Aqdhoruvan / Petraan Porulvaip Puzhi", english: "The removal of the killing hunger of the poor is the place for one to lay up his wealth" },
  { number: 227, tamil: "பாத்தூண் மரீஇ யவனைப் பசியென்னும்\nதீப்பிணி தீண்டல் அரிது.", transliteration: "Paaththoon Mareei Yavanaip Pasiyennum / Theeppini Theental Aridhu", english: "The fiery disease of hunger shall never touch him who habitually distributes his food to others" },
  { number: 228, tamil: "ஈத்துவக்கும் இன்பம் அறியார்கொல் தாமுடைமை\nவைத்திழக்கும் வன்க ணவர்.", transliteration: "Eeththuvakkum Inpam Ariyaarkol Thaamutaimai / Vaiththizhakkum Vanka Navar", english: "Do the hard-eyed who lay up and lose their possessions not know the happiness which springs from the pleasure of giving ?" },
  { number: 229, tamil: "இரத்தலின் இன்னாது மன்ற நிரப்பிய\nதாமே தமியர் உணல்.", transliteration: "Iraththalin Innaadhu Mandra Nirappiya / Thaame Thamiyar Unal", english: "Solitary and unshared eating for the sake of filling up one's own riches is certainly much more" },
  { number: 230, tamil: "சாதலின் இன்னாத தில்லை இனிததூஉம்\nஈதல் இயையாக் கடை.", transliteration: "Saadhalin Innaadha Thillai Inidhadhooum / Eedhal Iyaiyaak Katai", english: "Nothing is more unpleasant than death: yet even that is pleasant where charity cannot be exercised" },
  { number: 231, tamil: "ஈதல் இசைபட வாழ்தல் அதுவல்லது\nஊதியம் இல்லை உயிர்க்கு.", transliteration: "Eedhal Isaipata Vaazhdhal Adhuvalladhu / Oodhiyam Illai Uyirkku", english: "Give to the poor and live with praise There is no greater profit to man than that" },
  { number: 232, tamil: "உரைப்பார் உரைப்பவை எல்லாம் இரப்பார்க்கொன்று\nஈவார்மேல் நிற்கும் புகழ்.", transliteration: "Uraippaar Uraippavai Ellaam Irappaarkkondru / Eevaarmel Nirkum Pukazh", english: "Whatsoever is spoken in the world will abide as praise upon that man who gives alms to the poor" },
  { number: 233, tamil: "ஒன்றா உலகத்து உயர்ந்த புகழல்லால்\nபொன்றாது நிற்பதொன் றில்.", transliteration: "Ondraa Ulakaththu Uyarndha Pukazhallaal / Pondraadhu Nirpadhon Ril", english: "There is nothing that stands forth in the world imperishable, except fame, exalted in solitary greatness" },
  { number: 234, tamil: "நிலவரை நீள்புகழ் ஆற்றின் புலவரைப்\nபோற்றாது புத்தேள் உலகு.", transliteration: "Nilavarai Neelpukazh Aatrin Pulavaraip / Potraadhu Puththel Ulaku", english: "If one has acquired extensive fame within the limits of this earth, the world of the Gods will no longer praise those sages who have attained that world" },
  { number: 235, tamil: "நத்தம்போல் கேடும் உளதாகும் சாக்காடும்\nவித்தகர்க் கல்லால் அரிது.", transliteration: "Naththampol Ketum Uladhaakum Saakkaatum / Viththakark Kallaal Aridhu", english: "Prosperity to the body of fame, resulting in poverty to the body of flesh and the stability to the former arising from the death of the latter, are achievable only by the wise" },
  { number: 236, tamil: "தோன்றின் புகழொடு தோன்றுக அஃதிலார்\nதோன்றலின் தோன்றாமை நன்று.", transliteration: "Thondrin Pukazhotu Thondruka Aqdhilaar / Thondralin Thondraamai Nandru", english: "If you are born (in this world), be born with qualities conductive to fame From those who are destitute of them it will be better not to be born" },
  { number: 237, tamil: "புகழ்பட வாழாதார் தந்நோவார் தம்மை\nஇகழ்வாரை நோவது எவன்?", transliteration: "Pukazhpata Vaazhaadhaar Thannovaar Thammai / Ikazhvaarai Novadhu Evan?", english: "Why do those who cannot live with praise, grieve those who despise them, instead of grieving themselves for their own inability" },
  { number: 238, tamil: "வசையென்ப வையத்தார்க் கெல்லாம் இசையென்னும்\nஎச்சம் பெறாஅ விடின்.", transliteration: "Vasaiyenpa Vaiyaththaark Kellaam Isaiyennum / Echcham Peraaa Vitin", english: "Not to beget fame will be esteemed a disgrace by the wise in this world" },
  { number: 239, tamil: "வசையிலா வண்பயன் குன்றும் இசையிலா\nயாக்கை பொறுத்த நிலம்.", transliteration: "Vasaiyilaa Vanpayan Kundrum Isaiyilaa / Yaakkai Poruththa Nilam", english: "The ground which supports a body without fame will diminish in its rich produce" },
  { number: 240, tamil: "வசையொழிய வாழ்வாரே வாழ்வார் இசையொழிய\nவாழ்வாரே வாழா தவர்.", transliteration: "Vasaiyozhiya Vaazhvaare Vaazhvaar Isaiyozhiya / Vaazhvaare Vaazhaa Thavar", english: "Those live who live without disgrace Those who live without fame live not" },
  { number: 241, tamil: "அருட்செல்வம் செல்வத்துள் செல்வம் பொருட்செல்வம்\nபூரியார் கண்ணும் உள.", transliteration: "Arutchelvam Selvaththul Selvam Porutchelvam / Pooriyaar Kannum Ula", english: "The wealth of kindness is wealth of wealth, in as much as the wealth of property is possessed by the basest of men" },
  { number: 242, tamil: "நல்லாற்றாள் நாடி அருளாள்க பல்லாற்றால்\nதேரினும் அஃதே துணை.", transliteration: "Nallaatraal Naati Arulaalka Pallaatraal / Therinum Aqdhe Thunai", english: "(Stand) in the good path, consider, and be kind. Even considering according to the conflicting tenets of the different sects, kindness will be your best aid, (in the acquisition of heavenly bliss.)" },
  { number: 243, tamil: "அருள்சேர்ந்த நெஞ்சினார்க் கில்லை இருள்சேர்ந்த\nஇன்னா உலகம் புகல்.", transliteration: "Arulserndha Nenjinaark Killai Irulserndha / Innaa Ulakam Pukal", english: "They will never enter the world of darkness and wretchedness whose minds are the abode of kindness" },
  { number: 244, tamil: "மன்னுயிர் ஓம்பி அருளாள்வார்க்கு இல்லென்ப\nதன்னுயிர் அஞ்சும் வினை.", transliteration: "Mannuyir Ompi Arulaalvaarkku Illenpa / Thannuyir Anjum Vinai", english: "(The wise) say that the evils, which his soul would dread, will never come upon the man who exercises kindness and protects the life (of other creatures)" },
  { number: 245, tamil: "அல்லல் அருளாள்வார்க்கு இல்லை வளிவழங்கும்\nமல்லன்மா ஞாலங் கரி.", transliteration: "Allal Arulaalvaarkku Illai Valivazhangum / Mallanmaa Gnaalang Kari", english: "This great rich earth over which the wind blows, is a witness that sorrow never comes upon the kindhearted" },
  { number: 246, tamil: "பொருள்நீங்கிப் பொச்சாந்தார் என்பர் அருள்நீங்கி\nஅல்லவை செய்தொழுகு வார்.", transliteration: "Porulneengip Pochchaandhaar Enpar Arulneengi / Allavai Seydhozhuku Vaar", english: "(The wise) say that those who neglect kindness and practise cruelties, neglected virtue (in their former birth), and forgot (the sorrows which they must suffer.)" },
  { number: 247, tamil: "அருளில்லார்க்கு அவ்வுலகம் இல்லை பொருளில்லார்க்கு\nஇவ்வுலகம் இல்லாகி யாங்கு.", transliteration: "Arulillaarkku Avvulakam Illai Porulillaarkku / Ivvulakam Illaaki Yaangu", english: "As this world is not for those who are without wealth, so that world is not for those who are without kindness" },
  { number: 248, tamil: "பொருளற்றார் பூப்பர் ஒருகால் அருளற்றார்\nஅற்றார்மற் றாதல் அரிது.", transliteration: "Porulatraar Pooppar Orukaal Arulatraar / Atraarmar Raadhal Aridhu", english: "Those who are without wealth may, at some future time, become prosperous; those who are destitute of kindness are utterly destitute; for them there is no change" },
  { number: 249, tamil: "தெருளாதான் மெய்ப்பொருள் கண்டற்றால் தேரின்\nஅருளாதான் செய்யும் அறம்.", transliteration: "Therulaadhaan Meypporul Kantatraal Therin / Arulaadhaan Seyyum Aram", english: "If you consider, the virtue of him who is without kindness is like the perception of the true being by him who is without wisdom" },
  { number: 250, tamil: "வலியார்முன் தன்னை நினைக்கதான் தன்னின்\nமெலியார்மேல் செல்லு மிடத்து.", transliteration: "Valiyaarmun Thannai Ninaikka Thaan / Thannin Meliyaarmel Sellu Mitaththu", english: "When a man is about to rush upon those who are weaker than himself, let him remember how he has stood (trembling) before those who are stronger than himself" },
  { number: 251, tamil: "தன்னூன் பெருக்கற்குத் தான்பிறிது ஊனுண்பான்\nஎங்ஙனம் ஆளும் அருள்?", transliteration: "Thannoon Perukkarkuth Thaanpiridhu Oonunpaan / Engnganam Aalum Arul?", english: "How can he be possessed of kindness, who to increase his own flesh, eats the flesh of other creatures" },
  { number: 252, tamil: "பொருளாட்சி போற்றாதார்க்கு இல்லை அருளாட்சி\nஆங்கில்லை ஊன்தின் பவர்க்கு.", transliteration: "Porulaatchi Potraadhaarkku Illai Arulaatchi / Aangillai Oondhin Pavarkku", english: "As those possess no property who do not take care of it, so those possess no kindness who feed on flesh" },
  { number: 253, tamil: "படைகொண்டார் நெஞ்சம்போல் நன்னூக்காது ஒன்றன்\nஉடல்சுவை உண்டார் மனம்.", transliteration: "Pataikontaar Nenjampol Nannookkaadhu Ondran / Utalsuvai Untaar Manam", english: "Like the (murderous) mind of him who carries a weapon (in his hand), the mind of him who feasts with pleasure on the body of another (creature), has no regard for goodness" },
  { number: 254, tamil: "அருளல்ல தியாதெனிற் கொல்லாமை கோறல்\nபொருளல்லது அவ்வூன் தினல்.", transliteration: "Arulalladhu Yaadhenin Kollaamai Koral / Porulalladhu Avvoon Thinal", english: "If it be asked what is kindness and what its opposite, the answer would be preservation and destruction of life; and therefore it is not right to feed on the flesh (obtained by taking away life)" },
  { number: 255, tamil: "உண்ணாமை உள்ளது உயிர்நிலை ஊனுண்ண\nஅண்ணாத்தல் செய்யாது அளறு.", transliteration: "Unnaamai Ulladhu Uyirnilai Oonunna / Annaaththal Seyyaadhu Alaru", english: "Not to eat flesh contributes to the continuance of life; therefore if a man eat flesh, hell will not open its mouth (to let him escape out, after he has once fallen in)" },
  { number: 256, tamil: "தினற்பொருட்டால் கொல்லாது உலகெனின் யாரும்\nவிலைப்பொருட்டால் ஊன்றருவா ரில்.", transliteration: "Thinarporuttaal Kollaadhu Ulakenin Yaarum / Vilaipporuttaal Oondraruvaa Ril", english: "If the world does not destroy life for the purpose of eating, then no one would sell flesh for the sake of money" },
  { number: 257, tamil: "உண்ணாமை வேண்டும் புலாஅல் பிறிதொன்றன்\nபுண்ணது உணர்வார்ப் பெறின்.", transliteration: "Unnaamai Ventum Pulaaal Piridhondran / Punnadhu Unarvaarp Perin", english: "If men should come to know that flesh is nothing but the unclean ulcer of a body, let them abstain from eating it" },
  { number: 258, tamil: "செயிரின் தலைப்பிரிந்த காட்சியார் உண்ணார்\nஉயிரின் தலைப்பிரிந்த ஊன்.", transliteration: "Seyirin Thalaippirindha Kaatchiyaar Unnaar / Uyirin Thalaippirindha Oon", english: "The wise, who have freed themselves from mental delusion, will not eat the flesh which has been severed from an animal" },
  { number: 259, tamil: "அவிசொரிந் தாயிரம் வேட்டலின் ஒன்றன்\nஉயிர்செகுத் துண்ணாமை நன்று.", transliteration: "Avisorin Thaayiram Vettalin Ondran / Uyirsekuth Thunnaamai Nandru", english: "Not to kill and eat (the flesh of) an animal, is better than the pouring forth of ghee etc, in a thousand sacrifices" },
  { number: 260, tamil: "கொல்லான் புலாலை மறுத்தானைக் கைகூப்பி\nஎல்லா உயிருந் தொழும்.", transliteration: "Kollaan Pulaalai Maruththaanaik Kaikooppi / Ellaa Uyirun Thozhum", english: "All creatures will join their hands together, and worship him who has never taken away life, nor eaten flesh" },
  { number: 261, tamil: "உற்றநோய் நோன்றல் உயிர்க்குறுகண் செய்யாமை\nஅற்றே தவத்திற் குரு.", transliteration: "Utranoi Nondral Uyirkkurukan Seyyaamai / Atre Thavaththir Kuru", english: "The nature of religious discipline consists, in the endurance (by the ascetic) of the sufferings which it brings on himself, and in abstaining from giving pain to others" },
  { number: 262, tamil: "தவமும் தவமுடையார்க்கு ஆகும் அதனை\nஅஃதிலார் மேற்கொள் வது.", transliteration: "Thavamum Thavamutaiyaarkku Aakum Adhanai / Aqdhilaar Merkol Vadhu", english: "Austerities can only be borne, and their benefits enjoyed, by those who have practised them (in a former birth); it will be useless for those who have not done so, to attempt to practise them (now)" },
  { number: 263, tamil: "துறந்தார்க்குத் துப்புரவு வேண்டி மறந்தார்கொல்\nமற்றை யவர்கள் தவம்.", transliteration: "Thurandhaarkkuth Thuppuravu Venti Marandhaarkol / Matrai Yavarkal Thavam", english: "It is to provide food etc, for the ascetics who have abandoned (the desire of earthly possessions) that other persons have forgotten (to practise) austerity ?" },
  { number: 264, tamil: "ஒன்னார்த் தெறலும் உவந்தாரை ஆக்கலும்\nஎண்ணின் தவத்தான் வரும்.", transliteration: "Onnaarth Theralum Uvandhaarai Aakkalum / Ennin Thavaththaan Varum", english: "If (the ascetic) desire the destruction of his enemies, or the aggrandizement of his friends, it will be effected by (the power of) his austerities" },
  { number: 265, tamil: "வேண்டிய வேண்டியாங் கெய்தலால் செய்தவம்\nஈண்டு முயலப் படும்.", transliteration: "Ventiya Ventiyaang Keydhalaal Seydhavam / Eentu Muyalap Patum", english: "Religious dislipline is practised in this world, because it secures the attainment of whatever one may wish to enjoy (in the world to come)" },
  { number: 266, tamil: "தவஞ்செய்வார் தங்கருமஞ் செய்வார்மற் றல்லார்\nஅவஞ்செய்வார் ஆசையுட் பட்டு.", transliteration: "Thavanj Cheyvaar Thangarumanj Cheyvaarmar / Rallaar Avanjeyvaar Aasaiyut Pattu", english: "Those discharge their duty who perform austerities; all others accomplish their own destruction, through the entanglement of the desire (of riches and sensual pleasure)" },
  { number: 267, tamil: "சுடச்சுடரும் பொன்போல் ஒளிவிடும் துன்பஞ்\nசுடச்சுட நோற்கிற் பவர்க்கு.", transliteration: "Sutachchutarum Ponpol Olivitum Thunpanjjch / Utachchuta Norkir Pavarkku", english: "Just as gold is purified as heated in the fire, will those shine, who have endured the burning of pain (in frequent austerities)" },
  { number: 268, tamil: "தன்னுயிர் தான்அறப் பெற்றானை ஏனைய\nமன்னுயி ரெல்லாந் தொழும்.", transliteration: "Thannuyir Thaanarap Petraanai Enaiya / Mannuyi Rellaan Thozhum", english: "All other creatures will worship him who has attained the control of his own soul" },
  { number: 269, tamil: "கூற்றம் குதித்தலும் கைகூடும் நோற்றலின்\nஆற்றல் தலைப்பட் டவர்க்குல்.", transliteration: "Kootram Kudhiththalum Kaikootum Notralin / Aatral Thalaippat Tavarkkul", english: "Those who have attained the power which religious discipline confers, will be able also to pass the limit of Yama, (the God of death)" },
  { number: 270, tamil: "இலர்பல ராகிய காரணம் நோற்பார்\nசிலர்பலர் நோலா தவர்.", transliteration: "Ilarpala Raakiya Kaaranam Norpaar / Silarpalar Nolaa Thavar", english: "Because there are few who practise austerity and many who do not, there are many destitute and few rich in this world" },
  { number: 271, tamil: "வஞ்ச மனத்தான் படிற்றொழுக்கம் பூதங்கள்\nஐந்தும் அகத்தே நகும்.", transliteration: "Vanja Manaththaan Patitrozhukkam Poodhangal / Aindhum Akaththe Nakum", english: "The five elements (of his body) will laugh within him at the feigned conduct of the deceitful minded man" },
  { number: 272, tamil: "வானுயர் தோற்றம் எவன்செய்யும் தன்னெஞ்சம்\nதான்அறி குற்றப் படின்.", transliteration: "Vaanuyar Thotram Evanseyyum Thannenjam / Thaanari Kutrap Patin", english: "What avails an appearance (of sanctity) high as heaven, if his mind suffers (the indulgence) of conscious sin" },
  { number: 273, tamil: "வலியில் நிலைமையான் வல்லுருவம் பெற்றம்\nபுலியின்தோல் போர்த்துமேய்ந் தற்று.", transliteration: "Valiyil Nilaimaiyaan Valluruvam Petram / Puliyindhol Porththumeyn Thatru", english: "The assumed appearance of power, by a man who has no power (to restrain his senses and perform austerity), is like a cow feeding on grass covered with a tiger's skin" },
  { number: 274, tamil: "தவமறைந்து அல்லவை செய்தல் புதல்மறைந்து\nவேட்டுவன் புள்சிமிழ்த் தற்று.", transliteration: "Thavamaraindhu Allavai Seydhal Pudhalmaraindhu / Vettuvan Pulsimizhth Thatru", english: "He who hides himself under the mask of an ascetic and commits sins, like a sportsman who conceals himself in the thicket to catch birds" },
  { number: 275, tamil: "பற்றற்றேம் என்பார் படிற்றொழுக்கம் எற்றெற்றென்று\nஏதம் பலவுந் தரும்.", transliteration: "Patratrem Enpaar Patitrozhukkam Etretrendru / Edham Palavun Tharum", english: "The false conduct of those who say they have renounced all desire will one day bring them sorrows that will make them cry out, \"Oh! what have we done, what have we done.\"" },
  { number: 276, tamil: "நெஞ்சின் துறவார் துறந்தார்போல் வஞ்சித்து\nவாழ்வாரின் வன்கணார் இல்.", transliteration: "Nenjin Thuravaar Thurandhaarpol Vanjiththu / Vaazhvaarin Vankanaar Il", english: "Amongst living men there are none so hard-hearted as those who without to saking (desire) in their heart, falsely take the appearance of those who have forsaken (it)" },
  { number: 277, tamil: "புறங்குன்றி கண்டனைய ரேனும் அகங்குன்றி\nமுக்கிற் கரியார் உடைத்து.", transliteration: "Purangundri Kantanaiya Renum Akangundri / Mukkir Kariyaar Utaiththu", english: "(The world) contains persons whose outside appears (as fair) as the (red) berry of the Abrus, but whose inside is as black as the nose of that berry" },
  { number: 278, tamil: "மனத்தது மாசாக மாண்டார் நீராடி\nமறைந்தொழுகு மாந்தர் பலர்.", transliteration: "Manaththadhu Maasaaka Maantaar Neeraati / Maraindhozhuku Maandhar Palar", english: "There are many men of masked conduct, who perform their ablutions, and (make a show) of" },
  { number: 279, tamil: "கணைகொடிது யாழ்கோடு செவ்விதுஆங் கன்ன\nவினைபடு பாலால் கொளல்.", transliteration: "Kanaikotidhu Yaazhkotu Sevvidhuaang Kanna / Vinaipatu Paalaal Kolal", english: "As, in its use, the arrow is crooked, and the curved lute is straight, so by their deeds, (and not by their appearance) let (the uprightness or crookedness of) men be estimated" },
  { number: 280, tamil: "மழித்தலும் நீட்டலும் வேண்டா உலகம்\nபழித்தது ஒழித்து விடின்.", transliteration: "Mazhiththalum Neettalum Ventaa Ulakam / Pazhiththadhu Ozhiththu Vitin", english: "There is no need of a shaven crown, nor of tangled hair, if a man abstain from those deeds which the wise have condemned" },
  { number: 281, tamil: "எள்ளாமை வேண்டுவான் என்பான் எனைத்தொன்றும்\nகள்ளாமை காக்கதன் நெஞ்சு.", transliteration: "Ellaamai Ventuvaan Enpaan Enaiththondrum / Kallaamai Kaakkadhan Nenju", english: "Let him, who desires not to be despised, keep his mind from (the desire of) defrauding another of the smallest thing" },
  { number: 282, tamil: "உள்ளத்தால் உள்ளலும் தீதே பிறன்பொருளைக்\nகள்ளத்தால் கள்வேம் எனல்.", transliteration: "Ullaththaal Ullalum Theedhe Piranporulaik / Kallaththaal Kalvem Enal", english: "Even the thought (of sin) is sin; think not then of crafiily stealing the property of another" },
  { number: 283, tamil: "களவினால் ஆகிய ஆக்கம் அளவிறந்து\nஆவது போலக் கெடும்.", transliteration: "Kalavinaal Aakiya Aakkam Alavirandhu / Aavadhu Polak Ketum", english: "The property, which is acquired by fraud, will entirely perish, even while it seems to increase" },
  { number: 284, tamil: "களவின்கண் கன்றிய காதல் விளைவின்கண்\nவீயா விழுமம் தரும்.", transliteration: "Kalavinkan Kandriya Kaadhal Vilaivinkan / Veeyaa Vizhumam Tharum", english: "The eager desire of defrauding others will, when it brings forth its fruit, produce undying sorrow" },
  { number: 285, tamil: "அருள்கருதி அன்புடைய ராதல் பொருள்கருதிப்\nபொச்சாப்புப் பார்ப்பார்கண் இல்.", transliteration: "Arulkarudhi Anputaiya Raadhal Porulkarudhip / Pochchaappup Paarppaarkan Il", english: "The study of kindness and the exercise of benevolence is not with those who watch for another's forgetfulness, though desire of his property" },
  { number: 286, tamil: "அளவின்கண் நின்றொழுகல் ஆற்றார் களவின்கண்\nகன்றிய காத லவர்.", transliteration: "Alavinkan Nindrozhukal Aatraar Kalavinkan / Kandriya Kaadha Lavar", english: "They cannot walk steadfastly, according to rule, who eagerly desire to defraud others" },
  { number: 287, tamil: "களவென்னும் காரறி வாண்மை அளவென்னும்\nஆற்றல் புரிந்தார்கண்ட இல்.", transliteration: "Kalavennum Kaarari Vaanmai Alavennum / Aatral Purindhaarkanta Il", english: "That black-knowledge which is called fraud, is not in those who desire that greatness which is called rectitude" },
  { number: 288, tamil: "அளவறிந்தார் நெஞ்சத் தறம்போல நிற்கும்\nகளவறிந்தார் நெஞ்சில் கரவு.", transliteration: "Alavarindhaar Nenjath Tharampola Nirkum / Kalavarindhaar Nenjil Karavu", english: "Deceit dwells in the mind of those who are conversant with fraud, even as virtue in the minds of those who are conversant with rectitude" },
  { number: 289, tamil: "அளவல்ல செய்தாங்கே வீவர் களவல்ல\nமற்றைய தேற்றா தவர்.", transliteration: "Alavalla Seydhaange Veevar Kalavalla / Matraiya Thetraa Thavar", english: "Those, who are acquainted with nothing but fraud, will perish in the very commission of transgression" },
  { number: 290, tamil: "கள்வார்க்குத் தள்ளும் உயிர்நிலை கள்வார்க்குத்\nதள்ளாது புத்தே ளுளகு.", transliteration: "Kalvaarkkuth Thallum Uyirnilai Kalvaarkkuth / Thallaadhu Puththe Lulaku", english: "Even their body will fail the fraudulent; but even the world of the gods will not fail those who are free from fraud" },
  { number: 291, tamil: "வாய்மை எனப்படுவது யாதெனின் யாதொன்றும்\nதீமை இலாத சொலல்.", transliteration: "Vaaimai Enappatuvadhu Yaadhenin Yaadhondrum / Theemai Ilaadha Solal", english: "Truth is the speaking of such words as are free from the least degree of evil (to others)" },
  { number: 292, tamil: "பொய்மையும் வாய்மை யிடத்த புரைதீர்ந்த\nநன்மை பயக்கும் எனின்.", transliteration: "Poimaiyum Vaaimai Yitaththa Puraidheerndha / Nanmai Payakkum Enin", english: "Even falsehood has the nature of truth, if it confer a benefit that is free from fault" },
  { number: 293, tamil: "தன்நெஞ் சறிவது பொய்யற்க பொய்த்தபின்\nதன்நெஞ்சே தன்னைச் சுடும்.", transliteration: "Thannenj Charivadhu Poiyarka Poiththapin / Thannenje Thannaich Chutum", english: "Let not a man knowingly tell a lie; for after he has told the lie, his mind will burn him (with the memory of his guilt)" },
  { number: 294, tamil: "உள்ளத்தாற் பொய்யா தொழுகின் உலகத்தார்\nஉள்ளத்து ளெல்லாம் உளன்.", transliteration: "Ullaththaar Poiyaa Thozhukin Ulakaththaar / Ullaththu Lellaam Ulan", english: "He who, in his conduct, preserves a mind free from deceit, will dwell in the minds of all men" },
  { number: 295, tamil: "மனத்தொடு வாய்மை மொழியின் தவத்தொடு\nதானஞ்செய் வாரின் தலை.", transliteration: "Manaththotu Vaaimai Mozhiyin Thavaththotu / Thaananjey Vaarin Thalai", english: "He, who speaks truth with all his heart, is superior to those who make gifts and practise austerities" },
  { number: 296, tamil: "பொய்யாமை அன்ன புகழில்லை எய்யாமை\nஎல்லா அறமுந் தரும்.", transliteration: "Poiyaamai Anna Pukazhillai Eyyaamai / Ellaa Aramun Tharum", english: "There is no praise like the praise of never uttering a falsehood: without causing any suffering, it will lead to every virtue" },
  { number: 297, tamil: "பொய்யாமை பொய்யாமை ஆற்றின் அறம்பிற\nசெய்யாமை செய்யாமை நன்று.", transliteration: "Poiyaamai Poiyaamai Aatrin Arampira / Seyyaamai Seyyaamai Nandru", english: "If a man has the power to abstain from falsehood, it will be well with him, even though he practise no other virtue" },
  { number: 298, tamil: "புறள்தூய்மை நீரான் அமையும் அகந்தூய்மை\nவாய்மையால் காணப் படும்.", transliteration: "Puraldhooimai Neeraan Amaiyum Akandhooimai / Vaaimaiyaal Kaanap Patum", english: "Purity of body is produced by water and purity of mind by truthfulness" },
  { number: 299, tamil: "எல்லா விளக்கும் விளக்கல்ல சான்றோர்க்குப்\nபொய்யா விளக்கே விளக்கு.", transliteration: "Ellaa Vilakkum Vilakkalla Saandrorkkup / Poiyaa Vilakke Vilakku", english: "All lamps of nature are not lamps; the lamp of truth is the lamp of the wise" },
  { number: 300, tamil: "யாமெய்யாக் கண்டவற்றுள் இல்லை எனைத்தொன்றும்\nவாய்மையின் நல்ல பிற.", transliteration: "Yaameyyaak Kantavatrul Illai Enaiththondrum / Vaaimaiyin Nalla Pira", english: "Amidst all that we have seen (described) as real (excellence), there is nothing so good as truthfulness" },
  { number: 301, tamil: "செல்லிடத்துக் காப்பான் சினங்காப்பான் அல்லிடத்துக்\nகாக்கின்என் காவாக்கால் என்?", transliteration: "Sellitaththuk Kaappaan Sinangaappaan Allitaththuk / Kaakkinen Kaavaakkaal En?", english: "He restrains his anger who restrains it when it can injure; when it cannot injure, what does it matter whether he restrain it, or not ?" },
  { number: 302, tamil: "செல்லா இடத்துச் சினந்தீது செல்லிடத்தும்\nஇல்அதனின் தீய பிற.", transliteration: "Sellaa Itaththuch Chinandheedhu Sellitaththum / Iladhanin Theeya Pira", english: "Anger is bad, even when it cannot injure; when it can injure; there is no greater evil" },
  { number: 303, tamil: "மறத்தல் வெகுளியை யார்மாட்டும் தீய\nபிறத்தல் அதனான் வரும்.", transliteration: "Maraththal Vekuliyai Yaarmaattum Theeya / Piraththal Adhanaan Varum", english: "Forget anger towards every one, as fountains of evil spring from it" },
  { number: 304, tamil: "நகையும் உவகையும் கொல்லும் சினத்தின்\nபகையும் உளவோ பிற.", transliteration: "Nakaiyum Uvakaiyum Kollum Sinaththin / Pakaiyum Ulavo Pira", english: "What other foe to man works such annoy?" },
  { number: 305, tamil: "தன்னைத்தான் காக்கின் சினங்காக்க காவாக்கால்\nதன்னையே கொல்லுஞ் சினம்.", transliteration: "Thannaiththaan Kaakkin Sinangaakka Kaavaakkaal / Thannaiye Kollunj Chinam", english: "If a man would guard himself, let him guard against anger; if he do not guard it, anger will kill him" },
  { number: 306, tamil: "சினமென்னும் சேர்ந்தாரைக் கொல்லி இனமென்னும்\nஏமப் புணையைச் சுடும்.", transliteration: "Sinamennum Serndhaaraik Kolli Inamennum / Emap Punaiyaich Chutum", english: "The fire of anger will burn up even the pleasant raft of friendship" },
  { number: 307, tamil: "சினத்தைப் பொருளென்று கொண்டவன் கேடு\nநிலத்தறைந்தான் கைபிழையா தற்று.", transliteration: "Sinaththaip Porulendru Kontavan Ketu / Nilaththaraindhaan Kaipizhaiyaa Thatru", english: "Destruction will come upon him who ragards anger as a good thing, as surely as the hand of him who strikes the ground will not fail" },
  { number: 308, tamil: "இணர்எரி தோய்வன்ன இன்னா செயினும்\nபுணரின் வெகுளாமை நன்று.", transliteration: "Inareri Thoivanna Innaa Seyinum / Punarin Vekulaamai Nandru", english: "Though one commit things against you as painful (to bear) as if a bundle of fire had been thrust upon you, it will be well, to refrain, if possible, from anger" },
  { number: 309, tamil: "உள்ளிய தெல்லாம் உடனெய்தும் உள்ளத்தால்\nஉள்ளான் வெகுளி எனின்.", transliteration: "Ulliya Thellaam Utaneydhum Ullaththaal / Ullaan Vekuli Enin", english: "If a man never indulges anger in his heart, he will at once obtain whatever he has thought of" },
  { number: 310, tamil: "இறந்தார் இறந்தார் அனையர் சினத்தைத்\nதுறந்தார் துறந்தார் துணை.", transliteration: "Irandhaar Irandhaar Anaiyar Sinaththaith / Thurandhaar Thurandhaar Thunai", english: "Those, who give way to excessive anger, are no better than dead men; but those, who are freed from it, are equal to those who are freed (from death)" },
  { number: 311, tamil: "சிறப்பீனும் செல்வம் பெறினும் பிறர்க்குஇன்னா\nசெய்யாமை மாசற்றார் கோள்.", transliteration: "Sirappeenum Selvam Perinum Pirarkku / Innaa Seyyaamai Maasatraar Kol", english: "It is the determination of the spotless not to cause sorrow to others, although they could (by so causing) obtain the wealth which confers greatness" },
  { number: 312, tamil: "கறுத்துஇன்னா செய்தவக் கண்ணும் மறுத்தின்னா\nசெய்யாமை மாசற்றார் கோள்.", transliteration: "Karuththuinnaa Seydhavak Kannum Maruththinnaa / Seyyaamai Maasatraar Kol", english: "It is the determination of the spotless not to do evil, even in return, to those who have cherished enmity and done them evil" },
  { number: 313, tamil: "செய்யாமல் செற்றார்க்கும் இன்னாத செய்தபின்\nஉய்யா விழுமந் தரும்.", transliteration: "Seyyaamal Setraarkkum Innaadha Seydhapin / Uyyaa Vizhuman Tharum", english: "In an ascetic inflict suffering even on those who hate him, when he has not done them any evil, it will afterwards give him irretrievable sorrow" },
  { number: 314, tamil: "இன்னாசெய் தாரை ஒறுத்தல் அவர்நாண\nநன்னயஞ் செய்து விடல்.", transliteration: "Innaasey Thaarai Oruththal Avarnaana / Nannayanj Cheydhu Vital", english: "The (proper) punishment to those who have done evil (to you), is to put them to shame by showing them kindness, in return and to forget both the evil and the good done on both sides" },
  { number: 315, tamil: "அறிவினான் ஆகுவ துண்டோ பிறிதின்நோய்\nதந்நோய்போல் போற்றாக் கடை.", transliteration: "Arivinaan Aakuva Thunto Piridhinnoi / Thannoipol Potraak Katai", english: "What benefit has he derived from his knowledge, who does not endeavour to keep off pain from another as much as from himself ?" },
  { number: 316, tamil: "இன்னா எனத்தான் உணர்ந்தவை துன்னாமை\nவேண்டும் பிறன்கண் செயல்.", transliteration: "Innaa Enaththaan Unarndhavai Thunnaamai / Ventum Pirankan Seyal", english: "Let not a man consent to do those things to another which, he knows, will cause sorrow" },
  { number: 317, tamil: "எனைத்தானும் எஞ்ஞான்றும் யார்க்கும் மனத்தானாம்\nமாணாசெய் யாமை தலை.", transliteration: "Enaiththaanum Egngnaandrum Yaarkkum Manaththaanaam / Maanaasey Yaamai Thalai", english: "It is the chief of all virtues not knowingly to do any person evil, even in the lowest degree, and at any time" },
  { number: 318, tamil: "தன்னுயிர்ககு ஏன்னாமை தானறிவான் என்கொலோ\nமன்னுயிர்க்கு இன்னா செயல்.", transliteration: "Thannuyirkaku Ennaamai Thaanarivaan Enkolo / Mannuyirkku Innaa Seyal", english: "Why does a man inflict upon other creatures those sufferings, which he has found by experience are sufferings to himself ?" },
  { number: 319, tamil: "பிறர்க்கின்னா முற்பகல் செய்யின் தமக்குஇன்னா\nபிற்பகல் தாமே வரும்.", transliteration: "Pirarkkinnaa Murpakal Seyyin Thamakku / Innaa Pirpakal Thaame Varum", english: "If a man inflict sorrow upon others in the morning, it will come upon him unsought in the very evening" },
  { number: 320, tamil: "நோயெல்லாம் நோய்செய்தார் மேலவாம் நோய்செய்யார்\nநோயின்மை வேண்டு பவர்.", transliteration: "Noyellaam Noiseydhaar Melavaam Noiseyyaar / Noyinmai Ventu Pavar", english: "Sorrow will come upon those who cause pain to others; therfore those, who desire to be free from sorrow, give no pain to others" },
  { number: 321, tamil: "அறவினை யாதெனின் கொல்லாமை கோறல்\nபிறவினை எல்லாந் தரும்.", transliteration: "Aravinai Yaadhenin Kollaamai Koral / Piravinai Ellaan Tharum", english: "Never to destroy life is the sum of all virtuous conduct The destruction of life leads to every evil" },
  { number: 322, tamil: "பகுத்துண்டு பல்லுயிர் ஓம்புதல் நூலோர்\nதொகுத்தவற்றுள் எல்லாந் தலை.", transliteration: "Pakuththuntu Palluyir Ompudhal Noolor / Thokuththavatrul Ellaan Thalai", english: "The chief of all (the virtues) which authors have summed up, is the partaking of food that has been shared with others, and the preservation of the mainfold life of other creatures" },
  { number: 323, tamil: "ஒன்றாக நல்லது கொல்லாமை மற்றதன்\nபின்சாரப் பொய்யாமை நன்று.", transliteration: "Ondraaka Nalladhu Kollaamai Matradhan / Pinsaarap Poiyaamai Nandru", english: "Not to destroy life is an incomparably (great) good next to it in goodness ranks freedom from falsehood" },
  { number: 324, tamil: "நல்லாறு எனப்படுவது யாதெனின் யாதொன்றும்\nகொல்லாமை சூழும் நெறி.", transliteration: "Nallaaru Enappatuvadhu Yaadhenin Yaadhondrum / Kollaamai Soozhum Neri", english: "Good path is that which considers how it may avoid killing any creature" },
  { number: 325, tamil: "நிலைஅஞ்சி நீத்தாருள் எல்லாம் கொலைஅஞ்சிக்\nகொல்லாமை சூழ்வான் தலை.", transliteration: "Nilaianji Neeththaarul Ellaam Kolaianjik / Kollaamai Soozhvaan Thalai", english: "Of all those who, fearing the permanence of earthly births, have abandoned desire, he is the chief who, fearing (the guilt of) murder, considers how he may avoid the destruction of life" },
  { number: 326, tamil: "கொல்லாமை மேற்கொண் டொழுகுவான் வாழ்நாள்மேல்\nசெல்லாது உயிருண்ணுங் கூற்று.", transliteration: "Kollaamai Merkon Tozhukuvaan Vaazhnaalmel / Sellaadhu Uyirunnung Kootru", english: "Yama, the destroyer of life, will not attack the life of him, who acts under the determination of never destroying life" },
  { number: 327, tamil: "தன்னுயிர் நீப்பினும் செய்யற்க தான்பிறிது\nஇன்னுயிர் நீக்கும் வினை.", transliteration: "Thannuyir Neeppinum Seyyarka Thaanpiridhu / Innuyir Neekkum Vinai", english: "Let no one do that which would destroy the life of another, although he should by so doing, lose his own life" },
  { number: 328, tamil: "நன்றாகும் ஆக்கம் பெரிதெனினும் சான்றோர்க்குக்\nகொன்றாகும் ஆக்கங் கடை.", transliteration: "Nandraakum Aakkam Peridheninum Saandrorkkuk / Kondraakum Aakkang Katai", english: "The advantage which might flow from destroying life in sacrifice, is dishonourable to the wise (who renounced the world), even although it should be said to be productive of great good" },
  { number: 329, tamil: "கொலைவினைய ராகிய மாக்கள் புலைவினையர்\nபுன்மை தெரிவா ரகத்து.", transliteration: "Kolaivinaiya Raakiya Maakkal Pulaivinaiyar / Punmai Therivaa Rakaththu", english: "To minds of them who what is vileness know" },
  { number: 330, tamil: "உயிருடம்பின் நீக்கியா ரென்ப செயிருடம்பின்\nசெல்லாத்தீ வாழ்க்கை யவர்.", transliteration: "Uyir Utampin Neekkiyaar Enpa / Seyir Utampin Sellaaththee Vaazhkkai", english: "(The wise) will say that men of diseased bodies, who live in degradation and in poverty, are those who separated the life from the body of animals (in a former birth)" },
  { number: 331, tamil: "நில்லாத வற்றை நிலையின என்றுணரும்\nபுல்லறி வாண்மை கடை.", transliteration: "Nillaadha Vatrai Nilaiyina Endrunarum / Pullari Vaanmai Katai", english: "That ignorance which considers those things to be stable which are not so, is dishonourable (to the wise)" },
  { number: 332, tamil: "கூத்தாட்டு அவைக்குழாத் தற்றே பெருஞ்செல்வம்\nபோக்கும் அதுவிளிந் தற்று.", transliteration: "Kooththaattu Avaik Kuzhaath Thatre / Perunjelvam Pokkum Adhuvilin Thatru", english: "The acquisition of wealth is like the gathering together of an assembly for a theatre; its expenditure is like the breaking up of that assembly" },
  { number: 333, tamil: "அற்கா இயல்பிற்றுச் செல்வம் அதுபெற்றால்\nஅற்குப ஆங்கே செயல்.", transliteration: "Arkaa Iyalpitruch Chelvam Adhupetraal / Arkupa Aange Seyal", english: "Wealth is perishable; let those who obtain it immediately practise those (virtues) which are imperishable" },
  { number: 334, tamil: "நாளென ஒன்றுபோற் காட்டி உயிர்ஈரும்\nவாளது உணர்வார்ப் பெறின்.", transliteration: "Naalena Ondrupor Kaatti Uyir / Eerum Vaaladhu Unarvaarp Perin", english: "Time, which shows itself (to the ignorant) as if it were something (real) is in the estimation of the wise (only) a saw which cuts down life" },
  { number: 335, tamil: "நாச்செற்று விக்குள்மேல் வாராமுன் நல்வினை\nமேற்சென்று செய்யப் படும்", transliteration: "Naachchetru Vikkulmel Vaaraamun Nalvinai / Mersendru Seyyap Patum", english: "Let virtuous deeds be done quickly, before the hiccup comes making the tongue silent" },
  { number: 336, tamil: "நெருநல் உளனொருவன் இன்றில்லை என்னும்\nபெருமை உடைத்துஇவ் வுலகு.", transliteration: "Nerunal Ulanoruvan Indrillai Ennum / Perumai Utaiththuiv Vulaku", english: "This world possesses the greatness that one who yesterday was is not today" },
  { number: 337, tamil: "ஒருபொழுதும் வாழ்வது அறியார் கருதுப\nகோடியும் அல்ல பல.", transliteration: "Orupozhudhum Vaazhvadhu Ariyaar Karudhupa / Kotiyum Alla Pala", english: "Innumerable are the thoughts which occupy the mind of (the unwise), who know not that they shall live another moment" },
  { number: 338, tamil: "குடம்பை தனித்துஒழியப் புள்பறந் தற்றே\nஉடம்பொடு உயிரிடை நட்பு.", transliteration: "Kutampai Thaniththu Ozhiyap Pulparan / Thatre Utampotu Uyiritai Natpu", english: "The love of the soul to the body is like (the love of) a bird to its egg which it flies away from and leaves empty" },
  { number: 339, tamil: "உறங்கு வதுபோலுஞ் சாக்காடு உறங்கி\nவிழிப்பது போலும் பிறப்பு.", transliteration: "Urangu Vadhupolunj Chaakkaatu Urangi / Vizhippadhu Polum Pirappu", english: "Death is like sleep; birth is like awaking from it" },
  { number: 340, tamil: "புக்கில் அமைந்தின்று கொல்லோ உடம்பினுள்\nதுச்சில் இருந்த உயிர்க்கு.", transliteration: "Pukkil Amaindhindru Kollo Utampinul / Thuchchil Irundha Uyirkku", english: "It seems as if the soul, which takes a temporary shelter in a body, had not attained a home" },
  { number: 341, tamil: "யாதனின் யாதனின் நீங்கியான் நோதல்\nஅதனின் அதனின் இலன்.", transliteration: "Yaadhanin Yaadhanin Neengiyaan Nodhal / Adhanin Adhanin Ilan", english: "Whatever thing, a man has renounced, by that thing; he cannot suffer pain" },
  { number: 342, tamil: "வேண்டின்உண் டாகத் துறக்க துறந்தபின்\nஈண்டுஇயற் பால பல.", transliteration: "Ventin Un Taakath Thurakka / Thurandhapin Eentuiyar Paala Pala", english: "After a man has renounced (all things), there will still be many things in this world (which he may enjoy); if he should desire them, let him, while it is time abandon (the world)" },
  { number: 343, tamil: "அடல்வேண்டும் ஐந்தன் புலத்தை விடல்வேண்டும்\nவேண்டிய வெல்லாம் ஒருங்கு.", transliteration: "Atalventum Aindhan Pulaththai Vitalventum / Ventiya Vellaam Orungu", english: "Let the five senses be destroyed; and at the same time, let everything be abandoned that (the ascetic) has (formerly) desired" },
  { number: 344, tamil: "இயல்பாகும் நோன்பிற்கொன்று இன்மை உடைமை\nமயலாகும் மற்றும் பெயர்த்து.", transliteration: "Iyalpaakum Nonpirkondru Inmai Utaimai / Mayalaakum Matrum Peyarththu", english: "To be altogether destitute is the proper condition of those who perform austerities; if they possess anything, it will change (their resolution) and bring them back to their confused state" },
  { number: 345, tamil: "மற்றும் தொடர்ப்பாடு எவன்கொல் பிறப்பறுக்கல்\nஉற்றார்க்கு உடம்பும் மிகை.", transliteration: "Matrum Thotarppaatu Evankol Pirapparukkal / Utraarkku Utampum Mikai", english: "What means the addition of other things those who are attempting to cut off (future) births, when even their body is too much (for them)" },
  { number: 346, tamil: "யான்எனது என்னும் செருக்குஅறுப்பான் வானோர்க்கு\nஉயர்ந்த உலகம் புகும்.", transliteration: "Yaan Enadhu Ennum Serukku / Aruppaan Vaanorkku Uyarndha Ulakam", english: "Shall enter realms above the powers divine" },
  { number: 347, tamil: "பற்றி விடாஅ இடும்பைகள் பற்றினைப்\nபற்றி விடாஅ தவர் க்கு.", transliteration: "Patri Vitaaa Itumpaikal Patrinaip / Patri Vitaaa Thavarkku", english: "Sorrows will never let go their hold of those who give not up their hold of desire" },
  { number: 348, tamil: "தலைப்பட்டார் தீரத் துறந்தார் மயங்கி\nவலைப்பட்டார் மற்றை யவர்.", transliteration: "Thalaippattaar Theerath Thurandhaar Mayangi / Valaippattaar Matrai Yavar", english: "Those who have entirely renounced (all things and all desire) have obtained (absorption into God); all others wander in confusion, entangled in the net of (many) births" },
  { number: 349, tamil: "பற்றற்ற கண்ணே பிறப்பறுக்கும் மற்று\nநிலையாமை காணப் படும்.", transliteration: "Patratra Kanne Pirapparukkum Matru / Nilaiyaamai Kaanap Patum", english: "At the moment in which desire has been abandoned, (other) births will be cut off; when that has not been done, instability will be seen" },
  { number: 350, tamil: "பற்றுக பற்றற்றான் பற்றினை அப்பற்றைப்\nபற்றுக பற்று விடற்கு.", transliteration: "Patruka Patratraan Patrinai Appatraip / Patruka Patru Vitarku", english: "Desire the desire of Him who is without desire; in order to renounce desire, desire that desire" },
  { number: 351, tamil: "பொருளல்ல வற்றைப் பொருளென்று உணரும்\nமருளானாம் மாணாப் பிறப்பு.", transliteration: "Porulalla Vatraip Porulendru Unarum / Marulaanaam Maanaap Pirappu", english: "Inglorious births are produced by the confusion (of mind) which considers those things to be real which are not real" },
  { number: 352, tamil: "இருள்நீங்கி இன்பம் பயக்கும் மருள்நீங்கி\nமாசறு காட்சி யவர்க்கு.", transliteration: "Irulneengi Inpam Payakkum Marulneengi / Maasaru Kaatchi Yavarkku", english: "A clear, undimmed vision of things will deliver its possessors from the darkness of future births, and confer the felicity (of heaven)" },
  { number: 353, tamil: "ஐயத்தின் நீங்கித் தெளிந்தார்க்கு வையத்தின்\nவானம் நணிய துடைத்து.", transliteration: "Aiyaththin Neengith Thelindhaarkku Vaiyaththin / Vaanam Naniya Thutaiththu", english: "Heaven is nearer than earth to those men of purified minds who are freed from from doubt" },
  { number: 354, tamil: "ஐயுணர்வு எய்தியக் கண்ணும் பயமின்றே\nமெய்யுணர்வு இல்லா தவர்க்கு.", transliteration: "Aiyunarvu Eydhiyak Kannum Payamindre / Meyyunarvu Illaa Thavarkku", english: "Even those who have all the knowledge which can be attained by the five senses, will derive no benefit from it, if they are without a knowledge of the true nature of things" },
  { number: 355, tamil: "எப்பொருள் எத்தன்மைத் தாயினும் அப்பொருள்\nமெய்ப்பொருள் காண்பது அறிவு.", transliteration: "Epporul Eththanmaith Thaayinum Apporul / Meypporul Kaanpadhu Arivu", english: "(True) knowledge is the perception concerning every thing of whatever kind, that that thing is the true thing" },
  { number: 356, tamil: "கற்றீண்டு மெய்ப்பொருள் கண்டார் தலைப்படுவர்\nமற்றீண்டு வாரா நெறி.", transliteration: "Katreentu Meypporul Kantaar Thalaippatuvar / Matreentu Vaaraa Neri", english: "They, who in this birth have learned to know the True Being, enter the road which returns not into this world" },
  { number: 357, tamil: "ஓர்த்துள்ளம் உள்ளது உணரின் ஒருதலையாப்\nபேர்த்துள்ள வேண்டா பிறப்பு.", transliteration: "Orththullam Ulladhu Unarin Orudhalaiyaap / Perththulla Ventaa Pirappu", english: "Let it not be thought that there is another birth for him whose mind having thoroughly considered (all it has been taught) has known the True Being" },
  { number: 358, tamil: "பிறப்பென்னும் பேதைமை நீங்கச் சிறப்பென்னும்\nசெம்பொருள் காண்பது அறிவு.", transliteration: "Pirappennum Pedhaimai Neengach Chirappennum / Semporul Kaanpadhu Arivu", english: "True knowledge consists in the removal of ignorance; which is (the cause of) births, and the perception of the True Being who is (the bestower of) heaven" },
  { number: 359, tamil: "சார்புணர்ந்து சார்பு கெடஒழுகின் மற்றழித்துச்\nசார்தரா சார்தரு நோய்.", transliteration: "Saarpunarndhu Saarpu Ketaozhukin Matrazhiththuch / Chaardharaa Saardharu Noi", english: "He who so lives as to know Him who is the support of all things and abandon all desire, will be freed from the evils which would otherwise cleave to him and destroy (his efforts after absorption)" },
  { number: 360, tamil: "காமம் வெகுளி மயக்கம் இவ்மூன்றன்\nநாமம் கெடக்கெடும் நோய்.", transliteration: "Kaamam Vekuli Mayakkam Ivaimundran / Naamam Ketakketum Noi", english: "If the very names of these three things, desire, anger, and confusion of mind, be destroyed, then will also perish evils (which flow from them)" },
  { number: 361, tamil: "அவாஎன்ப எல்லா உயிர்க்கும் எஞ்ஞான்றும்\nதவாஅப் பிறப்பீனும் வித்து.", transliteration: "Avaaenpa Ellaa Uyirkkum Enj / Gnaandrum Thavaaap Pirappeenum Viththu", english: "(The wise) say that the seed, which produces unceasing births, at all times, to all creatures, is desire" },
  { number: 362, tamil: "வேண்டுங்கால் வேண்டும் பிறவாமை மற்றது\nவேண்டாமை வேண்ட வரும்.", transliteration: "Ventungaal Ventum Piravaamai Matradhu / Ventaamai Venta Varum", english: "If anything be desired, freedom from births should be desired; that (freedom from births) will be attained by desiring to be without desire" },
  { number: 363, tamil: "வேண்டாமை அன்ன விழுச்செல்வம் ஈண்டில்லை\nஆண்டும் அஃதொப்பது இல்.", transliteration: "Ventaamai Anna Vizhuchchelvam Eentillai / Aantum Aqdhoppadhu Il", english: "There is in this world no excellence equal to freedom from desire; and even in that world, there is nothing like it" },
  { number: 364, tamil: "தூஉய்மை என்பது அவாவின்மை மற்றது\nவாஅய்மை வேண்ட வரும்.", transliteration: "Thoouymai Enpadhu Avaavinmai Matradhu / Vaaaimai Venta Varum", english: "Purity (of mind) consists in freedom from desire; and that (freedom from desire) is the fruit of the love of truth" },
  { number: 365, tamil: "அற்றவர் என்பார் அவாஅற்றார் மற்றையார்\nஅற்றாக அற்றது இலர்.", transliteration: "Atravar Enpaar Avaaatraar Matraiyaar / Atraaka Atradhu Ilar", english: "They are said to be free (from future birth) who are freed from desire; all others (who, whatever else they may be free from, are not freed from desire) are not thus free" },
  { number: 366, tamil: "அஞ்சுவ தோரும் அறனே ஒருவனை\nவஞ்சிப்ப தோரும் அவா.", transliteration: "Anjuva Thorum Arane Oruvanai / Vanjippa Thorum Avaa", english: "It is the chief duty of (an ascetic) to watch against desire with (jealous) fear; for it has power to deceive (and destroy) him" },
  { number: 367, tamil: "அவாவினை ஆற்ற அறுப்பின் தவாவினை\nதான்வேண்டு மாற்றான் வரும்.", transliteration: "Avaavinai Aatra Aruppin Thavaavinai / Thaanventu Maatraan Varum", english: "If a man thoroughly cut off all desire, the deeds, which confer immortality, will come to him, in the path in which he seeks them" },
  { number: 368, tamil: "அவாஇல்லார்க் கில்லாகுந் துன்பம் அஃதுண்டேல்\nதவாஅது மேன்மேல் வரும்.", transliteration: "Avaaillaark Killaakun Thunpam Aqdhuntel / Thavaaadhu Menmel Varum", english: "There is no sorrow to those who are without desire; but where that is, (sorrow) will incessantly come, more and more" },
  { number: 369, tamil: "இன்பம் இடையறா தீண்டும் அவாவென்னும்\nதுன்பத்துள் துன்பங் கெடின்.", transliteration: "Inpam Itaiyaraa Theentum Avaavennum / Thunpaththul Thunpang Ketin", english: "Even while in this body, joy will never depart (from the mind, in which) desire, that sorrow of sorrows, has been destroyed" },
  { number: 370, tamil: "ஆரா இயற்கை அவாநீப்பின் அந்நிலையே\nபேரா இயற்கை தரும்.", transliteration: "Aaraa Iyarkai Avaaneeppin Annilaiye / Peraa Iyarkai Tharum", english: "The removal of desire, whose nature it is never to be satisfied, will immediately confer a nature that can never be changed" },
  { number: 371, tamil: "ஆகூழால் தோன்றும் அசைவின்மை கைப்பொருள்\nபோகூழால் தோன்றும் மடி.", transliteration: "Aakoozhaal Thondrum Asaivinmai Kaipporul / Pokoozhaal Thondrum Mati", english: "Perseverance comes from a prosperous fate, and idleness from an adverse fate" },
  { number: 372, tamil: "பேதைப் படுக்கும் இழவூழ் அறிவகற்றும்\nஆகலூழ் உற்றக் கடை.", transliteration: "Pedhaip Patukkum Izhavoozh Arivakatrum / Aakaloozh Utrak Katai", english: "An adverse fate produces folly, and a prosperous fate produces enlarged knowledge" },
  { number: 373, tamil: "நுண்ணிய நூல்பல கற்பினும் மற்றுந்தன்\nஉண்மை யறிவே மிகும்.", transliteration: "Nunniya Noolpala Karpinum Matrundhan / Unmai Yarive Mikum", english: "Although (a man) may study the most polished treatises, the knowledge which fate has decreed to him will still prevail" },
  { number: 374, tamil: "இருவேறு உலகத்து இயற்கை திருவேறு\nதெள்ளிய ராதலும் வேறு.", transliteration: "Iruveru Ulakaththu Iyarkai Thiruveru / Thelliya Raadhalum Veru", english: "There are (through fate) two different natures in the world, hence the difference (observable in men) in (their acquisition of) wealth, and in their attainment of knowledge" },
  { number: 375, tamil: "நல்லவை எல்லாஅந் தீயவாம் தீயவும்\nநல்லவாம் செல்வம் செயற்கு.", transliteration: "Nallavai Ellaaan Theeyavaam Theeyavum / Nallavaam Selvam Seyarku", english: "In the acquisition of property, every thing favourable becomes unfavourable, and (on the other hand) everything unfavourable becomes favourable, (through the power of fate)" },
  { number: 376, tamil: "பரியினும் ஆகாவாம் பாலல்ல உய்த்துச்\nசொரியினும் போகா தம.", transliteration: "Pariyinum Aakaavaam Paalalla Uyththuch / Choriyinum Pokaa Thama", english: "Whatever is not conferred by fate cannot be preserved although it be guarded with most painful care; and that, which fate has made his, cannot be lost, although one should even take it and throw it away" },
  { number: 377, tamil: "வகுத்தான் வகுத்த வகையல்லால் கோடி\nதொகுத்தார்க்கு துய்த்தல் அரிது.", transliteration: "Vakuththaan Vakuththa Vakaiyallaal Koti / Thokuththaarkku Thuyththal Aridhu", english: "Even those who gather together millions will only enjoy them, as it has been determined by the disposer (of all things)" },
  { number: 378, tamil: "துறப்பார்மன் துப்புர வில்லார் உறற்பால\nஊட்டா கழியு மெனின்.", transliteration: "Thurappaarman Thuppura Villaar Urarpaala / Oottaa Kazhiyu Menin", english: "The destitute will renounce desire (and become ascetics), if (fate) do not make them suffer the hindrances to which they are liable, and they pass away" },
  { number: 379, tamil: "நன்றாங்கால் நல்லவாக் காண்பவர் அன்றாங்கால்\nஅல்லற் படுவ தெவன்?", transliteration: "Nandraangaal Nallavaak Kaanpavar Andraangaal / Allar Patuva Thevan?", english: "How is it that those, who are pleased with good fortune, trouble themselves when evil comes, (since both are equally the decree of fate) ?" },
  { number: 380, tamil: "ஊழிற் பெருவலி யாவுள மற்றொன்று\nசூழினுந் தான்முந் துறும்.", transliteration: "Oozhir Peruvali Yaavula Matrondru / Soozhinun Thaanmun Thurum", english: "What is stronger than fate ? If we think of an expedient (to avert it), it will itself be with us before (the thought)" },
  { number: 381, tamil: "படைகுடி கூழ்அமைச்சு நட்பரண் ஆறும்\nஉடையான் அரசருள் ஏறு.", transliteration: "Pataikuti Koozhamaichchu Natparan Aarum / Utaiyaan Arasarul Eru", english: "He who possesses these six things, an army, a people, wealth, ministers, friends and a fortress, is a lion among kings" },
  { number: 382, tamil: "அஞ்சாமை ஈகை அறிவூக்கம் இந்நான்கும்\nஎஞ்சாமை வேந்தர்க் கியல்பு.", transliteration: "Anjaamai Eekai Arivookkam Innaankum / Enjaamai Vendhark Kiyalpu", english: "Never to fail in these four things, fearlessness, liberality, wisdom, and energy, is the kingly character" },
  { number: 383, tamil: "தூங்காமை கல்வி துணிவுடைமை இம்மூன்றும்\nநீங்கா நிலனான் பவர்க்கு.", transliteration: "Thoongaamai Kalvi Thunivutaimai Immoondrum / Neengaa Nilanaan Pavarkku", english: "These three things, viz, vigilance, learning, and bravery, should never be wanting in the ruler of a country" },
  { number: 384, tamil: "அறனிழுக்கா தல்லவை நீக்கி மறனிழுக்கா\nமானம் உடைய தரசு.", transliteration: "Aranizhukkaa Thallavai Neekki Maranizhukkaa / Maanam Utaiya Tharasu", english: "He is a king who, with manly modesty, swerves not from virtue, and refrains from vice" },
  { number: 385, tamil: "இயற்றலும் ஈட்டலுங் காத்தலும் காத்த\nவகுத்தலும் வல்ல தரசு.", transliteration: "Iyatralum Eettalung Kaaththalum Kaaththa / Vakuththalum Valla Tharasu", english: "He is a king who is able to acquire (wealth), to lay it up, to guard, and to distribute it" },
  { number: 386, tamil: "காட்சிக் கெளியன் கடுஞ்சொல்லன் அல்லனேல்\nமீக்கூறும் மன்னன் நிலம்", transliteration: "Kaatchik Keliyan Katunjollan Allanel / Meekkoorum Mannan Nilam", english: "The whole world will exalt the country of the king who is easy of access, and who is free from harsh language" },
  { number: 387, tamil: "இன்சொலால் ஈத்தளிக்க வல்லார்க்குத் தன்சொலால்\nதான்கண் டனைத்திவ் வுலகு.", transliteration: "Insolaal Eeththalikka Vallaarkkuth Thansolaal / Thaankan Tanaiththiv Vulaku", english: "The world will praise and submit itself to the mind of the king who is able to give with affability, and to protect all who come to him" },
  { number: 388, tamil: "முறைசெய்து காப்பாற்றும் மன்னவன் மக்கட்கு\nஇறையென்று வைக்கப் படும்.", transliteration: "Muraiseydhu Kaappaatrum Mannavan Makkatku / Iraiyendru Vaikkap Patum", english: "That king, will be esteemed a God among men, who performs his own duties, and protects (his subjects)." },
  { number: 389, tamil: "செவிகைப்பச் சொற்பொறுக்கும் பண்புடை வேந்தன்\nகவிகைக்கீழ்த் தங்கும் உலகு.", transliteration: "Sevikaippach Chorporukkum Panputai Vendhan / Kavikaikkeezhth Thangum Ulaku", english: "The whole world will dwell under the umbrella of the king, who can bear words that embitter the ear" },
  { number: 390, tamil: "கொடையளி செங்கோல் குடியோம்பல் நான்கும்\nஉடையானாம் வேந்தர்க் கொளி.", transliteration: "Kotaiyali Sengol Kutiyompal Naankum / Utaiyaanaam Vendhark Koli", english: "He is the light of kings who has there four things, beneficence, benevolence, rectitude, and care for his people" },
  { number: 391, tamil: "கற்க கசடறக் கற்பவை கற்றபின்\nநிற்க அதற்குத் தக.", transliteration: "Karka Kasatarak Karpavai Katrapin / Nirka Adharkuth Thaka", english: "Let a man learn thoroughly whatever he may learn, and let his conduct be worthy of his learning" },
  { number: 392, tamil: "எண்ணென்ப ஏனை எழுத்தென்ப இவ்விரண்டும்\nகண்ணென்ப வாழும் உயிர்க்கு.", transliteration: "Ennenpa Enai Ezhuththenpa Ivvirantum / Kannenpa Vaazhum Uyirkku", english: "Letters and numbers are the two eyes of man" },
  { number: 393, tamil: "கண்ணுடையர் என்பவர் கற்றோர் முகத்திரண்டு\nபுண்ணுடையர் கல்லா தவர்.", transliteration: "Kannutaiyar Enpavar Katror Mukaththirantu / Punnutaiyar Kallaa Thavar", english: "The learned are said to have eyes, but the unlearned have (merely) two sores in their face" },
  { number: 394, tamil: "உவப்பத் தலைக்கூடி உள்ளப் பிரிதல்\nஅனைத்தே புலவர் தொழில்.", transliteration: "Uvappath Thalaikkooti Ullap Piridhal / Anaiththe Pulavar Thozhil", english: "It is the part of the learned to give joy to those whom they meet, and on leaving, to make them think (Oh! when shall we meet them again.)" },
  { number: 395, tamil: "உடையார்முன் இல்லார்போல் ஏக்கற்றுங் கற்றார்\nகடையரே கல்லா தவர்.", transliteration: "Utaiyaarmun Illaarpol Ekkatrung Katraar / Kataiyare Kallaa Thavar", english: "The unlearned are inferior to the learned, before whom they stand begging, as the destitute before the wealthy" },
  { number: 396, tamil: "தொட்டனைத் தூறும் மணற்கேணி மாந்தர்க்குக்\nகற்றனைத் தூறும் அறிவு.", transliteration: "Thottanaith Thoorum Manarkeni Maandharkkuk / Katranaith Thoorum Arivu", english: "Water will flow from a well in the sand in proportion to the depth to which it is dug, and knowledge will flow from a man in proportion to his learning" },
  { number: 397, tamil: "யாதானும் நாடாமால் ஊராமால் என்னொருவன்\nசாந்துணையுங் கல்லாத வாறு.", transliteration: "Yaadhaanum Naataamaal Ooraamaal Ennoruvan / Saandhunaiyung Kallaadha Vaaru", english: "How is it that any one can remain without learning, even to his death, when (to the learned man) every country is his own (country), and every town his own (town) ?" },
  { number: 398, tamil: "ஒருமைக்கண் தான்கற்ற கல்வி ஒருவற்கு\nஎழுமையும் ஏமாப் புடைத்து.", transliteration: "Orumaikkan Thaan Katra Kalvi / Oruvarku Ezhumaiyum Emaap Putaiththu", english: "The learning, which a man has acquired in one birth, will yield him pleasure during seven births" },
  { number: 399, tamil: "தாமின் புறுவது உலகின் புறக்கண்டு\nகாமுறுவர் கற்றறிந் தார்.", transliteration: "Thaamin Puruvadhu Ulakin Purak / Kantu Kaamuruvar Katrarin Thaar", english: "The learned will long (for more learning), when they see that while it gives pleasure to themselves, the world also derives pleasure from it" },
  { number: 400, tamil: "கேடில் விழுச்செல்வம் கல்வி யொருவற்கு\nமாடல்ல மற்றை யவை.", transliteration: "Ketil Vizhuchchelvam Kalvi Yoruvarku / Maatalla Matrai Yavai", english: "Learning is the true imperishable riches; all other things are not riches" },
  { number: 401, tamil: "அரங்கின்றி வட்டாடி யற்றே நிரம்பிய\nநூலின்றிக் கோட்டி கொளல்.", transliteration: "Arangindri Vattaati Yatre Nirampiya / Noolindrik Kotti Kolal", english: "To speak in an assembly (of the learned) without fullness of knowledge, is like playing at chess (on a board) without squares" },
  { number: 402, tamil: "கல்லாதான் சொற்கா முறுதல் முலையிரண்டும்\nஇல்லாதாள் பெண்காமுற் றற்று.", transliteration: "Kallaadhaan Sorkaa Murudhal Mulaiyirantum / Illaadhaal Penkaamur Ratru", english: "The desire of the unlearned to speak (in an assembly), is like a woman without breasts desiring (the enjoyment of ) woman-hood" },
  { number: 403, tamil: "கல்லா தவரும் நனிநல்லர் கற்றார்முன்\nசொல்லா திருக்கப் பெறின்.", transliteration: "Kallaa Thavarum Naninallar Katraarmun / Sollaa Thirukkap Perin", english: "The unlearned also are very excellent men, if they know how to keep silence before the learned" },
  { number: 404, tamil: "கல்லாதான் ஒட்பம் கழியநன் றாயினும்\nகொள்ளார் அறிவுடை யார்.", transliteration: "Kallaadhaan Otpam Kazhiyanan Raayinum / Kollaar Arivutai Yaar", english: "Although the natural knowledge of an unlearned man may be very good, the wise will not accept for true knowledge" },
  { number: 405, tamil: "கல்லா ஒருவன் தகைமை தலைப்பெய்து\nசொல்லாடச் சோர்வு படும்.", transliteration: "Kallaa Oruvan Thakaimai Thalaippeydhu / Sollaatach Chorvu Patum", english: "The self-conceit of an unlearned man will fade away, as soon as he speaks in an assembly (of" },
  { number: 406, tamil: "உளரென்னும் மாத்திரையர் அல்லால் பயவாக்\nகளரனையர் கல்லா தவர்.", transliteration: "Ularennum Maaththiraiyar Allaal Payavaak / Kalaranaiyar Kallaa Thavar", english: "The unlearned are like worthless barren land: all that can be said of them is, that they exist" },
  { number: 407, tamil: "நுண்மாண் நுழைபுலம் இல்லான் எழில்நலம்\nமண்மாண் புனைபாவை யற்று.", transliteration: "Nunmaan Nuzhaipulam Illaan Ezhilnalam / Manmaan Punaipaavai Yatru", english: "The beauty and goodness of one who is destitute of knowledge by the study of great and exquisite works, is like (the beauty and goodness) of a painted earthen doll" },
  { number: 408, tamil: "நல்லார்கண் பட்ட வறுமையின் இன்னாதே\nகல்லார்கண் பட் ட திரு.", transliteration: "Nallaarkan Patta Varumaiyin Innaadhe / Kallaarkan Patta Thiru", english: "Wealth, gained by the unlearned, will give more sorrow than the poverty which may come upon the learned" },
  { number: 409, tamil: "மேற்பிறந்தா ராயினும் கல்லாதார் கீழ்ப்பிறந்தும்\nகற்றார் அனைத்திலர் பாடு.", transliteration: "Merpirandhaa Raayinum Kallaadhaar Keezhppirandhum / Katraar Anaiththilar Paatu", english: "The unlearned, though born in a high caste, are not equal in dignity to the learned; though they may have been born in a low caste" },
  { number: 410, tamil: "விலங்கொடு மக்கள் அனையர் இலங்குநூல்\nகற்றாரோடு ஏனை யவர்.", transliteration: "Vilangotu Makkal Anaiyar Ilangunool / Katraarotu Enai Yavar", english: "As beasts by the side of men, so are other men by the side of those who are learned in celebrated works" },
  { number: 411, tamil: "செல்வத்துட் செல்வஞ் செவிச்செல்வம் அச்செல்வம்\nசெல்வத்து ளெல்லாந் தலை.", transliteration: "Selvaththut Selvanj Chevichchelvam Achchelvam / Selvaththu Lellaan Thalai", english: "Wealth (gained) by the ear is wealth of wealth; that wealth is the chief of all wealth" },
  { number: 412, tamil: "செவுக்குண வில்லாத போழ்து சிறிது\nவயிற்றுக்கும் ஈயப் படும்.", transliteration: "Sevikkuna Villaadha Pozhdhu Siridhu / Vayitrukkum Eeyap Patum", english: "When there is no food for the ear, give a little also to the stomach" },
  { number: 413, tamil: "செவியுணவிற் கேள்வி யுடையார் அவியுணவின்\nஆன்றாரோ டொப்பர் நிலத்து.", transliteration: "Seviyunavir Kelvi Yutaiyaar Aviyunavin / Aandraaro Toppar Nilaththu", english: "Those who in this world enjoy instruction which is the food of the ear, are equal to the Gods, who enjoy the food of the sacrifices" },
  { number: 414, tamil: "கற்றில னாயினுங் கேட்க அஃதொருவற்கு\nஒற்கத்தின் ஊற்றாந் துணை.", transliteration: "Katrila Naayinung Ketka Aqdhoruvarku / Orkaththin Ootraan Thunai", english: "Although a man be without learning, let him listen (to the teaching of the learned); that will be to him a staff in adversity" },
  { number: 415, tamil: "இழுக்கல் உடையுழி ஊற்றுக்கோல் அற்றே\nஒழுக்க முடையார்வாய்ச் சொல்.", transliteration: "Izhukkal Utaiyuzhi Ootrukkol Atre / Ozhukka Mutaiyaarvaaich Chol", english: "The words of the good are like a staff in a slippery place" },
  { number: 416, tamil: "எனைத்தானும் நல்லவை கேட்க அனைத்தானும்\nஆன்ற பெருமை தரும்.", transliteration: "Enaiththaanum Nallavai Ketka Anaiththaanum / Aandra Perumai Tharum", english: "Let a man listen, never so little, to good (instruction), even that will bring him great dignity" },
  { number: 417, tamil: "பிழைத்துணர்ந்தும் பேதைமை சொல்லா ரிழைத்துணர்ந்\nதீண்டிய கேள்வி யவர்.", transliteration: "Pizhaith Thunarndhum Pedhaimai Sollaa / Rizhaiththunarn Theentiya Kelvi Yavar", english: "Not even when they have imperfectly understood (a matter), will those men speak foolishly, who have profoundly studied and diligently listened (to instruction)" },
  { number: 418, tamil: "கேட்பினுங் கேளாத் தகையவே கேள்வியால்\nதோட்கப் படாத செவி.", transliteration: "Ketpinung Kelaath Thakaiyave Kelviyaal / Thotkap Pataadha Sevi", english: "The ear which has not been bored by instruction, although it hears, is deaf" },
  { number: 419, tamil: "நுணங்கிய கேள்விய ரல்லார் வணங்கிய\nவாயின ராதல் அரிது.", transliteration: "Nunangiya Kelviya Rallaar Vanangiya / Vaayina Raadhal Aridhu", english: "It is a rare thing to find modesty, a reverend mouth- with those who have not received choice instruction" },
  { number: 420, tamil: "செவியிற் சுவையுணரா வாயுணர்வின் மாக்கள்\nஅவியினும் வாழினும் என்?", transliteration: "Seviyir Suvaiyunaraa Vaayunarvin Maakkal / Aviyinum Vaazhinum En?", english: "What does it matter whether those men live or die, who can judge of tastes by the mouth, and not by the ear ?" },
  { number: 421, tamil: "அறிவற்றங் காக்குங் கருவி செறுவார்க்கும்\nஉள்ளழிக்க லாகா அரண்.", transliteration: "Arivatrang Kaakkung Karuvi Seruvaarkkum / Ullazhikka Laakaa Aran", english: "Wisdom is a weapon to ward off destruction; it is an inner fortress which enemies cannot destroy" },
  { number: 422, tamil: "சென்ற இடத்தால் செலவிடா தீதொரீஇ\nநன்றின்பால் உய்ப்ப தறிவு.", transliteration: "Sendra Itaththaal Selavitaa Theedhoreei / Nandrinpaal Uyppa Tharivu", english: "Not to permit the mind to go where it lists, to keep it from evil, and to employ it in good, this is wisdom" },
  { number: 423, tamil: "எப்பொருள் யார்யார்வாய்க் கேட்பினும் அப்பொருள்\nமெய்ப்பொருள் காண்ப தறிவு.", transliteration: "Epporul Yaaryaarvaaik Ketpinum Apporul / Meypporul Kaanpa Tharivu", english: "To discern the truth in every thing, by whomsoever spoken, is wisdom" },
  { number: 424, tamil: "எண்பொருள வாகச் செலச்சொல்லித் தான்பிறர்வாய்\nநுண்பொருள் காண்ப தறிவு.", transliteration: "Enporula Vaakach Chelachchollith Thaanpirarvaai / Nunporul Kaanpa Tharivu", english: "To speak so as that the meaning may easily enter the mind of the hearer, and to discern the subtlest thought which may lie hidden in the words of others, this is wisdom" },
  { number: 425, tamil: "உலகம் தழீஇய தொட்பம் மலர்தலும்\nகூம்பலும் இல்ல தறிவு.", transliteration: "Ulakam Thazheeiya Thotpam Malardhalum / Koompalum Illa Tharivu", english: "To secure the friendship of the great is true wisdom; it is (also) wisdom to keep (that friendship unchanged, and) not opening and closing (like the lotus flower)" },
  { number: 426, tamil: "எவ்வ துறைவது உலகம் உலகத்தோடு\nஅவ்வ துறைவ தறிவு.", transliteration: "Evva Thuraivadhu Ulakam Ulakaththotu / Avva Thuraiva Tharivu", english: "To live as the world lives, is wisdom" },
  { number: 427, tamil: "அறிவுடையார் ஆவ தறிவார் அறிவிலார்\nஅஃதறி கல்லா தவர்.", transliteration: "Arivutaiyaar Aava Tharivaar Arivilaar / Aqdhari Kallaa Thavar", english: "The wise are those who know beforehand what will happen; those who do not know this are the unwise" },
  { number: 428, tamil: "அஞ்சுவ தஞ்சாமை பேதைமை அஞ்சுவது\nஅஞ்சல் அறிவார் தொழில்.", transliteration: "Anjuva Thanjaamai Pedhaimai Anjuvadhu / Anjal Arivaar Thozhil", english: "Not to fear what ought to be feared, is folly; it is the work of the wise to fear what should be feared" },
  { number: 429, tamil: "எதிரதாக் காக்கும் அறிவினார்க் கில்லை\nஅதிர வருவதோர் நோய்.", transliteration: "Edhiradhaak Kaakkum Arivinaark Killai / Adhira Varuvadhor Noi", english: "No terrifying calamity will happen to the wise, who (foresee) and guard against coming evils" },
  { number: 430, tamil: "அறிவுடையார் எல்லா முடையார் அறிவிலார்\nஎன்னுடைய ரேனும் இலர்.", transliteration: "Arivutaiyaar Ellaa Mutaiyaar Arivilaar / Ennutaiya Renum Ilar", english: "Those who possess wisdom, possess every thing; those who have not wisdom, whatever they may possess, have nothing" },
  { number: 431, tamil: "செருக்குஞ் சினமும் சிறுமையும் இல்லார்\nபெருக்கம் பெருமித நீர்த்து.", transliteration: "Serukkunj Chinamum Sirumaiyum Illaar / Perukkam Perumidha Neerththu", english: "Truly great is the excellence of those (kings) who are free from pride, anger, and lust" },
  { number: 432, tamil: "இவறலும் மாண்பிறந்த மானமும் மாணா\nஉவகையும் ஏதம் இறைக்கு.", transliteration: "Ivaralum Maanpirandha Maanamum Maanaa / Uvakaiyum Edham Iraikku", english: "Avarice, undignified pride, and low pleasures are faults in a king" },
  { number: 433, tamil: "தினைத்துணையாங் குற்றம் வரினும் பனைத்துணையாக்\nகொள்வர் பழிநாணு வார்.", transliteration: "Thinaiththunaiyaang Kutram Varinum Panaiththunaiyaak / Kolvar Pazhinaanu Vaar", english: "Those who fear guilt, if they commit a fault small as a millet seed, will consider it to be as large as a palmyra tree" },
  { number: 434, tamil: "குற்றமே காக்க பொருளாகக் குற்றமே\nஅற்றந் த்ரூஉம் பகை.", transliteration: "Kutrame Kaakka Porulaakak Kutrame / Atran Tharooum Pakai", english: "Guard against faults as a matter (of great consequence; for) faults are a deadly enemy" },
  { number: 435, tamil: "வருமுன்னர்க் காவாதான் வாழ்க்கை எரிமுன்னர்\nவைத்தூறு போலக் கெடும்.", transliteration: "Varumunnark Kaavaadhaan Vaazhkkai Erimunnar / Vaiththooru Polak Ketum", english: "The prosperity of him who does not timely guard against faults, will perish like straw before fire" },
  { number: 436, tamil: "தன்குற்றம் நீக்கிப் பிறர்குற்றங் காண்கிற்பின்\nஎன்குற்ற மாகும் இறைக்கு?", transliteration: "Thankutram Neekkip Pirarkutrang Kaankirpin / Enkutra Maakum Iraikku?", english: "What fault will remain in the king who has put away his own evils, and looks after the evils of others" },
  { number: 437, tamil: "செயற்பால செய்யா திவறியான் செல்வம்\nஉயற்பால தன்றிக் கெடும்.", transliteration: "Seyarpaala Seyyaa Thivariyaan Selvam / Uyarpaala Thandrik Ketum", english: "The wealth of the avaricious man, who does not expend it for the purposes for which he ought to expend it will waste away and not continue" },
  { number: 438, tamil: "பற்றுள்ளம் என்னும் இவறன்மை எற்றுள்ளும்\nஎண்ணப் படுவதொன் றன்று.", transliteration: "Patrullam Ennum Ivaranmai Etrullum / Ennap Patuvadhon Randru", english: "Griping avarice is not to be reckoned as one among other faults; (it stands alone - greater than all)" },
  { number: 439, tamil: "வியவற்க எஞ்ஞான்றும் தன்னை நயவற்க\nநன்றி பயவா வினை.", transliteration: "Viyavarka Egngnaandrum Thannai Nayavarka / Nandri Payavaa Vinai", english: "Let no (one) praise himself, at any time; let him not desire to do useless things" },
  { number: 440, tamil: "காதல காதல் அறியாமை உய்க்கிற்பின்\nஏதில ஏதிலார் நூல்.", transliteration: "Kaadhala Kaadhal Ariyaamai Uykkirpin / Edhila Edhilaar Nool", english: "If (a king) enjoys, privately the things which he desires, the designs of his enemies will be useless" },
  { number: 441, tamil: "அறனறிந்து மூத்த அறிவுடையார் கேண்மை\nதிறனறிந்து தேர்ந்து கொளல்.", transliteration: "Aranarindhu Mooththa Arivutaiyaar Kenmai / Thiranarindhu Therndhu Kolal", english: "Let (a king) ponder well its value, and secure the friendship of men of virtue and of mature knowledge" },
  { number: 442, tamil: "உற்றநோய் நீக்கி உறாஅமை முற்காக்கும்\nபெற்றியார்ப் பேணிக் கொளல்.", transliteration: "Utranoi Neekki Uraaamai Murkaakkum / Petriyaarp Penik Kolal", english: "Let (a king) procure and kindly care for men who can overcome difficulties when they occur, and guard against them before they happen" },
  { number: 443, tamil: "அரியவற்று ளெல்லாம் அரிதே பெரியாரைப்\nபேணித் தமராக் கொளல்.", transliteration: "Ariyavatru Lellaam Aridhe Periyaaraip / Penith Thamaraak Kolal", english: "To cherish great men and make them his own, is the most difficult of all difficult things" },
  { number: 444, tamil: "தம்மிற் பெரியார் தமரா ஒழுகுதல்\nவன்மையு ளெல்லாந் தலை.", transliteration: "Thammir Periyaar Thamaraa Ozhukudhal / Vanmaiyu Lellaan Thalai", english: "So to act as to make those men, his own, who are greater than himself is of all powers the highest" },
  { number: 445, tamil: "சூழ்வார்கண் ணாக ஒழுகலான் மன்னவன்\nசூழ்வாரைக் சூழ்ந்து கொளல்.", transliteration: "Soozhvaarkan Naaka Ozhukalaan Mannavan / Soozhvaaraik Soozhndhu Kolal", english: "As a king must use his ministers as eyes (in managing his kingdom), let him well examine their character and qualifications before he engages them" },
  { number: 446, tamil: "தக்கா ரினத்தனாய்த் தானொழுக வல்லானைச்\nசெற்றார் செயக்கிடந்த தில்.", transliteration: "Thakkaa Rinaththanaaith Thaanozhuka Vallaanaich / Chetraar Seyakkitandha Thil", english: "There will be nothing left for enemies to do, against him who has the power of acting (so as to secure) the fellowship of worthy men" },
  { number: 447, tamil: "இடிக்குந் துணையாரை யாள்வரை யாரே\nகெடுக்குந் தகைமை யவர்.", transliteration: "Itikkun Thunaiyaarai Yaalvarai Yaare / Ketukkun Thakaimai Yavar", english: "Who are great enough to destroy him who has servants that have power to rebuke him ?" },
  { number: 448, tamil: "இடிப்பாரை இல்லாத ஏமரா மன்னன்\nகெடுப்பா ரிலானுங் கெடும்.", transliteration: "Itippaarai Illaadha Emaraa Mannan / Ketuppaa Rilaanung Ketum", english: "The king, who is without the guard of men who can rebuke him, will perish, even though there be no one to destroy him" },
  { number: 449, tamil: "முதலிலார்க ஊதிய மில்லை மதலையாஞ்\nசார்பிலார்க் கில்லை நிலை.", transliteration: "Mudhalilaarkku Oodhiya Millai Madhalaiyaanjjch / Aarpilaark Killai Nilai", english: "There can be no gain to those who have no capital; and in like manner there can be no permanence to" },
  { number: 450, tamil: "பல்லார் பகைகொளலிற் பத்தடுத்த தீமைத்தே\nநல்லார் தொடர்கை விடல்.", transliteration: "Pallaar Pakai Kolalir Paththatuththa / Theemaiththe Nallaar Thotarkai Vital", english: "It is tenfold more injurious to abandon the friendship of the good, than to incur the hatred of the many" },
  { number: 451, tamil: "சிற்றினம் அஞ்சும் பெருமை சிறுமைதான்\nசுற்றமாச் சூழ்ந்து விடும்.", transliteration: "Sitrinam Anjum Perumai Sirumaidhaan / Sutramaach Choozhndhu Vitum", english: "(True) greatness fears the society of the base; it is only the low - minded who will regard them as friends" },
  { number: 452, tamil: "நிலத்தியல்பால் நீர்திரிந் தற்றாகும் மாந்தர்க்கு\nஇனத்தியல்ப தாகும் அறிவு.", transliteration: "Nilaththiyalpaal Neerdhirin Thatraakum Maandharkku / Inaththiyalpa Thaakum Arivu", english: "As water changes (its nature), from the nature of the soil (in which it flows), so will the character of men resemble that of their associates" },
  { number: 453, tamil: "மனத்தானாம் மாந்தர்க் குணர்ச்சி இனத்தானாம்\nஇன்னான் எனப்படுஞ் சொல்.", transliteration: "Manaththaanaam Maandhark Kunarchchi Inaththaanaam / Innaan Enappatunj Chol", english: "The power of knowing is from the mind; (but) his character is from that of his associates" },
  { number: 454, tamil: "மனத்து ளதுபோலக் காட்டி ஒருவற்கு\nஇனத்துள தாகும் அறிவு.", transliteration: "Manaththu Ladhupolak Kaatti Oruvarku / Inaththula Thaakum Arivu", english: "Wisdom appears to rest in the mind, but it really exists to a man in his companions" },
  { number: 455, tamil: "மனந்தூய்மை செய்வினை தூய்மை இரண்டும்\nஇனந்தூய்மை தூவா வரும்.", transliteration: "Manandhooimai Seyvinai Thooimai Irantum / Inandhooimai Thoovaa Varum", english: "Chaste company is the staff on which come, these two things, viz, purity of mind and purity of conduct" },
  { number: 456, tamil: "மனந்தூயார்க் கெச்சம்நன் றாகும் இனந்தூயார்க்கு\nஇல்லைநன் றாகா வினை.", transliteration: "Manandhooyaark Kechchamnan Raakum Inandhooyaarkku / Illainan Raakaa Vinai", english: "To the pure-minded there will be a good posterity By those whose associates are pure, no deeds will be done that are not good" },
  { number: 457, tamil: "மனநலம் மன்னுயிர்க் காக்கம் இனநலம்\nஎல்லாப் புகழும் தரும்.", transliteration: "Mananalam Mannuyirk Kaakkam Inanalam / Ellaap Pukazhum Tharum", english: "Goodness of mind will give wealth, and good society will bring with it all praise, to men" },
  { number: 458, tamil: "மனநலம் நன்குடைய ராயினும் சான்றோர்க்கு\nஇனநலம் ஏமாப் புடைத்து.", transliteration: "Mananalam Nankutaiya Raayinum Saandrorkku / Inanalam Emaap Putaiththu", english: "Yet good companionship is confirmation strong" },
  { number: 459, tamil: "மனநலத்தின் ஆகும் மறுமைமற் றஃதும்\nஇனநலத்தின் ஏமாப் புடைத்து.", transliteration: "Mananalaththin Aakum Marumaimar Raqdhum / Inanalaththin Emaap Putaiththu", english: "Future bliss is (the result) of goodness of mind; and even this acquires strength from the society of the good" },
  { number: 460, tamil: "நல்லினத்தி னூங்குந் துணையில்லை தீயினத்தின்\nஅல்லற் படுப்பதூஉம் இல்.", transliteration: "Nallinaththi Noongun Thunaiyillai Theeyinaththin / Allar Patuppadhooum Il", english: "There is no greater help than the company of the good; there is no greater source of sorrow than the company of the wicked" },
  { number: 461, tamil: "அழிவதூஉம் ஆவதூஉம் ஆகி வழிபயக்கும்\nஊதியமும் சூழ்ந்து செயல்.", transliteration: "Azhivadhooum Aavadhooum Aaki Vazhipayakkum / Oodhiyamum Soozhndhu Seyal", english: "Let a man reflect on what will be lost, what will be acquired and (from these) what will be his ultimate gain, and (then, let him) act" },
  { number: 462, tamil: "தெரிந்த இனத்தொடு தேர்ந்தெண்ணிச் செய்வார்க்கு\nஅரும்பொருள் யாதொன்றும் இல்", transliteration: "Therindha Inaththotu Therndhennich Cheyvaarkku / Arumporul Yaadhondrum Il", english: "There is nothing too difficult to (be attained by) those who, before they act, reflect well themselves, and thoroughly consider (the matter) with chosen friends" },
  { number: 463, tamil: "ஆக்கம் கருதி முதலிழக்கும் செய்வினை\nஊக்கார் அறிவுடை யார்.", transliteration: "Aakkam Karudhi Mudhalizhakkum Seyvinai / Ookkaar Arivutai Yaar", english: "Wise men will not, in the hopes of profit, undertake works that will consume their principal" },
  { number: 464, tamil: "தெளிவி லதனைத் தொடங்கார் இளிவென்னும்\nஏதப்பாடு அஞ்சு பவர்.", transliteration: "Thelivi Ladhanaith Thotangaar Ilivennum / Edhappaatu Anju Pavar", english: "Those who fear reproach will not commence anything which has not been (thoroughly considered) and made clear to them" },
  { number: 465, tamil: "வகையறச் சூழா தெழுதல் பகைவரைப்\nபாத்திப் படுப்பதோ ராறு.", transliteration: "Vakaiyarach Choozhaa Thezhudhal Pakaivaraip / Paaththip Patuppadho Raaru", english: "One way to promote the prosperity of an enemy, is (for a king) to set out (to war) without having thoroughly weighed his ability (to cope with its chances)" },
  { number: 466, tamil: "செய்தக்க அல்ல செயக்கெடும் செய்தக்க\nசெய்யாமை யானுங் கெடும்.", transliteration: "Seydhakka Alla Seyak Ketum / Seydhakka Seyyaamai Yaanung Ketum", english: "He will perish who does not what is not fit to do; and he also will perish who does not do what it is fit to" },
  { number: 467, tamil: "எண்ணித் துணிக கருமம் துணிந்தபின்\nஎண்ணுவம் என்பது இழுக்கு.", transliteration: "Ennith Thunika Karumam Thunindhapin / Ennuvam Enpadhu Izhukku", english: "Consider, and then undertake a matter; after having undertaken it, to say \"We will consider,\" is folly" },
  { number: 468, tamil: "ஆற்றின் வருந்தா வருத்தம் பலர்நின்று\nபோற்றினும் பொத்துப் படும்.", transliteration: "Aatrin Varundhaa Varuththam Palarnindru / Potrinum Poththup Patum", english: "The work, which is not done by suitable methods, will fail though many stand to uphold it" },
  { number: 469, tamil: "நன்றாற்ற லுள்ளுந் தவுறுண்டு அவரவர்\nபண்பறிந் தாற்றாக் கடை.", transliteration: "Nandraatra Lullun Thavuruntu Avaravar / Panparin Thaatraak Katai", english: "There are failures even in acting well, when it is done without knowing the various dispositions of men" },
  { number: 470, tamil: "எள்ளாத எண்ணிச் செயல்வேண்டும் தம்மோடு\nகொள்ளாத கொள்ளாது உலகு.", transliteration: "Ellaadha Ennich Cheyalventum Thammotu / Kollaadha Kollaadhu Ulaku", english: "Let a man reflect, and do things which bring no reproach; the world will not approve, with him, of things which do not become of his position to adopt" },
  { number: 471, tamil: "வினைவலியும் தன்வலியும் மாற்றான் வலியும்\nதுணைவலியும் தூக்கிச் செயல்.", transliteration: "Vinaivaliyum Thanvaliyum Maatraan Valiyum / Thunaivaliyum Thookkich Cheyal", english: "Let (one) weigh well the strength of the deed (he purposes to do), his own strength, the strength of his enemy, and the strength of the allies (of both), and then let him act" },
  { number: 472, tamil: "ஒல்வ தறிவது அறிந்ததன் கண்தங்கிச்\nசெல்வார்க்குச் செல்லாதது இல்.", transliteration: "Olva Tharivadhu Arindhadhan Kandhangich / Chelvaarkkuch Chellaadhadhu Il", english: "There is nothing which may not be accomplished by those who, before they attack (an enemy), make themselves acquainted with their own ability, and with whatever else is (needful) to be known, and" },
  { number: 473, tamil: "உடைத்தம் வலியறியார் ஊக்கத்தின் ஊக்கி\nஇடைக்கண் முரிந்தார் பலர்.", transliteration: "Utaiththam Valiyariyaar Ookkaththin Ookki / Itaikkan Murindhaar Palar", english: "There are many who, ignorant of their (want of) power (to meet it), have haughtily set out to war, and broken down in the midst of it" },
  { number: 474, tamil: "அமைந்தாங் கொழுகான் அளவறியான் தன்னை\nவியந்தான் விரைந்து கெடும்.", transliteration: "Amaindhaang Kozhukaan Alavariyaan Thannai / Viyandhaan Viraindhu Ketum", english: "He will quickly perish who, ignorant of his own resources flatters himself of his greatness, and does" },
  { number: 475, tamil: "பீலிபெய் சாகாடும் அச்சிறும் அப்பண்டஞ்\nசால மிகுத்துப் பெயின்.", transliteration: "Peelipey Saakaatum Achchirum Appantanjjch / Aala Mikuththup Peyin", english: "The axle tree of a bandy, loaded only with peacocks' feathers will break, if it be greatly overloaded" },
  { number: 476, tamil: "நுனிக்கொம்பர் ஏறினார் அஃதிறந் தூக்கின்\nஉயிர்க்கிறுதி ஆகி விடும்.", transliteration: "Nunikkompar Erinaar Aqdhiran Thookkin / Uyirkkirudhi Aaki Vitum", english: "There will be an end to the life of him who, having climbed out to the end of a branch, ventures to go further" },
  { number: 477, tamil: "ஆற்றின் அறவறிந்து ஈக அதுபொருள்\nபோற்றி வழங்கு நெறி.", transliteration: "Aatrin Aravarindhu Eeka Adhuporul / Potri Vazhangu Neri", english: "Let a man know the measure of his ability (to give), and let him give accordingly; such giving is the way to preserve his property" },
  { number: 478, tamil: "ஆகாறு அளவிட்டி தாயினுங் கேடில்லை\nபோகாறு அகலாக் கடை.", transliteration: "Aakaaru Alavitti Thaayinung Ketillai / Pokaaru Akalaak Katai", english: "Even though the income (of a king) be small, it will not cause his (ruin), if his outgoings be not larger than his income" },
  { number: 479, tamil: "அளவறிந்து வாழாதான் வாழ்க்கை உளபோல\nஇல்லாகித் தோன்றாக் கெடும்.", transliteration: "Alavara�ndhu Vaazhaadhaan Vaazhkkai Ulapola / Illaakith Thondraak Ketum", english: "The prosperity of him who lives without knowing the measure (of his property), will perish, even while it seems to continue" },
  { number: 480, tamil: "உளவரை தூக்காத ஒப்புர வாண்மை\nவளவரை வல்லைக் கெடும்.", transliteration: "Ulavarai Thookkaadha Oppura Vaanmai / Valavarai Vallaik Ketum", english: "The measure of his wealth will quickly perish, whose liberality weighs not the measure of his property" },
  { number: 481, tamil: "பகல்வெல்லும் கூகையைக் காக்கை இகல்வெல்லும்\nவேந்தர்க்கு வேண்டும் பொழுது.", transliteration: "Pakalvellum Kookaiyaik Kaakkai Ikalvellum / Vendharkku Ventum Pozhudhu", english: "A crow will overcome an owl in the day time; so the king who would conquer his enemy must have (a suitable) time" },
  { number: 482, tamil: "பருவத்தோடு ஒட்ட ஒழுகல் திருவினைத்\nதீராமை ஆர்க்குங் கயிறு.", transliteration: "Paruvaththotu Otta Ozhukal Thiruvinaith / Theeraamai Aarkkung Kayiru", english: "Acting at the right season, is a cord that will immoveably bind success (to a king)" },
  { number: 483, tamil: "அருவினை யென்ப உளவோ கருவியான்\nகாலம் அற஧ந்து செயின்.", transliteration: "Aruvinai Yenpa Ulavo Karuviyaan / Kaalam Arindhu Seyin", english: "Is there anything difficult for him to do, who acts, with (the right) instruments at the right time ?" },
  { number: 484, tamil: "ஞாலம் கருதினுங் கைகூடுங் காலம்\nகருதி இடத்தாற் செயின்.", transliteration: "Gnaalam Karudhinung Kaikootung Kaalam / Karudhi Itaththaar Seyin", english: "Though (a man) should meditate (the conquest of) the world, he may accomplish it if he acts in the right time, and at the right place" },
  { number: 485, tamil: "காலம் கருதி இருப்பர் கலங்காது\nஞாலம் கருது பவர்.", transliteration: "Kaalam Karudhi Iruppar Kalangaadhu / Gnaalam Karudhu Pavar", english: "They who thoughtfully consider and wait for the (right) time (for action), may successfully meditate (the conquest of) the world" },
  { number: 486, tamil: "ஊக்க முடையான் ஒடுக்கம் பொருதகர்\nதாக்கற்குப் பேருந் தகைத்து.", transliteration: "Ookka Mutaiyaan Otukkam Porudhakar / Thaakkarkup Perun Thakaiththu", english: "The self-restraint of the energetic (while waiting for a suitable opportunity), is like the drawing back of a fighting-ram in order to butt" },
  { number: 487, tamil: "பொள்ளென ஆங்கே புறம்வேரார் காலம்பார்த்து\nஉள்வேர்ப்பர் ஒள்ளி யவர்.", transliteration: "Pollena Aange Puramveraar Kaalampaarththu / Ulverppar Olli Yavar", english: "The wise will not immediately and hastily shew out their anger; they will watch their time, and restrain it within" },
  { number: 488, tamil: "செறுநரைக் காணின் சுமக்க இறுவரை\nகாணின் கிழக்காம் தலை.", transliteration: "Serunaraik Kaanin Sumakka Iruvarai / Kaanin Kizhakkaam Thalai", english: "If one meets his enemy, let him show him all respect, until the time for his destruction is come; when that is come, his head will be easily brought low" },
  { number: 489, tamil: "எய்தற் கரியது இயைந்தக்கால் அந்நிலையே\nசெய்தற் கரிய செயல்.", transliteration: "Eydhar Kariyadhu Iyaindhakkaal Annilaiye / Seydhar Kariya Seyal", english: "If a rare opportunity occurs, while it lasts, let a man do that which is rarely to be accomplished (but for such an opportunity)" },
  { number: 490, tamil: "கொக்கொக்க கூம்பும் பருவத்து மற்றதன்\nகுத்தொக்க சீர்த்த இடத்து.", transliteration: "Kokkokka Koompum Paruvaththu Matradhan / Kuththokka Seerththa Itaththu", english: "At the time when one should use self-control, let him restrain himself like a heron; and, let him like it, strike, when there is a favourable opportunity" },
  { number: 491, tamil: "தொடங்கற்க எவ்வினையும் எள்ளற்க முற்றும்\nஇடங்கண்ட பின்அல் லது.", transliteration: "Thotangarka Evvinaiyum Ellarka Mutrum / Itanganta Pinal Ladhu", english: "Let not (a king) despise (an enemy), nor undertake any thing (against him), until he has obtained (a suitable) place for besieging him" },
  { number: 492, tamil: "முரண்சேர்ந்த மொய்ம்பி னவர்க்கும் அரண்சேர்ந்தாம்\nஆக்கம் பலவுந் தரும்.", transliteration: "Muranserndha Moimpi Navarkkum Aranserndhaam / Aakkam Palavun Tharum", english: "Even to those who are men of power and expedients, an attack in connection with a fortification will yield many advantages" },
  { number: 493, tamil: "ஆற்றாரும் ஆற்றி அடுப இடனறிந்து\nபோற்றார்கண் போற்றிச் செயின்.", transliteration: "Aatraarum Aatri Atupa Itanarindhu / Potraarkan Potrich Cheyin", english: "Even the powerless will become powerful and conquer, if they select a proper field (of action), and guard themselves, while they make war on their enemies" },
  { number: 494, tamil: "எண்ணியார் எண்ணம் இழப்பர் இடனறிந்து\nதுன்னியார் துன்னிச் செயின்.", transliteration: "Enniyaar Ennam Izhappar Itanarindhu / Thunniyaar Thunnich Cheyin", english: "If they who draw near (to fight) choose a suitable place to approach (their enemy), the latter, will have to relinquish the thought which they once entertained, of conquering them" },
  { number: 495, tamil: "நெடும்புனலுள் வெல்லும் முதலை அடும்புனலின்\nநீங்கின் அதனைப் பிற.", transliteration: "Netumpunalul Vellum Mudhalai Atumpunalin / Neengin Adhanaip Pira", english: "In deep water, a crocodile will conquer (all other animals); but if it leave the water, other animals will conquer it" },
  { number: 496, tamil: "கடலோடா கால்வல் நெடுந்தேர் கடலோடும்\nநாவாயும் ஓடா நிலத்து.", transliteration: "Katalotaa Kaalval Netundher Katalotum / Naavaayum Otaa Nilaththu", english: "Wide chariots, with mighty wheels, will not run on the ocean; neither will ships that the traverse ocean, move on the earth" },
  { number: 497, tamil: "அஞ்சாமை அல்லால் துணைவேண்டா எஞ்சாமை\nஎண்ணி இடத்தால் செயின்.", transliteration: "Anjaamai Allaal Thunaiventaa Enjaamai / Enni Itaththaal Seyin", english: "You will need no other aid than fearlessness, if you thoroughly reflect (on what you are to do), and select (a suitable) place for your operations" },
  { number: 498, tamil: "சிறுபடையான் செல்லிடம் சேரின் உறுபடையான்\nஊக்கம் அழிந்து விடும்.", transliteration: "Sirupataiyaan Sellitam Serin Urupataiyaan / Ookkam Azhindhu Vitum", english: "The power of one who has a large army will perish, if he goes into ground where only a small army can act" },
  { number: 499, tamil: "சிறைநலனும் சீரும் இலரெனினும் மாந்தர்\nஉறைநிலத்தோடு ஒட்டல் அரிது.", transliteration: "Sirainalanum Seerum Ilareninum Maandhar / Urainilaththotu Ottal Aridhu", english: "It is a hazardous thing to attack men in their own country, although they may neither have power nor a good fortress" },
  { number: 500, tamil: "காலாழ் களரில் நரியடும் கண்ணஞ்சா\nவேலாள் முகத்த களிறு.", transliteration: "Kaalaazh Kalaril Nariyatum Kannanjaa / Velaal Mukaththa Kaliru", english: "A fox can kill a fearless, warrior-faced elephant, if it go into mud in which its legs sink down" },
  { number: 501, tamil: "அறம்பொருள் இன்பம் உயிரச்சம் நான்கின்\nதிறந்தெரிந்து தேறப் படும்.", transliteration: "Aramporul Inpam Uyirachcham Naankin / Thirandherindhu Therap Patum", english: "Let (a minister) be chosen, after he has been tried by means of these four things, viz,-his virtue, (love of) money, (love of) sexual pleasure, and tear of (losing) life" },
  { number: 502, tamil: "குடிப்பிறந்து குற்றத்தின் நீங்கி வடுப்பரியும்\nநாணுடையான் சுட்டே தெளிவு.", transliteration: "Kutippirandhu Kutraththin Neengi Vatuppariyum / Naanutaiyaan Sutte Thelivu", english: "(The king's) choice should (fall) on him, who is of good family, who is free from faults, and who has the modesty which fears the wounds (of sin)" },
  { number: 503, tamil: "அரியகற்று ஆசற்றார் கண்ணும் தெரியுங்கால்\nஇன்மை அரிதே வெளிறு.", transliteration: "Ariyakatru Aasatraar Kannum Theriyungaal / Inmai Aridhe Veliru", english: "When even men, who have studied the most difficult works, and who are free from faults, are (carefully) examined, it is a rare thing to find them without ignorance" },
  { number: 504, tamil: "குணம்நாடிக் குற்றமும் நாடி அவற்றுள்\nமிகைநாடி மிக்க கொளல்.", transliteration: "Kunamnaatik Kutramum Naati Avatrul / Mikainaati Mikka Kolal", english: "Let (a king) consider (a man's) good qualities, as well as his faults, and then judge (of his character) by that which prevails" },
  { number: 505, tamil: "பெருமைக்கும் ஏனைச் சிறுமைக்கும் தத்தம்\nகருமமே கட்டளைக் கல்.", transliteration: "Perumaikkum Enaich Chirumaikkum Thaththam / Karumame Kattalaik Kal", english: "A man's deeds are the touchstone of his greatness and littleness" },
  { number: 506, tamil: "அற்றாரைத் தேறுதல் ஓம்புக மற்றவர்\nபற்றிலர் நாணார் பழி.", transliteration: "Atraaraith Therudhal Ompuka Matravar / Patrilar Naanaar Pazhi", english: "Let (a king) avoid choosing men who have no relations; such men have no attachment, and thereforehave no fear of crime" },
  { number: 507, tamil: "காதன்மை கந்தா அறிவறியார்த் தேறுதல்\nபேதைமை எல்லாந் தரும்.", transliteration: "Kaadhanmai Kandhaa Arivariyaarth Therudhal / Pedhaimai Ellaan Tharum", english: "Yields all his being up to folly's blind control" },
  { number: 508, tamil: "தேரான் பிறனைத் தெளிந்தான் வழிமுறை\nதீரா இடும்பை தரும்.", transliteration: "Theraan Piranaith Thelindhaan Vazhimurai / Theeraa Itumpai Tharum", english: "Sorrow that will not leave even his posterity will come upon him chooses a stranger whose character he has not known" },
  { number: 509, tamil: "தேறற்க யாரையும் தேராது தேர்ந்தபின்\nதேறுக தேறும் பொருள்.", transliteration: "Therarka Yaaraiyum Theraadhu Therndhapin / Theruka Therum Porul", english: "Let (a king) choose no one without previous consideration; after he has made his choice, let him unhesitatingly select for each such duties as are appropriate" },
  { number: 510, tamil: "தேரான் தெளிவும் தெளிந்தான்கண் ஐயுறவும்\nதீரா இடும்பை தரும்.", transliteration: "Theraan Thelivum Thelindhaankan Aiyuravum / Theeraa Itumpai Tharum", english: "To make choice of one who has not been examined, and to entertain doubts respecting one who has been chosen, will produce irremediable sorrow" },
  { number: 511, tamil: "நன்மையும் தீமையும் நாடி நலம்புரிந்த\nதன்மையான் ஆளப் படும்.", transliteration: "Nanmaiyum Theemaiyum Naati Nalampurindha / Thanmaiyaan Aalap Patum", english: "He should be employed (by a king), whose nature leads him to choose the good, after having weighed both the evil and the good in any undertaking" },
  { number: 512, tamil: "வாரி பெருக்கி வளம்படுத்து உற்றவை\nஆராய்வான் செய்க வினை.", transliteration: "Vaari Perukki Valampatuththu Utravai / Aaraaivaan Seyka Vinai", english: "Let him do (the king's) work who can enlarge the sources (of revenue), increase wealth and considerately prevent the accidents (which would destroy it)" },
  { number: 513, tamil: "அன்பறிவு தேற்றம் அவாவின்மை இந்நான்கும்\nநன்குடையான் கட்டே தெளிவு.", transliteration: "Anparivu Thetram Avaavinmai Innaankum / Nankutaiyaan Katte Thelivu", english: "Let the choice (of a king) fall upon him who largely possesses these four things, love, knowledge, a clear mind and freedom from covetousness" },
  { number: 514, tamil: "எனைவகையான் தேறியக் கண்ணும் வினைவகையான்\nவேறாகும் மாந்தர் பலர்.", transliteration: "Enaivakaiyaan Theriyak Kannum Vinaivakaiyaan / Veraakum Maandhar Palar", english: "Even when (a king) has tried them in every possible way, there are many men who change, from the nature of the works (in which they may be employed)" },
  { number: 515, tamil: "அறிந்தாற்றிச் செய்கிற்பாற்கு அல்லால் வினைதான்\nசிறந்தானென்று ஏவற்பாற் றன்று.", transliteration: "Arindhaatrich Cheykirpaarku Allaal Vinaidhaan / Sirandhaanendru Evarpaar Randru", english: "(A king's) work can only be accomplished by a man of wisdom and patient endurance; it is not of a nature to be given to one from mere personal attachment" },
  { number: 516, tamil: "செய்வானை நாடி வினைநாடிக் காலத்தோடு\nஎய்த உணர்ந்து செயல்.", transliteration: "Seyvaanai Naati Vinainaatik Kaalaththotu / Eydha Unarndhu Seyal", english: "Let (a king) act, after having considered the agent (whom he is to employ), the deed (he desires to do), and the time which is suitable to it" },
  { number: 517, tamil: "இதனை இதனால் இவன்முடிக்கும் என்றாய்ந்து\nஅதனை அவன்கண் விடல்.", transliteration: "Ithanai Ithanaal Ivanmutikkum Endraaindhu / Adhanai Avankan Vital", english: "After having considered, \"this man can accomplish this, by these means\", let (the king) leave with him the discharge of that duty" },
  { number: 518, tamil: "வினைக்குரிமை நாடிய பின்றை அவனை\nஅதற்குரிய னாகச் செயல்.", transliteration: "Vinaik Kurimai Naatiya Pindrai / Avanai Adharkuriya Naakach Cheyal", english: "Having considered what work a man is fit for, let (the king) employ him in that work" },
  { number: 519, tamil: "வினைக்கண் வினையுடையான் கேண்மைவே றாக\nநினைப்பானை நீங்கும் திரு.", transliteration: "Vinaikkan Vinaiyutaiyaan Kenmaive Raaka / Ninaippaanai Neengum Thiru", english: "Prosperity will leave (the king) who doubts the friendship of the man who steadily labours in the discharge of his duties" },
  { number: 520, tamil: "நாடோறும் நாடுக மன்னன் வினைசெய்வான்\nகோடாமை கோடா துலகு.", transliteration: "Naatorum Naatuka Mannan Vinaiseyvaan / Kotaamai Kotaa Thulaku", english: "Let a king daily examine the conduct of his servants; if they do not act crookedly, the world will not act crookedly" },
  { number: 521, tamil: "பற்றற்ற கண்ணும் பழைமைபா ராட்டுதல்\nசுற்றத்தார் கண்ணே உள.", transliteration: "Patratra Kannum Pazhaimaipaa Raattudhal / Sutraththaar Kanne Ula", english: "Even when (a man's) property is all gone, relatives will act towards him with their accustomed (kindness)" },
  { number: 522, tamil: "விருப்பறாச் சுற்றம் இயையின் அருப்பறா\nஆக்கம் பலவும் தரும்.", transliteration: "Virupparaach Chutram Iyaiyin Arupparaa / Aakkam Palavum Tharum", english: "If (a man's) relatives remain attached to him with unchanging love, it will be a source of everincreasing wealth" },
  { number: 523, tamil: "அளவளா வில்லாதான் வாழ்க்கை குளவளாக்\nகோடின்றி நீர்நிறைந் தற்று.", transliteration: "Alavalaa Villaadhaan Vaazhkkai Kulavalaak / Kotindri Neernirain Thatru", english: "The wealth of one who does not mingle freely with his relatives, will be like the filling of water in a" },
  { number: 524, tamil: "சுற்றத்தால் சுற்றப் படஒழுகல் செல்வந்தான்\nபெற்றத்தால் பெற்ற பயன்.", transliteration: "Sutraththaal Sutrap Pataozhukal Selvandhaan / Petraththaal Petra Payan", english: "To live surrounded by relatives, is the advantage to be derived from the acquisition of wealth" },
  { number: 525, tamil: "கொடுத்தலும் இன்சொலும் ஆற்றின் அடுக்கிய\nசுற்றத்தால் சுற்றப் படும்.", transliteration: "Kotuththalum Insolum Aatrin Atukkiya / Sutraththaal Sutrap Patum", english: "He will be surrounded by numerous relatives who manifests generosity and affability" },
  { number: 526, tamil: "பெருங்கொடையான் பேணான் வெகுளி அவனின்\nமருங்குடையார் மாநிலத்து இல்.", transliteration: "Perungotaiyaan Penaan Vekuli Avanin / Marungutaiyaar Maanilaththu Il", english: "No one, in all the world, will have so many relatives (about him), as he who makes large gift, and does not give way to anger" },
  { number: 527, tamil: "காக்கை கரவா கரைந்துண்ணும் ஆக்கமும்\nஅன்னநீ ரார்க்கே உள.", transliteration: "Kaakkai Karavaa Karaindhunnum Aakkamum / Annanee Raarkke Ula", english: "The crows do not conceal (their prey), but will call out for others (to share with them) while they eat it; wealth will be with those who show a similar disposition (towards their relatives)" },
  { number: 528, tamil: "பொதுநோக்கான் வேந்தன் வரிசையா நோக்கின்\nஅதுநோக்கி வாழ்வார் பலர்.", transliteration: "Podhunokkaan Vendhan Varisaiyaa Nokkin / Adhunokki Vaazhvaar Palar", english: "Many relatives will live near a king, when they observe that he does not look on all alike, but that he looks on each man according to his merit" },
  { number: 529, tamil: "தமராகிக் தற்றுறந்தார் சுற்றம் அமராமைக்\nகாரணம் இன்றி வரும்.", transliteration: "Thamaraakik Thatrurandhaar Sutram Amaraamaik / Kaaranam Indri Varum", english: "Those who have been friends and have afterwards forsaken him, will return and join themselves (to him), when the cause of disagreement is not to be found in him" },
  { number: 530, tamil: "உழைப்பிரிந்து காரணத்தின் வந்தானை வேந்தன்\nஇழைத் திருந்து எண்ணிக் கொளல்.", transliteration: "Uzhaippirindhu Kaaranaththin Vandhaanai Vendhan / Izhaith Thirundhu Ennik Kolal", english: "When one may have left him, and for some cause has returned to him, let the king fulfil the object (for which he has come back) and thoughtfully receive him again" },
  { number: 531, tamil: "இறந்த வெகுளியின் தீதே சிறந்த\nஉவகை மகிழ்ச்சியிற் சோர்வு.", transliteration: "Irandha Vekuliyin Theedhe Sirandha / Uvakai Makizhchchiyir Sorvu", english: "More evil than excessive anger, is forgetfulness which springs from the intoxication of great joy" },
  { number: 532, tamil: "பொச்சாப்புக் கொல்லும் புகழை அறிவினை\nநிச்ச நிரப்புக் கொன் றாங்கு.", transliteration: "Pochchaappuk Kollum Pukazhai Arivinai / Nichcha Nirappuk Kon Raangu", english: "Forgetfulness will destroy fame, even as constant poverty destroys knowledge" },
  { number: 533, tamil: "பொச்சாப்பார்க் கில்லை புகழ்மை அதுஉலகத்து\nஎப்பால்நூ லோர்க்கும் துணிவு.", transliteration: "Pochchaappaark Killai Pukazhmai Adhuulakaththu / Eppaalnoo Lorkkum Thunivu", english: "Thoughtlessness will never acquire fame; and this tenet is upheld by all treatises in the world" },
  { number: 534, tamil: "அச்ச முடையார்க்கு அரணில்லை ஆங்கில்லை\nபொச்சாப் புடையார்க்கு நன்கு.", transliteration: "Achcha Mutaiyaarkku Aranillai Aangillai / Pochchaap Putaiyaarkku Nanku", english: "Just as the coward has no defence (by whatever fortifications ha may be surrounded), so the thoughtless has no good (whatever advantages he may possess)" },
  { number: 535, tamil: "முன்னுறக் காவாது இழுக்கியான் தன்பிழை\nபின்னூறு இரங்கி விடும்.", transliteration: "Munnurak Kaavaadhu Izhukkiyaan Thanpizhai / Pinnooru Irangi Vitum", english: "The thoughtless man, who provides not against the calamities that may happen, will afterwards repent for his fault" },
  { number: 536, tamil: "இழுக்காமை யார்மாட்டும் என்றும் வழுக்காமை\nவாயின் அதுவொப்பது இல்.", transliteration: "Izhukkaamai Yaarmaattum Endrum Vazhukkaamai / Vaayin Adhuvoppadhu Il", english: "There is nothing comparable with the possession of unfailing thoughtfulness at all times; and towards all persons" },
  { number: 537, tamil: "அரியஎன்று ஆகாத இல்லைபொச் சாவாக்\nகருவியால் போற்றிச் செயின்.", transliteration: "Ariyaendru Aakaadha Illaipoch Chaavaak / Karuviyaal Potrich Cheyin", english: "There is nothing too difficult to be accomplished, if a man set about it carefully, with unflinching endeavour" },
  { number: 538, tamil: "புகழ்ந்தவை போற்றிச் செயல்வேண்டும் செய்யாது\nஇகழ்ந்தார்க்கு எழுமையும் இல்.", transliteration: "Pukazhndhavai Potrich Cheyalventum Seyyaadhu / Ikazhndhaarkku Ezhumaiyum Il", english: "Let (a man) observe and do these things which have been praised (by the wise); if he neglects and fails to perform them, for him there will be no (happiness) throughout the seven births" },
  { number: 539, tamil: "இகழ்ச்சியின் கெட்டாரை உள்ளுக தாந்தம்\nமகிழ்ச்சியின் மைந்துறும் போழ்து.", transliteration: "Ikazhchchiyin Kettaarai Ulluka Thaandham / Makizhchchiyin Maindhurum Pozhdhu", english: "Let (a king) think of those who have been ruined by neglect, when his mind is elated with joy" },
  { number: 540, tamil: "உள்ளியது எய்தல் எளிதுமன் மற்றுந்தான்\nஉள்ளியது உள்ளப் பெறின்.", transliteration: "Ulliyadhu Eydhal Elidhuman Matrundhaan / Ulliyadhu Ullap Perin", english: "It is easy for (one) to obtain whatever he may think of, if he can again think of it" },
  { number: 541, tamil: "ஓர்ந்துகண் ணோடாது இறைபுரிந்து யார்மாட்டும்\nதேர்ந்துசெய் வஃதே முறை.", transliteration: "Orndhukan Notaadhu Iraipurindhu Yaarmaattum / Therndhusey Vaqdhe Murai", english: "To examine into (the crimes which may be committed), to show no favour (to any one), to desire to act with impartiality towards all, and to inflict (such punishments) as may be wisely resolved on," },
  { number: 542, tamil: "வானோக்கி வாழும் உலகெல்லாம் மன்னவன்\nகோல் நோக்கி வாழுங் குடி.", transliteration: "Vaanokki Vaazhum Ulakellaam Mannavan / Kol Nokki Vaazhung Kuti", english: "When there is rain, the living creation thrives; and so when the king rules justly, his subjects thrive" },
  { number: 543, tamil: "அந்தணர் நூற்கும் அறத்திற்கும் ஆதியாய்\nநின்றது மன்னவன் கோல்.", transliteration: "Andhanar Noorkum Araththirkum Aadhiyaai / Nindradhu Mannavan Kol", english: "The sceptre of the king is the firm support of the Vedas of the Brahmin, and of all virtues therein described" },
  { number: 544, tamil: "குடிதழீஇக் கோலோச்சும் மாநில மன்னன்\nஅடிதழீஇ நிற்கும் உலகு.", transliteration: "Kutidhazheeik Kolochchum Maanila Mannan / Atidhazheei Nirkum Ulaku", english: "The world will constantly embrace the feet of the great king who rules over his subjects with love" },
  { number: 545, tamil: "இயல்புளிக் கோலோச்சும் மன்னவன் நாட்ட\nபெயலும் விளையுளும் தொக்கு.", transliteration: "Iyalpulik Kolochchum Mannavan Naatta / Peyalum Vilaiyulum Thokku", english: "Rain and plentiful crops will ever dwell together in the country of the king who sways his sceptre with justice" },
  { number: 546, tamil: "வேலன்று வென்றி தருவது மன்னவன்\nகோலதூஉங் கோடா தெனின்.", transliteration: "Velandru Vendri Tharuvadhu Mannavan / Koladhooung Kotaa Thenin", english: "It is not the javelin that gives victory, but the king's sceptre, if it do no injustice" },
  { number: 547, tamil: "இறைகாக்கும் வையகம் எல்லாம் அவனை\nமுறைகாக்கும் முட்டாச் செயின்.", transliteration: "Iraikaakkum Vaiyakam Ellaam Avanai / Muraikaakkum Muttaach Cheyin", english: "The king defends the whole world; and justice, when administered without defect, defends the king" },
  { number: 548, tamil: "எண்பதத்தான் ஓரா முறைசெய்யா மன்னவன்\nதண்பதத்தான் தானே கெடும்.", transliteration: "Enpadhaththaan Oraa Muraiseyyaa Mannavan / Thanpadhaththaan Thaane Ketum", english: "The king who gives not facile audience (to those who approach him), and who does not examine and pass judgment (on their complaints), will perish in disgrace" },
  { number: 549, tamil: "குடிபுறங் காத்தோம்பிக் குற்றம் கடிதல்\nவடுவன்று வேந்தன் தொழில்.", transliteration: "Kutipurang Kaaththompik Kutram Katidhal / Vatuvandru Vendhan Thozhil", english: "In guarding his subjects (against injury from others), and in preserving them himself; to punish crime" },
  { number: 550, tamil: "கொலையிற் கொடியாரை வேந்தொறுத்தல் பைங்கூழ்\nகளைகட் டதனொடு நேர்.", transliteration: "Kolaiyir Kotiyaarai Vendhoruththal Paingoozh / Kalaikat Tadhanotu Ner", english: "For a king to punish criminals with death, is like pulling up the weeds in the green corn" },
  { number: 551, tamil: "கொலைமேற்கொண் டாரிற் கொடிதே அலைமேற்கொண்டு\nஅல்லவை செய்தொழுகும் வேந்து.", transliteration: "Kolaimerkon Taarir Kotidhe Alaimerkontu / Allavai Seydhozhukum Vendhu", english: "The king who gives himself up to oppression and acts unjustly (towards his subjects) is more cruel than the man who leads the life of a murderer" },
  { number: 552, tamil: "வேலொடு நின்றான் இடுவென் றதுபோலும்\nகோலொடு நின்றான் இரவு.", transliteration: "Velotu Nindraan Ituven Radhupolum / Kolotu Nindraan Iravu", english: "The request (for money) of him who holds the sceptre is like the word of a highway robber who stands with a weapon in hand and says \"give up your wealth\"" },
  { number: 553, tamil: "நாடொறும் நாடி முறைசெய்யா மன்னவன்\nநாடொறும் நாடு கெடும்.", transliteration: "Naatorum Naati Muraiseyyaa Mannavan / Naatorum Naatu Ketum", english: "The country of the king who does not daily examine into the wrongs done and distribute justice, will daily fall to ruin" },
  { number: 554, tamil: "கூழுங் குடியும் ஒருங்கிழக்கும் கோல்கோடிச்\nசூழாது செய்யும் அரசு.", transliteration: "Koozhung Kutiyum Orungizhakkum Kolkotich / Choozhaadhu Seyyum Arasu", english: "The king, who, without reflecting (on its evil consequences), perverts justice, will lose at once both his wealth and his subjects" },
  { number: 555, tamil: "அல்லற்பட்டு ஆற்றாது அழுதகண் ணீரன்றே\nசெல்வத்தைத் தேய்க்கும் படை", transliteration: "Allarpattu Aatraadhu Azhudhakan Neerandre / Selvaththaith Theykkum Patai", english: "Will not the tears, shed by a people who cannot endure the oppression which they suffer (from their king), become a saw to waste away his wealth ?" },
  { number: 556, tamil: "மன்னர்க்கு மன்னுதல் செங்கோன்மை அஃதின்றேல்\nமன்னாவாம் மன்னர்க் கொளி.", transliteration: "Mannarkku Mannudhal Sengonmai Aqdhindrel / Mannaavaam Mannark Koli", english: "Righteous government gives permanence to (the fame of) kings; without that their fame will have no endurance" },
  { number: 557, tamil: "துளியின்மை ஞாலத்திற்கு எற்றற்றே வேந்தன்\nஅளியின்மை வாழும் உயிர்க்கு.", transliteration: "Thuliyinmai Gnaalaththirku Etratre Vendhan / Aliyinmai Vaazhum Uyirkku", english: "As is the world without rain, so live a people whose king is without kindness" },
  { number: 558, tamil: "இன்மையின் இன்னாது உடைமை முறைசெய்யா\nமன்னவன் கோற்கீழ்ப் படின்.", transliteration: "Inmaiyin Innaadhu Utaimai Muraiseyyaa / Mannavan Korkeezhp Patin", english: "Property gives more sorrow than poverty, to those who live under the sceptre of a king without justice" },
  { number: 559, tamil: "முறைகோடி மன்னவன் செய்யின் உறைகோடி\nஒல்லாது வானம் பெயல்.", transliteration: "Muraikoti Mannavan Seyyin Uraikoti / Ollaadhu Vaanam Peyal", english: "If the king acts contrary to justice, rain will become unseasonable, and the heavens will withhold their showers" },
  { number: 560, tamil: "ஆபயன் குன்றும் அறுதொழிலோர் நூல்மறப்பர்\nகாவலன் காவான் எனின்.", transliteration: "Aapayan Kundrum Arudhozhilor Noolmarappar / Kaavalan Kaavaan Enin", english: "If the guardian (of the country) neglects to guard it, the produce of the cows will fail, and the men of six duties viz, the Brahmins will forget the vedas" },
  { number: 561, tamil: "தக்காங்கு நாடித் தலைச்செல்லா வண்ணத்தால்\nஒத்தாங்கு ஒறுப்பது வேந்து.", transliteration: "Thakkaangu Naatith Thalaichchellaa Vannaththaal / Oththaangu Oruppadhu Vendhu", english: "He is a king who having equitably examined (any injustice which has been brought to his notice), suitably punishes it, so that it may not be again committed" },
  { number: 562, tamil: "கடிதோச்சி மெல்ல எறிக நெடிதாக்கம்\nநீங்காமை வேண்டு பவர்.", transliteration: "Katidhochchi Mella Erika Netidhaakkam / Neengaamai Ventu Pavar", english: "Let the king, who desires that his prosperity may long remain, commence his preliminary enquires with strictness, and then punish with mildness" },
  { number: 563, tamil: "வெருவந்த செய்தொழுகும் வெங்கோல னாயின்\nஒருவந்தம் ஒல்லைக் கெடும்.", transliteration: "Veruvandha Seydhozhukum Vengola Naayin / Oruvandham Ollaik Ketum", english: "The cruel-sceptred king, who acts so as to put his subjects in fear, will certainly and quickly come to ruin" },
  { number: 564, tamil: "இறைகடியன் என்றுரைக்கும் இன்னாச்சொல் வேந்தன்\nஉறைகடுகி ஒல்லைக் கெடும்.", transliteration: "Iraikatiyan Endruraikkum Innaachchol Vendhan / Uraikatuki Ollaik Ketum", english: "The king who is spoken of as cruel will quickly perish; his life becoming shortened" },
  { number: 565, tamil: "அருஞ்செவ்வி இன்னா முகத்தான் பெருஞ்செல்வம்\nபேஎய்கண் டன்னது உடைத்து.", transliteration: "Arunjevvi Innaa Mukaththaan Perunjelvam / Peeykan Tannadhu Utaiththu", english: "The great wealth of him who is difficult of access and possesses a sternness of countenance, is like that which has been obtained by a devil" },
  { number: 566, tamil: "கடுஞ்சொல்லன் கண்ணிலன் ஆயின் நெடுஞ்செல்வம்\nநீடின்றி ஆங்கே கெடும்.", transliteration: "Katunjollan Kannilan Aayin Netunjelvam / Neetindri Aange Ketum", english: "The abundant wealth of the king whose words are harsh and whose looks are void of kindness, will instantly perish instead of abiding long, with him" },
  { number: 567, tamil: "கடுமொழியும் கையிகந்த தண்டமும் வேந்தன்\nஅடுமுரண் தேய்க்கும் அரம்.", transliteration: "Katumozhiyum Kaiyikandha Thantamum Vendhan / Atumuran Theykkum Aram", english: "Severe words and excessive punishments will be a file to waste away a king's power for destroying (his enemies)" },
  { number: 568, tamil: "இனத்தாற்றி எண்ணாத வேந்தன் சினத்தாற்றிச்\nசீறிற் சிறுகும் திரு.", transliteration: "Inaththaatri Ennaadha Vendhan Sinaththaatrich / Cheerir Sirukum Thiru", english: "The prosperity of that king will waste away, who without reflecting (on his affairs himself), commits them to his ministers, and (when a failure occurs) gives way to anger, and rages against them" },
  { number: 569, tamil: "செருவந்த போழ்திற் சிறைசெய்யா வேந்தன்\nவெருவந்து வெய்து கெடும்.", transliteration: "Seruvandha Pozhdhir Siraiseyyaa Vendhan / Veruvandhu Veydhu Ketum", english: "The king who has not provided himself with a place of defence, will in times of war be seized with fear and quickly perish" },
  { number: 570, tamil: "கல்லார்ப் பிணிக்கும் கடுங்கோல் அதுவல்லது\nஇல்லை நிலக்குப் பொறை.", transliteration: "Kallaarp Pinikkum Katungol Adhuvalladhu / Illai Nilakkup Porai", english: "The earth bears up no greater burden than ignorant men whom a cruel sceptre attaches to itself (as the ministers of its evil deeds)" },
  { number: 571, tamil: "கண்ணோட்டம் என்னும் கழிபெருங் காரிகை\nஉண்மையான் உண்டிவ் வுலகு.", transliteration: "Kannottam Ennum Kazhiperung Kaarikai / Unmaiyaan Untiv Vulaku", english: "The world exists through that greatest ornament (of princes), a gracious demeanour" },
  { number: 572, tamil: "கண்ணோட்டத் துள்ளது உலகியல் அஃதிலார்\nஉண்மை நிலக்குப் பொறை.", transliteration: "Kannottath Thulladhu Ulakiyal Aqdhilaar / Unmai Nilakkup Porai", english: "The prosperity of the world springs from the kindliness, the existence of those who have no (kindliness) is a burden to the earth" },
  { number: 573, tamil: "பண்என்னாம் பாடற்கு இயைபின்றேல் கண்என்னாம்\nகண்ணோட்டம் இல்லாத கண்.", transliteration: "Panennaam Paatarku Iyaipindrel Kanennaam / Kannottam Illaadha Kan", english: "Of what avail is a song if it be inconsistent with harmony ? what is the use of eyes which possess no kindliness" },
  { number: 574, tamil: "உளபோல் முகத்தெவன் செய்யும் அளவினால்\nகண்ணோட்டம் இல்லாத கண்.", transliteration: "Ulapol Mukaththevan Seyyum Alavinaal / Kannottam Illaadha Kan", english: "Beyond appearing to be in the face, what good do they do, those eyes in which is no well-regulated kindness ?" },
  { number: 575, tamil: "கண்ணிற்கு அணிகலம் கண்ணோட்டம் அஃதின்றேல்\nபுண்ணென்று உணரப் படும்", transliteration: "Kannirku Anikalam Kannottam Aqdhindrel / Punnendru Unarap Patum", english: "Kind looks are the ornaments of the eyes; without these they will be considered (by the wise) to be merely two sores" },
  { number: 576, tamil: "மண்ணோ டியைந்த மரத்தனையர் கண்ணோ\nடியைந்துகண் ணோடா தவர்.", transliteration: "Manno Tiyaindha Maraththanaiyar Kanno / Tiyaindhukan Notaa Thavar", english: "They resemble the trees of the earth, who although they have eyes, never look kindly (on others)" },
  { number: 577, tamil: "கண்ணோட்டம் இல்லவர் கண்ணிலர் கண்ணுடையார்\nகண்ணோட்டம் இன்மையும் இல்.", transliteration: "Kannottam Illavar Kannilar Kannutaiyaar / Kannottam Inmaiyum Il", english: "Men without kind looks are men without eyes; those who (really) have eyes are also not devoid of kind looks" },
  { number: 578, tamil: "கருமம் சிதையாமல் கண்ணோட வல்லார்க்கு\nஉரிமை உடைத்திவ் வுலகு.", transliteration: "Karumam Sidhaiyaamal Kannota Vallaarkku / Urimai Utaiththiv Vulaku", english: "The world is theirs (kings) who are able to show kindness, without injury to their affairs, (administration of justice)" },
  { number: 579, tamil: "ஒறுத்தாற்றும் பண்பினார் கண்ணும்கண் ணோடிப்\nபொறுத்தாற்றும் பண்பே தலை.", transliteration: "Oruththaatrum Panpinaar Kannumkan Notip / Poruththaatrum Panpe Thalai", english: "Patiently to bear with, and show kindness to those who grieve us, is the most excellent of all dispositions" },
  { number: 580, tamil: "பெயக்கண்டும் நஞ்சுண் டமைவர் நயத்தக்க\nநாகரிகம் வேண்டு பவர்.", transliteration: "Peyakkantum Nanjun Tamaivar Nayaththakka / Naakarikam Ventu Pavar", english: "Those who desire (to cultivate that degree of) urbanity which all shall love, even after swallowing the poison served to them by their friends, will be friendly with them" },
  { number: 581, tamil: "ஒற்றும் உரைசான்ற நூலும் இவையிரண்டும்\nதெற்றென்க மன்னவன் கண்.", transliteration: "Otrum Uraisaandra Noolum Ivaiyirantum / Thetrenka Mannavan Kan", english: "Let a king consider as his eyes these two things, a spy and a book (of laws) universally esteemed" },
  { number: 582, tamil: "எல்லார்க்கும் எல்லாம் நிகழ்பவை எஞ்ஞான்றும்\nவல்லறிதல் வேந்தன் தொழில்.", transliteration: "Ellaarkkum Ellaam Nikazhpavai Egngnaandrum / Vallaridhal Vendhan Thozhil", english: "'Tis duty of the king to learn with speed" },
  { number: 583, tamil: "ஒற்றினான் ஒற்றிப் பொருள்தெரியா மன்னவன்\nகொற்றங் கொளக்கிடந்தது இல்.", transliteration: "Otrinaan Otrip Poruldheriyaa Mannavan / Kotrang Kolakkitandhadhu Il", english: "There is no way for a king to obtain conquests, who knows not the advantage of discoveries made by a spy" },
  { number: 584, tamil: "வினைசெய்வார் தம்சுற்றம் வேண்டாதார் என்றாங்கு\nஅனைவரையும் ஆராய்வது ஒற்று.", transliteration: "Vinaiseyvaar Thamsutram Ventaadhaar Endraangu / Anaivaraiyum Aaraaivadhu Otru", english: "He is a spy who watches all men, to wit, those who are in the king's employment, his relatives, and his enemies" },
  { number: 585, tamil: "கடாஅ உருவொடு கண்ணஞ்சாது யாண்டும்\nஉகாஅமை வல்லதே ஒற்று.", transliteration: "Kataaa Uruvotu Kannanjaadhu Yaantum / Ukaaamai Valladhe Otru", english: "A spy is one who is able to assume an appearance which may create no suspicion (in the minds of others), who fears no man's face, and who never reveals (his purpose)" },
  { number: 586, tamil: "துறந்தார் படிவத்த ராகி இறந்தாராய்ந்து\nஎன்செயினும் சோர்விலது ஒற்று.", transliteration: "Thurandhaar Pativaththa Raaki Irandhaaraaindhu / Enseyinum Sorviladhu Otru", english: "He is a spy who, assuming the appearance of an ascetic, goes into (whatever place he wishes), examines into (all, that is needful), and never discovers himself, whatever may be done to him" },
  { number: 587, tamil: "மறைந்தவை கேட்கவற் றாகி அறிந்தவை\nஐயப்பாடு இல்லதே ஒற்று.", transliteration: "Maraindhavai Ketkavar Raaki Arindhavai / Aiyappaatu Illadhe Otru", english: "A spy is one who is able to discover what is hidden and who retains no doubt concerning what he has known" },
  { number: 588, tamil: "ஒற்றொற்றித் தந்த பொருளையும் மற்றுமோர்\nஒற்றினால் ஒற்றிக் கொளல்.", transliteration: "Otrotrith Thandha Porulaiyum Matrumor / Otrinaal Otrik Kolal", english: "Let not a king receive the information which a spy has discovered and made known to him, until he has examined it by another spy" },
  { number: 589, tamil: "ஒற்றெற் றுணராமை ஆள்க உடன்மூவர்\nசொற்றொக்க தேறப் படும்.", transliteration: "Otrer Runaraamai Aalka Utanmoovar / Sotrokka Therap Patum", english: "Let a king employ spies so that one may have no knowledge of the other; and when the information of three agrees together, let him receive it" },
  { number: 590, tamil: "சிறப்பறிய ஒற்றின்கண் செய்யற்க செய்யின்\nபுறப்படுத்தான் ஆகும் மறை.", transliteration: "Sirappariya Otrinkan Seyyarka Seyyin / Purappatuththaan Aakum Marai", english: "Let not a king publicly confer on a spy any marks of his favour; if he does, he will divulge his own secret" },
  { number: 591, tamil: "உடையர் எனப்படுவது ஊக்கம் அஃதில்லார்\nஉடையது உடையரோ மற்று.", transliteration: "Utaiyar Enappatuvadhu Ookkam Aqdhillaar / Utaiyadhu Utaiyaro Matru", english: "Energy makes out the man of property; as for those who are destitute of it, do they (really) possess what they possess ?" },
  { number: 592, tamil: "உள்ளம் உடைமை உடைமை பொருளுடைமை\nநில்லாது நீங்கி விடும்.", transliteration: "Ullam Utaimai Utaimai Porulutaimai / Nillaadhu Neengi Vitum", english: "The possession of (energy of) mind is true property; the possession of wealth passes away and abides not" },
  { number: 593, tamil: "ஆக்கம் இழந்தேமென்று அல்லாவார் ஊக்கம்\nஒருவந்தம் கைத்துடை யார்.", transliteration: "Aakkam Izhandhemendru Allaavaar Ookkam / Oruvandham Kaiththutai Yaar", english: "They who are possessed of enduring energy will not trouble themselves, saying, \"we have lost our property.\"" },
  { number: 594, tamil: "ஆக்கம் அதர்வினாய்ச் செல்லும் அசைவிலா\nஊக்க முடையா னுழை.", transliteration: "Aakkam Adharvinaaich Chellum Asaivilaa / Ookka Mutaiyaa Nuzhai", english: "Wealth will find its own way to the man of unfailing energy" },
  { number: 595, tamil: "வெள்ளத் தனைய மலர்நீட்டம் மாந்தர்தம்\nஉள்ளத் தனையது உயர்வு.", transliteration: "Vellath Thanaiya Malarneettam Maandhardham / Ullath Thanaiyadhu Uyarvu", english: "The stalks of water-flowers are proportionate to the depth of water; so is men's greatness proportionate to their minds" },
  { number: 596, tamil: "உள்ளுவ தெல்லாம் உயர்வுள்ளல் மற்றது\nதள்ளினுந் தள்ளாமை நீர்த்து.", transliteration: "Ulluva Thellaam Uyarvullal Matradhu / Thallinun Thallaamai Neerththu", english: "In all that a king thinks of, let him think of his greatness; and if it should be thrust from him (by fate), it will have the nature of not being thrust from him" },
  { number: 597, tamil: "சிதைவிடத்து ஒல்கார் உரவோர் புதையம்பிற்\nபட்டுப்பா டூன்றுங் களிறு.", transliteration: "Sidhaivitaththu Olkaar Uravor Pudhaiyampir / Pattuppaa Toondrung Kaliru", english: "The strong minded will not faint, even when all is lost; the elephant stands firm, even when wounded by a shower of arrows" },
  { number: 598, tamil: "உள்ளம் இலாதவர் எய்தார் உலகத்து\nவள்ளியம் என்னுஞ் செருக்கு.", transliteration: "Ullam Ilaadhavar Eydhaar Ulakaththu / Valliyam Ennunj Cherukku", english: "Those who have no (greatness of) mind, will not acquire the joy of saying in the world, \"we have excercised liaberality\"" },
  { number: 599, tamil: "பரியது கூர்ங்கோட்டது ஆயினும் யானை\n஦வ்ருஉம் புலிதாக் குறின்.", transliteration: "Pariyadhu Koorngottadhu Aayinum Yaanai / Veruum Pulidhaak Kurin", english: "Although the elephant has a large body, and a sharp tusk, yet it fears the attack of the tiger" },
  { number: 600, tamil: "உரமொருவற்கு உள்ள வெறுக்கைஅஃ தில்லார்\nமரம்மக்க ளாதலே வேறு.", transliteration: "Uramoruvarku Ulla Verukkaiaq Thillaar / Marammakka Laadhale Veru", english: "Energy is mental wealth; those men who are destitute of it are only trees in the form of men" },
  { number: 601, tamil: "குடியென்னும் குன்றா விளக்கம் மடியென்னும்\nமாசூர மாய்ந்து கெடும்.", transliteration: "Kutiyennum Kundraa Vilakkam Matiyennum / Maasoora Maaindhu Ketum", english: "By the darkness, of idleness, the indestructible lamp of family (rank) will be extinguished" },
  { number: 602, tamil: "மடியை மடியா ஒழுகல் குடியைக்\nகுடியாக வேண்டு பவர்.", transliteration: "Matiyai Matiyaa Ozhukal Kutiyaik / Kutiyaaka Ventu Pavar", english: "Let those, who desire that their family may be illustrious, put away all idleness from their conduct" },
  { number: 603, tamil: "மடிமடிக் கொண்டொழுகும் பேதை பிறந்த\nகுடிமடியும் தன்னினும் முந்து.", transliteration: "Matimatik Kontozhukum Pedhai Pirandha / Kutimatiyum Thanninum Mundhu", english: "The (lustre of the) family of the ignorant man, who acts under the influence of destructive laziness will perish, even before he is dead" },
  { number: 604, tamil: "குடிமடிந்து குற்றம் பெருகும் மடிமடிந்து\nமாண்ட உஞற்றி லவர்க்கு.", transliteration: "Kutimatindhu Kutram Perukum Matimatindhu / Maanta Ugnatri Lavarkku", english: "Family (greatness) will be destroyed, and faults will increase, in those men who give way to laziness, and put forth no dignified exertions" },
  { number: 605, tamil: "நெடுநீர் மறவி மடிதுயில் நான்கும்\nகெடுநீரார் காமக் கலன்.", transliteration: "Netuneer Maravi Matidhuyil Naankum / Ketuneeraar Kaamak Kalan", english: "Procrastination, forgetfulness, idleness, and sleep, these four things, form the vessel which is desired by those destined to destruction" },
  { number: 606, tamil: "படியுடையார் பற்றமைந்தக் கண்ணும் மடியுடையார்\nமாண்பயன் எய்தல் அரிது.", transliteration: "Patiyutaiyaar Patramaindhak Kannum Matiyutaiyaar / Maanpayan Eydhal Aridhu", english: "It is a rare thing for the idle, even when possessed of the riches of kings who ruled over the whole earth, to derive any great benefit from it" },
  { number: 607, tamil: "இடிபுரிந்து எள்ளுஞ்சொல் கேட்பர் மடிபுரிந்து\nமாண்ட உஞற்றி லவர்.", transliteration: "Itipurindhu Ellunj Chol Ketpar / Matipurindhu Maanta Ugnatri Lavar", english: "Those who through idleness, and do not engage themselves in dignified exertion, will subject" },
  { number: 608, tamil: "மடிமை குடிமைக்கண் தங்கின்தன் ஒன்னார்க்கு\nஅடிமை புகுத்தி விடும்.", transliteration: "Matimai Kutimaikkan Thangindhan Onnaarkku / Atimai Pukuththi Vitum", english: "If idleness take up its abode in a king of high birth, it will make him a slave of his enemies" },
  { number: 609, tamil: "குடியாண்மை யுள்வந்த குற்றம் ஒருவன்\nமடியாண்மை மாற்றக் கெடும்.", transliteration: "Kutiyaanmai Yulvandha Kutram Oruvan / Matiyaanmai Maatrak Ketum", english: "When a man puts away idleness, the reproach which has come upon himself and his family will disappear" },
  { number: 610, tamil: "மடியிலா மன்னவன் எய்தும் அடியளந்தான்\nதாஅய தெல்லாம் ஒருங்கு.", transliteration: "Matiyilaa Mannavan Eydhum Atiyalandhaan / Thaaaya Thellaam Orungu", english: "The king who never gives way to idleness will obtain entire possession of (the whole earth) passed over by him who measured (the worlds) with His foot" },
  { number: 611, tamil: "அருமை உடைத்தென்று அசாவாமை வேண்டும்\nபெருமை முயற்சி தரும்.", transliteration: "Arumai Utaiththendru Asaavaamai Ventum / Perumai Muyarsi Tharum", english: "Yield not to the feebleness which says, \"this is too difficult to be done\"; labour will give the greatness (of mind) which is necessary (to do it)" },
  { number: 612, tamil: "வினைக்கண் வினைகெடல் ஓம்பல் வினைக்குறை\nதீர்ந்தாரின் தீர்ந்தன்று உலகு.", transliteration: "Vinaikkan Vinaiketal Ompal Vinaikkurai / Theerndhaarin Theerndhandru Ulaku", english: "Take care not to give up exertion in the midst of a work; the world will abandon those who abandon their unfinished work" },
  { number: 613, tamil: "தாளாண்மை என்னும் தகைமைக்கண் தங்கிற்றே\nவேளாண்மை என்னுஞ் செருக்கு.", transliteration: "Thaalaanmai Ennum Thakaimaikkan Thangitre / Velaanmai Ennunj Cherukku", english: "The lustre of munificence will dwell only with the dignity of laboriousness or efforts" },
  { number: 614, tamil: "தாளாண்மை இல்லாதான் வேளாண்மை பேடிகை\nவாளாண்மை போலக் கெடும்.", transliteration: "Thaalaanmai Illaadhaan Velaanmai Petikai / Vaalaanmai Polak Ketum", english: "The liberality of him, who does not labour, will fail, like the manliness of a hermaphrodite, who has a sword in its hand" },
  { number: 615, tamil: "இன்பம் விழையான் வினைவிழைவான் தன்கேளிர்\nதுன்பம் துடைத்தூன்றும் தூண்.", transliteration: "Inpam Vizhaiyaan Vinaivizhaivaan Thankelir / Thunpam Thutaiththoondrum Thoon", english: "He who desires not pleasure, but desires labour, will be a pillar to sustain his relations, wiping away their sorrows" },
  { number: 616, tamil: "முயற்சி திருவினை ஆக்கும் முயற்றின்மை\nஇன்மை புகுத்தி விடும்.", transliteration: "Muyarsi Thiruvinai Aakkum Muyatrinmai / Inmai Pukuththi Vitum", english: "Labour will produce wealth; idleness will bring poverty" },
  { number: 617, tamil: "மடியுளாள் மாமுகடி என்ப மடியிலான்\nதாளுளான் தாமரையி னாள்.", transliteration: "Matiyulaal Maamukati Enpa Matiyilaan / Thaalulaan Thaamaraiyi Naal", english: "They say that the black Mudevi (the goddess of adversity) dwells with laziness, and the Latchmi (the goddess of prosperity) dwells with the labour of the industrious" },
  { number: 618, tamil: "பொறியின்மை யார்க்கும் பழியன்று அறிவறிந்து\nஆள்வினை இன்மை பழி.", transliteration: "Poriyinmai Yaarkkum Pazhiyandru Arivarindhu / Aalvinai Inmai Pazhi", english: "Adverse fate is no disgrace to any one; to be without exertion and without knowing what should be known, is disgrace" },
  { number: 619, tamil: "தெய்வத்தான் ஆகா தெனினும் முயற்சிதன்\nமெய்வருத்தக் கூலி தரும்.", transliteration: "Theyvaththaan Aakaa Theninum Muyarsidhan / Meyvaruththak Kooli Tharum", english: "Although it be said that, through fate, it cannot be attained, yet labour, with bodily exertion, will yield its reward" },
  { number: 620, tamil: "ஊழையும் உப்பக்கம் காண்பர் உலைவின்றித்\nதாழாது உஞற்று பவர்.", transliteration: "Oozhaiyum Uppakkam Kaanpar Ulaivindrith / Thaazhaadhu Ugnatru Pavar", english: "They who labour on, without fear and without fainting will see even fate (put) behind their back" },
  { number: 621, tamil: "இடுக்கண் வருங்கால் நகுக அதனை\nஅடுத்தூர்வது அஃதொப்ப தில்.", transliteration: "Itukkan Varungaal Nakuka Adhanai / Atuththoorvadhu Aqdhoppa Thil", english: "If troubles come, laugh; there is nothing like that, to press upon and drive away sorrow" },
  { number: 622, tamil: "வெள்ளத் தனைய இடும்பை அறிவுடையான்\nஉள்ளத்தின் உள்ளக் கெடும்.", transliteration: "Vellath Thanaiya Itumpai Arivutaiyaan / Ullaththin Ullak Ketum", english: "A flood of troubles will be overcome by the (courageous) thought which the minds of the wise will entertain, even in sorrow" },
  { number: 623, tamil: "இடும்பைக்கு இடும்பை படுப்பர் இடும்பைக்கு\nஇடும்பை படாஅ தவர்.", transliteration: "Itumpaikku Itumpai Patuppar Itumpaikku / Itumpai Pataaa Thavar", english: "They give sorrow to sorrow, who in sorrow do not suffer sorrow" },
  { number: 624, tamil: "மடுத்தவா யெல்லாம் பகடன்னான் உற்ற\nஇடுக்கண் இடர்ப்பாடு உடைத்து.", transliteration: "Matuththavaa Yellaam Pakatannaan Utra / Itukkan Itarppaatu Utaiththu", english: "Troubles will vanish (i.e., will be troubled) before the man who (struggles against difficulties) as a" },
  { number: 625, tamil: "அடுக்கி வரினும் அழிவிலான் உற்ற\nஇடுக்கண் இடுக்கட் படும்.", transliteration: "Atukki Varinum Azhivilaan Utra / Itukkan Itukkat Patum", english: "The troubles of that man will be troubled (and disappear) who, however thickly they may come upon him, does not abandon (his purpose)" },
  { number: 626, tamil: "அற்றேமென்று அல்லற் படுபவோ பெற்றேமென்று\nஓம்புதல் தேற்றா தவர்.", transliteration: "Atremendru Allar Patupavo Petremendru / Ompudhal Thetraa Thavar", english: "Will those men ever cry out in sorrow, \"we are destitute\" who, (in their prosperity), give not way to (undue desire) to keep their wealth" },
  { number: 627, tamil: "இலக்கம் உடம்பிடும்பைக் கென்று கலக்கத்தைக்\nகையாறாக் கொள்ளாதாம் மேல்.", transliteration: "Ilakkam Utampitumpaik Kendru Kalakkaththaik / Kaiyaaraak Kollaadhaam Mel", english: "The great will not regard trouble as trouble, knowing that the body is the butt of trouble" },
  { number: 628, tamil: "இன்பம் விழையான் இடும்பை இயல்பென்பான்\nதுன்பம் உறுதல் இலன்.", transliteration: "Inpam Vizhaiyaan Itumpai Iyalpenpaan / Thunpam Urudhal Ilan", english: "That man never experiences sorrow, who does not seek for pleasure, and who considers distress to be natural (to man)" },
  { number: 629, tamil: "இன்பத்துள் இன்பம் விழையாதான் துன்பத்துள்\nதுன்பம் உறுதல் இலன்.", transliteration: "Inpaththul Inpam Vizhaiyaadhaan Thunpaththul / Thunpam Urudhal Ilan", english: "He does not suffer sorrow, in sorrow who does not look for pleasure in pleasure" },
  { number: 630, tamil: "இன்னாமை இன்பம் எனக்கொளின் ஆகுந்தன்\nஒன்னார் விழையுஞ் சிறப்பு.", transliteration: "Innaamai Inpam Enakkolin Aakundhan / Onnaar Vizhaiyunj Chirappu", english: "The elevation, which even his enemies will esteem, will be gained by him, who regards pain as pleasure" },
  { number: 631, tamil: "கருவியும் காலமும் செய்கையும் செய்யும்\nஅருவினையும் மாண்டது அமைச்சு.", transliteration: "Karuviyum Kaalamum Seykaiyum Seyyum / Aruvinaiyum Maantadhu Amaichchu", english: "The minister is one who can make an excellent choice of means, time, manner of execution, and the difficult undertaking (itself)" },
  { number: 632, tamil: "வன்கண் குடிகாத்தல் கற்றறிதல் ஆள்வினையோடு\nஐந்துடன் மாண்டது அமைச்சு.", transliteration: "Vankan Kutikaaththal Katraridhal Aalvinaiyotu / Aindhutan Maantadhu Amaichchu", english: "The minister is one who in addition to the aforesaid five things excels in the possession of firmness," },
  { number: 633, tamil: "பிரித்தலும் பேணிக் கொளலும் பிரிந்தார்ப்\nபொருத்தலும் வல்ல தமைச்சு.", transliteration: "Piriththalum Penik Kolalum Pirindhaarp / Poruththalum Valla Thamaichchu", english: "The minister is one who can effect discord (among foes), maintain the good-will of his friends and restore to friendship those who have seceded (from him)" },
  { number: 634, tamil: "தெரிதலும் தேர்ந்து செயலும் ஒருதலையாச்\nசொல்லலும் வல்லது அமைச்சு.", transliteration: "Theridhalum Therndhu Seyalum Orudhalaiyaach / Chollalum Valladhu Amaichchu", english: "The minister is one who is able to comprehend (the whole nature of an undertaking), execute it in the best manner possible, and offer assuring advice (in time of necessity)" },
  { number: 635, tamil: "அறனறிந்து ஆன்றமைந்த சொல்லான்எஞ் ஞான்றுந்\nதிறனறிந்தான் தேர்ச்சித் துணை.", transliteration: "Aranarindhu Aandramaindha Sollaanenj Gnaandrun / Thiranarindhaan Therchchith Thunai", english: "He is the best helper (of the king) who understanding the duties, of the latter, is by his special learning, able to tender the fullest advice, and at all times conversant with the best method (of" },
  { number: 636, tamil: "மதிநுட்பம் நூலோடு உடையார்க்கு அதிநுட்பம்\nயாவுள முன்நிற் பவை.", transliteration: "Madhinutpam Noolotu Utaiyaarkku Adhinutpam / Yaavula Munnir Pavai", english: "What (contrivances) are there so acute as to resist those who possess natural acuteness in addition to learning ?" },
  { number: 637, tamil: "செயற்கை அறிந்தக் கடைத்தும் உலகத்து\nஇயற்கை அறிந்து செயல்.", transliteration: "Seyarkai Arindhak Kataiththum Ulakaththu / Iyarkai Arindhu Seyal", english: "Though you are acquainted with the (theoretical) methods (of performing an act), understand the ways of the world and act accordingly" },
  { number: 638, tamil: "அறிகொன்று அறியான் எனினும் உறுதி\nஉழையிருந்தான் கூறல் கடன்.", transliteration: "Arikondru Ariyaan Eninum Urudhi / Uzhaiyirundhaan Kooral Katan", english: "Although the king be utterly ignorant, it is the duty of the minister to give (him) sound advice" },
  { number: 639, tamil: "பழுதெண்ணும் மந்திரியின் பக்கததுள் தெவ்வோர்\nஎழுபது கோடி உறும்.", transliteration: "Pazhudhennum Mandhiriyin Pakkadhadhul Thevvor / Ezhupadhu Koti Urum", english: "Far better are seventy crores of enemies (for a king) than a minister at his side who intends (his) ruin" },
  { number: 640, tamil: "முறைப்படச் சூழ்ந்தும் முடிவிலவே செய்வர்\nதிறப்பாடு இலாஅ தவர்.", transliteration: "Muraippatach Choozhndhum Mutivilave Seyvar / Thirappaatu Ilaaa Thavar", english: "Those ministers who are destitute of (executive) ability will fail to carry out their projects, although they may have contrived aright" },
  { number: 641, tamil: "நாநலம் என்னும் நலனுடைமை அந்நலம்\nயாநலத்து உள்ளதூஉம் அன்று.", transliteration: "Naanalam Ennum Nalanutaimai Annalam / Yaanalaththu Ulladhooum Andru", english: "The possession of that goodness which is called the goodness of speech is (even to others) better than any other goodness" },
  { number: 642, tamil: "ஆக்கமுங் கேடும் அதனால் வருதலால்\nகாத்தோம்பல் சொல்லின்கட் சோர்வு.", transliteration: "Aakkamung Ketum Adhanaal Varudhalaal / Kaaththompal Sollinkat Sorvu", english: "Since (both) wealth and evil result from (their) speech, ministers should most carefully guard themselves against faultiness therein" },
  { number: 643, tamil: "கேட்டார்ப் பிணிக்கும் தகையவாய்க் கேளாரும்\nவேட்ப மொழிவதாம் சொல்.", transliteration: "Kettaarp Pinikkum Thakaiyavaaik Kelaarum / Vetpa Mozhivadhaam Sol", english: "The (minister's) speech is that which seeks (to express) elements as bind his friends (to himself) and is so delivered as to make even his enemies desire (his friendship)" },
  { number: 644, tamil: "திறனறிந்து சொல்லுக சொல்லை அறனும்\nபொருளும் அதனினூஉங்கு இல்.", transliteration: "Thiranarindhu Solluka Sollai Aranum / Porulum Adhaninooungu Il", english: "Understand the qualities (of your hearers) and (then) make your speech; for superior to it, there is neither virtue nor wealth" },
  { number: 645, tamil: "சொல்லுக சொல்லைப் பிறிதோர்சொல் அச்சொல்லை\nவெல்லுஞ்சொல் இன்மை அறிந்து.", transliteration: "Solluka Sollaip Piridhorsol Achchollai / Vellunjol Inmai Arindhu", english: "Deliver your speech, after assuring yourself that no counter speech can defeat your own" },
  { number: 646, tamil: "வேட்பத்தாஞ் சொல்லிப் பிறர்சொல் பயன்கோடல்\nமாட்சியின் மாசற்றார் கோள்.", transliteration: "Vetpaththaanj Chollip Pirarsol Payankotal / Maatchiyin Maasatraar Kol", english: "It is the opinion of those who are free from defects in diplomacy that the minister should speak so as to make his hearers desire (to hear more) and grasp the meaning of what he hears himself" },
  { number: 647, tamil: "சொலல்வல்லன் சோர்விலன் அஞ்சான் அவனை\nஇகல்வெல்லல் யார்க்கும் அரிது.", transliteration: "Solalvallan Sorvilan Anjaan Avanai / Ikalvellal Yaarkkum Aridhu", english: "It is impossible for any one to conquer him by intrique who possesses power of speech, and is neither faulty nor timid" },
  { number: 648, tamil: "விரைந்து தொழில்கேட்கும் ஞாலம் நிரந்தினிது\nசொல்லுதல் வல்லார்ப் பெறின்.", transliteration: "Viraindhu Thozhilketkum Gnaalam Nirandhinidhu / Solludhal Vallaarp Perin", english: "If there be those who can speak on various subjects in their proper order and in a pleasing manner, the world would readily accept them" },
  { number: 649, tamil: "பலசொல்லக் காமுறுவர் மன்றமா சற்ற\nசிலசொல்லல் தேற்றா தவர்.", transliteration: "Palasollak Kaamuruvar Mandramaa Satra / Silasollal Thetraa Thavar", english: "They will desire to utter many words, who do not know how to speak a few faultless ones" },
  { number: 650, tamil: "இணருழ்த்தும் நாறா மலரனையர் கற்றது\nஉணர விரித்துரையா தார்.", transliteration: "Inaruzhththum Naaraa Malaranaiyar Katradhu / Unara Viriththuraiyaa Thaar", english: "Those who are unable to set forth their acquirements (before others) are like flowers blossoming in a cluster and yet without fragrance" },
  { number: 651, tamil: "துணைநலம் ஆக்கம் த்ருஉம் வினைநலம்\nவேண்டிய எல்லாந் தரும்.", transliteration: "Thunainalam Aakkam Tharuum Vinainalam / Ventiya Ellaan Tharum", english: "The efficacy of support will yield (only) wealth; (but) the efficacy of action will yield all that is desired" },
  { number: 652, tamil: "என்றும் ஒருவுதல் வேண்டும் புகழொடு\nநன்றி பயவா வினை.", transliteration: "Endrum Oruvudhal Ventum Pukazhotu / Nandri Payavaa Vinai", english: "Ministers should at all times avoid acts which, in addition to fame, yield no benefit (for the future)" },
  { number: 653, tamil: "ஒஓதல் வேண்டும் ஒளிமாழ்கும் செய்வினை\nஆஅதும் என்னு மவர்.", transliteration: "Oodhal Ventum Olimaazhkum Seyvinai / Aaadhum Ennu Mavar", english: "Those who say, \"we will become (better)\" should avoid the performance of acts that would destroy (their fame)" },
  { number: 654, tamil: "இடுக்கண் படினும் இளிவந்த செய்யார்\nநடுக்கற்ற காட்சி யவர்.", transliteration: "Itukkan Patinum Ilivandha Seyyaar / Natukkatra Kaatchi Yavar", english: "Those who have infallible judgement though threatened with peril will not do acts which have brought disgrace (on former ministers)" },
  { number: 655, tamil: "எற்றென்று இரங்குவ செய்யற்க செய்வானேல்\nமற்றன்ன செய்யாமை நன்று.", transliteration: "Etrendru Iranguva Seyyarka Seyvaanel / Matranna Seyyaamai Nandru", english: "Let a minister never do acts of which he would have to grieve saying, \"what is this I have done\"; (but) should he do (them), it were good that he grieved not" },
  { number: 656, tamil: "ஈன்றாள் பசிகாண்பான் ஆயினுஞ் செய்யற்க\nசான்றோர் பழிக்கும் வினை.", transliteration: "Eendraal Pasikaanpaan Aayinunj Cheyyarka / Saandror Pazhikkum Vinai", english: "Though a minister may see his mother starve; let him do not act which the wise would (treat with contempt)" },
  { number: 657, tamil: "பழிமலைந்து எய்திய ஆக்கத்தின் சான்றோர்\nகழிநல் குரவே தலை.", transliteration: "Pazhimalaindhu Eydhiya Aakkaththin Saandror / Kazhinal Kurave Thalai", english: "Far more excellent is the extreme poverty of the wise than wealth obtained by heaping up of sinful" },
  { number: 658, tamil: "கடிந்த கடிந்தொரார் செய்தார்க்கு அவைதாம்\nமுடிந்தாலும் பீழை தரும்.", transliteration: "Katindha Katindhoraar Seydhaarkku Avaidhaam / Mutindhaalum Peezhai Tharum", english: "The actions of those, who have not desisted from doing deeds forbidden (by the great), will, even if they succeed, cause them sorrow" },
  { number: 659, tamil: "அழக்கொண்ட எல்லாம் அழப்போம் இழப்பினும்\nபிற்பயக்கும் நற்பா லவை.", transliteration: "Azhak Konta Ellaam Azhappom / Izhappinum Pirpayakkum Narpaa Lavai", english: "All that has been obtained with tears (to the victim) will depart with tears (to himself); but what has been by fair means; though with loss at first, will afterwards yield fruit" },
  { number: 660, tamil: "சலத்தால் பொருள்செய்தே மார்த்தல் பசுமண்\nகலத்துள்நீர் பெய்திரீஇ யற்று.", transliteration: "Salaththaal Porulseydhe Maarththal Pasuman / Kalaththulneer Peydhireei Yatru", english: "(For a minister) to protect (his king) with wealth obtained by foul means is like preserving a vessel of wet clay by filling it with water" },
  { number: 661, tamil: "வினைத்திட்பம் என்பது ஒருவன் மனத்திட்பம்\nமற்றைய எல்லாம் பிற.", transliteration: "Vinaiththitpam Enpadhu Oruvan Manaththitpam / Matraiya Ellaam Pira", english: "Firmness in action is (simply) one's firmness of mind; all other (abilities) are not of this nature" },
  { number: 662, tamil: "ஊறொரால் உற்றபின் ஒல்காமை இவ்விரண்டின்\nஆறென்பர் ஆய்ந்தவர் கோள்.", transliteration: "Oororaal Utrapin Olkaamai Ivvirantin / Aarenpar Aaindhavar Kol", english: "Not to perform a ruinous act, and not to be discouraged by the ruinous termination of an act, are the two maxims which, the wise say, from the principles of those who have investigated the subject" },
  { number: 663, tamil: "கடைக்கொட்கச் செய்தக்க தாண்மை இடைக்கொட்கின்\nஎற்றா விழுமந் தரும்.", transliteration: "Kataikkotkach Cheydhakka Thaanmai Itaikkotkin / Etraa Vizhuman Tharum", english: "So to perform an act as to publish it (only) at its termination is (true) manliness; for to announce it beforehand, will cause irremediable sorrow" },
  { number: 664, tamil: "சொல்லுதல் யார்க்கும் எளிய அரியவாம்\nசொல்லிய வண்ணம் செயல்.", transliteration: "Solludhal Yaarkkum Eliya Ariyavaam / Solliya Vannam Seyal", english: "To say (how an act is to be performed) is (indeed) easy for any one; but far difficult it is to do according to what has been said" },
  { number: 665, tamil: "வீறெய்தி மாண்டார் வினைத்திட்பம் வேந்தன்கண்\nஊறெய்தி உள்ளப் படும்.", transliteration: "Veereydhi Maantaar Vinaiththitpam Vendhankan / Ooreydhi Ullap Patum", english: "The firmness in action of those who have become great by the excellence (of their counsel) will, by attaining its fulfilment in the person of the king, be esteemed (by all)." },
  { number: 666, tamil: "எண்ணிய எண்ணியாங்கு எய்துவர் எண்ணியார்\nதிண்ணியர் ஆகப் பெறின்.", transliteration: "Enniya Enniyaangu Eydhu Enniyaar / Thinniyar Aakap Perin", english: "If those who have planned (an undertaking) possess firmness (in executing it) they will obtain what they have desired even as they have desired it" },
  { number: 667, tamil: "உருவுகண்டு எள்ளாமை வேண்டும் உருள்பெருந்தேர்க்கு\nஅச்சாணி அன்னார் உடைத்து.", transliteration: "Uruvukantu Ellaamai Ventum Urulperundherkku / Achchaani Annaar Utaiththu", english: "Let none be despised for (their) size; (for) the world has those who resemble the linch-pin of the big rolling car" },
  { number: 668, tamil: "கலங்காது கண்ட வினைக்கண் துளங்காது\nதூக்கங் கடிந்து செயல்.", transliteration: "Kalangaadhu Kanta Vinaikkan Thulangaadhu / Thookkang Katindhu Seyal", english: "An act that has been firmly resolved on must be as firmly carried out without delay" },
  { number: 669, tamil: "துன்பம் உறவரினும் செய்க துணிவாற்றி\nஇன்பம் பயக்கும் வினை.", transliteration: "Thunpam Uravarinum Seyka Thunivaatri / Inpam Payakkum Vinai", english: "Though it should cause increasing sorrow (at the outset), do with firmness the act that yield bliss (in the end)" },
  { number: 670, tamil: "எனைத்திட்பம் எய்தியக் கண்ணும் வினைத்திட்பம்\nவேண்டாரை வேண்டாது உலகு.", transliteration: "Enaiththitpam Ey Thiyak Kannum / Vinaiththitpam Ventaarai Ventaadhu Ulaku", english: "The great will not esteem those who esteem not firmness of action, whatever other abilities the latter may possess" },
  { number: 671, tamil: "சூழ்ச்சி முடிவு துணிவெய்தல் அத்துணிவு\nதாழ்ச்சியுள் தங்குதல் தீது.", transliteration: "Soozhchchi Mutivu Thuniveydhal Aththunivu / Thaazhchchiyul Thangudhal Theedhu", english: "Consultation ends in forming a resolution (to act); (but) delay in the execution of that resolve is an evil" },
  { number: 672, tamil: "தூங்குக தூங்கிச் செயற்பால தூங்கற்க\nதூங்காது செய்யும் வினை.", transliteration: "Thoonguka Thoongich Cheyarpaala Thoongarka / Thoongaadhu Seyyum Vinai", english: "Sleep over such (actions) as may be slept over; (but) never over such as may not be slept over" },
  { number: 673, tamil: "ஒல்லும்வா யெல்லாம் வினைநன்றே ஒல்லாக்கால்\nசெல்லும்வாய் நோக்கிச் செயல்.", transliteration: "Ollumvaa Yellaam Vinainandre Ollaakkaal / Sellumvaai Nokkich Cheyal", english: "Whenever it is possible (to overcome your enemy) the act (of fighting) is certainly good; if not, endeavour to employ some more successful method" },
  { number: 674, tamil: "வினைபகை என்றிரண்டின் எச்சம் நினையுங்கால்\nதீயெச்சம் போலத் தெறும்.", transliteration: "Vinaipakai Endrirantin Echcham Ninaiyungaal / Theeyechcham Polath Therum", english: "When duly considered, the incomplete execution of an undertaking and hostility will grow and destroy one like the (unextinguished) remnant of a fire" },
  { number: 675, tamil: "பொருள்கருவி காலம் வினையிடனொடு ஐந்தும்\nஇருள்தீர எண்ணிச் செயல்.", transliteration: "Porulkaruvi Kaalam Vinaiyitanotu Aindhum / Iruldheera Ennich Cheyal", english: "Do an act after a due consideration of the (following) five, viz money, means, time, execution and place" },
  { number: 676, tamil: "முடிவும் இடையூறும் முற்றியாங்கு எய்தும்\nபடுபயனும் பார்த்துச் செயல்.", transliteration: "Mutivum Itaiyoorum Mutriyaangu Eydhum / Patupayanum Paarththuch Cheyal", english: "An act is to be performed after considering the exertion required, the obstacles to be encountered, and the great profit to be gained (on its completion)" },
  { number: 677, tamil: "செய்வினை செய்வான் செயன்முறை அவ்வினை\nஉள்ளறிவான் உள்ளம் கொளல்.", transliteration: "Seyvinai Seyvaan Seyanmurai Avvinai / Ullarivaan Ullam Kolal", english: "The method of performance for one who has begun an act is to ascertain the mind of him who knows the secret thereof" },
  { number: 678, tamil: "வினையான் வினையாக்கிக் கோடல் நனைகவுள்\nயானையால் யானையாத் தற்று.", transliteration: "Vinaiyaan Vinaiyaakkik Kotal Nanaikavul / Yaanaiyaal Yaanaiyaath Thatru", english: "To make one undertaking the means of accomplishing another (similar to it) is like making one rutting elephant the means of capturing another" },
  { number: 679, tamil: "நட்டார்க்கு நல்ல செயலின் விரைந்ததே\nஒட்டாரை ஒட்டிக் கொளல்.", transliteration: "Nattaarkku Nalla Seyalin Viraindhadhe / Ottaarai Ottik Kolal", english: "One should rather hasten to secure the alliance of the foes (of one's foes) than perform good offices to one's friends" },
  { number: 680, tamil: "உறைசிறியார் உள்நடுங்கல் அஞ்சிக் குறைபெறின்\nகொள்வர் பெரியார்ப் பணிந்து.", transliteration: "Uraisiriyaar Ulnatungal Anjik Kuraiperin / Kolvar Periyaarp Panindhu", english: "Ministers of small states, afraid of their people being frightened, will yield to and acknowledge their superior foes, if the latter offer them a chance of reconciliation" },
  { number: 681, tamil: "அன்புடைமை ஆன்ற குடிப்பிறத்தல் வேந்தவாம்\nபண்புடைமை தூதுரைப்பான் பண்பு.", transliteration: "Anputaimai Aandra Kutippiraththal Vendhavaam / Panputaimai Thoodhuraippaan Panpu", english: "The qualification of an ambassador are affection (for his relations) a fitting birth, and the possession of attributes pleasing to royalty" },
  { number: 682, tamil: "அன்பறிவு ஆராய்ந்த சொல்வன்மை தூதுரைப்பார்க்கு\nஇன்றி யமையாத மூன்று.", transliteration: "Anparivu Aaraaindha Solvanmai Thoodhuraippaarkku / Indri Yamaiyaadha Moondru", english: "Love (to his sovereign), knowledge (of his affairs), and a discriminating power of speech (before other sovereigns) are the three sine qua non qualifications of an ambassador" },
  { number: 683, tamil: "நூலாருள் நூல்வல்லன் ஆகுதல் வேலாருள்\nவென்றி வினையுரைப்பான் பண்பு.", transliteration: "Noolaarul Noolvallan Aakudhal Velaarul / Vendri Vinaiyuraippaan Panpu", english: "To be powerful in politics among those who are learned (in ethics) is the character of him who speaks" },
  { number: 684, tamil: "அறிவுரு வாராய்ந்த கல்விஇம் மூன்றன்\nசெறிவுடையான் செல்க வினைக்கு.", transliteration: "Arivuru Vaaraaindha Kalviim Moondran / Serivutaiyaan Selka Vinaikku", english: "He may go on a mission (to foreign rulers) who has combined in him all these three viz, (natural) sense, an attractive bearing and well-tried learning" },
  { number: 685, tamil: "தொகச்சொல்லித் தூவாத நீக்கி நகச்சொல்லி\nநன்றி பயப்பதாந் தூது.", transliteration: "Thokach Chollith Thoovaadha Neekki / Nakachcholli Nandri Payappadhaan Thoodhu", english: "He is an ambassador who (in the presence of foreign rulers) speaks briefly, avoids harshness, talks so as to make them smile, and thus brings good (to his own sovereign)" },
  { number: 686, tamil: "கற்றுக்கண் அஞ்சான் செலச்சொல்லிக் காலத்தால்\nதக்கது அறிவதாம் தூது.", transliteration: "Katrukkan Anjaan Selachchollik Kaalaththaal / Thakkadhu Arivadhaam Thoodhu", english: "He is an ambassador who having studied (politics) talks impressively, is not afraid of angry looks, and knows (to employ) the art suited to the time" },
  { number: 687, tamil: "கடனறிந்து காலங் கருதி இடனறிந்து\nஎண்ணி உரைப்பான் தலை.", transliteration: "Katanarindhu Kaalang Karudhi Itanarindhu / Enni Uraippaan Thalai", english: "He is chief (among ambassadors) who understands the proper decorum (before foreign princes), seeks the (proper) occasion, knows the (most suitable) place, and delivers his message after (due)" },
  { number: 688, tamil: "தூய்மை துணைமை துணிவுடைமை இம்மூன்றின்\nவாய்மை வழியுரைப்பான் பண்பு.", transliteration: "Thooimai Thunaimai Thunivutaimai Immoondrin / Vaaimai Vazhiyuraippaan Panpu", english: "The qualifications of him who faithfully delivers his (sovereign's) message are purity, the support (of foreign ministers), and boldness, with truthfulness in addition to the (aforesaid) three" },
  { number: 689, tamil: "விடுமாற்றம் வேந்தர்க்கு உரைப்பான் வடுமாற்றம்\nவாய்சேரா வன்கணவன்.", transliteration: "Vitumaatram Vendharkku Uraippaan Vatumaatram / Vaaiseraa Vanka Navan", english: "He alone is fit to communicate (his sovereign's) reply, who possesses the firmness not to utter even inadvertently what may reflect discredit (on the latter)" },
  { number: 690, tamil: "இறுதி பயப்பினும் எஞ்சாது இறைவற்கு\nஉறுதி பயப்பதாம் தூது.", transliteration: "Irudhi Payappinum Enjaadhu Iraivarku / Urudhi Payappadhaam Thoodhu", english: "He is the ambassador who fearlessly seeks his sovereign's good though it should cost him his life (to deliver his message)" },
  { number: 691, tamil: "அகலாது அணுகாது தீக்காய்வார் போல்க\nஇகல்வேந்தர்ச் சேர்ந்தொழுகு வார்.", transliteration: "Akalaadhu Anukaadhu Theekkaaivaar Polka / Ikalvendharch Cherndhozhuku Vaar", english: "Thus let them act who dwell beneath of warlike kings the palace-roof" },
  { number: 692, tamil: "மன்னர் விழைப விழையாமை மன்னரால்\nமன்னிய ஆக்கந் தரும்.", transliteration: "Mannar Vizhaipa Vizhaiyaamai Mannaraal / Manniya Aakkan Tharum", english: "For ministers not to cover the things desired by their kings will through the kings themselves yield them everlasting wealth" },
  { number: 693, tamil: "போற்றின் அரியவை போற்றல் கடுத்தபின்\nதேற்றுதல் யார்க்கும் அரிது.", transliteration: "Potrin Ariyavai Potral Katuththapin / Thetrudhal Yaarkkum Aridhu", english: "Ministers who would save themselves should avoid (the commission of) serious errors for if the king's suspicion is once roused, no one can remove it" },
  { number: 694, tamil: "செவிச்சொல்லும் சேர்ந்த நகையும் அவித்தொழுகல்\nஆன்ற பெரியா ரகத்து.", transliteration: "Sevichchollum Serndha Nakaiyum Aviththozhukal / Aandra Periyaa Rakaththu", english: "While in the presence of the sovereign, ministers should neither whisper to nor smile at others" },
  { number: 695, tamil: "எப்பொருளும் ஓரார் தொடரார்மற் றப்பொருளை\nவிட்டக்கால் கேட்க மறை.", transliteration: "Epporulum Oraar Thotaraarmar Rapporulai / Vittakkaal Ketka Marai", english: "(When the king is engaged) in secret counsel (with others), ministers should neither over-hear anything whatever nor pry into it with inquisitive questions, but (wait to) listen when it is divulged (by" },
  { number: 696, tamil: "குறிப்பறிந்து காலங் கருதி வெறுப்பில\nவேண்டுப வேட்பச் சொலல்.", transliteration: "Kuripparindhu Kaalang Karudhi Veruppila / Ventupa Vetpach Cholal", english: "Knowing the (king's disposition and seeking the right time, (the minister) should in a pleasing manner suggest things such as are desirable and not disagreeable" },
  { number: 697, tamil: "வேட்பன சொல்லி வினையில எஞ்ஞான்றும்\nகேட்பினும் சொல்லா விடல்.", transliteration: "Vetpana Solli Vinaiyila Egngnaandrum / Ketpinum Sollaa Vital", english: "Ministers should (always) give agreeable advice but on no occasion recommend useless actions, though requested (to do so)" },
  { number: 698, tamil: "இளையர் இனமுறையர் என்றிகழார் நின்ற\nஒளியோடு ஒழுகப் படும்.", transliteration: "Ilaiyar Inamuraiyar Endrikazhaar Nindra / Oliyotu Ozhukap Patum", english: "Ministers should behave in accordance with the (Divine) light in the person of kings and not despise them saying, \"He is our junior (in age) and connected with our family!\"" },
  { number: 699, tamil: "கொளப்பட்டேம் என்றெண்ணிக் கொள்ளாத செய்யார்\nதுளக்கற்ற காட்சி யவர்.", transliteration: "Kolappattem Endrennik Kollaadha Seyyaar / Thulakkatra Kaatchi Yavar", english: "Those whose judgement is firm will not do what is disagreeable (to the sovereign) saying (within" },
  { number: 700, tamil: "பழையம் எனக்கருதிப் பண்பல்ல செய்யும்\nகெழுதகைமை கேடு தரும்.", transliteration: "Pazhaiyam Enakkarudhip Panpalla Seyyum / Kezhudhakaimai Ketu Tharum", english: "The (foolish) claim with which a minister does unbecoming acts because of his (long) familiarity (with the king) will ensure his ruin" },
  { number: 701, tamil: "கூறாமை நோக்கக் குறிப்பறிவான் எஞ்ஞான்றும்\nமாறாநீர் வையக் கணி.", transliteration: "Kooraamai Nokkake Kuripparivaan Egngnaandrum / Maaraaneer Vaiyak Kani", english: "The minister who by looking (at the king) understands his mind without being told (of it), will be a perpetual ornament to the world which is surrounded by a never-drying sea" },
  { number: 702, tamil: "ஐயப் படாஅது அகத்தது உணர்வானைத்\nதெய்வத்தோ டொப்பக் கொளல்.", transliteration: "Aiyap Pataaadhu Akaththadhu Unarvaanaith / Theyvaththo Toppak Kolal", english: "He is to be esteemed a god who is able to ascertain without a doubt what is within (one's mind)" },
  { number: 703, tamil: "குறிப்பிற் குறிப்புணர் வாரை உறுப்பினுள்\nயாது கொடுத்தும் கொளல்.", transliteration: "Kurippir Kurippunar Vaarai Uruppinul / Yaadhu Kotuththum Kolal", english: "The king should ever give whatever (is asked) of his belongings and secure him who, by the indications (of his own mind) is able to read those of another" },
  { number: 704, tamil: "குறித்தது கூறாமைக் கொள்வாரோ டேனை\nஉறுப்போ ரனையரால் வேறு.", transliteration: "Kuriththadhu Kooraamaik Kolvaaro Tenai / Uruppo Ranaiyaraal Veru", english: "Those who understand one's thoughts without being informed (thereof) and those who do not, may (indeed) resemble one another bodily; still are they different (mentally)" },
  { number: 705, tamil: "குறிப்பிற் குறிப்புணரா வாயின் உறுப்பினுள்\nஎன்ன பயத்தவோ கண்?", transliteration: "Kurippir Kurippunaraa Vaayin Uruppinul / Enna Payaththavo Kan?", english: "Of what use are the eyes amongst one's members, if they cannot by their own indications dive those of another ?" },
  { number: 706, tamil: "அடுத்தது காட்டும் பளிங்குபோல் நெஞ்சம்\nகடுத்தது காட்டும் முகம்.", transliteration: "Atuththadhu Kaattum Palingupol Nenjam / Katuththadhu Kaattum Mukam", english: "As the mirror reflects what is near so does the face show what is uppermost in the mind" },
  { number: 707, tamil: "முகத்தின் முதுக்குறைந்தது உண்டோ உவப்பினும்\nகாயினும் தான்முந் துறும்.", transliteration: "Mukaththin Mudhukkuraindhadhu Unto Uvappinum / Kaayinum Thaanmun Thurum", english: "Is there anything so full of knowledge as the face ? (No) it precedes the mind, whether (the latter is) pleased or vexed" },
  { number: 708, tamil: "முகம்நோக்கி நிற்க அமையும் அகம்நோக்கி\nஉற்ற துணர்வார்ப் பெறின்.", transliteration: "Mukamnokki Nirka Amaiyum Akamnokki / Utra Thunarvaarp Perin", english: "If the king gets those who by looking into his mind can understand (and remove) what has occurred (to him) it is enough that he stand looking at their face" },
  { number: 709, tamil: "பகைமையும் கேண்மையும் கண்ணுரைக்கும் கண்ணின்\nவகைமை உணர்வார்ப் பெறின்.", transliteration: "Pakaimaiyum Kenmaiyum Kannuraikkum Kannin / Vakaimai Unarvaarp Perin", english: "If a king gets ministers who can read the movements of the eye, the eyes (of foreign kings) will (themselves) reveal (to him) their hatred or friendship" },
  { number: 710, tamil: "நுண்ணியம் என்பார் அளக்குங்கோல் காணுங்கால்\nகண்ணல்லது இல்லை பிற.", transliteration: "Nunniyam Enpaar Alakkungol Kaanungaal / Kannalladhu Illai Pira", english: "The measuring-rod of those (ministers) who say \"we are acute\" will on inquiry be found to be their (own) eyes and nothing else" },
  { number: 711, tamil: "அவையறிநது ஆராய்ந்து சொல்லுக சொல்லின்\nதொகையறிந்த தூய்மை யவர்.", transliteration: "Avaiyarinadhu Aaraaindhu Solluka Sollin / Thokaiyarindha Thooimai Yavar", english: "Let the pure who know the arrangement of words speak with deliberation after ascertaining (the nature of) the court (then assembled)" },
  { number: 712, tamil: "இடைதெரிந்து நன்குணர்ந்து சொல்லுக சொல்லின்\nநடைதெரிந்த நன்மை யவர்.", transliteration: "Itaidherindhu Nankunarndhu Solluka Sollin / Nataidherindha Nanmai Yavar", english: "Let the good who know the uses of words speak with a clear knowledge after ascertaining the time (suited to the court)" },
  { number: 713, tamil: "அவையறியார் சொல்லல்மேற் கொள்பவர் சொல்லின்\nவகையறியார் வல்லதூஉம் இல்.", transliteration: "Avaiyariyaar Sollalmer Kolpavar Sollin / Vakaiyariyaar Valladhooum Il", english: "Those who undertake to speak without knowing the (nature of the) court are ignorant of the quality of words as well as devoid of the power (of learning)" },
  { number: 714, tamil: "ஒளியார்முன் ஒள்ளிய ராதல் வெளியார்முன்\nவான்சுதை வண்ணம் கொளல்.", transliteration: "Oliyaarmun Olliya Raadhal Veliyaarmun / Vaansudhai Vannam Kolal", english: "Ministers should be lights in the assembly of the enlightned, but assume the pure whiteness of mortar (ignorance) in that of fools" },
  { number: 715, tamil: "நன்றென்ற வற்றுள்ளும் நன்றே முதுவருள்\nமுந்து கிளவாச் செறிவு.", transliteration: "Nandrendra Vatrullum Nandre Mudhuvarul / Mundhu Kilavaach Cherivu", english: "The modesty by which one does not rush forward and speak in (an assembly of) superiors is the best among all (one's) good qualities" },
  { number: 716, tamil: "ஆற்றின் நிலைதளர்ந் தற்றே வியன்புலம்\nஏற்றுணர்வார் முன்னர் இழுக்கு.", transliteration: "Aatrin Nilaidhalarn Thatre Viyanpulam / Etrunarvaar Munnar Izhukku", english: "(For a minister) to blunder in the presence of those who have acquired a vast store of learning and know (the value thereof) is like a good man stumbling (and falling away) from the path (of virtue)" },
  { number: 717, tamil: "கற்றறிந்தார் கல்வி விளங்கும் கசடறச்\nசொல்தெரிதல் வல்லார் அகத்து.", transliteration: "Katrarindhaar Kalvi Vilangum Kasatarach / Choldheridhal Vallaar Akaththu", english: "The learning of those who have read and understood (much) will shine in the assembly of those who faultlessly examine (the nature of) words" },
  { number: 718, tamil: "உணர்வ துடையார்முன் சொல்லல் வளர்வதன்\nபாத்தியுள் நீர்சொரிந் தற்று.", transliteration: "Unarva Thutaiyaarmun Sollal Valarvadhan / Paaththiyul Neersorin Thatru", english: "Lecturing to those who have the ability to understand (for themselves) is like watering a bed of plants that are growing (of themselves)" },
  { number: 719, tamil: "புல்லவையுள் பொச்சாந்தும் சொல்லற்க நல்லவையுள்\nநன்குசலச் சொல்லு வார்.", transliteration: "Pullavaiyul Pochchaandhum Sollarka Nallavaiyul / Nankusalach Chollu Vaar", english: "Those who are able to speak good things impressively in an assembly of the good should not even forgetfully speak them in that of the low" },
  { number: 720, tamil: "அங்கணத்துள் உக்க அமிழ்தற்றால் தங்கணத்தார்\nஅல்லார்முன் கோட்டி கொளல்.", transliteration: "Anganaththul Ukka Amizhdhatraal Thanganaththaar / Allaarmun Kotti Kolal", english: "To utter (a good word) in the assembly of those who are of inferior rank is like dropping nectar on the ground" },
  { number: 721, tamil: "வகையறிந்து வல்லவை வாய்சோரார் சொல்லின்\nதொகையறிந்த தூய்மை யவர்.", transliteration: "Vakaiyarindhu Vallavai Vaaisoraar Sollin / Thokaiyarindha Thooimai Yavar", english: "The pure who know the classification of words having first ascertained the nature (of the court) will not (through fear) falter in their speech before the powerful body" },
  { number: 722, tamil: "கற்றாருள் கற்றார் எனப்படுவர் கற்றார்முன்\nகற்ற செலச்சொல்லு வார்.", transliteration: "Katraarul Katraar Enappatuvar Katraarmun / Katra Selachchollu Vaar", english: "Those who can agreeably set forth their acquirements before the learned will be regarded as the most learned among the learned" },
  { number: 723, tamil: "பகையகத்துச் சாவார் எளியர் அரியர்\nஅவையகத்து அஞ்சா தவர்.", transliteration: "Pakaiyakaththuch Chaavaar Eliyar Ariyar / Avaiyakaththu Anjaa Thavar", english: "Many indeed may (fearlessly) die in the presence of (their) foes; (but) few are those who are fearless in the assembly (of the learned)" },
  { number: 724, tamil: "கற்றார்முன் கற்ற செலச்சொல்லித் தாம்கற்ற\nமிக்காருள் மிக்க கொளல்.", transliteration: "Katraarmun Katra Selachchollith Thaamkatra / Mikkaarul Mikka Kolal", english: "(Ministers) should agreeably set forth their acquirements before the learned and acquire more (knowledge) from their superiors (in learning)" },
  { number: 725, tamil: "ஆற்றின் அளவறிந்து கற்க அவையஞ்சா\nமாற்றங் கொடுத்தற் பொருட்டு.", transliteration: "Aatrin Alavarindhu Karka Avaiyanjaa / Maatrang Kotuththar Poruttu", english: "In order to reply fearlessly before a foreign court, (ministers) should learn logic according to the rules (of grammar)" },
  { number: 726, tamil: "வாளொடென் வன்கண்ணர் அல்லார்க்கு நூலொடென்\nநுண்ணவை அஞ்சு பவர்க்கு.", transliteration: "Vaaloten Vankannar Allaarkku Nooloten / Nunnavai Anju Pavarkku", english: "What have they to do with a sword who are not valiant, or they with learning who are afraid of an intelligent assembly ?" },
  { number: 727, tamil: "பகையகத்துப் பேடிகை ஒள்வாள் அவையகத்து\nஅஞ்சு மவன்கற்ற நூல்.", transliteration: "Pakaiyakaththup Petikai Olvaal Avaiyakaththu / Anju Mavankatra Nool", english: "The learning of him who is diffident before an assembly is like the shining sword of an hermaphrodite in the presence of his foes" },
  { number: 728, tamil: "பல்லவை கற்றும் பயமிலரே நல்லவையுள்\nநன்கு செலச்சொல்லா தார்.", transliteration: "Pallavai Katrum Payamilare Nallavaiyul / Nanku Selachchollaa Thaar", english: "Those who cannot agreeably speak good things before a good assembly are indeed unprofitable persons inspite of all their various acquirements" },
  { number: 729, tamil: "கல்லா தவரின் கடையென்ப கற்றறிந்தும்\nநல்லா ரவையஞ்சு வார்.", transliteration: "Kallaa Thavarin Kataiyenpa Katrarindhum / Nallaa Ravaiyanju Vaar", english: "They who, though they have learned and understood, are yet afraid of the assembly of the good, are said to be inferior (even) to the illiterate" },
  { number: 730, tamil: "உளரெனினும் இல்லாரொடு ஒப்பர் களன்அஞ்சிக்\nகற்ற செலச்சொல்லா தார்.", transliteration: "Ulareninum Illaarotu Oppar Kalananjik / Katra Selachchollaa Thaar", english: "Those who through fear of the assembly are unable to set forth their learning in an interesting manner, though alive, are yet like the dead" },
  { number: 731, tamil: "தள்ளா விளையுளும் தக்காரும் தாழ்விலாச்\nசெல்வரும் சேர்வது நாடு.", transliteration: "Thallaa Vilaiyulum Thakkaarum Thaazhvilaach / Chelvarum Servadhu Naatu", english: "A kingdom is that in which (those who carry on) a complete cultivation, virtuous persons, and" },
  { number: 732, tamil: "பெரும்பொருளால் பெட்டக்க தாகி அருங்கேட்டால்\nஆற்ற விளைவது நாடு.", transliteration: "Perumporulaal Pettakka Thaaki Arungettaal / Aatra Vilaivadhu Naatu", english: "A kingdom is that which is desire for its immense wealth, and which grows greatly in prosperity, being free from destructive causes" },
  { number: 733, tamil: "பொறையொருங்கு மேல்வருங்கால் தாங்கி இறைவற்கு\nஇறையொருங்கு நேர்வது நாடு.", transliteration: "Poraiyorungu Melvarungaal Thaangi Iraivarku / Iraiyorungu Nervadhu Naatu", english: "A kingdom is that which can bear any burden that may be pressed on it (from adjoining kingdoms) and (yet) pay the full tribute to its sovereign" },
  { number: 734, tamil: "உறுபசியும் ஓவாப் பிணியும் செறுபகையும்\nசேரா தியல்வது நாடு.", transliteration: "Urupasiyum Ovaap Piniyum Serupakaiyum / Seraa Thiyalvadhu Naatu", english: "A kingdom is that which continues to be free from excessive starvation, irremediable epidemics, and destructive foes" },
  { number: 735, tamil: "பல்குழுவும் பாழ்செய்யும் உட்பகையும் வேந்தலைக்கும்\nகொல்குறும்பும் இல்லது நாடு.", transliteration: "Palkuzhuvum Paazhseyyum Utpakaiyum Vendhalaikkum / Kolkurumpum Illadhu Naatu", english: "A kingdom is that which is without various (irregular) associations, destructive internal enemies, and murderous savages who (sometimes) harass the sovereign" },
  { number: 736, tamil: "கேடறியாக் கெட்ட இடத்தும் வளங்குன்றா\nநாடென்ப நாட்டின் தலை.", transliteration: "Ketariyaak Ketta Itaththum Valangundraa / Naatenpa Naattin Thalai", english: "The learned say that the best kingdom is that which knows no evil (from its foes), and, if injured (at all), suffers no diminution in its fruitfulness" },
  { number: 737, tamil: "இருபுனலும் வாய்ந்த மலையும் வருபுனலும்\nவல்லரணும் நாட்டிற்கு உறுப்பு.", transliteration: "Irupunalum Vaaindha Malaiyum Varupunalum / Vallaranum Naattirku Uruppu", english: "The constituents of a kingdom are the two waters (from above and below), well situated hills and an undestructible fort" },
  { number: 738, tamil: "பிணியின்மை செல்வம் விளைவின்பம் ஏமம்\nஅணியென்ப நாட்டிவ் வைந்து.", transliteration: "Piniyinmai Selvam Vilaivinpam Emam / Aniyenpa Naattiv Vaindhu", english: "Freedom from epidemics, wealth, produce, happiness and protection (to subjects); these five, the learned, say, are the ornaments of a kingdom" },
  { number: 739, tamil: "நாடென்ப நாடா வளத்தன நாடல்ல\nநாட வளந்தரு நாடு.", transliteration: "Naatenpa Naataa Valaththana Naatalla / Naata Valandharu Naatu", english: "The learned say that those are kingdom whose wealth is not laboured for, and those not, whose wealth is only obtained through labour" },
  { number: 740, tamil: "ஆங்கமை வெய்தியக் கண்ணும் பயமின்றே\nவேந்தமை வில்லாத நாடு.", transliteration: "Aangamai Veydhiyak Kannum Payamindre / Vendhamai Villaadha Naatu", english: "Although in possession of all the above mentioned excellences, these are indeed of no use to a country, in the absence of harmony between the sovereign and the sujects" },
  { number: 741, tamil: "ஆற்று பவர்க்கும் அரண்பொருள் அஞ்சித்தற்\nபோற்று பவர்க்கும் பொருள்.", transliteration: "Aatru Pavarkkum Aranporul Anjiththar / Potru Pavarkkum Porul", english: "A fort is an object of importance to those who march (against their foes) as well as to those who through fear (of pursuers) would seek it for shelter" },
  { number: 742, tamil: "மணிநீரும் மண்ணும் மலையும் அணிநிழற்\nகாடும் உடைய தரண்.", transliteration: "Manineerum Mannum Malaiyum Aninizhar / Kaatum Utaiya Tharan", english: "A fort is that which has everlasting water, plains, mountains and cool shady forests" },
  { number: 743, tamil: "உயர்வகலம் திண்மை அருமைஇந் நான்கின்\nஅமைவரண் என்றுரைக்கும் நூல்.", transliteration: "Uyarvakalam Thinmai Arumaiin Naankin / Amaivaran Endruraikkum Nool", english: "The learned say that a fortress is an enclosure having these four (qualities) viz, height, breadth, strength and inaccessibility" },
  { number: 744, tamil: "சிறுகாப்பிற் பேரிடத்த தாகி உறுபகை\nஊக்கம் அழிப்ப தரண்.", transliteration: "Sirukaappir Peritaththa Thaaki Urupakai / Ookkam Azhippa Tharan", english: "A fort is that which has an extensive space within, but only small places to be guarded, and such as can destroy the courage of besieging foes" },
  { number: 745, tamil: "கொளற்கரிதாய்க் கொண்டகூழ்த் தாகி அகத்தார்\nநிலைக்கெளிதாம் நீரது அரண்.", transliteration: "Kolarkaridhaaik Kontakoozhth Thaaki Akaththaar / Nilaikkelidhaam Neeradhu Aran", english: "A fort is that which cannot be captured, which abounds in suitable provisions, and affords a position of easy defence to its inmates" },
  { number: 746, tamil: "எல்லாப் பொருளும் உடைத்தாய் இடத்துதவும்\nநல்லாள் உடையது அரண்.", transliteration: "Ellaap Porulum Utaiththaai Itaththudhavum / Nallaal Utaiyadhu Aran", english: "A fort is that which has all (needful) things, and excellent heroes that can help it against destruction (by foes)" },
  { number: 747, tamil: "முற்றியும் முற்றா தெறிந்தும் அறைப்படுத்தும்\nபற்றற் கரியது அரண்.", transliteration: "Mutriyum Mutraa Therindhum Araippatuththum / Patrar Kariyadhu Aran", english: "A fort is that which cannot be captured by blockading, assaulting, or undermining it" },
  { number: 748, tamil: "முற்றாற்றி முற்றி யவரையும் பற்றாற்றிப்\nபற்றியார் வெல்வது அரண்.", transliteration: "Mutraatri Mutri Yavaraiyum Patraatrip / Patriyaar Velvadhu Aran", english: "That is a fort whose inmates are able to overcome without losing their ground, even abler men who have besieged it" },
  { number: 749, tamil: "முனைமுகத்து மாற்றலர் சாய வினைமுகத்து\nவீறெய்தி மாண்ட தரண்.", transliteration: "Munaimukaththu Maatralar Saaya Vinaimukaththu / Veereydhi Maanta Tharan", english: "A fort is that which derives excellence from the stratagems made (by its inmates) to defeat their enemies in the battlefield" },
  { number: 750, tamil: "எனைமாட்சித் தாகியக் கண்ணும் வினைமாட்சி\nஇல்லார்கண் இல்லது அரண்.", transliteration: "Enaimaatchith Thaakiyak Kannum Vinaimaatchi / Illaarkan Illadhu Aran", english: "Although a fort may possess all (the above-said) excellence, it is, as it were without these, if its inmates possess not the excellence of action" },
  { number: 751, tamil: "பொருளல் லவரைப் பொருளாகச் செய்யும்\nபொருளல்லது இல்லை பொருள்.", transliteration: "Porulal Lavaraip Porulaakach Cheyyum / Porulalladhu Illai Porul", english: "Besides wealth there is nothing that can change people of no importance into those of (some) importance" },
  { number: 752, tamil: "இல்லாரை எல்லாரும் எள்ளுவர் செல்வரை\nஎல்லாரும் செய்வர் சிறப்பு.", transliteration: "Illaarai Ellaarum Elluvar Selvarai / Ellaarum Seyvar Sirappu", english: "All despise the poor; (but) all praise the rich" },
  { number: 753, tamil: "பொருளென்னும் பொய்யா விளக்கம் இருளறுக்கும்\nஎண்ணிய தேயத்துச் சென்று.", transliteration: "Porulennum Poiyaa Vilakkam Irularukkum / Enniya Theyaththuch Chendru", english: "The imperishable light of wealth goes into regions desired (by its owner) and destroys the darkness (of enmity therein)" },
  { number: 754, tamil: "அறன்ஈனும் இன்பமும் ஈனும் திறனறிந்து\nதீதின்றி வந்த பொருள்.", transliteration: "Araneenum Inpamum Eenum Thiranarindhu / Theedhindri Vandha Porul", english: "The wealth acquired with a knowledge of the proper means and without foul practices will yield virtue and happiness" },
  { number: 755, tamil: "அருளொடும் அன்பொடும் வாராப் பொருளாக்கம்\nபுல்லார் புரள விடல்.", transliteration: "Arulotum Anpotum Vaaraap Porulaakkam / Pullaar Purala Vital", english: "(Kings) should rather avoid than seek the accumulation of wealth which does not flow in with mercy and love" },
  { number: 756, tamil: "உறுபொருளும் உல்கு பொருளும்தன் ஒன்னார்த்\nதெறுபொருளும் வேந்தன் பொருள்.", transliteration: "Uruporulum Ulku Porulumdhan Onnaarth / Theruporulum Vendhan Porul", english: "The spoils of slaughtered foes; these are the royal revenues" },
  { number: 757, tamil: "அருளென்னும் அன்பீன் குழவி பொருளென்னும்\nசெல்வச் செவிலியால் உண்டு.", transliteration: "Arulennum Anpeen Kuzhavi Porulennum / Selvach Cheviliyaal Untu", english: "The child mercy which is borne by love grows under the care of the rich nurse of wealth" },
  { number: 758, tamil: "குன்றேறி யானைப்போர் கண்டற்றால் தன்கைத்தொன்று\nஉண்டாகச் செய்வான் வினை.", transliteration: "Kundreri Yaanaip Por Kantatraal / Thankaiththondru Untaakach Cheyvaan Vinai", english: "An undertaking of one who has wealth in one's hands is like viewing an elephant-fight from a hill-top" },
  { number: 759, tamil: "செய்க பொருளைச் செறுநர் செருக்கறுக்கும்\nஎஃகதனிற் கூரிய தில்.", transliteration: "Seyka Porulaich Cherunar Serukkarukkum / Eqkadhanir Kooriya Thil", english: "Accumulate wealth; it will destroy the arrogance of (your) foes; there is no weapon sharper than it" },
  { number: 760, tamil: "ஒண்பொருள் காழ்ப்ப இயற்றியார்க்கு எண்பொருள்\nஏனை இரண்டும் ஒருங்கு.", transliteration: "Onporul Kaazhppa Iyatriyaarkku Enporul / Enai Irantum Orungu", english: "To those who have honestly acquired an abundance of riches, the other two, (virtue and pleasure) are things easy (of acquisition)" },
  { number: 761, tamil: "உறுப்பமைந்து ஊறஞ்சா வெல்படை வேந்தன்\nவெறுக்கையுள் எல்லாம் தலை.", transliteration: "Uruppamaindhu Ooranjaa Velpatai Vendhan / Verukkaiyul Ellaam Thalai", english: "The army which is complete in (its) parts and conquers without fear of wounds is the chief wealth of the king" },
  { number: 762, tamil: "உலைவிடத்து ஊறஞ்சா வன்கண் தொலைவிடத்துத்\nதொல்படைக் கல்லால் அரிது.", transliteration: "Ulaivitaththu Ooranjaa Vankan Tholaivitaththuth / Tholpataik Kallaal Aridhu", english: "Ancient army can alone have the valour which makes it stand by its king at the time of defeat, fearless of wounds and unmindful of its reduced strength" },
  { number: 763, tamil: "ஒலித்தக்கால் என்னாம் உவரி எலிப்பகை\nநாகம் உயிர்ப்பக் கெடும்.", transliteration: "Oliththakkaal Ennaam Uvari Ela�ppakai / Naakam Uyirppak Ketum", english: "What if (a host of) hostile rats roar like the sea ? They will perish at the mere breath of the cobra" },
  { number: 764, tamil: "அழிவின்றி அறைபோகா தாகி வழிவந்த\nவன்க ணதுவே படை.", transliteration: "Azhivindri Araipokaa Thaaki Vazhivandha / Vanka Nadhuve Patai", english: "That indeed is an army which has stood firm of old without suffering destruction or deserting (to the enemy)" },
  { number: 765, tamil: "கூற்றுடன்று மேல்வரினும் கூடி எதிர்நிற்கும்\nஆற்ற லதுவே படை.", transliteration: "Kootrutandru Melvarinum Kooti Edhirnirkum / Aatra Ladhuve Patai", english: "That indeed is an army which is capable of offering a united resistance, even if Yama advances against it with fury" },
  { number: 766, tamil: "மறமானம் மாண்ட வழிச்செலவு தேற்றம்\nஎனநான்கே ஏமம் படைக்கு.", transliteration: "Maramaanam Maanta Vazhichchelavu Thetram / Enanaanke Emam Pataikku", english: "Valour, honour, following in the excellent-footsteps (of its predecessors) and trust-worthiness; these four alone constitute the safeguard of an army" },
  { number: 767, tamil: "தார்தாங்கிச் செல்வது தானை தலைவந்த\nபோர்தாங்கும் தன்மை அறிந்து.", transliteration: "Thaardhaangich Chelvadhu Thaanai Thalaivandha / Pordhaangum Thanmai Arindhu", english: "That is an army which knowing the art of warding off an impending struggle, can bear against the dust-van (of a hostile force)" },
  { number: 768, tamil: "அடல்தகையும் ஆற்றலும் இல்லெனினும் தானை\nபடைத்தகையால் பாடு பெறும்.", transliteration: "Ataldhakaiyum Aatralum Illeninum Thaanai / Pataiththakaiyaal Paatu Perum", english: "Though destitute of courage to fight and strength (to endure), an army may yet gain renown by the splendour of its appearance" },
  { number: 769, tamil: "சிறுமையும் செல்லாத் துனியும் வறுமையும்\nஇல்லாயின் வெல்லும் படை.", transliteration: "Sirumaiyum Sellaath Thuniyum Varumaiyum / Illaayin Vellum Patai", english: "An army can triumph (over its foes) if it is free from diminution; irremediable aversion and poverty" },
  { number: 770, tamil: "நிலைமக்கள் சால உடைத்தெனினும் தானை\nதலைமக்கள் இல்வழி இல்.", transliteration: "Nilaimakkal Saala Utaiththeninum Thaanai / Thalaimakkal Ilvazhi Il", english: "Though an army may contain a large number of permanent soldiers, it cannot last if it has no generals" },
  { number: 771, tamil: "என்னைமுன் நில்லன்மின் தெவ்விர் பலரென்னை\nமுன்நின்று கல்நின் றவர்.", transliteration: "Ennaimun Nillanmin Thevvir Palarennai / Munnindru Kalnin Ravar", english: "O my foes, stand not before my leader; (for) many are those who did so but afterwards stood (in the shape of) statues" },
  { number: 772, tamil: "கான முயலெய்த அம்பினில் யானை\nபிழைத்தவேல் ஏந்தல் இனிது.", transliteration: "Kaana Muyaleydha Ampinil Yaanai / Pizhaiththavel Endhal Inidhu", english: "It is more pleasant to hold the dart that has missed an elephant than that which has hit hare in the forest" },
  { number: 773, tamil: "பேராண்மை என்ப தறுகண்ஒன் றுற்றக்கால்\nஊராண்மை மற்றதன் எஃகு.", transliteration: "Peraanmai Enpa Tharukanon Rutrakkaal / Ooraanmai Matradhan Eqku", english: "The learned say that fierceness (incontest with a foe) is indeed great valour; but to become a benefactor in case of accident (to a foe) is the extreme (limit) of that valour" },
  { number: 774, tamil: "கைவேல் களிற்றொடு போக்கி வருபவன்\nமெய்வேல் பறியா நகும்.", transliteration: "Kaivel Kalitrotu Pokki Varupavan / Meyvel Pariyaa Nakum", english: "The hero who after casting the lance in his hand on an elephant, comes (in search of another) will pluck the one (that sticks) in his body and laugh (exultingly)" },
  { number: 775, tamil: "விழித்தகண் வேல்கொண டெறிய அழித்திமைப்பின்\nஒட்டன்றோ வன்க ணவர்க்கு.", transliteration: "Vizhiththakan Velkona Teriya Azhiththimaippin / Ottandro Vanka Navarkku", english: "Is it not a defeat to the valiant to wink and destroy their ferocious look when a lance in cast at them (by their foe) ?" },
  { number: 776, tamil: "விழுப்புண் படாதநாள் எல்லாம் வழுக்கினுள்\nவைக்கும்தன் நாளை எடுத்து.", transliteration: "Vizhuppun Pataadhanaal Ellaam Vazhukkinul / Vaikkumdhan Naalai Etuththu", english: "The hero will reckon among wasted days all those on which he had not received severe wounds" },
  { number: 777, tamil: "சுழலும் இசைவேண்டி வேண்டா உயிரார்\nகழல்யாப்புக் காரிகை நீர்த்து.", transliteration: "Suzhalum Isaiventi Ventaa Uyiraar / Kazhalyaappuk Kaarikai Neerththu", english: "The fastening of ankle-ring by those who disire a world-wide renown and not (the safety of) their lives is like adorning (themselves)" },
  { number: 778, tamil: "உறின்உயிர் அஞ்சா மறவர் இறைவன்\nசெறினும் சீர்குன்றல் இலர்.", transliteration: "Urinuyir Anjaa Maravar Iraivan / Serinum Seerkundral Ilar", english: "The heroes who are not afraid of losing their life in a contest will not cool their ardour, even if the king prohibits (their fighting)" },
  { number: 779, tamil: "இழைத்தது இகவாமைச் சாவாரை யாரே\nபிழைத்தது ஒறுக்கிற் பவர்.", transliteration: "Izhaiththadhu Ikavaamaich Chaavaarai Yaare / Pizhaiththadhu Orukkir Pavar", english: "Who would reproach with failure those who seal their oath with their death ?" },
  { number: 780, tamil: "புரந்தார்கண் நீர்மல்கச் சாகிற்பின் சாக்காடு\nஇரந்துகோள் தக்கது உடைத்து.", transliteration: "Purandhaarkan Neermalkach Chaakirpin Saakkaatu / Irandhukol Thakkadhu Utaiththu", english: "If (heroes) can so die as to fill with tears the eyes of their rulers, such a death deserves to be obtained even by begging" },
  { number: 781, tamil: "செயற்கரிய யாவுள நட்பின் அதுபோல்\nவினைக்கரிய யாவுள காப்பு.", transliteration: "Seyarkariya Yaavula Natpin Adhupol / Vinaikkariya Yaavula Kaappu", english: "What so sure defence 'gainst all that foe can do?" },
  { number: 782, tamil: "நிறைநீர நீரவர் கேண்மை பிறைமதிப்\nபின்னீர பேதையார் நட்பு.", transliteration: "Niraineera Neeravar Kenmai Piraimadhip / Pinneera Pedhaiyaar Natpu", english: "The friendship of the wise waxes like the new moon; (but) that of fools wanes like the full moon" },
  { number: 783, tamil: "நவில்தொறும் நூல்நயம் போலும் பயில்தொறும்\nபண்புடை யாளர் தொடர்பு.", transliteration: "Navildhorum Noolnayam Polum Payildhorum / Panputai Yaalar Thotarpu", english: "Like learning, the friendship of the noble, the more it is cultivated, the more delightful does it become" },
  { number: 784, tamil: "நகுதற் பொருட்டன்று நட்டல் மிகுதிக்கண்\nமேற்செனறு இடித்தற் பொருட்டு.", transliteration: "Nakudhar Poruttandru Nattal Mikudhikkan / Mersenaru Itiththar Poruttu", english: "Friendship is to be practised not for the purpose of laughing but for that of being beforehand in giving one another sharp rebukes in case of transgression" },
  { number: 785, tamil: "புணர்ச்சி பழகுதல் வேண்டா உணர்ச்சிதான்\nநட்பாங் கிழமை தரும்.", transliteration: "Punarchchi Pazhakudhal Ventaa Unarchchidhaan / Natpaang Kizhamai Tharum", english: "Living together and holding frequent intercourse are not necessary (for friendship); (mutual) understanding can alone create a claim for it" },
  { number: 786, tamil: "முகநக நட்பது நட்பன்று நெஞ்சத்து\nஅகநக நட்பது நட்பு.", transliteration: "Mukanaka Natpadhu Natpandru Nenjaththu / Akanaka Natpadhu Natpu", english: "The love that dwells (merely in the smiles of the face is not friendship; (but) that which dwells deep in the smiles of the heart is true friendship" },
  { number: 787, tamil: "அழிவி னவைநீக்கி ஆறுய்த்து அழிவின்கண்\nஅல்லல் உழப்பதாம் நட்பு.", transliteration: "Azhivi Navaineekki Aaruyththu Azhivinkan / Allal Uzhappadhaam Natpu", english: "(True) friendship turns aside from evil (ways) makes (him) walk in the (good) way, and, in case of loss if shares his sorrow (with him)" },
  { number: 788, tamil: "உடுக்கை இழந்தவன் கைபோல ஆங்கே\nஇடுக்கண் களைவதாம் நட்பு.", transliteration: "Utukkai Izhandhavan Kaipola Aange / Itukkan Kalaivadhaam Natpu", english: "(True) friendship hastens to the rescue of the afflicted (as readily) as the hand of one whose garment is loosened (before an assembly)" },
  { number: 789, tamil: "நட்பிற்கு வீற்றிருக்கை யாதெனின் கொட்பின்றி\nஒல்லும்வாய் ஊன்றும் நிலை.", transliteration: "Natpirku Veetrirukkai Yaadhenin Kotpindri / Ollumvaai Oondrum Nilai", english: "Friendship may be said to be on its throne when it possesses the power of supporting one at all times and under all circumstances, (in the practice or virtue and wealth)" },
  { number: 790, tamil: "இனையர் இவரெமக்கு இன்னம்யாம் என்று\nபுனையினும் புல்லென்னும் நட்பு.", transliteration: "Inaiyar Ivaremakku Innamyaam Endru / Punaiyinum Pullennum Natpu", english: "Though friends may praise one another saying, \"He is so intimate with us, and we so much (with him)\"; (still) such friendship will appear mean" },
  { number: 791, tamil: "நாடாது நட்டலிற் கேடில்லை நட்டபின்\nவீடில்லை நட்பாள் பவர்க்கு.", transliteration: "Naataadhu Nattalir Ketillai Nattapin / Veetillai Natpaal Pavarkku", english: "As those who are of a friendly nature will not forsake (a friend) after once loving (him), there is no evil so great as contracting a friendship without due inquiry" },
  { number: 792, tamil: "ஆய்ந்தாய்ந்து கொள்ளாதான் கேண்மை கடைமுறை\nதான்சாம் துயரம் தரும்.", transliteration: "Aaindhaaindhu Kollaadhaan Kenmai Kataimurai / Thaansaam Thuyaram Tharum", english: "The friendship contracted by him who has not made repeated inquiry will in the end grieve (him) to death" },
  { number: 793, tamil: "குணமும் குடிமையும் குற்றமும் குன்றா\nஇனனும் அறிந்தியாக்க நட்பு.", transliteration: "Kunamum Kutimaiyum Kutramum Kundraa / Inanum Arindhiyaakka Natpu", english: "Make friendship (with one) after ascertaining (his) character, birth, defects and the whole of one's relations" },
  { number: 794, tamil: "குடிப்பிறந்து தன்கண் பழிநாணு வானைக்\nகொடுத்தும் கொளல்வேண்டும் நட்பு.", transliteration: "Kutippirandhu Thankan Pazhinaanu Vaanaik / Kotuththum Kolalventum Natpu", english: "The friendship of one who belongs to a (good) family and is afraid of (being charged with) guilt, is worth even purchasing" },
  { number: 795, tamil: "அழச்சொல்லி அல்லது இடித்து வழக்கறிய\nவல்லார்நடபு ஆய்ந்து கொளல்.", transliteration: "Azhachcholli Alladhu Itiththu Vazhakkariya / Vallaarnatapu Aaindhu Kolal", english: "You should examine and secure the friendship of those who can speak so as to make you weep over a crime (before its commission) or rebuke you severely (after you have done it) and are able to teach" },
  { number: 796, tamil: "கேட்டினும் உண்டோர் உறுதி கிளைஞரை\nநீட்டி அளப்பதோர் கோல்.", transliteration: "Kettinum Untor Urudhi Kilaignarai / Neetti Alappadhor Kol", english: "Even in ruin there is some good; (for) it is a rod by which one may measure fully (the affection of one's) relations" },
  { number: 797, tamil: "ஊதியம் என்பது ஒருவற்குப் பேதையார்\nகேண்மை ஒரீஇ விடல்.", transliteration: "Oodhiyam Enpadhu Oruvarkup Pedhaiyaar / Kenmai Oreei Vital", english: "It is indead a gain for one to renounce the friendship of fools" },
  { number: 798, tamil: "உள்ளற்க உள்ளம் சிறுகுவ கொள்ளற்க\nஅல்லற்கண் ஆற்றறுப்பார் நட்பு.", transliteration: "Ullarka Ullam Sirukuva Kollarka / Allarkan Aatraruppaar Natpu", english: "Do not think of things that discourage your mind, nor contract friendship with those who would forsake you in adversity" },
  { number: 799, tamil: "கெடுங்காலைக் கைவிடுவார் கேண்மை அடுங்காலை\nஉள்ளினும் உள்ளஞ் சுடும்.", transliteration: "Ketungaalaik Kaivituvaar Kenmai Atungaalai / Ullinum Ullanj Chutum", english: "The very thought of the friendship of those who have deserted one at the approach of adversity will burn one's mind at the time of death" },
  { number: 800, tamil: "மருவுக மாசற்றார் கேண்மைஒன் றீத்தும்\nஒருவுக ஒப்பிலார் நட்பு.", transliteration: "Maruvuka Maasatraar Kenmaion Reeththum / Oruvuka Oppilaar Natpu", english: "Continue to enjoy the friendship of the pure; (but) renounce even with a gift, the friendship of those who do not agree (with the world)" },
  { number: 801, tamil: "பழைமை எனப்படுவது யாதெனின் யாதும்\nகிழமையைக் கீழ்ந்திடா நட்பு.", transliteration: "Pazhaimai Enappatuvadhu Yaadhenin Yaadhum / Kizhamaiyaik Keezhndhitaa Natpu", english: "Imtimate friendship is that which cannot in the least be injured by (things done through the) right (of longstanding intimacy)" },
  { number: 802, tamil: "நட்பிற் குறுப்புக் கெழுதகைமை மற்றதற்கு\nஉப்பாதல் சான்றோர் கடன்.", transliteration: "Natpir Kuruppuk Kezhudhakaimai Matradharku / Uppaadhal Saandror Katan", english: "The constituents of friendship are (things done through) the right of intimacy; to be pleased with such a right is the duty of the wise" },
  { number: 803, tamil: "பழகிய நட்பெவன் செய்யுங் கெழுதகைமை\nசெய்தாங்கு அமையாக் கடை.", transliteration: "Pazhakiya Natpevan Seyyung Kezhudhakaimai / Seydhaangu Amaiyaak Katai", english: "Of what avail is long-standing friendship, if friends do not admit as their own actions done through the right of intimacy ?" },
  { number: 804, tamil: "விழைதகையான் வேண்டி இருப்பர் கெழுதகையாற்\nகேளாது நட்டார் செயின்.", transliteration: "Vizhaidhakaiyaan Venti Iruppar Kezhudhakaiyaar / Kelaadhu Nattaar Seyin", english: "If friends, through the right of friendship, do (anything) without being asked, the wise will be pleased with them on account of its desirability" },
  { number: 805, tamil: "பேதைமை ஒன்றோ பெருங்கிழமை என்றுணர்க\nநோதக்க நட்டார் செயின்.", transliteration: "Pedhaimai Ondro Perungizhamai Endrunarka / Nodhakka Nattaar Seyin", english: "If friends should perform what is painful, understand that it is owing not only to ignorance, but also to the strong claims of intimacy" },
  { number: 806, tamil: "எல்லைக்கண் நின்றார் துறவார் தொலைவிடத்தும்\nதொல்லைக்கண் நின்றார் தொடர்பு.", transliteration: "Ellaikkan Nindraar Thuravaar Tholaivitaththum / Thollaikkan Nindraar Thotarpu", english: "Those who stand within the limits (of true friendship) will not even in adversity give up the intimacy of long-standing friends" },
  { number: 807, tamil: "அழிவந்த செய்யினும் அன்பறார் அன்பின்\nவழிவந்த கேண்மை யவர்.", transliteration: "Azhivandha Seyyinum Anparaar Anpin / Vazhivandha Kenmai Yavar", english: "Those who have (long) stood in the path of affection will not give it up even if their friends cause (them) their ruin" },
  { number: 808, tamil: "கேளிழுக்கம் கேளாக் கெழுதகைமை வல்லார்க்கு\nநாளிழுக்கம் நட்டார் செயின்.", transliteration: "Kelizhukkam Kelaak Kezhudhakaimai Vallaarkku / Naalizhukkam Nattaar Seyin", english: "To those who understand that by which they should not listen to (tales about) the faults of their friends, that is a (profitable) day on which the latter may commit a fault" },
  { number: 809, tamil: "கெடாஅ வழிவந்த கேண்மையார் கேண்மை\nவிடாஅர் விழையும் உலகு.", transliteration: "Ketaaa Vazhivandha Kenmaiyaar Kenmai / Vitaaar Vizhaiyum Ulaku", english: "They will be loved by the world, who have not forsaken the friendship of those with whom they have kept up an unbroken long-standing intimacy" },
  { number: 810, tamil: "விழையார் விழையப் படுப பழையார்கண்\nபண்பின் தலைப்பிரியா தார்.", transliteration: "Vizhaiyaar Vizhaiyap Patupa Pazhaiyaarkan / Panpin Thalaippiriyaa Thaar", english: "Even enemies will love those who have never changed in their affection to their long-standingfriends" },
  { number: 811, tamil: "பருகுவார் போலினும் பண்பிலார் கேண்மை\nபெருகலிற் குன்றல் இனிது.", transliteration: "Parukuvaar Polinum Panpilaar Kenmai / Perukalir Kundral Inidhu", english: "The decrease of friendship with those who look as if they would eat you up (through excess of love) while they are really destitute of goodness is far better than its increase" },
  { number: 812, tamil: "உறின்நட்டு அறினொருஉம் ஒப்பிலார் கேண்மை\nபெறினும் இழப்பினும் என்?", transliteration: "Urinnattu Arinoruum Oppilaar Kenmai / Perinum Izhappinum En?", english: "Of what avail is it to get or lose the friendship of those who love when there is gain and leave when there is none ?" },
  { number: 813, tamil: "உறுவது சீர்தூக்கும் நட்பும் பெறுவது\nகொள்வாரும் கள்வரும் நேர்.", transliteration: "Uruvadhu Seerdhookkum Natpum Peruvadhu / Kolvaarum Kalvarum Ner", english: "Friendship who calculate the profits (of their friendship), prostitutes who are bent on obtaining their gains, and thieves are (all) of the same character" },
  { number: 814, tamil: "அமரகத்து ஆற்றறுக்கும் கல்லாமா அன்னார்\nதமரின் தனிமை தலை.", transliteration: "Amarakaththu Aatrarukkum Kallaamaa Annaar / Thamarin Thanimai Thalai", english: "Solitude is more to be desired than the society of those who resemble the untrained horses which throw down (their riders) in the fields of battle" },
  { number: 815, tamil: "செய்தேமஞ் சாராச் சிறியவர் புன்கேண்மை\nஎய்தலின் எய்தாமை நன்று.", transliteration: "Seydhemanj Chaaraach Chiriyavar Punkenmai / Eydhalin Eydhaamai Nandru", english: "It is far better to avoid that to contract the evil friendship of the base who cannot protect (their friends) even when appointed to do so" },
  { number: 816, tamil: "பேதை பெருங்கெழீஇ நட்பின் அறிவுடையார்\nஏதின்மை கோடி உறும்.", transliteration: "Pedhai Perungezheei Natpin Arivutaiyaar / Edhinmai Koti Urum", english: "The hatred of the wise is ten-million times more profitable than the excessive intimacy of the fool" },
  { number: 817, tamil: "நகைவகைய ராகிய நட்பின் பகைவரால்\nபத்தடுத்த கோடி உறும்.", transliteration: "Nakaivakaiya Raakiya Natpin Pakaivaraal / Paththatuththa Koti Urum", english: "What comes from enemies is a hundred million times more profitable than what comes from the friendship of those who cause only laughter" },
  { number: 818, tamil: "ஒல்லும் கருமம் உடற்று பவர்கேண்மை\nசொல்லாடார் சோர விடல்.", transliteration: "Ollum Karumam Utatru Pavarkenmai / Sollaataar Sora Vital", english: "Gradually abandon without revealing (beforehand) the friendship of those who pretend inability to carry out what they (really) could do" },
  { number: 819, tamil: "கனவினும் இன்னாது மன்னோ வினைவேறு\nசொல்வேறு பட்டார் தொடர்பு.", transliteration: "Kanavinum Innaadhu Manno Vinaiveru / Solveru Pattaar Thotarpu", english: "The friendship of those whose actions do not agree with their words will distress (one) even in (one's) dreams" },
  { number: 820, tamil: "எனைத்தும் குறுகுதல் ஓம்பல் மனைக்கெழீஇ\nமன்றில் பழிப்பார் தொடர்பு.", transliteration: "Enaiththum Kurukudhal Ompal Manaikkezheei / Mandril Pazhippaar Thotarpu", english: "Avoid even the least approach to a contraction of friendship with those who would love you in private but ridicule you in public" },
  { number: 821, tamil: "சீரிடம் காணின் எறிதற்குப் பட்டடை\nநேரா நிரந்தவர் நட்பு.", transliteration: "Seeritam Kaanin Eridharkup Pattatai / Neraa Nirandhavar Natpu", english: "The friendship of those who behave like friends without inward affection is a weapon that may be thrown when a favourable opportunity presents itself" },
  { number: 822, tamil: "இனம்போன்று இனமல்லார் கேண்மை மகளிர்\nமனம்போல வேறு படும்.", transliteration: "Inampondru Inamallaar Kenmai Makalir / Manampola Veru Patum", english: "The friendship of those who seem to be friends while they are not, will change like the love of women" },
  { number: 823, tamil: "பலநல்ல கற்றக் கடைத்து மனநல்லர்\nஆகுதல் மாணார்க் கரிது.", transliteration: "Palanalla Katrak Kataiththu Mananallar / Aakudhal Maanaark Karidhu", english: "Though (one's) enemies may have mastered many good books, it will be impossible for them to become truly loving at heart" },
  { number: 824, tamil: "முகத்தின் இனிய நகாஅ அகத்தின்னா\nவஞ்சரை அஞ்சப் படும்.", transliteration: "Mukaththin Iniya Nakaaa Akaththinnaa / Vanjarai Anjap Patum", english: "One should fear the deceitful who smile sweetly with their face but never love with their heart" },
  { number: 825, tamil: "மனத்தின் அமையா தவரை எனைத்தொன்றும்\nசொல்லினால் தேறற்பாற்று அன்று.", transliteration: "Manaththin Amaiyaa Thavarai Enaiththondrum / Sollinaal Therarpaatru Andru", english: "In nothing whatever is it proper to rely on the words of those who do not love with their heart" },
  { number: 826, tamil: "நட்டார்போல் நல்லவை சொல்லினும் ஒட்டார்சொல்\nஒல்லை உணரப் படும்.", transliteration: "Nattaarpol Nallavai Sollinum Ottaarsol / Ollai Unarap Patum", english: "Though (one's) foes may utter good things as though they were friends, once will at once understand (their evil, import)" },
  { number: 827, tamil: "சொல்வணக்கம் ஒன்னார்கண் கொள்ளற்க வில்வணக்கம்\nதீங்கு குறித்தமை யான்.", transliteration: "Solvanakkam Onnaarkan Kollarka Vilvanakkam / Theengu Kuriththamai Yaan", english: "Since the bending of the bow bespeaks evil, one should not accept (as good) the humiliating speeches of one's foes" },
  { number: 828, tamil: "தொழுதகை யுள்ளும் படையொடுங்கும் ஒன்னார்\nஅழுதகண் ணீரும் அனைத்து.", transliteration: "Thozhudhakai Yullum Pataiyotungum Onnaar / Azhudhakan Neerum Anaiththu", english: "A weapon may be hid in the very hands with which (one's) foes adore (him) (and) the tears they shed are of the same nature" },
  { number: 829, tamil: "மிகச்செய்து தம்மெள்ளு வாரை நகச்செய்து\nநட்பினுள் சாப்புல்லற் பாற்று.", transliteration: "Mikachcheydhu Thammellu Vaarai Nakachcheydhu / Natpinul Saappullar Paatru", english: "It is the duty of kings to affect great love but make it die (inwardly); as regard those foes who shew them great friendship but despise them (in their heart)" },
  { number: 830, tamil: "பகைநட்பாம் காலம் வருங்கால் முகநட்டு\nஅகநட்பு ஒரீஇ விடல்.", transliteration: "Pakainatpaam Kaalam Varungaal Mukanattu / Akanatpu Oreei Vital", english: "When one's foes begin to affect friendship, one should love them with one's looks, and, cherishing no love in the heart, give up (even the former)" },
  { number: 831, tamil: "பேதைமை என்பதொன்று யாதெனின் ஏதங்கொண்டு\nஊதியம் போக விடல்.", transliteration: "Pedhaimai Enpadhondru Yaadhenin Edhangontu / Oodhiyam Poka Vital", english: "Folly is one (of the chief defects); it is that which (makes one) incur loss and forego gain" },
  { number: 832, tamil: "பேதைமையுள் எல்லாம் பேதைமை காதன்மை\nகையல்ல தன்கட் செயல்.", transliteration: "Pedhaimaiyul Ellaam Pedhaimai Kaadhanmai / Kaiyalla Thankat Seyal", english: "The greatest folly is that which leads one to take delight in doing what is forbidden" },
  { number: 833, tamil: "நாணாமை நாடாமை நாரின்மை யாதொன்றும்\nபேணாமை பேதை தொழில்", transliteration: "Naanaamai Naataamai Naarinmai Yaadhondrum / Penaamai Pedhai Thozhil", english: "Shamelessness indifference (to what must be sought after), harshness, and aversion for everything (that ought to be desired) are the qualities of the fool" },
  { number: 834, tamil: "ஓதி உணர்ந்தும் பிறர்க்குரைத்தும் தானடங்காப்\nபேதையின் பேதையார் இல்.", transliteration: "Odhi Unarndhum Pirarkkuraiththum Thaanatangaap / Pedhaiyin Pedhaiyaar Il", english: "There are no greater fools than he who, though he has read and understood (a great deal) and even taught it to others, does not walk according to his own teaching" },
  { number: 835, tamil: "ஒருமைச் செயலாற்றும் பேதை எழுமையும்\nதான்புக் கழுந்தும் அளறு.", transliteration: "Orumaich Cheyalaatrum Pedhai Ezhumaiyum / Thaanpuk Kazhundhum Alaru", english: "A fool can procure in a single birth a hell into which he may enter and suffer through all the seven births" },
  { number: 836, tamil: "பொய்படும் ஒன்றோ புனைபூணும் கையறியாப்\nபேதை வினைமேற் கொளின்.", transliteration: "Poipatum Ondro Punaipoonum Kaiyariyaap / Pedhai Vinaimer Kolin", english: "If the fool, who knows not how to act undertakes a work, he will (certainly) fail (But) is it all ? He will even adorn himself with fetters" },
  { number: 837, tamil: "ஏதிலார் ஆரத் தமர்பசிப்பர் பேதை\nபெருஞ்செல்வம் உற்றக் கடை.", transliteration: "Edhilaar Aarath Thamarpasippar Pedhai / Perunjelvam Utrak Katai", english: "If a fool happens to get an immense fortune, his neighbours will enjoy it while his relations starve" },
  { number: 838, tamil: "மையல் ஒருவன் களித்தற்றால் பேதைதன்\nகையொன்று உடைமை பெறின்.", transliteration: "Maiyal Oruvan Kaliththatraal Pedhaidhan / Kaiyondru Utaimai Perin", english: "A fool happening to possess something is like the intoxication of one who is (already) giddy" },
  { number: 839, tamil: "பெரிதினிது பேதையார் கேண்மை பிரிவின்கண்\nபீழை தருவதொன் றில்.", transliteration: "Peridhinidhu Pedhaiyaar Kenmai Pirivinkan / Peezhai Tharuvadhon Ril", english: "The friendship between fools is exceedingly delightful (to each other): for at parting there will be" },
  { number: 840, tamil: "கழாஅக்கால் பள்ளியுள் வைத்தற்றால் சான்றோர்\nகுழாஅத்துப் பேதை புகல்.", transliteration: "Kazhaaakkaal Palliyul Vaiththatraal Saandror / Kuzhaaaththup Pedhai Pukal", english: "The appearance of a fool in an assembly of the learned is like placing (one's) unwashed feet on a bed" },
  { number: 841, tamil: "அறிவின்மை இன்மையுள் இன்மை பிறிதின்மை\nஇன்மையா வையா துலகு.", transliteration: "Arivinmai Inmaiyul Inmai Piridhinmai / Inmaiyaa Vaiyaa Thulaku", english: "The want of wisdom is the greatest of all wants; but that of wealth the world will not regard as such" },
  { number: 842, tamil: "அறிவிலான் நெஞ்சுவந்து ஈதல் பிறிதியாதும்\nஇல்லை பெறுவான் தவம்.", transliteration: "Arivilaan Nenjuvandhu Eedhal Piridhiyaadhum / Illai Peruvaan Thavam", english: "(The cause of) a fool cheerfully giving (something) is nothing else but the receiver's merit (in a former birth)" },
  { number: 843, tamil: "அறிவிலார் தாந்தம்மைப் பீழிக்கும் பீழை\nசெறுவார்க்கும் செய்தல் அரிது.", transliteration: "Arivilaar Thaandhammaip Peezhikkum Peezhai / Seruvaarkkum Seydhal Aridhu", english: "The suffering that fools inflict upon themselves is hardly possible even to foes" },
  { number: 844, tamil: "வெண்மை எனப்படுவ தியாதெனின் ஒண்மை\nஉடையம்யாம் என்னும் செருக்கு.", transliteration: "Venmai Enappatuva Thiyaadhenin Onmai / Utaiyamyaam Ennum Serukku", english: "What is called want of wisdom is the vanity which says, \"We are wise\"" },
  { number: 845, tamil: "கல்லாத மேற்கொண் டொழுகல் கசடற\nவல்லதூஉம் ஐயம் தரும்.", transliteration: "Kallaadha Merkon Tozhukal Kasatara / Valladhooum Aiyam Tharum", english: "Fools pretending to know what has not been read (by them) will rouse suspicion even as to what they have thoroughly mastered" },
  { number: 846, tamil: "அற்றம் மறைத்தலோ புல்லறிவு தம்வயின்\nகுற்றம் மறையா வழி.", transliteration: "Atram Maraiththalo Pullarivu Thamvayin / Kutram Maraiyaa Vazhi", english: "Even to cover one's nakedness would be folly, if (one's) faults were not covered (by forsaking them)" },
  { number: 847, tamil: "அருமறை சோரும் அறிவிலான் செய்யும்\nபெருமிறை தானே தனக்கு.", transliteration: "Arumarai Sorum Arivilaan Seyyum / Perumirai Thaane Thanakku", english: "The fool who neglects precious counsel does, of his own accord, a great injury to himself" },
  { number: 848, tamil: "ஏவவும் செய்கலான் தான்தேறான் அவ்வுயிர்\nபோஒம் அளவுமோர் நோய்.", transliteration: "Evavum Seykalaan Thaandheraan Avvuyir / Poom Alavumor Noi", english: "The fool will not perform (his duties) even when advised nor ascertain them himself; such a soul is a" },
  { number: 849, tamil: "காணாதான் காட்டுவான் தான்காணான் காணாதான்\nகண்டானாம் தான்கண்ட வாறு.", transliteration: "Kaanaadhaan Kaattuvaan Thaankaanaan Kaanaadhaan / Kantaanaam Thaankanta Vaaru", english: "One who would teach a fool will (simply) betray his folly; and the fool would (still) think himself \"wise in his own conceit\"" },
  { number: 850, tamil: "உலகத்தார் உண்டென்பது இல்லென்பான் வையத்து\nஅலகையா வைக்கப் படும்.", transliteration: "Ulakaththaar Untenpadhu Illenpaan Vaiyaththu / Alakaiyaa Vaikkap Patum", english: "He who denies the existence of what the world believes in will be regarded as a demon on earth" },
  { number: 851, tamil: "இகலென்ப எல்லா உயிர்க்கும் பகலென்னும்\nபண்பின்மை பார஧க்கும் நோய்.", transliteration: "Ikalenpa Ellaa Uyirkkum Pakalennum / Panpinmai Paarikkum Noi", english: "The disease which fosters the evil of disunion among all creatures is termed hatred by the wise" },
  { number: 852, tamil: "பகல்கருதிப் பற்றா செயினும் இகல்கருதி\nஇன்னாசெய் யாமை தலை.", transliteration: "Pakalkarudhip Patraa Seyinum Ikalkarudhi / Innaasey Yaamai Thalai", english: "Though disagreeable things may be done from (a feeling of) disunion, it is far better that nothing painful be done from (that of) hatred" },
  { number: 853, tamil: "இகலென்னும் எவ்வநோய் நீக்கின் தவலில்லாத்\nதாவில் விளக்கம் தரும்.", transliteration: "Ikalennum Evvanoi Neekkin Thavalillaath / Thaavil Vilakkam Tharum", english: "To rid one-self of the distressing dtsease of hatred will bestow (on one) a never-decreasing imperishable fame" },
  { number: 854, tamil: "இன்பத்துள் இன்பம் பயக்கும் இகலென்னும்\nதுன்பத்துள் துன்பங் கெடின்.", transliteration: "Inpaththul Inpam Payakkum Ikalennum / Thunpaththul Thunpang Ketin", english: "If hatred which is the greatest misery is destroyed, it will yield the greatest delight" },
  { number: 855, tamil: "இகலெதிர் சாய்ந்தொழுக வல்லாரை யாரே\nமிக்லூக்கும் தன்மை யவர்.", transliteration: "Ikaledhir Saaindhozhuka Vallaarai Yaare / Mikalookkum Thanmai Yavar", english: "Who indeed would think of conquering those who naturally shrink back from hatred ?" },
  { number: 856, tamil: "இகலின் மிகலினிது என்பவன் வாழ்க்கை\nதவலும் கெடலும் நணித்து.", transliteration: "Ikalin Mikalinidhu Enpavan Vaazhkkai / Thavalum Ketalum Naniththu", english: "Failure and ruin are not far from him who says it is sweet to excel in hatred" },
  { number: 857, tamil: "மிகல்மேவல் மெய்ப்பொருள் காணார் இகல்மேவல்\nஇன்னா அறிவி னவர்.", transliteration: "Mikalmeval Meypporul Kaanaar Ikalmeval / Innaa Arivi Navar", english: "Who only know to work men woe, fulfilled of enmity" },
  { number: 858, tamil: "இகலிற்கு எதிர்சாய்தல் ஆக்கம் அதனை\nமிக்லூக்கின் ஊக்குமாம் கேடு.", transliteration: "Ikalirku Edhirsaaidhal Aakkam Adhanai / Mikalookkin Ookkumaam Ketu", english: "Shrinking back from hatred will yield wealth; indulging in its increase will hasten ruin" },
  { number: 859, tamil: "இகல்காணான் ஆக்கம் வருங்கால் அதனை\nமிகல்காணும் கேடு தரற்கு.", transliteration: "Ikalkaanaan Aakkam Varungaal Adhanai / Mikalkaanum Ketu Thararku", english: "At the approach of wealth one will not think of hatred (but) to secure one's ruin, one will look to its increase" },
  { number: 860, tamil: "இகலானாம் இன்னாத எல்லாம் நகலானாம்\nநன்னயம் என்னும் செருக்கு.", transliteration: "Ikalaanaam Innaadha Ellaam Nakalaanaam / Nannayam Ennum Serukku", english: "All calamities are caused by hatred; but by the delight (of friendship) is caused the great wealth of good virtues" },
  { number: 861, tamil: "வலியார்க்கு மாறேற்றல் ஓம்புக ஓம்பா\nமெலியார்மேல் மேக பகை.", transliteration: "Valiyaarkku Maaretral Ompuka Ompaa / Meliyaarmel Meka Pakai", english: "Avoid offering resistance to the strong; (but) never fail to cherish enmity towards the weak" },
  { number: 862, tamil: "அன்பிலன் ஆன்ற துணையிலன் தான்துவ்வான்\nஎன்பரியும் ஏதிலான் துப்பு.", transliteration: "Anpilan Aandra Thunaiyilan Thaandhuvvaan / Enpariyum Edhilaan Thuppu", english: "How can he who is unloving, destitute of powerful aids, and himself without strength overcome the might of his foe ?" },
  { number: 863, tamil: "அஞ்சும் அறியான் அமைவிலன் ஈகலான்\nதஞ்சம் எளியன் பகைக்கு.", transliteration: "Anjum Ariyaan Amaivilan Eekalaan / Thanjam Eliyan Pakaikku", english: "In the estimation of foes miserably weak is he, who is timid, ignorant, unsociable and niggardly" },
  { number: 864, tamil: "நீங்கான் வெகுளி நிறையிலன் எஞ்ஞான்றும்\nயாங்கணும் யார்க்கும் எளிது.", transliteration: "Neengaan Vekuli Niraiyilan Egngnaandrum / Yaanganum Yaarkkum Elidhu", english: "He who neither refrains from anger nor keeps his secrets will at all times and in all places be easily conquered by all" },
  { number: 865, tamil: "வழிநோக்கான் வாய்ப்பன செய்யான் பழிநோக்கான்\nபண்பிலன் பற்றார்க்கு இனிது.", transliteration: "Vazhinokkaan Vaaippana Seyyaan Pazhinokkaan / Panpilan Patraarkku Inidhu", english: "(A) pleasing (object) to his foes is he who reads not moral works, does nothing that is enjoined by them cares not for reproach and is not possessed of good qualities" },
  { number: 866, tamil: "காணாச் சினத்தான் கழிபெருங் காமத்தான்\nபேணாமை பேணப் படும்.", transliteration: "Kaanaach Chinaththaan Kazhiperung Kaamaththaan / Penaamai Penap Patum", english: "Highly to be desired is the hatred of him whose anger is blind, and whose lust increases beyond measure" },
  { number: 867, tamil: "கொடுத்தும் கொளல்வேண்டும் மன்ற அடுத்திருந்து\nமாணாத செய்வான் பகை.", transliteration: "Kotuththum Kolalventum Mandra Atuththirundhu / Maanaadha Seyvaan Pakai", english: "It is indeed necessary to obtain even by purchase the hatred of him who having begun (a work) does what is not conductive (to its accomplishment)" },
  { number: 868, tamil: "குணனிலனாய்க் குற்றம் பலவாயின் மாற்றார்க்கு\nஇனனிலனாம் ஏமாப் புடைத்து.", transliteration: "Kunanilanaaik Kutram Palavaayin Maatraarkku / Inanilanaam Emaap Putaiththu", english: "He will become friendless who is without (any good) qualities and whose faults are many; (such a character) is a help to (his) foes" },
  { number: 869, tamil: "செறுவார்க்குச் சேணிகவா இன்பம் அறிவிலா\nஅஞ்சும் பகைவர்ப் பெறின்.", transliteration: "Seruvaarkkuch Chenikavaa Inpam Arivilaa / Anjum Pakaivarp Perin", english: "There will be no end of lofty delights to the victorious, if their foes are (both) ignorant and timid" },
  { number: 870, tamil: "கல்லான் வெகுளும் சிறுபொருள் எஞ்ஞான்றும்\nஒல்லானை ஒல்லா தொளி.", transliteration: "Kallaan Vekulum Siruporul Egngnaandrum / Ollaanai Ollaa Tholi", english: "The light (of fame) will never be gained by him who gains not the trifling reputation of having fought an unlearned (foe)" },
  { number: 871, tamil: "பகைஎன்னும் பண்பி லதனை ஒருவன்\nநகையேயும் வேண்டற்பாற்று அன்று.", transliteration: "Pakaiennum Panpi Ladhanai Oruvan / Nakaiyeyum Ventarpaatru Andru", english: "The evil of hatred is not of a nature to be desired by one even in sport" },
  { number: 872, tamil: "வில்லேர் உழவர் பகைகொளினும் கொள்ளற்க\nசொல்லேர் உழவர் பகை.", transliteration: "Viller Uzhavar Pakaikolinum Kollarka / Soller Uzhavar Pakai", english: "Though you may incur the hatred of warriors whose ploughs are bows, incur not that of ministers whose ploughs are words" },
  { number: 873, tamil: "ஏமுற் றவரினும் ஏழை தமியனாய்ப்\nபல்லார் பகைகொள் பவன்.", transliteration: "Emur Ravarinum Ezhai Thamiyanaaip / Pallaar Pakaikol Pavan", english: "He who being alone, incurs the hatred of many is more infatuated than even mad men" },
  { number: 874, tamil: "பகைநட்பாக் கொண்டொழுகும் பண்புடை யாளன்\nதகைமைக்கண் தங்கிற்று உலகு.", transliteration: "Pakainatpaak Kontozhukum Panputai Yaalan / Thakaimaikkan Thangitru Ulaku", english: "Whose worthy rule can change his foes to friends" },
  { number: 875, tamil: "தன்துணை இன்றால் பகையிரண்டால் தான்ஒருவன்\nஇன்துணையாக் கொள்கவற்றின் ஒன்று.", transliteration: "Thandhunai Indraal Pakaiyirantaal Thaanoruvan / Indhunaiyaak Kolkavatrin Ondru", english: "He who is alone and helpless while his foes are two should secure one of them as an agreeable help (to himself)" },
  { number: 876, tamil: "தேறினும் தேறா விடினும் அழிவின்கண்\nதேறான் பகாஅன் விடல்.", transliteration: "Thera�num Theraa Vitinum Azhivinkan / Theraan Pakaaan Vital", english: "Though (one's foe is) aware or not of one's misfortune one should act so as neither to join nor separate (from him)" },
  { number: 877, tamil: "நோவற்க நொந்தது அறியார்க்கு மேவற்க\nமென்மை பகைவர் அகத்து.", transliteration: "Novarka Nondhadhu Ariyaarkku Mevarka / Menmai Pakaivar Akaththu", english: "Relate not your suffering even to friends who are ignorant of it, nor refer to your weakness in the presence of your foes" },
  { number: 878, tamil: "வகையறிந்து தற்செய்து தற்காப்ப மாயும்\nபகைவர்கண் பட்ட செருக்கு.", transliteration: "Vakaiyarindhu Tharseydhu Tharkaappa Maayum / Pakaivarkan Patta Serukku", english: "The joy of one's foes will be destroyed if one guards oneself by knowing the way (of acting) and securing assistance" },
  { number: 879, tamil: "இளைதாக முள்மரம் கொல்க களையுநர்\nகைகொல்லும் காழ்த்த இடத்து.", transliteration: "Ilaidhaaka Mulmaram Kolka Kalaiyunar / Kaikollum Kaazhththa Itaththu", english: "A thorny tree should be felled while young, (for) when it is grown it will destroy the hand of the feller" },
  { number: 880, tamil: "உயிர்ப்ப உளரல்லர் மன்ற செயிர்ப்பவர்\nசெம்மல் சிதைக்கலா தார்.", transliteration: "Uyirppa Ularallar Mandra Seyirppavar / Semmal Sidhaikkalaa Thaar", english: "Those who do not destroy the pride of those who hate (them) will certainly not exist even to breathe" },
  { number: 881, tamil: "நிழல்நீரும் இன்னாத இன்னா தமர்நீரும்\nஇன்னாவாம் இன்னா செயின்.", transliteration: "Nizhalneerum Innaadha Innaa Thamarneerum / Innaavaam Innaa Seyin", english: "Shade and water are not pleasant, (if) they cause disease; so are the qualities of (one's) relations not agreeable, (if) they cause pain" },
  { number: 882, tamil: "வாள்போல பகைவரை அஞ்சற்க அஞ்சுக\nகேள்போல் பகைவர் தொடர்பு.", transliteration: "Vaalpola Pakaivarai Anjarka Anjuka / Kelpol Pakaivar Thotarpu", english: "Fear not foes (who say they would cut) like a sword; (but) fear the friendship of foes (who seemingly" },
  { number: 883, tamil: "உட்பகை அஞ்சித்தற் காக்க உலைவிடத்து\nமட்பகையின் மாணத் தெறும்.", transliteration: "Utpakai Anjiththar Kaakka Ulaivitaththu / Matpakaiyin Maanath Therum", english: "Fear internal enmity and guard yourself; (if not) it will destroy (you) in an evil hour, as surely as the tool which cuts the potter's clay" },
  { number: 884, tamil: "மனமாணா உட்பகை தோன்றின் இனமாணா\nஏதம் பலவும் தரும்.", transliteration: "Manamaanaa Utpakai Thondrin Inamaanaa / Edham Palavum Tharum", english: "The secret enmity of a person whose mind in unreformed will lead to many evils causing disaffection among (one's) relations" },
  { number: 885, tamil: "உறல்முறையான் உட்பகை தோன்றின் இறல்முறையான்\nஏதம் பலவும் தரும்.", transliteration: "Uralmuraiyaan Utpakai Thondrin Iralmuraiyaan / Edham Palavum Tharum", english: "If there appears internal hatred in a (king's) family; it will lead to many a fatal crime" },
  { number: 886, tamil: "ஒன்றாமை ஒன்றியார் கட்படின் எஞ்ஞான்றும்\nபொன்றாமை ஒன்றல் அரிது.", transliteration: "Ondraamai Ondriyaar Katpatin Egngnaandrum / Pondraamai Ondral Aridhu", english: "If hatred arises among (one's) own people, it will be hardly possible (for one) to escape death" },
  { number: 887, tamil: "செப்பின் புணர்ச்சிபோல் கூடினும் கூடாதே\nஉட்பகை உற்ற குடி.", transliteration: "Seppin Punarchchipol Kootinum Kootaadhe / Utpakai Utra Kuti", english: "Never indeed will a family subject to internal hatred unite (really) though it may present an apparent union like that of a casket and its lid" },
  { number: 888, tamil: "அரம்பொருத பொன்போலத் தேயும் உரம்பொருது\nஉட்பகை உற்ற குடி.", transliteration: "Aramporudha Ponpolath Theyum Uramporudhu / Utpakai Utra Kuti", english: "A family subject to internal hatred will wear out and lose its strength like iron that has been filed away" },
  { number: 889, tamil: "எட்பக வன்ன சிறுமைத்தே ஆயினும்\nஉட்பகை உள்ளதாங் கேடு.", transliteration: "Etpaka Vanna Sirumaiththe Aayinum / Utpakai Ulladhaang Ketu", english: "Although internal hatred be as small as the fragment of the sesamum (seed), still does destruction dwell in it" },
  { number: 890, tamil: "உடம்பாடு இலாதவர் வாழ்க்கை குடங்கருள்\nபாம்போடு உடனுறைந் தற்று.", transliteration: "Utampaatu Ilaadhavar Vaazhkkai Kutangarul / Paampotu Utanurain Thatru", english: "Living with those who do not agree (with one) is like dwelling with a cobra (in the same) hut" },
  { number: 891, tamil: "ஆற்றுவார் ஆற்றல் இகழாமை போற்றுவார்\nபோற்றலுள் எல்லாம் தலை.", transliteration: "Aatruvaar Aatral Ikazhaamai Potruvaar / Potralul Ellaam Thalai", english: "Not to disregard the power of those who can carry out (their wishes) is more important than all the watchfulness of those who guard (themselves against evil)" },
  { number: 892, tamil: "பெரியாரைப் பேணாது ஒழுகிற் பெரியாரால்\nபேரா இடும்பை தரும்.", transliteration: "Periyaaraip Penaadhu Ozhukir Periyaaraal / Peraa Itumpai Tharum", english: "To behave without respect for the great (rulers) will make them do (us) irremediable evils" },
  { number: 893, tamil: "கெடல்வேண்டின் கேளாது செய்க அடல்வேண்டின்\nஆற்று பவர்கண் இழுக்கு.", transliteration: "Ketalventin Kelaadhu Seyka Atalventin / Aatru Pavarkan Izhukku", english: "If a person desires ruin, let him not listen to the righteous dictates of law, but commit crimes against those who are able to slay (other sovereigns)" },
  { number: 894, tamil: "கூற்றத்தைக் கையால் விளித்தற்றால் ஆற்றுவார்க்கு\nஆற்றாதார் இன்னா செயல்.", transliteration: "Kootraththaik Kaiyaal Viliththatraal Aatruvaarkku / Aatraadhaar Innaa Seyal", english: "The weak doing evil to the strong is like beckoning Yama to come (and destroy them)" },
  { number: 895, tamil: "யாண்டுச்சென்று யாண்டும் உளராகார் வெந்துப்பின்\nவேந்து செறப்பட் டவர்.", transliteration: "Yaantuch Chendru Yaantum Ularaakaar / Vendhuppin Vendhu Serappat Tavar", english: "Those who have incurred the wrath of a cruel and mighty potentate will not prosper wherever they may go" },
  { number: 896, tamil: "எரியால் சுடப்படினும் உய்வுண்டாம் உய்யார்\nபெரியார்ப் பிழைத்தொழுகு வார்.", transliteration: "Eriyaal Sutappatinum Uyvuntaam Uyyaar / Periyaarp Pizhaiththozhuku Vaar", english: "Though burnt by a fire (from a forest), one may perhaps live; (but) never will he live who has shown disrespect to the great (devotees)" },
  { number: 897, tamil: "வகைமாண்ட வாழ்க்கையும் வான்பொருளும் என்னாம்\nதகைமாண்ட தக்கார் செறின்.", transliteration: "Vakaimaanta Vaazhkkaiyum Vaanporulum Ennaam / Thakaimaanta Thakkaar Serin", english: "If a king incurs the wrath of the righteous great, what will become of his government with its splendid auxiliaries and (all) its untold wealth ?" },
  { number: 898, tamil: "குன்றன்னார் குன்ற மதிப்பின் குடியொடு\nநின்றன்னார் மாய்வர் நிலத்து.", transliteration: "Kundrannaar Kundra Madhippin Kutiyotu / Nindrannaar Maaivar Nilaththu", english: "If (the) hill-like (devotees) resolve on destruction, those who seemed to be everlasting will be destroyed root and branch from the earth" },
  { number: 899, tamil: "ஏந்திய கொள்கையார் சீறின் இடைமுரிந்து\nவேந்தனும் வேந்து கெடும்.", transliteration: "Endhiya Kolkaiyaar Seerin Itaimurindhu / Vendhanum Vendhu Ketum", english: "Kings even fall from high estate and perish in the flame" },
  { number: 900, tamil: "இறந்தமைந்த சார்புடையர் ஆயினும் உய்யார்\nசிறந்தமைந்த சீரார் செறின்.", transliteration: "Irandhamaindha Saarputaiyar Aayinum Uyyaar / Sirandhamaindha Seeraar Serin", english: "Though in possession of numerous auxiliaries, they will perish who are-exposed to the wrath of the noble whose penance is boundless" },
  { number: 901, tamil: "மனைவிழைவார் மாண்பயன் எய்தார் வினைவிழையார்\nவேண்டாப் பொருளும் அது.", transliteration: "Manaivizhaivaar Maanpayan Eydhaar Vinaivizhaiyaar / Ventaap Porulum Adhu", english: "Those who lust after their wives will not attain the excellence of virtue; and it is just this that is not desired by those who are bent on acquiring wealth" },
  { number: 902, tamil: "பேணாது பெண்விழைவான் ஆக்கம் பெரியதோர்\nநாணாக நாணுத் தரும்.", transliteration: "Penaadhu Penvizhaivaan Aakkam Periyadhor / Naanaaka Naanuth Tharum", english: "The wealth of him who, regardless (of his manliness), devotes himself to his wife's feminine nature will cause great shame (to ali men) and to himself;" },
  { number: 903, tamil: "இல்லாள்கண் தாழ்ந்த இயல்பின்மை எஞ்ஞான்றும்\nநல்லாருள் நாணுத் தரும்.", transliteration: "Illaalkan Thaazhndha Iyalpinmai Egngnaandrum / Nallaarul Naanuth Tharum", english: "The frailty that stoops to a wife will always make (her husband) feel ashamed among the good" },
  { number: 904, tamil: "மனையாளை அஞ்சும் மறுமையி லாளன்\nவினையாண்மை வீறெய்த லின்று.", transliteration: "Manaiyaalai Anjum Marumaiyi Laalan / Vinaiyaanmai Veereydha Lindru", english: "The undertaking of one, who fears his wife and is therefore destitute of (bliss), will never be applauded" },
  { number: 905, tamil: "இல்லாளை அஞ்சுவான் அஞ்சுமற் றெஞ்ஞான்றும்\nநல்லார்க்கு நல்ல செயல்.", transliteration: "Illaalai Anjuvaan Anjumar Regngnaandrum / Nallaarkku Nalla Seyal", english: "He that fears his wife will always be afraid of doing good deeds (even) to the good" },
  { number: 906, tamil: "இமையாரின் வாழினும் பாடிலரே இல்லாள்\nஅமையார்தோள் அஞ்சு பவர்.", transliteration: "Imaiyaarin Vaazhinum Paatilare Illaal / Amaiyaardhol Anju Pavar", english: "They that fear the bamboo-like shoulders of their wives will be destitute of manliness though they may flourish like the Gods" },
  { number: 907, tamil: "பெண்ணேவல் செய்தொழுகும் ஆண்மையின் நாணுடைப்\nபெண்ணே பெருமை உடைத்து.", transliteration: "Penneval Seydhozhukum Aanmaiyin Naanutaip / Penne Perumai Utaiththu", english: "Even shame faced womanhood is more to be esteemed than the shameless manhood that performs" },
  { number: 908, tamil: "நட்டார் குறைமுடியார் நன்றாற்றார் நன்னுதலாள்\nபெட் டாங்கு ஒழுகு பவர்.", transliteration: "Nattaar Kuraimutiyaar Nandraatraar Nannudhalaal / Pettaangu Ozhuku Pavar", english: "Those who yield to the wishes of their wives will neither relieve the wants of (their) friends nor perform virtuous deeds" },
  { number: 909, tamil: "அறவினையும் ஆன்ற பொருளும் பிறவினையும்\nபெண்ஏவல் செய்வார்கண் இல்.", transliteration: "Aravinaiyum Aandra Porulum Piravinaiyum / Peneval Seyvaarkan Il", english: "From those who obey the commands of their wives are to be expected neither deeds of virtue, nor those of wealth nor (even) those of pleasure" },
  { number: 910, tamil: "எண்சேர்ந்த நெஞ்சத் திடனுடையார்க்கு எஞ்ஞான்றும்\nபெண்சேர்ந்தாம் பேதைமை இல்.", transliteration: "Enserndha Nenjath Thitanutaiyaarkku Egngnaandrum / Penserndhaam Pedhaimai Il", english: "The foolishness that results from devotion to a wife will never be found in those who possess a reflecting mind and a prosperity (flowing) therefrom" },
  { number: 911, tamil: "அன்பின் விழையார் பொருள்விழையும் ஆய்தொடியார்\nஇன்சொல் இழுக்குத் தரும்.", transliteration: "Anpin Vizhaiyaar Porulvizhaiyum Aaidhotiyaar / Insol Izhukkuth Tharum", english: "The sweet words of elegant braceleted (prostitutes) who desire (a man) not from affection but from avarice, will cause sorrow" },
  { number: 912, tamil: "பயன்தூக்கிப் பண்புரைக்கும் பண்பின் மகளிர்\nநயன்தூக்கி நள்ளா விடல்.", transliteration: "Payandhookkip Panpuraikkum Panpin Makalir / Nayandhookki Nallaa Vital", english: "One must ascertain the character of the ill-natured women who after ascertaining the wealth (of a man) speak (as if they were) good natured-ones, and avoid intercourse (with them)" },
  { number: 913, tamil: "பொருட்பெண்டிர் பொய்ம்மை முயக்கம் இருட்டறையில்\nஏத஧ல் பிணந்தழீஇ அற்று.", transliteration: "Porutpentir Poimmai Muyakkam Iruttaraiyil / Edhil Pinandhazheei Atru", english: "The false embraces of wealth-loving women are like (hired men) embracing a strange corpse in a dark room" },
  { number: 914, tamil: "பொருட்பொருளார் புன்னலந் தோயார் அருட்பொருள்\nஆயும் அறிவி னவர்.", transliteration: "Porutporulaar Punnalan Thoyaar Arutporul / Aayum Arivi Navar", english: "The wise who seek the wealth of grace will not desire the base favours of those who regard wealth (and not pleasure) as (their) riches" },
  { number: 915, tamil: "பொதுநலத்தார் புன்னலம் தோயார் மதிநலத்தின்\nமாண்ட அறிவி னவர்.", transliteration: "Podhunalaththaar Punnalam Thoyaar Madhinalaththin / Maanta Arivi Navar", english: "Those whose knowledge is made excellent by their (natural) sense will not covet the trffling delights" },
  { number: 916, tamil: "தந்நலம் பாரிப்பார் தோயார் தகைசெருக்கிப்\nபுன்னலம் பாரிப்பார் தோள்.", transliteration: "Thannalam Paarippaar Thoyaar Thakaiserukkip / Punnalam Paarippaar Thol", english: "Those who would spread (the fame of) their own goodness will not desire the shoulders of those,who rejoice in their accomplishments and bestow their despicable favours (on all who pay)" },
  { number: 917, tamil: "நிறைநெஞ்சம் இல்லவர் தோய்வார் பிறநெஞ்சிற்\nபேணிப் புணர்பவர் தோள்.", transliteration: "Nirainenjam Illavar Thoivaar Piranenjir / Penip Punarpavar Thol", english: "Those who are destitute of a perfectly (reformed) mind will covet the shoulders of those who embrace (them) while their hearts covet other things" },
  { number: 918, tamil: "ஆயும் அறிவினர் அல்லார்க்கு அணங்கென்ப\nமாய மகளிர் முயக்கு.", transliteration: "Aayum Arivinar Allaarkku Anangenpa / Maaya Makalir Muyakku", english: "The wise say that to such as are destitute of discerning sense the embraces of faithless women are (as ruinous as those of) the celestail female" },
  { number: 919, tamil: "வரைவிலா மாணிழையார் மென்தோள் புரையிலாப்\nபூரியர்கள் ஆழும் அளறு.", transliteration: "Varaivilaa Maanizhaiyaar Mendhol Puraiyilaap / Pooriyarkal Aazhum Alaru", english: "The delicate shoulders of prostitutes with excellent jewels are a hell into which are plunged the ignorant base" },
  { number: 920, tamil: "இருமனப் பெண்டிரும் கள்ளும் கவறும்\nதிருநீக்கப் பட்டார் தொடர்பு.", transliteration: "Irumanap Pentirum Kallum Kavarum / Thiruneekkap Pattaar Thotarpu", english: "Treacherous women, liquor, and gambling are the associates of such as have forsaken by Fortune" },
  { number: 921, tamil: "உட்கப் படாஅர் ஒளியிழப்பர் எஞ்ஞான்றும்\nகட்காதல் கொண்டொழுகு வார்.", transliteration: "Utkap Pataaar Oliyizhappar Egngnaandrum / Katkaadhal Kontozhuku Vaar", english: "Those who always thirst after drink will neither inspire fear (in others) nor retain the light (of their fame)" },
  { number: 922, tamil: "உண்ணற்க கள்ளை உணில்உண்க சான்றோரான்\nஎண்ணப் படவேண்டா தார்.", transliteration: "Unnarka Kallai Unilunka Saandroraan / Ennap Pataventaa Thaar", english: "Let no liquor be drunk; if it is desired, let it be drunk by those who care not for esteem of the great" },
  { number: 923, tamil: "ஈன்றாள் முகத்தேயும் இன்னாதால் என்மற்றுச்\nசான்றோர் முகத்துக் களி.", transliteration: "Eendraal Mukaththeyum Innaadhaal Enmatruch / Chaandror Mukaththuk Kali", english: "Intoxication is painful even in the presence of (one's) mother; what will it not then be in that of the wise ?" },
  { number: 924, tamil: "நாண்என்னும் நல்லாள் புறங்கொடுக்கும் கள்ளென்னும்\nபேணாப் பெருங்குற்றத் தார்க்கு.", transliteration: "Naanennum Nallaal Purangotukkum Kallennum / Penaap Perungutrath Thaarkku", english: "The fair maid of modesty will turn her back on those who are guilty of the great and abominable crime of drunkenness" },
  { number: 925, tamil: "கையறி யாமை உடைத்தே பொருள்கொடுத்து\nமெய்யறி யாமை கொளல்.", transliteration: "Kaiyari Yaamai Utaiththe Porulkotuththu / Meyyari Yaamai Kolal", english: "To give money and purchase unconsciousness is the result of one's ignorance of (one's own actions)" },
  { number: 926, tamil: "துஞ்சினார் செத்தாரின் வேறல்லர் எஞ்ஞான்றும்\nநஞ்சுண்பார் கள்ளுண் பவர்.", transliteration: "Thunjinaar Seththaarin Verallar Egngnaandrum / Nanjunpaar Kallun Pavar", english: "They that sleep resemble the deed; (likewise) they that drink are no other than poison-eaters" },
  { number: 927, tamil: "உள்ளொற்றி உள்ளூர் நகப்படுவர் எஞ்ஞான்றும்\nகள்ளொற்றிக் கண்சாய் பவர்", transliteration: "Ullotri Ulloor Nakappatuvar Egngnaandrum / Kallotrik Kansaai Pavar", english: "Those who always intoxicate themselves by a private (indulgence in) drink; will have their secrets detected and laughed at by their fellow-townsmen" },
  { number: 928, tamil: "களித்தறியேன் என்பது கைவிடுக நெஞ்சத்து\nஒளித்ததூஉம் ஆங்கே மிகும்.", transliteration: "Kaliththariyen Enpadhu Kaivituka Nenjaththu / Oliththadhooum Aange Mikum", english: "Let (the drunkard) give up saying \"I have never drunk\"; (for) the moment (he drinks) he will simply betray his former attempt to conceal" },
  { number: 929, tamil: "களித்தானைக் காரணம் காட்டுதல் கீழ்நீர்க்\nகுளித்தானைத் தீத்துரீஇ அற்று.", transliteration: "Kaliththaanaik Kaaranam Kaattudhal Keezhneerk / Kuliththaanaith Theeththureei Atru", english: "Reasoning with a drunkard is like going under water with a torch in search of a drowned man" },
  { number: 930, tamil: "கள்ளுண்ணாப் போழ்திற் களித்தானைக் காணுங்கால்\nஉள்ளான்கொல் உண்டதன் சோர்வு.", transliteration: "Kallunnaap Pozhdhir Kaliththaanaik Kaanungaal / Ullaankol Untadhan Sorvu", english: "When (a drunkard) who is sober sees one who is not, it looks as if he remembered not the evil effects of his (own) drink" },
  { number: 931, tamil: "வேண்டற்க வென்றிடினும் சூதினை வென்றதூஉம்\nதூண்டிற்பொன் மீன்விழுங்கி அற்று.", transliteration: "Ventarka Vendritinum Soodhinai Vendradhooum / Thoontirpon Meenvizhungi Atru", english: "Though able to win, let not one desire gambling; (for) even what is won is like a fish swallowing the iron in fish-hook" },
  { number: 932, tamil: "ஒன்றெய்தி நூறிழக்கும் சூதர்க்கும் உண்டாங்கொல்\nநன்றெய்தி வாழ்வதோர் ஆறு.", transliteration: "Ondreydhi Noorizhakkum Soodharkkum Untaangol / Nandreydhi Vaazhvadhor Aaru", english: "That they may good obtain, and see a prosperous day? Is there indeed a means of livelihood that can bestow happiness on gamblers who gain one and lose a hundred?" },
  { number: 933, tamil: "உருளாயம் ஓவாது கூறின் பொருளாயம்\nபோஒய்ப் புறமே படும்.", transliteration: "Urulaayam Ovaadhu Koorin Porulaayam / Pooip Purame Patum", english: "If the king is incessantly addicted to the rolling dice in the hope of gain, his wealth and the resources thereof will take their departure and fall into other's hands" },
  { number: 934, tamil: "சிறுமை பலசெய்து சீரழக்கும் சூதின்\nவறுமை தருவதொன்று இல்.", transliteration: "Sirumai Palaseydhu Seerazhikkum Soodhin / Varumai Tharuvadhondru Il", english: "There is nothing else that brings (us) poverty like gambling which causes many a misery and destroys (one's) reputation" },
  { number: 935, tamil: "கவறும் கழகமும் கையும் தருக்கி\nஇவறியார் இல்லாகி யார்.", transliteration: "Kavarum Kazhakamum Kaiyum Tharukki / Ivariyaar Illaaki Yaar", english: "Penniless are those who by reason of their attachment would never forsake gambling, the gamblingplace and the handling (of dice)" },
  { number: 936, tamil: "அகடாரார் அல்லல் உழப்பர்சூ தென்னும்\nமுகடியான் மூடப்பட் டார்.", transliteration: "Akataaraar Allal Uzhapparsoo Thennum / Mukatiyaan Mootappat Taar", english: "Those who are swallowed by the goddess called \"gambling\" will never have their hunger satisfied, but suffer the pangs of hell in the next world" },
  { number: 937, tamil: "பழகிய செல்வமும் பண்பும் கெடுக்கும்\nகழகத்துக் காலை புகின்.", transliteration: "Pazhakiya Selvamum Panpum Ketukkum / Kazhakaththuk Kaalai Pukin", english: "To waste time at the place of gambling will destroy inherited wealth and goodness of character" },
  { number: 938, tamil: "பொருள்கெடுத்துப் பொய்மேற் கொளீஇ அருள்கெடுத்து\nஅல்லல் உழப்பிக்கும் சூது.", transliteration: "Porul Ketuththup Poimer Koleei / Arulketuththu Allal Uzhappikkum Soodhu", english: "Gambling destroys property, teaches falsehood, puts an end to benevolence, and brings in misery (here and hereafter)" },
  { number: 939, tamil: "உடைசெல்வம் ஊண்ஒளி கல்விஎன்று ஐந்தும்\nஅடையாவாம் ஆயங் கொளின்.", transliteration: "Utaiselvam Oonoli Kalviendru Aindhum / Ataiyaavaam Aayang Kolin", english: "The habit of gambling prevents the attainment of these five: clothing, wealth, food, fame and learning" },
  { number: 940, tamil: "இழத்தொறூஉம் காதலிக்கும் சூதேபோல் துன்பம்\nஉழத்தொறூஉம் காதற்று உயிர்.", transliteration: "Izhaththoru�um Kaadhalikkum Soodhepol Thunpam / Uzhaththoru�um Kaadhatru Uyir", english: "As the gambler loves (his vice) the more he loses by it, so does the soul love (the body) the more it suffers through it" },
  { number: 941, tamil: "மிகினும் குறையினும் நோய்செய்யும் நூலோர்\nவளிமுதலா எண்ணிய மூன்று.", transliteration: "Mikinum Kuraiyinum Noiseyyum Noolor / Valimudhalaa Enniya Moondru", english: "If (food and work are either) excessive or deficient, the three things enumerated by (medical) writers, flatulence, biliousness, and phlegm, will cause (one) disease" },
  { number: 942, tamil: "மருந்தென வேண்டாவாம் யாக்கைக்கு அருந்தியது\nஅற்றது போற்றி உணின்.", transliteration: "Marundhena Ventaavaam Yaakkaikku Arundhiyadhu / Atradhu Potri Unin", english: "No medicine is necessary for him who eats after assuring (himself) that what he has (already) eaten has been digested" },
  { number: 943, tamil: "அற்றால் அறவறிந்து உண்க அஃதுடம்பு\nபெற்றான் நெடிதுய்க்கும் ஆறு.", transliteration: "Atraal Aravarindhu Unka Aqdhutampu / Petraan Netidhuykkum Aaru", english: "If (one's food has been) digested let one eat with moderation; (for) that is the way to prolong the life of an embodied soul" },
  { number: 944, tamil: "அற்றது அறிந்து கடைப்பிடித்து மாறல்ல\nதுய்க்க துவரப் பசித்து.", transliteration: "Atradhu Arindhu Kataippitiththu Maaralla / Thuykka Thuvarap Pasiththu", english: "(First) assure yourself that your food has been digested and never fail to eat, when very hungry, whatever is not disagreeable (to you)" },
  { number: 945, tamil: "மாறுபாடு இல்லாத உண்டி மறுத்துண்ணின்\nஊறுபாடு இல்லை உயிர்க்கு.", transliteration: "Maarupaatu Illaadha Unti Maruththunnin / Oorupaatu Illai Uyirkku", english: "There will be no disaster to one's life if one eats with moderation, food that is not disagreeable" },
  { number: 946, tamil: "இழிவறிந்து உண்பான்கண் இன்பம்போல் நிற்கும்\nகழிபேர் இரையான்கண் நோய்.", transliteration: "Izhivarindhu Unpaankan Inpampol Nirkum / Kazhiper Iraiyaankan Noi", english: "As pleasure dwells with him who eats moderately, so disease (dwells) with the glutton who eats voraciously" },
  { number: 947, tamil: "தீயள வன்றித் தெரியான் பெரிதுண்ணின்\nநோயள வின்றிப் படும்.", transliteration: "Theeyala Vandrith Theriyaan Peridhunnin / Noyala Vindrip Patum", english: "He will be afflicted with numberless diseases, who eats immoderately, ignorant (of the rules of health)" },
  { number: 948, tamil: "நோய்நாடி நோய்முதல் நாடி அதுதணிக்கும்\nவாய்நாடி வாய்ப்பச் செயல்.", transliteration: "Noinaati Noimudhal Naati Adhudhanikkum / Vaainaati Vaaippach Cheyal", english: "Let the physician enquire into the (nature of the) disease, its cause and its method of cure and treat it faithfully according to (medical rule)" },
  { number: 949, tamil: "உற்றான் அளவும் பிணியளவும் காலமும்\nகற்றான் கருதிச் செயல்.", transliteration: "Utraan Alavum Piniyalavum Kaalamum / Katraan Karudhich Cheyal", english: "The learned (physician) should ascertain the condition of his patient; the nature of his disease, and the season (of the year) and (then) proceed (with his treatment)" },
  { number: 950, tamil: "உற்றவன் தீர்ப்பான் மருந்துழைச் செல்வானென்று\nஅப்பால் நாற் கூற்றே மருந்து.", transliteration: "Utravan Theerppaan Marundhuzhaich Chelvaanendru / Appaal Naar Kootre Marundhu", english: "Medical science consists of four parts, viz, patient, physician, medicine and compounder; and each of these (again) contains four sub-divisions" },
  { number: 951, tamil: "இற்பிறந்தார் கண்அல்லது இல்லை இயல்பாகச்\nசெப்பமும் நாணும் ஒருங்கு.", transliteration: "Irpirandhaar Kanalladhu Illai Iyalpaakach / Cheppamum Naanum Orungu", english: "Consistency (of thought, word and deed) and fear (of sin) are conjointly natural only to the high-born" },
  { number: 952, tamil: "ஒழுக்கமும் வாய்மையும் நாணும்இம் மூன்றும்\nஇழுக்கார் குடிப்பிறந் தார்.", transliteration: "Ozhukkamum Vaaimaiyum Naanum Im / Moondrum Izhukkaar Kutippiran Thaar", english: "The high-born will never deviate from these three; good manners, truthfulness and modesty" },
  { number: 953, tamil: "நகைஈகை இன்சொல் இகழாமை நான்கும்\nவகையென்ப வாய்மைக் குடிக்கு.", transliteration: "Nakaieekai Insol Ikazhaamai Naankum / Vakaiyenpa Vaaimaik Kutikku", english: "A cheerful countenance, liberality, pleasant words, and an unreviling disposition, these four are said to be the proper qualities of the truly high-born" },
  { number: 954, tamil: "அடுக்கிய கோடி பெறினும் குடிப்பிறந்தார்\nகுன்றுவ செய்தல் இலர்.", transliteration: "Atukkiya Koti Perinum Kutippirandhaar / Kundruva Seydhal Ilar", english: "Though blessed with immense wealth, the noble will never do anything unbecoming" },
  { number: 955, tamil: "வழங்குவ துள்வீழ்ந்தக் கண்ணும் பழங்குடி\nபண்பில் தலைப்பிரிதல் இன்று.", transliteration: "Vazhanguva Thulveezhndhak Kannum Pazhanguti / Panpil Thalaippiridhal Indru", english: "Though their means fall off, those born in ancient families, will not lose their character (for liberality)" },
  { number: 956, tamil: "சலம்பற்றிச் சால்பில செய்யார்மா சற்ற\nகுலம்பற்றி வாழ்தும் என் பார்.", transliteration: "Salampatrich Chaalpila Seyyaarmaa Satra / Kulampatri Vaazhdhum En Paar", english: "Those who seek to preserve the irreproachable honour of their families will not viciously do what is detrimental thereto" },
  { number: 957, tamil: "குடிப்பிறந்தார் கண்விளங்கும் குற்றம் விசும்பின்\nமத஧க்கண் மறுப்போல் உயர்ந்து.", transliteration: "Kutippirandhaar Kanvilangum Kutram Visumpin / Madhikkan Maruppol Uyarndhu", english: "As spots on her bright orb that walks sublime the evening sky" },
  { number: 958, tamil: "நலத்தின்கண் நாரின்மை தோன்றின் அவனைக்\nகுலத்தின்கண் ஐயப் படும்.", transliteration: "Nalaththinkan Naarinmai Thondrin Avanaik / Kulaththinkan Aiyap Patum", english: "If one of a good family betrays want of affection, his descent from it will be called in question" },
  { number: 959, tamil: "நிலத்தில் கிடந்தமை கால்காட்டும் காட்டும்\nகுலத்தில் பிறந்தார்வாய்ச் சொல்.", transliteration: "Nilaththil Kitandhamai Kaalkaattum Kaattum / Kulaththil Pirandhaarvaaich Chol", english: "As the sprout indicates the nature of the soil, (so) the speech of the noble indicates (that of one's birth)" },
  { number: 960, tamil: "நலம்வேண்டின் நாணுடைமை வேண்டும் குலம்வேண்டின்\nவேண்டுக யார்க்கும் பணிவு.", transliteration: "Nalamventin Naanutaimai Ventum Kulam / Ventin Ventuka Yaarkkum Panivu", english: "He who desires a good name must desire modesty; and he who desires (the continuance of) a family greatness must be submissive to all" },
  { number: 961, tamil: "இன்றி அமையாச் சிறப்பின ஆயினும்\nகுன்ற வருப விடல்.", transliteration: "Indri Amaiyaach Chirappina Aayinum / Kundra Varupa Vital", english: "Actions that would degrade (one's) family should not be done; though they may be so important that not doing them would end in death" },
  { number: 962, tamil: "சீரினும் சீரல்ல செய்யாரே சீரொடு\nபேராண்மை வேண்டு பவர்.", transliteration: "Seerinum Seeralla Seyyaare Seerotu / Peraanmai Ventu Pavar", english: "Those who desire (to maintain their) honour, will surely do nothing dishonourable, even for the sake of fame" },
  { number: 963, tamil: "பெருக்கத்து வேண்டும் பணிதல் சிறிய\nசுருக்கத்து வேண்டும் உயர்வு.", transliteration: "Perukkaththu Ventum Panidhal Siriya / Surukkaththu Ventum Uyarvu", english: "In great prosperity humility is becoming; dignity, in great adversity" },
  { number: 964, tamil: "தலையின் இழிந்த மயிரனையர் மாந்தர்\nநிலையின் இழிந்தக் கடை.", transliteration: "Thalaiyin Izhindha Mayiranaiyar Maandhar / Nilaiyin Izhindhak Katai", english: "They who have fallen from their (high) position are like the hair which has fallen from the head" },
  { number: 965, tamil: "குன்றின் அனையாரும் குன்றுவர் குன்றுவ\nகுன்றி அனைய செயின்.", transliteration: "Kundrin Anaiyaarum Kundruvar Kundruva / Kundri Anaiya Seyin", english: "Even those who are exalted like a hill will be thought low, if they commit deeds that are debasing" },
  { number: 966, tamil: "புகழ்இன்றால் புத்தேள்நாட்டு உய்யாதால் என்மற்று\nஇகழ்வார்பின் சென்று நிலை.", transliteration: "Pukazhindraal Puththelnaattu Uyyaadhaal Enmatru / Ikazhvaarpin Sendru Nilai", english: "Why follow men who scorn, and at their bidding wait?" },
  { number: 967, tamil: "ஒட்டார்பின் சென்றொருவன் வாழ்தலின் அந்நிலையே\nகெட்டான் எனப்படுதல் நன்று.", transliteration: "Ottaarpin Sendroruvan Vaazhdhala�n Annilaiye / Kettaan Enappatudhal Nandru", english: "It is better for a man to be said of him that he died in his usual state than that he eked out his life by following those who disgraced him" },
  { number: 968, tamil: "மருந்தோமற்று ஊன்ஓம்பும் வாழ்க்கை பெருந்தகைமை\nபீடழிய வந்த இடத்து.", transliteration: "Marundhomatru Oonompum Vaazhkkai Perundhakaimai / Peetazhiya Vandha Itaththu", english: "For the high-born to keep their body in life when their honour is gone will certainly not prove a remedy against death" },
  { number: 969, tamil: "மயிர்நீப்பின் வாழாக் கவரிமா அன்னார்\nஉயிர்நீப்பர் மானம் வரின்.", transliteration: "Mayirneeppin Vaazhaak Kavarimaa Annaar / Uyirneeppar Maanam Varin", english: "Those who give up (their) life when (their) honour is at stake are like the yark which kills itself at the loss of (even one of) its hairs" },
  { number: 970, tamil: "இளிவரின் வாழாத மானம் உடையார்\nஒளிதொழுது ஏத்தும் உலகு.", transliteration: "Ilivarin Vaazhaadha Maanam Utaiyaar / Olidhozhudhu Eththum Ulaku", english: "The world will (always) praise and adore the fame of the honourable who would rather die than suffer indignity" },
  { number: 971, tamil: "ஒளிஒருவற்கு உள்ள வெறுக்கை இளிஒருவற்கு\nஅஃதிறந்து வாழ்தும் எனல்.", transliteration: "Olioruvarku Ulla Verukkai Ilioruvarku / Aqdhirandhu Vaazhdhum Enal", english: "One's light is the abundance of one's courage; one's darkness is the desire to live destitute of such (a state of mind.)" },
  { number: 972, tamil: "பிறப்பொக்கும் எல்லா உயிர்க்கும் சிறப்பொவ்வா\nசெய்தொழில் வேற்றுமை யான்.", transliteration: "Pirappokkum Ellaa Uyirkkum Sirappovvaa / Seydhozhil Vetrumai Yaan", english: "All human beings agree as regards their birth but differ as regards their characteristics, because of the different qualities of their actions" },
  { number: 973, tamil: "மேலிருந்தும் மேலல்லார் மேலல்லர் கீழிருந்தும்\nகீழல்லார் கீழல் லவர்.", transliteration: "Melirundhum Melallaar Melallar Keezhirundhum / Keezhallaar Keezhal Lavar", english: "Though (raised) above, the base cannot become great; though (brought) low, the great cannot become base" },
  { number: 974, tamil: "ஒருமை மகளிரே போலப் பெருமையும்\nதன்னைத்தான் கொண்டொழுகின் உண்டு.", transliteration: "Orumai Makalire Polap Perumaiyum / Thannaiththaan Kontozhukin Untu", english: "Exists while to itself is true" },
  { number: 975, tamil: "பெருமை யுடையவர் ஆற்றுவார் ஆற்றின்\nஅருமை உடைய செயல்.", transliteration: "Perumai Yutaiyavar Aatruvaar Aatrin / Arumai Utaiya Seyal", english: "(Though reduced) the great will be able to perform, in the proper way, deeds difficult (for others to do)" },
  { number: 976, tamil: "சிறியார் உணர்ச்சியுள் இல்லை பெரியாரைப்\nபேணிக் கொள் வேம் என்னும் நோக்கு.", transliteration: "Siriyaar Unarchchiyul Illai Periyaaraip / Penikkol Vemennum Nokku", english: "It is never in the nature of the base to seek the society of the great and partake of their nature" },
  { number: 977, tamil: "இறப்பே புரிந்த தொழிற்றாம் சிறப்புந்தான்\nசீரல் லவர்கண் படின்.", transliteration: "Irappe Purindha Thozhitraam Sirappundhaan / Seeral Lavarkan Patin", english: "Even nobility of birth, wealth and learning, if in (the possession of) the base, will (only) produce everincreasing pride" },
  { number: 978, tamil: "பணியுமாம் என்றும் பெருமை சிறுமை\nஅணியுமாம் தன்னை வியந்து.", transliteration: "Paniyumaam Endrum Perumai Sirumai / Aniyumaam Thannai Viyandhu", english: "The great will always humble himself; but the mean will exalt himself in self-admiration" },
  { number: 979, tamil: "பெருமை பெருமிதம் இன்மை சிறுமை\nபெருமிதம் ஊர்ந்து விடல்.", transliteration: "Perumai Perumidham Inmai Sirumai / Perumidham Oorndhu Vital", english: "Freedom from conceit is (the nature of true) greatness; (while) obstinacy therein is (that of) meanness" },
  { number: 980, tamil: "அற்றம் மறைக்கும் பெருமை சிறுமைதான்\nகுற்றமே கூறி விடும்.", transliteration: "Atram Maraikkum Perumai Sirumaidhaan / Kutrame Koori Vitum", english: "The great hide the faults of others; the base only divulge them" },
  { number: 981, tamil: "கடன்என்ப நல்லவை எல்லாம் கடன்அறிந்து\nசான்றாண்மை மேற்கொள் பவர்க்கு.", transliteration: "Katanenpa Nallavai Ellaam Katanarindhu / Saandraanmai Merkol Pavarkku", english: "It is said that those who are conscious of their duty and behave with a perfect goodness will regard as natural all that is good" },
  { number: 982, tamil: "குணநலம் சான்றோர் நலனே பிறநலம்\nஎந்நலத்து உள்ளதூஉம் அன்று.", transliteration: "Kunanalam Saandror Nalane Piranalam / Ennalaththu Ulladhooum Andru", english: "The only delight of the perfect is that of their goodness; all other (sensual) delights are not to be included among any (true) delights" },
  { number: 983, tamil: "அன்புநாண் ஒப்புரவு கண்ணோட்டம் வாய்மையொடு\nஐந்துசால் ஊன்றிய தூண்.", transliteration: "Anpunaan Oppuravu Kannottam Vaaimaiyotu / Aindhusaal Oondriya Thoon", english: "Affection, fear (of sin), benevolence, favour and truthfulness; these are the five pillars on which perfect goodness rests" },
  { number: 984, tamil: "கொல்லா நலத்தது நோன்மை பிறர்தீமை\nசொல்லா நலத்தது சால்பு.", transliteration: "Kollaa Nalaththadhu Nonmai Pirardheemai / Sollaa Nalaththadhu Saalpu", english: "Penance consists in the goodness that kills not , and perfection in the goodness that tells not others' faults" },
  { number: 985, tamil: "ஆற்றுவார் ஆற்றல் பணிதல் அதுசான்றோர்\nமாற்றாரை மாற்றும் படை.", transliteration: "Aatruvaar Aatral Panidhal Adhusaandror / Maatraarai Maatrum Patai", english: "Stooping (to inferiors) is the strength of those who can accomplish (an undertaking); and that is the weapon with which the great avert their foes" },
  { number: 986, tamil: "சால்பிற்குக் கட்டளை யாதெனின் தோல்வி\nதுலையல்லார் கண்ணும் கொளல்.", transliteration: "Saalpirkuk Kattalai Yaadhenin Tholvi / Thulaiyallaar Kannum Kolal", english: "The touch-stone of perfection is to receive a defeat even at the hands of one's inferiors" },
  { number: 987, tamil: "இன்னாசெய் தார்க்கும் இனியவே செய்யாக்கால்\nஎன்ன பயத்ததோ சால்பு.", transliteration: "Innaasey Thaarkkum Iniyave Seyyaakkaal / Enna Payaththadho Saalpu", english: "Of what avail is perfect goodness if it cannot do pleasing things even to those who have pained (it) ?" },
  { number: 988, tamil: "இன்மை ஒருவற்கு இளிவன்று சால்பென்னும்\nதிண்மை உண் டாகப் பெறின்.", transliteration: "Inmai Oruvarku Ilivandru Saalpennum / Thinmai Un Taakap Perin", english: "Poverty is no disgrace to one who abounds in good qualities" },
  { number: 989, tamil: "ஊழி பெயரினும் தாம்பெயரார் சான்றாண்மைக்கு\nஆழி எனப்படு வார்.", transliteration: "Oozhi Peyarinum Thaampeyaraar Saandraanmaikku / Aazhi Enappatu Vaar", english: "Those who are said to be the shore of the sea of perfection will never change, though ages may change" },
  { number: 990, tamil: "சான்றவர் சான்றாண்மை குன்றின் இருநிலந்தான்\nதாங்காது மன்னோ பொறை.", transliteration: "Saandravar Saandraanmai Kundrin Irunilandhaan / Thaangaadhu Manno Porai", english: "If there is a defect in the character of the perfect, (even) the great world cannot bear (its) burden" },
  { number: 991, tamil: "எண்பதத்தால் எய்தல் எளிதென்ப யார்மாட்டும்\nபண்புடைமை என்னும் வழக்கு.", transliteration: "Enpadhaththaal Eydhal Elidhenpa Yaarmaattum / Panputaimai Ennum Vazhakku", english: "If one is easy of access to all, it will be easy for one to obtain the virtue called goodness" },
  { number: 992, tamil: "அன்புடைமை ஆன்ற குடிப்பிறத்தல் இவ்விரண்டும்\nபண்புடைமை என்னும் வழக்கு.", transliteration: "Anputaimai Aandra Kutippiraththal Ivvirantum / Panputaimai Ennum Vazhakku", english: "Affectionateness and birth in a good family, these two constitute what is called a proper behaviour to all" },
  { number: 993, tamil: "உறுப்பொத்தல் மக்களொப்பு அன்றால் வெறுத்தக்க\nபண்பொத்தல் ஒப்பதாம் ஒப்பு.", transliteration: "Uruppoththal Makkaloppu Andraal Veruththakka / Panpoththal Oppadhaam Oppu", english: "Resemblance of bodies is no resemblance of souls; true resemblance is the resemblance of qualities that attract" },
  { number: 994, tamil: "நயனொடு நன்றி புரிந்த பயனுடையார்\nபண்புபா ராட்டும் உலகு.", transliteration: "Nayanotu Nandri Purindha Payanutaiyaar / Panpupaa Raattum Ulaku", english: "The world applauds the character of those whose usefulness results from their equity and charity" },
  { number: 995, tamil: "நகையுள்ளும் இன்னா திகழ்ச்சி பகையுள்ளும்\nபண்புள பாடறிவார் மாட்டு.", transliteration: "Nakaiyullum Innaa Thikazhchchi Pakaiyullum / Panpula Paatarivaar Maattu", english: "Reproach is painful to one even in sport; those (therefore) who know the nature of others exhibit (pleasing) qualities even when they are hated" },
  { number: 996, tamil: "பண்புடையார்ப் பட்டுண்டு உலகம் அதுஇன்றேல்\nமண்புக்கு மாய்வது மன்.", transliteration: "Panputaiyaarp Pattuntu Ulakam Adhuindrel / Manpukku Maaivadhu Man", english: "The (way of the) world subsists by contact with the good; if not, it would bury itself in the earth and perish" },
  { number: 997, tamil: "அரம்போலும் கூர்மைய ரேனும் மரம்போல்வர்\nமக்கட்பண்பு இல்லா தவர்.", transliteration: "Arampolum Koormaiya Renum Marampolvar / Makkatpanpu Illaa Thavar", english: "He who is destitute of (true) human qualities (only) resembles a tree, though he may possess the sharpness of a file" },
  { number: 998, tamil: "நண்பாற்றார் ஆகி நயமில செய்வார்க்கும்\nபண்பாற்றார் ஆதல் கடை.", transliteration: "Nanpaatraar Aaki Nayamila Seyvaarkkum / Panpaatraar Aadhal Katai", english: "It is wrong (for the wise) not to exhibit (good) qualities even towards those who bearing no friendship (for them) do only what is hateful" },
  { number: 999, tamil: "நகல்வல்லர் அல்லார்க்கு மாயிரு ஞாலம்\nபகலும்பாற் பட்டன்று இருள்.", transliteration: "Nakalvallar Allaarkku Maayiru Gnaalam / Pakalumpaar Pattandru Irul", english: "To those who cannot rejoice, the wide world is buried darkness even in (broad) day light" },
  { number: 1000, tamil: "பண்பிலான் பெற்ற பெருஞ்செல்வம் நன்பால்\nகலந்தீமை யால்திரிந் தற்று.", transliteration: "Panpilaan Petra Perunjelvam Nanpaal / Kalandheemai Yaaldhirin Thatru", english: "The great wealth obtained by one who has no goodness will perish like pure milk spoilt by the" },
  { number: 1001, tamil: "வைத்தான்வாய் சான்ற பெரும்பொருள் அஃதுண்ணான்\nசெத்தான் செயக்கிடந்தது இல்.", transliteration: "Vaiththaanvaai Saandra Perumporul Aqdhunnaan / Seththaan Seyakkitandhadhu Il", english: "He who does not enjoy the immense riches he has heaped up in his house, is (to be reckoned as) dead, (for) there is nothing achieved (by him)" },
  { number: 1002, tamil: "பொருளானாம் எல்லாமென்று ஈயாது இவறும்\nமருளானாம் மாணாப் பிறப்பு", transliteration: "Porulaanaam Ellaamendru Eeyaadhu Ivarum / Marulaanaam Maanaap Pirappu", english: "He who knows that wealth yields every pleasure and yet is so blind as to lead miserly life will be born a demon" },
  { number: 1003, tamil: "ஈட்டம் இவறி இசைவேண்டா ஆடவர்\nதோற்றம் நிலக்குப் பொறை.", transliteration: "Eettam Ivari Isaiventaa Aatavar / Thotram Nilakkup Porai", english: "A burden to the earth are men bent on the acquisition of riches and not (true) fame" },
  { number: 1004, tamil: "எச்சமென்று என்எண்ணுங் கொல்லோ ஒருவரால்\nநச்சப் படாஅ தவன்.", transliteration: "Echchamendru Enennung Kollo Oruvaraal / Nachchap Pataaa Thavan", english: "What will the miser who is not liked (by any one) regard as his own (in the world to come) ?" },
  { number: 1005, tamil: "கொடுப்பதூஉம் துய்ப்பதூஉம் இல்லார்க்கு அடுக்கிய\nகோடியுண் டாயினும் இல்.", transliteration: "Kotuppadhooum Thuyppadhooum Illaarkku Atukkiya / Kotiyun Taayinum Il", english: "Those who neither give (to others) nor enjoy (their property) are (truly) destitute, though possessing immense riches" },
  { number: 1006, tamil: "ஏதம் பெருஞ்செல்வம் தான்துவ்வான் தக்கார்க்கொன்று\nஈதல் இயல்பிலா தான்.", transliteration: "Edham Perunjelvam Thaandhuvvaan Thakkaarkkondru / Eedhal Iyalpilaa Thaan", english: "He who enjoys not (his riches) nor relieves the wants of the worthy is a disease to his wealth" },
  { number: 1007, tamil: "அற்றார்க்கொன்று ஆற்றாதான் செல்வம் மிகநலம்\nபெற்றாள் தமியள்மூத் தற்று.", transliteration: "Atraarkkondru Aatraadhaan Selvam Mikanalam / Petraal Thamiyalmooth Thatru", english: "The wealth of him who never bestows anything on the destitute is like a woman of beauty growing old without a husband" },
  { number: 1008, tamil: "நச்சப் படாதவன் செல்வம் நடுவூருள்\nநச்சு மரம்பழுத் தற்று.", transliteration: "Nachchap Pataadhavan Selvam Natuvoorul / Nachchu Marampazhuth Thatru", english: "The wealth of him who is disliked (by all) is like the fruit-bearing of the etty tree in the midst of a town" },
  { number: 1009, tamil: "அன்பொரீஇத் தற்செற்று அறநோக்காது ஈட்டிய\nஒண்பொருள் கொள்வார் பிறர்.", transliteration: "Anporeeith Tharsetru Aranokkaadhu Eettiya / Onporul Kolvaar Pirar", english: "To heap up glittering wealth, their hoards shall others take" },
  { number: 1010, tamil: "சீருடைச் செல்வர் சிறுதுனி மாரி\nவறங்கூர்ந் தனையது உடைத்து.", transliteration: "Seerutaich Chelvar Sirudhuni Maari / Varangoorn Thanaiyadhu Utaiththu", english: "The short-lived poverty of those who are noble and rich is like the clouds becoming poor (for a while)" },
  { number: 1011, tamil: "கருமத்தால் நாணுதல் நாணுந் திருநுதல்\nநல்லவர் நாணுப் பிற.", transliteration: "Karumaththaal Naanudhal Naanun Thirunudhal / Nallavar Naanup Pira", english: "True modesty is the fear of (evil) deeds; all other modesty is (simply) the bashfulness of virtuous maids" },
  { number: 1012, tamil: "ஊணுடை எச்சம் உயிர்க்கெல்லாம் வேறல்ல\nநாணுடைமை மாந்தர் சிறப்பு.", transliteration: "Oonutai Echcham Uyirkkellaam Veralla / Naanutaimai Maandhar Sirappu", english: "Food, clothing and the like are common to all men but modesty is peculiar to the good" },
  { number: 1013, tamil: "ஊனைக் குறித்த உயிரெல்லாம் நாண்என்னும்\nநன்மை குறித்தது சால்பு.", transliteration: "Oonaik Kuriththa Uyirellaam Naanennum / Nanmai Kuriththadhu Saalpu", english: "As the body is the abode of the spirit, so the excellence of modesty is the abode of perfection" },
  { number: 1014, tamil: "அணிஅன்றோ நாணுடைமை சான்றோர்க்கு அஃதின்றேல்\nபிணிஅன்றோ பீடு நடை.", transliteration: "Aniandro Naanutaimai Saandrorkku Aqdhindrel / Piniandro Peetu Natai", english: "Is not the modesty ornament of the noble ? Without it, their haughtiness would be a pain (to others)" },
  { number: 1015, tamil: "பிறர்பழியும் தம்பழியும் நாணுவார் நாணுக்கு\nஉறைபதி என்னும் உலகு.", transliteration: "Pirarpazhiyum Thampazhiyum Naanuvaar Naanukku / Uraipadhi Ennum Ulaku", english: "The world regards as the abode of modesty him who fear his own and other's guilt" },
  { number: 1016, tamil: "நாண்வேலி கொள்ளாது மன்னோ வியன்ஞாலம்\nபேணலர் மேலா யவர்.", transliteration: "Naanveli Kollaadhu Manno Viyangnaalam / Penalar Melaa Yavar", english: "The great make modesty their barrier (of defence) and not the wide world" },
  { number: 1017, tamil: "நாணால் உயிரைத் துறப்பர் உயிர்ப்பொருட்டால்\nநாண்துறவார் நாணாள் பவர்.", transliteration: "Naanaal Uyiraith Thurappar Uyirpporuttaal / Naandhuravaar Naanaal Pavar", english: "The modest would rather lose their life for the sake of modesty than lose modesty for the sake of life" },
  { number: 1018, tamil: "பிறர்நாணத் தக்கது தான்நாணா னாயின்\nஅறம்நாணத் தக்கது உடைத்து.", transliteration: "Pirarnaanath Thakkadhu Thaannaanaa Naayin / Aramnaanath Thakkadhu Utaiththu", english: "Virtue is likely to forsake him who shamelessly does what others are ashamed of" },
  { number: 1019, tamil: "குலஞ்சுடும் கொள்கை பிழைப்பின் நலஞ்சுடும்\nநாணின்மை நின்றக் கடை.", transliteration: "Kulanjutum Kolkai Pizhaippin Nalanjutum / Naaninmai Nindrak Katai", english: "Want of manners injures one's family; but want of modesty injures one's character" },
  { number: 1020, tamil: "நாண்அகத் தில்லார் இயக்கம் மரப்பாவை\nநாணால் உயிர்மருட்டி அற்று.", transliteration: "Naanakath Thillaar Iyakkam Marappaavai / Naanaal Uyirmarutti Atru", english: "The actions of those who are without modesty at heart are like those of puppet moved by a string" },
  { number: 1021, tamil: "கருமம் செயஒருவன் கைதூவேன் என்னும்\nபெருமையின் பீடுடையது இல்.", transliteration: "Karumam Seyaoruvan Kaidhooven Ennum / Perumaiyin Peetutaiyadhu Il", english: "There is no higher greatness than that of one saying I will not cease in my effort (to raise my family)" },
  { number: 1022, tamil: "ஆள்வினையும் ஆன்ற அறிவும் எனஇரண்டின்\nநீள்வினையால் நீளும் குடி.", transliteration: "Aalvinaiyum Aandra Arivum Enairantin / Neelvinaiyaal Neelum Kuti", english: "One's family is raised by untiring perseverance in both effort and wise contrivances" },
  { number: 1023, tamil: "குடிசெய்வல் என்னும் ஒருவற்குத் தெய்வம்\nமடிதற்றுத் தான்முந் துறும்.", transliteration: "Kutiseyval Ennum Oruvarkuth Theyvam / Matidhatruth Thaanmun Thurum", english: "The Deity will clothe itself and appear before him who resolves on raising his family" },
  { number: 1024, tamil: "சூழாமல் தானே முடிவெய்தும் தம்குடியைத்\nதாழாது உஞற்று பவர்க்கு.", transliteration: "Soozhaamal Thaane Mutiveydhum Thamkutiyaith / Thaazhaadhu Ugnatru Pavarkku", english: "Those who are prompt in their efforts (to better their family) need no deliberation, such efforts will of themselves succeed" },
  { number: 1025, tamil: "குற்றம் இலனாய்க் குடிசெய்து வாழ்வானைச்\nசுற்றமாச் சுற்றும் உலகு.", transliteration: "Kutram Ilanaaik Kutiseydhu Vaazhvaanaich / Chutramaach Chutrum Ulaku", english: "People will eagerly seek the friendship of the prosperous soul who has raised his family without foul means" },
  { number: 1026, tamil: "நல்லாண்மை என்பது ஒருவற்குத் தான்பிறந்த\nஇல்லாண்மை ஆக்கிக் கொளல்.", transliteration: "Nallaanmai Enpadhu Oruvarkuth Thaanpirandha / Illaanmai Aakkik Kolal", english: "A man's true manliness consists in making himself the head and benefactor of his family" },
  { number: 1027, tamil: "அமரகத்து வன்கண்ணர் போலத் தமரகத்தும்\nஆற்றுவார் மேற்றே பொறை.", transliteration: "Amarakaththu Vankannar Polath Thamarakaththum / Aatruvaar Metre Porai", english: "Amid his kindred so the burthen rests upon the strong" },
  { number: 1028, tamil: "குடிசெய்வார்க் கில்லை பருவம் மடிசெய்து\nமானங் கருதக் கெடும்.", transliteration: "Kutiseyvaark Killai Paruvam Matiseydhu / Maanang Karudhak Ketum", english: "As a family suffers by (one's) indolence and false dignity there is to be so season (good or bad) to those who strive to raise their family" },
  { number: 1029, tamil: "இடும்பைக்கே கொள்கலம் கொல்லோ குடும்பத்தைக்\nகுற்ற மறைப்பான் உடம்பு.", transliteration: "Itumpaikke Kolkalam Kollo Kutumpaththaik / Kutra Maraippaan Utampu", english: "Is it only to suffering that his body is exposed who undertakes to preserve his family from evil ?" },
  { number: 1030, tamil: "இடுக்கண்கால் கொன்றிட வீழும் அடுத்தூன்றும்\nநல்லாள் இலாத குடி.", transliteration: "Itukkankaal Kondrita Veezhum Atuththoondrum / Nallaal Ilaadha Kuti", english: "If there are none to prop up and maintain a family (in distress), it will fall at the stroke of the axe of misfortune" },
  { number: 1031, tamil: "சுழன்றும்ஏர்ப் பின்னது உலகம் அதனால்\nஉழந்தும் உழவே தலை.", transliteration: "Suzhandrumerp Pinnadhu Ulakam Adhanaal / Uzhandhum Uzhave Thalai", english: "Agriculture, though laborious, is the most excellent (form of labour); for people, though they go about (in search of various employments), have at last to resort to the farmer" },
  { number: 1032, tamil: "உழுவார் உலகத்தார்க்கு ஆணிஅஃ தாற்றாது\nஎழுவாரை எல்லாம் பொறுத்து.", transliteration: "Uzhuvaar Ulakaththaarkku Aaniaq Thaatraadhu / Ezhuvaarai Ellaam Poruththu", english: "Agriculturists are (as it were) the linch-pin of the world for they support all other workers who cannot till the soil" },
  { number: 1033, tamil: "உழுதுண்டு வாழ்வாரே வாழ்வார்மற் றெல்லாம்\nதொழுதுண்டு பின்செல் பவர்.", transliteration: "Uzhudhuntu Vaazhvaare Vaazhvaarmar Rellaam / Thozhudhuntu Pinsel Pavar", english: "They alone live who live by agriculture; all others lead a cringing, dependent life" },
  { number: 1034, tamil: "பலகுடை நீழலும் தங்குடைக்கீழ்க் காண்பர்\nஅலகுடை நீழ லவர்.", transliteration: "Palakutai Neezhalum Thangutaikkeezhk Kaanpar / Alakutai Neezha Lavar", english: "Patriotic farmers desire to bring all other states under the control of their own king" },
  { number: 1035, tamil: "இரவார் இரப்பார்க்கொன்று ஈவர் கரவாது\nகைசெய்தூண் மாலை யவர்.", transliteration: "Iravaar Irappaarkkondru Eevar Karavaadhu / Kaiseydhoon Maalai Yavar", english: "Those whose nature is to live by manual labour will never beg but give something to those who beg" },
  { number: 1036, tamil: "உழவினார் கைம்மடங்கின் இல்லை விழைவதூஉம்\nவிட்டேம்என் பார்க்கும் நிலை.", transliteration: "Uzhavinaar Kaimmatangin Illai Vizhaivadhooum / Vittemen Paarkkum Nilai", english: "If the farmer's hands are slackened, even the ascetic state will fail" },
  { number: 1037, tamil: "தொடிப்புழுதி கஃசா உணக்கின் பிடித்தெருவும்\nவேண்டாது சாலப் படும்.", transliteration: "Thotippuzhudhi Kaqsaa Unakkin Pitiththeruvum / Ventaadhu Saalap Patum", english: "If the land is dried so as to reduce one ounce of earth to a quarter, it will grow plentifully even without a handful of manure" },
  { number: 1038, tamil: "ஏரினும் நன்றால் எருவிடுதல் கட்டபின்\nநீரினும் நன்றதன் காப்பு.", transliteration: "Erinum Nandraal Eruvitudhal Kattapin / Neerinum Nandradhan Kaappu", english: "Manuring is better than ploughing; after weeding, watching is better than watering (it)" },
  { number: 1039, tamil: "செல்லான் கிழவன் இருப்பின் நிலம்புலந்து\nஇல்லாளின் ஊடி விடும்.", transliteration: "Sellaan Kizhavan Iruppin Nilampulandhu / Illaalin Ooti Vitum", english: "If the owner does not (personally) attend to his cultivation, his land will behave like an angry wife and yield him no pleasure" },
  { number: 1040, tamil: "இலமென்று அசைஇ இருப்பாரைக் காணின்\nநிலமென்னும் நல்லாள் நகும்.", transliteration: "Ilamendru Asaii Iruppaaraik Kaanin / Nilamennum Nallaal Nakum", english: "The maiden, Earth, will laugh at the sight of those who plead poverty and lead an idle life" },
  { number: 1041, tamil: "இன்மையின் இன்னாதது யாதெனின் இன்மையின்\nஇன்மையே இன்னா தது.", transliteration: "Inmaiyin Innaadhadhu Yaadhenin Inmaiyin / Inmaiye Innaa Thadhu", english: "There is nothing that afflicts (one) like poverty" },
  { number: 1042, tamil: "இன்மை எனவொரு பாவி மறுமையும்\nஇம்மையும் இன்றி வரும்.", transliteration: "Inmai Enavoru Paavi Marumaiyum / Immaiyum Indri Varum", english: "When cruel poverty comes on, it deprives one of both the present and future (bliss)" },
  { number: 1043, tamil: "தொல்வரவும் தோலும் கெடுக்கும் தொகையாக\nநல்குரவு என்னும் நசை.", transliteration: "Tholvaravum Tholum Ketukkum Thokaiyaaka / Nalkuravu Ennum Nasai", english: "Hankering poverty destroys at once the greatness of (one's) ancient descent and (the dignity of one's) speech" },
  { number: 1044, tamil: "இற்பிறந்தார் கண்ணேயும் இன்மை இளிவந்த\nசொற்பிறக்கும் சோர்வு தரும்.", transliteration: "Irpirandhaar Kanneyum Inmai Ilivandha / Sorpirakkum Sorvu Tharum", english: "Even in those of high birth, poverty will produce the fault of uttering mean words" },
  { number: 1045, tamil: "நல்குரவு என்னும் இடும்பையுள் பல்குரைத்\nதுன்பங்கள் சென்று படும்.", transliteration: "Nalkuravu Ennum Itumpaiyul Palkuraith / Thunpangal Sendru Patum", english: "The misery of poverty brings in its train many (more) miseries" },
  { number: 1046, tamil: "நற்பொருள் நன்குணர்ந்து சொல்லினும் நல்கூர்ந்தார்\nசொற்பொருள் சோர்வு படும்.", transliteration: "Narporul Nankunarndhu Sollinum Nalkoorndhaar / Sorporul Sorvu Patum", english: "The words of the poor are profitless, though they may be sound in thought and clear in expression" },
  { number: 1047, tamil: "அறஞ்சாரா நல்குரவு ஈன்றதா யானும்\nபிறன்போல நோக்கப் படும்.", transliteration: "Aranjaaraa Nalkuravu Eendradhaa Yaanum / Piranpola Nokkap Patum", english: "He that is reduced to absolute poverty will be regarded as a stranger even by his own mother" },
  { number: 1048, tamil: "இன்றும் வருவது கொல்லோ நெருநலும்\nகொன்றது போலும் நிரப்பு.", transliteration: "Indrum Varuvadhu Kollo Nerunalum / Kondradhu Polum Nirappu", english: "Is the poverty that almost killed me yesterday, to meet me today too ?" },
  { number: 1049, tamil: "நெருப்பினுள் துஞ்சலும் ஆகும் நிரப்பினுள்\nயாதொன்றும் கண்பாடு அரிது.", transliteration: "Neruppinul Thunjalum Aakum Nirappinul / Yaadhondrum Kanpaatu Aridhu", english: "One may sleep in the midst of fire; but by no means in the midst of poverty" },
  { number: 1050, tamil: "துப்புர வில்லார் துவரத் துறவாமை\nஉப்பிற்கும் காடிக்கும் கூற்று.", transliteration: "Thuppura Villaar Thuvarath Thuravaamai / Uppirkum Kaatikkum Kootru", english: "The destitute poor, who do not renounce their bodies, only consume their neighbour's salt and water" },
  { number: 1051, tamil: "இரக்க இரத்தக்கார்க் காணின் கரப்பின்\nஅவர்பழி தம்பழி அன்று.", transliteration: "Irakka Iraththakkaark Kaanin Karappin / Avarpazhi Thampazhi Andru", english: "If you meet with those that may be begged of, you may beg; (but) if they withhold (their gift) it is their blame and not yours" },
  { number: 1052, tamil: "இன்பம் ஒருவற்கு இரத்தல் இரந்தவை\nதுன்பம் உறாஅ வரின்.", transliteration: "Inpam Oruvarku Iraththal Irandhavai / Thunpam Uraaa Varin", english: "Even begging may be pleasant, if what is begged for is obtained without grief (to him that begs)" },
  { number: 1053, tamil: "கரப்பிலா நெஞ்சின் கடனறிவார் முன்நின்று\nஇரப்புமோ ரேஎர் உடைத்து.", transliteration: "Karappilaa Nenjin Katanarivaar Munnindru / Irappumo Reer Utaiththu", english: "There is even a beauty in standing before and begging of those who are liberal in their gifts and understand their duty (to beggars)" },
  { number: 1054, tamil: "இரத்தலும் ஈதலே போலும் கரத்தல்\nகனவிலும் தேற்றாதார் மாட்டு.", transliteration: "Iraththalum Eedhale Polum Karaththal / Kanavilum Thetraadhaar Maattu", english: "To beg of such as never think of withholding (their charity) even in their dreams, is in fact the same as giving (it oneself);" },
  { number: 1055, tamil: "கரப்பிலார் வையகத்து உண்மையால் கண்ணின்று\nஇரப்பவர் மேற்கொள் வது.", transliteration: "Karappilaar Vaiyakaththu Unmaiyaal Kannindru / Irappavar Merkol Vadhu", english: "As there are in the world those that give without refusing, there are (also) those that prefer to beg by simply standing before them" },
  { number: 1056, tamil: "கரப்பிடும்பை யில்லாரைக் காணின் நிரப்பிடும்பை\nஎல்லாம் ஒருங்கு கெடும்.", transliteration: "Karappitumpai Yillaaraik Kaanin Nirappitumpai / Ellaam Orungu Ketum", english: "All the evil of begging will be removed at the sight of those who are far from the evil of refusing" },
  { number: 1057, tamil: "இகழ்ந்தெள்ளாது ஈவாரைக் காணின் மகிழ்ந்துள்ளம்\nஉள்ளுள் உவப்பது உடைத்து.", transliteration: "Ikazhndhellaadhu Eevaaraik Kaanin Makizhndhullam / Ullul Uvappadhu Utaiththu", english: "Beggars rejoice exceedingly when they behold those who bestow (their alms) with kindness and courtesy" },
  { number: 1058, tamil: "இரப்பாரை இல்லாயின் ஈர்ங்கண்மா ஞாலம்\nமரப்பாவை சென்றுவந் தற்று.", transliteration: "Irappaarai Illaayin Eernganmaa Gnaalam / Marappaavai Sendruvan Thatru", english: "If there were no beggars, (the actions done in) the cool wide world would only resemble the movement of a puppet" },
  { number: 1059, tamil: "ஈவார்கண் என்னுண்டாம் தோற்றம் இரந்துகோள்\nமேவார் இலாஅக் கடை.", transliteration: "Eevaarkan Ennuntaam Thotram Irandhukol / Mevaar Ilaaak Katai", english: "What (praise) would there be to givers (of alms) if there were no beggars to ask for and reveive (them)" },
  { number: 1060, tamil: "இரப்பான் வெகுளாமை வேண்டும் நிரப்பிடும்பை\nதானேயும் சாலும் கரி.", transliteration: "Irappaan Vekulaamai Ventum Nirappitumpai / Thaaneyum Saalum Kari", english: "He who begs ought not to be angry (at a refusal); for even the misery of (his own) poverty should be a sufficient reason (for so doing)" },
  { number: 1061, tamil: "கரவாது உவந்தீயும் கண்ணன்னார் கண்ணும்\nஇரவாமை கோடி உறும்.", transliteration: "Karavaadhu Uvandheeyum Kannannaar Kannum / Iravaamai Koti Urum", english: "Not to beg (at all) even from those excellent persons who cheerfully give without refusing, will do immense good" },
  { number: 1062, tamil: "இரந்தும் உயிர்வாழ்தல் வேண்டின் பரந்து\nகெடுக உலகியற்றி யான்.", transliteration: "Irandhum Uyirvaazhdhal Ventin Parandhu / Ketuka Ulakiyatri Yaan", english: "If the Creator of the world has decreed even begging as a means of livelihood, may he too go abegging and perish" },
  { number: 1063, tamil: "இன்மை இடும்பை இரந்துதீர் வாமென்னும்\nவன்மையின் வன்பாட்ட தில்.", transliteration: "Inmai Itumpai Irandhudheer Vaamennum / Vanmaiyin Vanpaatta Thil", english: "There is no greater folly than the boldness with which one seeks to remedy the evils of poverty by begging (rather than by working)" },
  { number: 1064, tamil: "இடமெல்லாம் கொள்ளாத் தகைத்தே இடமில்லாக்\nகாலும் இரவொல்லாச் சால்பு.", transliteration: "Itamellaam Kollaath Thakaiththe Itamillaak / Kaalum Iravollaach Chaalpu", english: "Even the whole world cannot sufficiently praise the dignity that would not beg even in the midst of destitution" },
  { number: 1065, tamil: "தெண்ணீர் அடுபுற்கை ஆயினும் தாள்தந்தது\nஉண்ணலின் ஊங்கினிய தில்.", transliteration: "Thenneer Atupurkai Aayinum Thaaldhandhadhu / Unnalin Oonginiya Thil", english: "Even thin gruel is ambrosia to him who has obtained it by labour" },
  { number: 1066, tamil: "ஆவிற்கு நீரென்று இரப்பினும் நாவிற்கு\nஇரவின் இளிவந்த தில்.", transliteration: "Aavirku Neerendru Irappinum Naavirku / Iravin Ilivandha Thil", english: "There is nothing more disgraceful to one's tongue than to use it in begging water even for a cow" },
  { number: 1067, tamil: "இரப்பன் இரப்பாரை எல்லாம் இரப்பின்\nகரப்பார் இரவன்மின் என்று.", transliteration: "Irappan Irappaarai Ellaam Irappin / Karappaar Iravanmin Endru", english: "I beseech all beggars and say, \"If you need to beg, never beg of those who give unwillingly.\"" },
  { number: 1068, tamil: "இரவென்னும் ஏமாப்பில் தோணி கரவென்னும்\nபார்தாக்கப் பக்கு விடும்.", transliteration: "Iravennum Emaappil Thoni Karavennum / Paardhaakkap Pakku Vitum", english: "The unsafe raft of begging will split when it strikes on the rock of refusal" },
  { number: 1069, tamil: "இரவுள்ள உள்ளம் உருகும் கரவுள்ள\nஉள்ளதூஉம் இன்றிக் கெடும்.", transliteration: "Iravulla Ullam Urukum Karavulla / Ulladhooum Indrik Ketum", english: "To think of (the evil of) begging is enough to melt one's heart; but to think of refusal is enough to break it" },
  { number: 1070, tamil: "கரப்பவர்க்கு யாங்கொளிக்கும் கொல்லோ இரப்பவர்\nசொல்லாடப் போஒம் உயிர்.", transliteration: "Karappavarkku Yaangolikkum Kollo Irappavar / Sollaatap Poom Uyir", english: "Saying \"No\" to a beggar takes away his life. (but as that very word will kill the refuser) where then would the latter's life hide itself ?" },
  { number: 1071, tamil: "மக்களே போல்வர் கயவர் அவரன்ன\nஒப்பாரி யாங்கண்ட தில்.", transliteration: "Makkale Polvar Kayavar Avaranna / Oppaari Yaanganta Thil", english: "The base resemble men perfectly (as regards form); and we have not seen such (exact) resemblance (among any other species)" },
  { number: 1072, tamil: "நன்றறி வாரிற் கயவர் திருவுடையர்\nநெஞ்சத்து அவலம் இலர்.", transliteration: "Nandrari Vaarir Kayavar Thiruvutaiyar / Nenjaththu Avalam Ilar", english: "The low enjoy more felicity than those who know what is good; for the former are not troubled with anxiety (as to the good)" },
  { number: 1073, tamil: "தேவர் அனையர் கயவர் அவருந்தாம்\nமேவன செய்தொழுக லான்.", transliteration: "Thevar Anaiyar Kayavar Avarundhaam / Mevana Seydhozhuka Laan", english: "The base resemble the Gods; for the base act as they like" },
  { number: 1074, tamil: "அகப்பட்டி ஆவாரைக் காணின் அவரின்\nமிகப்பட்டுச் செம்மாக்கும் கீழ்.", transliteration: "Akappatti Aavaaraik Kaanin Avarin / Mikappattuch Chemmaakkum Keezh", english: "The base feels proud when he sees persons whose acts meaner than his own" },
  { number: 1075, tamil: "அச்சமே கீழ்களது ஆசாரம் எச்சம்\nஅவாவுண்டேல் உண்டாம் சிறிது.", transliteration: "Achchame Keezhkaladhu Aasaaram Echcham / Avaavuntel Untaam Siridhu", english: "(The principle of) behaviour in the mean is chiefly fear; if not, hope of gain, to some extent" },
  { number: 1076, tamil: "அறைபறை அன்னர் கயவர்தாம் கேட்ட\nமறைபிறர்க்கு உய்த்துரைக்க லான்.", transliteration: "Araiparai Annar Kayavardhaam Ketta / Maraipirarkku Uyththuraikka Laan", english: "The base are like a drum that is beaten, for they unburden to others the secrets they have heard" },
  { number: 1077, tamil: "ஈர்ங்கை விதிரார் கயவர் கொடிறுடைக்கும்\nகூன்கையர் அல்லா தவர்க்கு.", transliteration: "Eerngai Vidhiraar Kayavar Kotirutaikkum / Koonkaiyar Allaa Thavarkku", english: "The mean will not (even) shake off (what sticks to) their hands (soon after a meal) to any but those who would break their jaws with their clenched fists" },
  { number: 1078, tamil: "சொல்லப் பயன்படுவர் சான்றோர் கரும்புபோல்\nகொல்லப் பயன்படும் கீழ்.", transliteration: "Sollap Payanpatuvar Saandror Karumpupol / Kollap Payanpatum Keezh", english: "The great bestow (their alms) as soon as they are informed; (but) the mean, like the sugar-cane, only when they are tortured to death" },
  { number: 1079, tamil: "உடுப்பதூஉம் உண்பதூஉம் காணின் பிறர்மேல்\nவடுக்காண வற்றாகும் கீழ்.", transliteration: "Utuppadhooum Unpadhooum Kaanin Pirarmel / Vatukkaana Vatraakum Keezh", english: "The base will bring an evil (accusation) against others, as soon as he sees them (enjoying) good food" },
  { number: 1080, tamil: "எற்றிற் குரியர் கயவரொன்று உற்றக்கால்\nவிற்றற்கு உரியர் விரைந்து.", transliteration: "Etrir Kuriyar Kayavarondru Utrakkaal / Vitrarku Uriyar Viraindhu", english: "The base will hasten to sell themselves as soon as a calamity has befallen them. For what else are they fitted ?" },
  { number: 1081, tamil: "அணங்குகொல் ஆய்மயில் கொல்லோ கனங்குழை\nமாதர்கொல் மாலும் என் நெஞ்சு.", transliteration: "Anangukol Aaimayil Kollo Kananguzhai / Maadharkol Maalum En Nenju", english: "Is this jewelled female a celestial, a choice peahen, or a human being ? My mind is perplexed" },
  { number: 1082, tamil: "நோக்கினாள் நோக்கெதிர் நோக்குதல் தாக்கணங்கு\nதானைக்கொண் டன்ன துடைத்து.", transliteration: "Nokkinaal Nokkedhir Nokkudhal Thaakkanangu / Thaanaikkon Tanna Thutaiththu", english: "This female beauty returning my looks is like a celestial maiden coming with an army to contend against me" },
  { number: 1083, tamil: "பண்டறியேன் கூற்றென் பதனை இனியறிந்தேன்\nபெண்டகையால் பேரமர்க் கட்டு.", transliteration: "Pantariyen Kootren Padhanai Iniyarindhen / Pentakaiyaal Peramark Kattu", english: "I never knew before what is called Yama; I see it now; it is the eyes that carry on a great fight with (the help of) female qualities" },
  { number: 1084, tamil: "கண்டார் உயிருண்ணும் தோற்றத்தால் பெண்டகைப்\nபேதைக்கு அமர்த்தன கண்.", transliteration: "Kantaar Uyirunnum Thotraththaal Pentakaip / Pedhaikku Amarththana Kan", english: "These eyes that seem to kill those who look at them are as it were in hostilities with this feminine simplicity" },
  { number: 1085, tamil: "கூற்றமோ கண்ணோ பிணையோ மடவரல்\nநோக்கமிம் மூன்றும் உடைத்து.", transliteration: "Kootramo Kanno Pinaiyo Matavaral / Nokkamim Moondrum Utaiththu", english: "Is it Yama, (a pair of) eyes or a hind ?- Are not all these three in the looks of this maid ?" },
  { number: 1086, tamil: "கொடும்புருவம் கோடா மறைப்பின் நடுங்கஞர்\nசெய்யல மன்இவள் கண்.", transliteration: "Kotumpuruvam Kotaa Maraippin Natungagnar / Seyyala Manival Kan", english: "Her eyes will cause (me) no trembling sorrow, if they are properly hidden by her cruel arched eyebrows" },
  { number: 1087, tamil: "கடாஅக் களிற்றின்மேற் கட்படாம் மாதர்\nபடாஅ முலைமேல் துகில்.", transliteration: "Kataaak Kalitrinmer Katpataam Maadhar / Pataaa Mulaimel Thukil", english: "The cloth that covers the firm bosom of this maiden is (like) that which covers the eyes of a rutting elephant" },
  { number: 1088, tamil: "ஒண்ணுதற் கோஒ உடைந்ததே ஞாட்பினுள்\nநண்ணாரும் உட்குமென் பீடு.", transliteration: "Onnudhar Koo Utaindhadhe Gnaatpinul / Nannaarum Utkumen Peetu", english: "On her bright brow alone is destroyed even that power of mine that used to terrify the most fearless" },
  { number: 1089, tamil: "பிணையேர் மடநோக்கும் நாணும் உடையாட்கு\nஅணியெவனோ ஏதில தந்து.", transliteration: "Pinaiyer Matanokkum Naanum Utaiyaatku / Aniyevano Edhila Thandhu", english: "Of what use are other jewels to her who is adorned with modesty, and the meek looks of a hind ?" },
  { number: 1090, tamil: "உண்டார்கண் அல்லது அடுநறாக் காமம்போல்\nகண்டார் மகிழ்செய்தல் இன்று.", transliteration: "Untaarkan Alladhu Atunaraak Kaamampol / Kantaar Makizhseydhal Indru", english: "Unlike boiled honey which yields delight only when it is drunk, love gives pleasure even when looked at" },
  { number: 1091, tamil: "இருநோக்கு இவளுண்கண் உள்ளது ஒருநோக்கு\nநோய்நோக்கொன் றந்நோய் மருந்து.", transliteration: "Irunokku Ivalunkan Ulladhu Orunokku / Noinokkon Rannoi Marundhu", english: "There are two looks in the dyed eyes of this (fair one); one causes pain, and the other is the cure thereof" },
  { number: 1092, tamil: "கண்களவு கொள்ளும் சிறுநோக்கம் காமத்தில்\nசெம்பாகம் அன்று பெரிது.", transliteration: "Kankalavu Kollum Sirunokkam Kaamaththil / Sempaakam Andru Peridhu", english: "A single stolen glance of her eyes is more than half the pleasure (of sexual embrace)" },
  { number: 1093, tamil: "நோக்கினாள் நோக்கி இறைஞ்சினாள் அஃதவள்\nயாப்பினுள் அட்டிய நீர்.", transliteration: "Nokkinaal Nokki Irainjinaal Aqdhaval / Yaappinul Attiya Neer", english: "She has looked (at men) and stooped (her head); and that (sign) waters as it were (the corn of) our love" },
  { number: 1094, tamil: "யான்நோக்கும் காலை நிலன்நோக்கும் நோக்காக்கால்\nதான்நோக்கி மெல்ல நகும்.", transliteration: "Yaannokkum Kaalai Nilannokkum Nokkaakkaal / Thaannokki Mella Nakum", english: "When I look, she looks down; when I do not, she looks and smiles gently" },
  { number: 1095, tamil: "குறிக்கொண்டு நோக்காமை அல்லால் ஒருகண்\nசிறக்கணித்தாள் போல நகும்", transliteration: "Kurikkontu Nokkaamai Allaal Orukan / Sirakkaniththaal Pola Nakum", english: "She not only avoids a direct look at me, but looks as it were with a half-closed eye and smiles" },
  { number: 1096, tamil: "உறாஅ தவர்போல் சொலினும் செறாஅர்சொல்\nஒல்லை உணரப் படும்.", transliteration: "Uraaa Thavarpol Solinum Seraaarsol / Ollai Unarap Patum", english: "Though they may speak harshly as if they were strangers, the words of the friendly are soon understood" },
  { number: 1097, tamil: "செறாஅச் சிறுசொல்லும் செற்றார்போல் நோக்கும்\nஉறாஅர்போன்று உற்றார் குறிப்பு.", transliteration: "Seraaach Chirusollum Setraarpol Nokkum / Uraaarpondru Utraar Kurippu", english: "Little words that are harsh and looks that are hateful are (but) the expressions of lovers who wish to act like strangers" },
  { number: 1098, tamil: "அசையியற்கு உண்டாண்டோர் ஏஎர்யான் நோக்கப்\nபசையினள் பைய நகும்.", transliteration: "Asaiyiyarku Untaantor Eeryaan Nokkap / Pasaiyinal Paiya Nakum", english: "When I look, the pitying maid looks in return and smiles gently; and that is a comforting sign for me" },
  { number: 1099, tamil: "ஏதிலார் போலப் பொதுநோக்கு நோக்குதல்\nகாதலார் கண்ணே உள.", transliteration: "Edhilaar Polap Podhunokku Nokkudhal / Kaadhalaar Kanne Ula", english: "Both the lovers are capable of looking at each other in an ordinary way, as if they were perfect strangers" },
  { number: 1100, tamil: "கண்ணொடு கண்இணை நோக்கொக்கின் வாய்ச்சொற்கள்\nஎன்ன பயனும் இல.", transliteration: "Kannotu Kaninai Nokkokkin Vaaichchorkal / Enna Payanum Ila", english: "The words of the mouths are of no use whatever, when there is perfect agreement between the eyes (of lovers)" },
  { number: 1101, tamil: "கண்டுகேட்டு உண்டுயிர்த்து உற்றறியும் ஐம்புலனும்\nஒண்தொடி கண்ணே உள.", transliteration: "Kantukettu Untuyirththu Utrariyum Aimpulanum / Ondhoti Kanne Ula", english: "The (simultaneous) enjoyment of the five senses of sight, hearing, taste, smell and touch can only be found with bright braceleted (women)" },
  { number: 1102, tamil: "பிணிக்கு மருந்து பிறமன் அணியிழை\nதன்நோய்க்குத் தானே மருந்து.", transliteration: "Pinikku Marundhu Piraman Aniyizhai / Thannoikkuth Thaane Marundhu", english: "The remedy for a disease is always something different (from it); but for the disease caused by this jewelled maid, she is herself the cure" },
  { number: 1103, tamil: "தாம்வீழ்வார் மென்றோள் துயிலின் இனிதுகொல்\nதாமரைக் கண்ணான் உலகு.", transliteration: "Thaamveezhvaar Mendrol Thuyilin Inidhukol / Thaamaraik Kannaan Ulaku", english: "Can the lotus-eyed Vishnu's heaven be indeed as sweet to those who delight to sleep in the delicate arms of their beloved ?" },
  { number: 1104, tamil: "நீங்கின் தெறூஉம் குறுகுங்கால் தண்ணென்னும்\nதீயாண்டுப் பெற்றாள் இவள்?", transliteration: "Neengin Theruum Kurukungaal Thannennum / Theeyaantup Petraal Ival?", english: "From whence has she got this fire that burns when I withdraw and cools when I approach ?" },
  { number: 1105, tamil: "வேட்ட பொழுதின் அவையவை போலுமே\nதோட்டார் கதுப்பினாள் தோள்.", transliteration: "Vetta Pozhudhin Avaiyavai Polume / Thottaar Kadhuppinaal Thol", english: "Each varied form of joy the soul can wish is found" },
  { number: 1106, tamil: "உறுதோறு உயிர்தளிர்ப்பத் தீண்டலால் பேதைக்கு\nஅமிழ்தின் இயன்றன தோள்.", transliteration: "Urudhoru Uyirdhalirppath Theentalaal Pedhaikku / Amizhdhin Iyandrana Thol", english: "The shoulders of this fair one are made of ambrosia, for they revive me with pleasure every time I embrace them" },
  { number: 1107, tamil: "தம்மில் இருந்து தமதுபாத்து உண்டற்றால்\nஅம்மா அரிவை முயக்கு.", transliteration: "Thammil Irundhu Thamadhupaaththu Untatraal / Ammaa Arivai Muyakku", english: "The embraces of a gold-complexioned beautiful female are as pleasant as to dwell in one's own house and live by one's own (earnings) after distributing (a portion of it in charity)" },
  { number: 1108, tamil: "வீழும் இருவர்க்கு இனிதே வளியிடை\nபோழப் படாஅ முயக்கு.", transliteration: "Veezhum Iruvarkku Inidhe Valiyitai / Pozhap Pataaa Muyakku", english: "To ardent lovers sweet is the embrace that cannot be penetrated even by a breath of breeze" },
  { number: 1109, tamil: "ஊடல் உணர்தல் புணர்தல் இவைகாமம்\nகூடியார் பெற்ற பயன்.", transliteration: "Ootal Unardhal Punardhal Ivaikaamam / Kootiyaar Petra Payan", english: "Love quarrel, reconciliation and intercourse - these are the advantages reaped by those who marry for lust" },
  { number: 1110, tamil: "அறிதோறு அறியாமை கண்டற்றால் காமம்\nசெறிதோறும் சேயிழை மாட்டு.", transliteration: "Aridhoru Ariyaamai Kantatraal Kaamam / Seridhorum Seyizhai Maattu", english: "As (one's) ignorance is discovered the more one learns, so does repeated intercourse with a welladorned female (only create a desire for more)" },
  { number: 1111, tamil: "நன்னீரை வாழி அனிச்சமே நின்னினும்\nமென்னீரள் யாம்வீழ் பவள்.", transliteration: "Nanneerai Vaazhi Anichchame Ninninum / Menneeral Yaamveezh Paval", english: "May you flourish, O Anicham! you have a delicate nature But my beloved is more delicate than you" },
  { number: 1112, tamil: "மலர்காணின் மையாத்தி நெஞ்சே இவள்கண்\nபலர்காணும் பூவொக்கும் என்று.", transliteration: "Malarkaanin Maiyaaththi Nenje Ivalkan / Palarkaanum Poovokkum Endru", english: "O my soul, fancying that flowers which are seen by many can resemble her eyes, you become confused at the sight of them" },
  { number: 1113, tamil: "முறிமேனி முத்தம் முறுவல் வெறிநாற்றம்\nவேலுண்கண் வேய்த்தோ ளவட்கு.", transliteration: "Murimeni Muththam Muruval Verinaatram / Velunkan Veyththo Lavatku", english: "The complexion of this bamboo-shouldered one is that of a shoot; her teeth, are pearls; her breath," },
  { number: 1114, tamil: "காணின் குவளை கவிழ்ந்து நிலன்நோக்கும்\nமாணிழை கண்ணொவ்வேம் என்று.", transliteration: "Kaanin Kuvalai Kavizhndhu Nilannokkum / Maanizhai Kannovvem Endru", english: "If the blue lotus could see, it would stoop and look at the ground saying, \"I can never resemble the eyes of this excellent jewelled one.\"" },
  { number: 1115, tamil: "அனிச்சப்பூக் கால்களையாள் பெய்தாள் நுகப்பிற்கு\nநல்ல படாஅ பறை.", transliteration: "Anichchappook Kaalkalaiyaal Peydhaal Nukappirku / Nalla Pataaa Parai", english: "No merry drums will be beaten for the (tender) waist of her who has adorned herself with the anicham without having removed its stem" },
  { number: 1116, tamil: "மதியும் மடந்தை முகனும் அறியா\nபதியின் கலங்கிய மீன்.", transliteration: "Madhiyum Matandhai Mukanum Ariyaa / Padhiyin Kalangiya Meen", english: "The stars have become confused in their places not being able to distinguish between the moon and the maid's countenance" },
  { number: 1117, tamil: "அறுவாய் நிறைந்த அவிர்மதிக்குப் க்குப் போல\nமறுவுண்டோ மாதர் முகத்து.", transliteration: "Aruvaai Niraindha Avirmadhikkup Pola / Maruvunto Maadhar Mukaththu", english: "Could there be spots in the face of this maid like those in the bright full moon ?" },
  { number: 1118, tamil: "மாதர் முகம்போல் ஒளிவிட வல்லையேல்\nகாதலை வாழி மத஧.", transliteration: "Maadhar Mukampol Olivita Vallaiyel / Kaadhalai Vaazhi Madhi", english: "If you can indeed shine like the face of women, flourish, O moon, for then would you be worth loving ?" },
  { number: 1119, tamil: "மலரன்ன கண்ணாள் முகமொத்தி யாயின்\nபலர்காணத் தோன்றல் மதி.", transliteration: "Malaranna Kannaal Mukamoththi Yaayin / Palarkaanath Thondral Madhi", english: "O moon, if you wish to resemble the face of her whose eyes are like (these) flowers, do not appear so as to be seen by all" },
  { number: 1120, tamil: "அனிச்சமும் அன்னத்தின் தூவியும் மாதர்\nஅடிக்கு நெருஞ்சிப் பழம்.", transliteration: "Anichchamum Annaththin Thooviyum Maadhar / Atikku Nerunjip Pazham", english: "The anicham and the feathers of the swan are to the feet of females, like the fruit of the (thorny) Nerunji" },
  { number: 1121, tamil: "பாலொடு தேன்கலந் தற்றே பணிமொழி\nவாலெயிறு ஊறிய நீர்.", transliteration: "Paalotu Thenkalan Thatre Panimozhi / Vaaleyiru Ooriya Neer", english: "The water which oozes from the white teeth of this soft speeched damsel is like a mixture of milk and honey" },
  { number: 1122, tamil: "உடம்பொடு உயிரிடை என்னமற் றன்ன\nமடந்தையொடு எம்மிடை நட்பு.", transliteration: "Utampotu Uyiritai Ennamar Ranna / Matandhaiyotu Emmitai Natpu", english: "The love between me and this damsel is like the union of body and soul" },
  { number: 1123, tamil: "கருமணியிற் பாவாய்நீ போதாயாம் வீழும்\nதிருநுதற்கு இல்லை இடம்.", transliteration: "Karumaniyir Paavaainee Podhaayaam Veezhum / Thirunudharku Illai Itam", english: "O you image in the pupil (of my eye)! depart; there is no room for (my) fair-browed beloved" },
  { number: 1124, tamil: "வாழ்தல் உயிர்க்கன்னள் ஆயிழை சாதல்\nஅதற்கன்னள் நீங்கும் இடத்து.", transliteration: "Vaazhdhal Uyirkkannal Aayizhai Saadhal / Adharkannal Neengum Itaththu", english: "My fair-jewelled one resembles the living soul (when she is in union with me), the dying soul when she leaves me" },
  { number: 1125, tamil: "உள்ளுவன் மன்யான் மறப்பின் மறப்பறியேன்\nஒள்ளமர்க் கண்ணாள் குணம்.", transliteration: "Ulluvan Manyaan Marappin Marappariyen / Ollamark Kannaal Kunam", english: "If I had forgotten her who has bright battling eyes, I would have remembered (thee); but I never forget her (Thus says he to her maid)" },
  { number: 1126, tamil: "கண்ணுள்ளின் போகார் இமைப்பின் பருகுவரா\nநுண்ணியர்எம் காத லவர்.", transliteration: "Kannullin Pokaar Imaippin Parukuvaraa / Nunniyarem Kaadha Lavar", english: "My lover would not depart from mine eyes; even if I wink, he would not suffer (from pain); he is so ethereal" },
  { number: 1127, tamil: "கண்ணுள்ளார் காத லவராகக் கண்ணும்\nஎழுதேம் கரப்பாக்கு அறிந்து.", transliteration: "Kannullaar Kaadha Lavaraakak Kannum / Ezhudhem Karappaakku Arindhu", english: "As my lover abides in my eyes, I will not even paint them, for he would (then) have to conceal himself" },
  { number: 1128, tamil: "நெஞ்சத்தார் காத லவராக வெய்துண்டல்\nஅஞ்சுதும் வேபாக் கறிந்து.", transliteration: "Nenjaththaar Kaadha Lavaraaka Veydhuntal / Anjudhum Vepaak Karindhu", english: "As my lover is in my heart, I am afraid of eating (anything) hot, for I know it would pain him" },
  { number: 1129, tamil: "இமைப்பின் கரப்பாக்கு அறிவல் அனைத்திற்கே\nஏதிலர் என்னும் இவ் வூர்.", transliteration: "Imaippin Karappaakku Arival Anaiththirke / Edhilar Ennum Iv Voor", english: "I will not wink, knowing that if I did, my lover would hide himself; and for this reason, this town says, he is unloving" },
  { number: 1130, tamil: "உவந்துறைவர் உள்ளத்துள் என்றும் இகந்துறைவர்\nஏதிலர் என்னும் இவ் வூர்.", transliteration: "Uvandhuraivar Ullaththul Endrum Ikandhuraivar / Edhilar Ennum Iv Voor", english: "My lover dwells in my heart with perpetual delight; but the town says he is unloving and (therefore) dwells afar" },
  { number: 1131, tamil: "காமம் உழந்து வருந்தினார்க்கு ஏமம்\nமடலல்லது இல்லை வலி.", transliteration: "Kaamam Uzhandhu Varundhinaarkku Emam / Matalalladhu Illai Vali", english: "To those who after enjoyment of sexual pleasure suffer (for want of more), there is no help so efficient as the palmyra horse" },
  { number: 1132, tamil: "நோனா உடம்பும் உயிரும் மடலேறும்\nநாணினை நீக்கி நிறுத்து.", transliteration: "Nonaa Utampum Uyirum Matalerum / Naaninai Neekki Niruththu", english: "Having got rid of shame, the suffering body and soul save themselves on the palmyra horse" },
  { number: 1133, tamil: "நாணொடு நல்லாண்மை பண்டுடையேன் இன்றுடையேன்\nகாமுற்றார் ஏறும் மடல்.", transliteration: "Naanotu Nallaanmai Pantutaiyen Indrutaiyen / Kaamutraar Erum Matal", english: "Modesty and manliness were once my own; now, my own is the palmyra horse that is ridden by the lustful" },
  { number: 1134, tamil: "காமக் கடும்புனல் உய்க்கும் நாணொடு\nநல்லாண்மை என்னும் புணை.", transliteration: "Kaamak Katumpunal Uykkum Naanotu / Nallaanmai Ennum Punai", english: "The raft of modesty and manliness, is, alas, carried-off by the strong current of lust" },
  { number: 1135, tamil: "தொடலைக் குறுந்தொடி தந்தாள் மடலொடு\nமாலை உழக்கும் துயர்.", transliteration: "Thotalaik Kurundhoti Thandhaal Matalotu / Maalai Uzhakkum Thuyar", english: "She with the small garland-like bracelets has given me the palmyra horse and the sorrow that is endured at night" },
  { number: 1136, tamil: "மடலூர்தல் யாமத்தும் உள்ளுவேன் மன்ற\nபடல்ஒல்லா பேதைக்கென் கண்.", transliteration: "Mataloordhal Yaamaththum Ulluven Mandra / Patalollaa Pedhaikken Kan", english: "Mine eyes will not close in sleep on your mistress's account; even at midnight will I think of mounting the palmyra horse" },
  { number: 1137, tamil: "கடலன்ன காமம் உழந்தும் மடலேறாப்\nபெண்ணின் பெருந்தக்க தில்.", transliteration: "Katalanna Kaamam Uzhandhum Mataleraap / Pennin Perundhakka Thil", english: "There is nothing so noble as the womanly nature that would not ride the palmyra horse, though plunged a sea of lust" },
  { number: 1138, tamil: "நிறையரியர் மன்அளியர் என்னாது காமம்\nமறையிறந்து மன்று படும்.", transliteration: "Niraiyariyar Manaliyar Ennaadhu Kaamam / Maraiyirandhu Mandru Patum", english: "Even the Lust (of women) transgresses its secrecy and appears in public, forgetting that they are too chaste and liberal (to be overcome by it)" },
  { number: 1139, tamil: "அறிகிலார் எல்லாரும் என்றேஎன் காமம்\nமறுகின் மறுகும் மருண்டு.", transliteration: "Arikilaar Ellaarum Endreen Kaamam / Marukin Marukum Maruntu", english: "And thus, in public ways, perturbed will rove" },
  { number: 1140, tamil: "யாம்கண்ணின் காண நகுப அறிவில்லார்\nயாம்பட்ட தாம்படா ஆறு.", transliteration: "Yaamkannin Kaana Nakupa Arivillaar / Yaampatta Thaampataa Aaru", english: "Even strangers laugh (at us) so as to be seen by us, for they have not suffered" },
  { number: 1141, tamil: "அலரெழ ஆருயிர் நிற்கும் அதனைப்\nபலரறியார் பாக்கியத் தால்.", transliteration: "Alarezha Aaruyir Na�rkum Adhanaip / Palarariyaar Paakkiyath Thaal", english: "My precious life is saved by the raise of rumour, and this, to my good luck no others are aware of" },
  { number: 1142, tamil: "மலரன்ன கண்ணாள் அருமை அறியாது\nஅலரெமக்கு ஈந்ததிவ் வூர்.", transliteration: "Malaranna Kannaal Arumai Ariyaadhu / Alaremakku Eendhadhiv Voor", english: "Not knowing the value of her whose eyes are like flowers this town has got up a rumour about me" },
  { number: 1143, tamil: "உறாஅதோ ஊரறிந்த கெளவை அதனைப்\nபெறாஅது பெற்றன்ன நீர்த்து.", transliteration: "Uraaadho Oorarindha Kelavai Adhanaip / Peraaadhu Petranna Neerththu", english: "Will I not get a rumour that is known to the (whole) town ? For what I have not got is as if I had got it (already)" },
  { number: 1144, tamil: "கவ்வையால் கவ்விது காமம் அதுவின்றேல்\nதவ்வென்னும் தன்மை இழந்து.", transliteration: "Kavvaiyaal Kavvidhu Kaamam Adhuvindrel / Thavvennum Thanmai Izhandhu", english: "Rumour increases the violence of my passion; without it it would grow weak and waste away" },
  { number: 1145, tamil: "களித்தொறும் கள்ளுண்டல் வேட்டற்றால் காமம்\nவெளிப்படுந் தோறும் இனிது.", transliteration: "Kaliththorum Kalluntal Vettatraal Kaamam / Velippatun Thorum Inidhu", english: "As drinking liquor is delightful (to one) whenever one is in mirth, so is lust delightful to me whenever it is the subject of rumour" },
  { number: 1146, tamil: "கண்டது மன்னும் ஒருநாள் அலர்மன்னும்\nதிங்களைப் பாம்புகொண் டற்று.", transliteration: "Kantadhu Mannum Orunaal Alarmannum / Thingalaip Paampukon Tatru", english: "It was but a single day that I looked on (my lover); but the rumour thereof has spread like the seizure of the moon by the serpent" },
  { number: 1147, tamil: "ஊரவர் கெளவை எருவாக அன்னைசொல்\nநீராக நீளும்இந் நோய்.", transliteration: "Ooravar Kelavai Eruvaaka Annaisol / Neeraaka Neelumin Noi", english: "This malady (of lust) is manured by the talk of women and watered by the (harsh) words of my mother" },
  { number: 1148, tamil: "நெய்யால் எரிநுதுப்பேம் என்றற்றால் கெளவையால்\nகாமம் நுதுப்பேம் எனல்.", transliteration: "Neyyaal Erinudhuppem Endratraal Kelavaiyaal / Kaamam Nudhuppem Enal", english: "To say that one could extinguish passion by rumour is like extinguishing fire with ghee" },
  { number: 1149, tamil: "அலர்நாண ஒல்வதோ அஞ்சலோம்பு என்றார்\nபலர்நாண நீத்தக் கடை.", transliteration: "Alarnaana Olvadho Anjalompu Endraar / Palarnaana Neeththak Katai", english: "When the departure of him who said \"fear not\" has put me to shame before others, why need I be ashamed of scandal" },
  { number: 1150, tamil: "தாம்வேண்டின் நல்குவர் காதலர் யாம்வேண்டும்\nகெளவை எடுக்கும்இவ் வூர்.", transliteration: "Thaamventin Nalkuvar Kaadhalar Yaamventum / Kelavai Etukkumiv Voor", english: "The rumour I desire is raised by the town (itself); and my lover would if desired consent (to my following him)" },
  { number: 1151, tamil: "செல்லாமை உண்டேல் எனக்குரை மற்றுநின்\nவல்வரவு வாழ்வார்க் குரை.", transliteration: "Sellaamai Untel Enakkurai Matrunin / Valvaravu Vaazhvaark Kurai", english: "If it is not departure, tell me; but if it is your speedy return, tell it to those who would be alive then" },
  { number: 1152, tamil: "இன்கண் உடைத்தவர் பார்வல் பிரிவஞ்சும்\nபுன்கண் உடைத்தால் புணர்வு.", transliteration: "Inkan Utaiththavar Paarval Pirivanjum / Punkan Utaiththaal Punarvu", english: "His very look was once pleasing; but (now) even intercourse is painful through fear of separation" },
  { number: 1153, tamil: "அரிதரோ தேற்றம் அறிவுடையார் கண்ணும்\nபிரிவோ ரிடத்துண்மை யான்.", transliteration: "Aridharo Thetram Arivutaiyaar Kannum / Pirivo Ritaththunmai Yaan", english: "As even the lover who understands (everything) may at times depart, confidence is hardly possible" },
  { number: 1154, tamil: "அளித்தஞ்சல் என்றவர் நீப்பின் தெளித்தசொல்\nதேறியார்க்கு உண்டோ தவறு.", transliteration: "Aliththanjal Endravar Neeppin Theliththasol / Theriyaarkku Unto Thavaru", english: "If he who bestowed his love and said \"fear not\" should depart, will it be the fault of those who believed in (his) assuring words ?" },
  { number: 1155, tamil: "ஓம்பின் அமைந்தார் பிரிவோம்பல் மற்றவர்\nநீங்கின் அரிதால் புணர்வு.", transliteration: "Ompin Amaindhaar Pirivompal Matravar / Neengin Aridhaal Punarvu", english: "If you would save (my life), delay the departure of my destined (husband); for if he departs, intercourse will become impossible" },
  { number: 1156, tamil: "பிரிவுரைக்கும் வன்கண்ணர் ஆயின் அரிதவர்\nநல்குவர் என்னும் நசை.", transliteration: "Pirivuraikkum Vankannar Aayin Aridhavar / Nalkuvar Ennum Nasai", english: "Is hard, when he could stand, and of departure speak to me" },
  { number: 1157, tamil: "துறைவன் துறந்தமை தூற்றாகொல் முன்கை\nஇறைஇறவா நின்ற வளை.", transliteration: "Thuraivan Thurandhamai Thootraakol Munkai / Iraiiravaa Nindra Valai", english: "Do not the rings that begin to slide down my fingers forebode the separation of my lord ?" },
  { number: 1158, tamil: "இன்னாது இனன்இல்ஊர் வாழ்தல் அதனினும்\nஇன்னாது இனியார்ப் பிரிவு.", transliteration: "Innaadhu Inaniloor Vaazhdhal Adhaninum / Innaadhu Iniyaarp Pirivu", english: "Painful is it to live in a friendless town; but far more painful is it to part from one's lover" },
  { number: 1159, tamil: "தொடிற்சுடின் அல்லது காமநோய் போல\nவிடிற்சுடல் ஆற்றுமோ தீ.", transliteration: "Thotirsutin Alladhu Kaamanoi Pola / Vitirsutal Aatrumo Thee", english: "Fire burns when touched; but, like the sickness of love, can it also burn when removed ?" },
  { number: 1160, tamil: "அரிதாற்றி அல்லல்நோய் நீக்கிப் பிரிவாற்றிப்\nபின்இருந்து வாழ்வார் பலர்.", transliteration: "Aridhaatri Allalnoi Neekkip Pirivaatrip / Pinirundhu Vaazhvaar Palar", english: "As if there were many indeed that can consent to the impossible, kill their pain, endure separation and yet continue to live afterwards" },
  { number: 1161, tamil: "மறைப்பேன்மன் யானிஃதோ நோயை இறைப்பவர்க்கு\nஊற்றுநீர் போல மிகும்.", transliteration: "Maraippenman Yaaniqdho Noyai Iraippavarkku / Ootruneer Pola Mikum", english: "I would hide this pain from others; but it (only) swells like a spring to those who drain it" },
  { number: 1162, tamil: "கரத்தலும் ஆற்றேன்இந் நோயைநோய் செய்தார்க்கு\nஉரைத்தலும் நாணுத் தரும்.", transliteration: "Karaththalum Aatrenin Noyainoi Seydhaarkku / Uraiththalum Naanuth Tharum", english: "I cannot conceal this pain, nor can I relate it without shame to him who has caused it" },
  { number: 1163, tamil: "காமமும் நாணும் உயிர்காவாத் தூங்கும்என்\nநோனா உடம்பின் அகத்து.", transliteration: "Kaamamum Naanum Uyirkaavaath Thoongumen / Nonaa Utampin Akaththu", english: "(Both) lust and shame, with my soul for their shoulder pole balance themselves on a body that cannot bear them" },
  { number: 1164, tamil: "காமக் கடல்மன்னும் உண்டே அதுநீந்தும்\nஏமப் புணைமன்னும் இல்.", transliteration: "Kaamak Katalmannum Unte Adhuneendhum / Emap Punaimannum Il", english: "There is indeed a flood of lust; but there is no raft of safety to cross it with" },
  { number: 1165, tamil: "துப்பின் எவனாவர் மன்கொல் துயர்வரவு\nநட்பினுள் ஆற்று பவர்.", transliteration: "Thuppin Evanaavar Mankol Thuyarvaravu / Natpinul Aatru Pavar", english: "What will they prove when angry tempests lower?" },
  { number: 1166, tamil: "இன்பம் கடல்மற்றுக் காமம் அஃதடுங்கால்\nதுன்பம் அதனிற் பெரிது.", transliteration: "Inpam Katalmatruk Kaamam Aqdhatungaal / Thunpam Adhanir Peridhu", english: "The pleasure of lust is (as great as) the sea; but the pain of lust is far greater" },
  { number: 1167, tamil: "காமக் கடும்புனல் நீந்திக் கரைகாணேன்\nயாமத்தும் யானே உளேன்.", transliteration: "Kaamak Katumpunal Neendhik Karaikaanen / Yaamaththum Yaane Ulen", english: "I have swam across the terrible flood of lust, but have not seen its shore; even at midnight I am alone; still I live" },
  { number: 1168, tamil: "மன்னுயிர் எல்லாம் துயிற்றி அளித்திரா\nஎன்னல்லது இல்லை துணை.", transliteration: "Mannuyir Ellaam Thuyitri Aliththiraa / Ennalladhu Illai Thunai", english: "The night which graciously lulls to sleep all living creatures, has me alone for her companion" },
  { number: 1169, tamil: "கொடியார் கொடுமையின் தாம்கொடிய இந்நாள்\nநெடிய கழியும் இரா.", transliteration: "Kotiyaar Kotumaiyin Thaamkotiya Innaal / Netiya Kazhiyum Iraa", english: "The long nights of these days are far more cruel than the heartless one who is torturing me" },
  { number: 1170, tamil: "உள்ளம்போன்று உள்வழிச் செல்கிற்பின் வெள்ளநீர்\nநீந்தல மன்னோஎன் கண்.", transliteration: "Ullampondru Ulvazhich Chelkirpin Vellaneer / Neendhala Mannoen Kan", english: "Could mine eyes travel like my thoughts to the abode (of my absent lord), they would not swim in this flood of tears" },
  { number: 1171, tamil: "கண்தாம் கலுழ்வ தெவன்கொலோ தண்டாநோய்\nதாம்காட்ட யாம்கண் டது.", transliteration: "Kandhaam Kaluzhva Thevankolo Thantaanoi / Thaamkaatta Yaamkan Tadhu", english: "As this incurable malady has been caused by my eyes which showed (him) to me, why should they now weep for (him)" },
  { number: 1172, tamil: "தெரிந்துணரா நோக்கிய உண்கண் பரிந்துணராப்\nபைதல் உழப்பது எவன்?", transliteration: "Therindhunaraa Nokkiya Unkan Parindhunaraap / Paidhal Uzhappadhu Evan?", english: "The dyed eyes that (then) looked without foresight, why should they now endure sorrow, without feeling sharply (their own fault)" },
  { number: 1173, tamil: "கதுமெனத் தாநோக்கித் தாமே கலுழும்\nஇதுநகத் தக்க துடைத்து.", transliteration: "Kadhumenath Thaanokkith Thaame Kaluzhum / Ithunakath Thakka Thutaiththu", english: "They themselves looked eagerly (on him) and now they weep. Is not this to be laughed at ?" },
  { number: 1174, tamil: "பெயலாற்றா நீருலந்த உண்கண் உயலாற்றா\nஉய்வில்நோய் என்கண் நிறுத்து.", transliteration: "Peyalaatraa Neerulandha Unkan Uyalaatraa / Uyvilnoi Enkan Niruththu", english: "These painted eyes have caused me a lasting mortal disease; and now they can weep no more, the tears having dried up" },
  { number: 1175, tamil: "படலாற்றா பைதல் உழக்கும் கடலாற்றாக்\nகாமநோய் செய்தஎன் கண்.", transliteration: "Patalaatraa Paidhal Uzhakkum Katalaatraak / Kaamanoi Seydhaen Kan", english: "Mine eyes have caused me a lust that is greater than the sea and (they themselves) endure the torture of sleeplessness" },
  { number: 1176, tamil: "ஓஒ இனிதே எமக்கிந்நோய் செய்தகண்\nதாஅம் இதற்பட் டது.", transliteration: "Oo Inidhe Emakkinnoi Seydhakan / Thaaam Itharpat Tadhu", english: "The eyes that have given me this disease have themselves been seized with this (suffering) Oh! I am much delighted" },
  { number: 1177, tamil: "உழந்துழந் துள்நீர் அறுக விழைந்திழைந்து\nவேண்டி அவர்க்கண்ட கண்.", transliteration: "Uzhandhuzhan Thulneer Aruka Vizhaindhizhaindhu / Venti Avarkkanta Kan", english: "The eyes that became tender and gazed intently on him, may they suffer so much as to dry up the fountain of their tears" },
  { number: 1178, tamil: "பேணாது பெட்டார் உளர்மன்னோ மற்றவர்க்\nகாணாது அமைவில கண்.", transliteration: "Penaadhu Pettaar Ularmanno Matravark / Kaanaadhu Amaivila Kan", english: "He is indeed here who loved me with his lips but not with his heart but mine eyes suffer from not seeing him" },
  { number: 1179, tamil: "வாராக்கால் துஞ்சா வரின்துஞ்சா ஆயிடை\nஆரஞர் உற்றன கண்.", transliteration: "Vaaraakkaal Thunjaa Varindhunjaa Aayitai / Aaragnar Utrana Kan", english: "When he is away they do not sleep; when he is present they do not sleep; in either case, mine eyes endure unbearable agony" },
  { number: 1180, tamil: "மறைபெறல் ஊரார்க்கு அரிதன்றால் எம்போல்\nஅறைபறை கண்ணார் அகத்து.", transliteration: "Maraiperal Ooraarkku Aridhandraal Empol / Araiparai Kannaar Akaththu", english: "It is not difficult for the people of this place to understand the secret of those whose eyes, like mine, are as it were beaten drums" },
  { number: 1181, tamil: "நயந்தவர்க்கு நல்காமை நேர்ந்தேன் பசந்தவென்\nபண்பியார்க்கு உரைக்கோ பிற.", transliteration: "Nayandhavarkku Nalkaamai Nerndhen Pasandhaven / Panpiyaarkku Uraikko Pira", english: "I who (then) consented to the absence of my loving lord, to whom can I (now) relate the fact of my having turned sallow" },
  { number: 1182, tamil: "அவர்தந்தார் என்னும் தகையால் இவர்தந்தென்\nமேனிமேல் ஊரும் பசப்பு.", transliteration: "Avardhandhaar Ennum Thakaiyaal Ivardhandhen / Menimel Oorum Pasappu", english: "Sallowness, as if proud of having been caused by him, would now ride on my person" },
  { number: 1183, tamil: "சாயலும் நாணும் அவர்கொண்டார் கைம்மாறா\nநோயும் பசலையும் தந்து.", transliteration: "Saayalum Naanum Avarkontaar Kaimmaaraa / Noyum Pasalaiyum Thandhu", english: "He has taken (away) my beauty and modesty, and given me instead disease and sallowness" },
  { number: 1184, tamil: "உள்ளுவன் மன்யான் உரைப்பது அவர்திறமால்\nகள்ளம் பிறவோ பசப்பு.", transliteration: "Ulluvan Manyaan Uraippadhu Avardhiramaal / Kallam Piravo Pasappu", english: "I think (of him); and what I speak about is but his excellence; still is there sallowness; and this is deceitful" },
  { number: 1185, tamil: "உவக்காண்எம் காதலர் செல்வார் இவக்காண்என்\nமேனி பசப்பூர் வது.", transliteration: "Uvakkaanem Kaadhalar Selvaar Ivakkaanen / Meni Pasappoor Vadhu", english: "Just as my lover departed then, did not sallowness spread here on my person ?" },
  { number: 1186, tamil: "விளக்கற்றம் பார்க்கும் இருளேபோல் கொண்கன்\nமுயக்கற்றம் பார்க்கும் பசப்பு.", transliteration: "Vilakkatram Paarkkum Irulepol Konkan / Muyakkatram Paarkkum Pasappu", english: "Just as darkness waits for the failing light; so does sallowness wait for the laxity of my husband's intercourse" },
  { number: 1187, tamil: "புல்லிக் கிடந்தேன் புடைபெயர்ந்தேன் அவ்வளவில்\nஅள்ளிக்கொள் வற்றே பசப்பு.", transliteration: "Pullik Kitandhen Putaipeyarndhen Avvalavil / Allikkol Vatre Pasappu", english: "I who was in close embrace just turned aside and the moment I did so, sallowness came on me like something to be seized on" },
  { number: 1188, tamil: "பசந்தாள் இவள்என்பது அல்லால் இவளைத்\nதுறந்தார் அவர்என்பார் இல்.", transliteration: "Pasandhaal Ivalenpadhu Allaal Ivalaith / Thurandhaar Avarenpaar Il", english: "Besides those who say \"she has turned sallow\" there are none who say \"he has forsaken her\"" },
  { number: 1189, tamil: "பசக்கமன் பட்டாங்கென் மேனி நயப்பித்தார்\nநன்னிலையர் ஆவர் எனின்.", transliteration: "Pasakkaman Pattaangen Meni Nayappiththaar / Nannilaiyar Aavar Enin", english: "If he is clear of guilt who has conciliated me (to his departure) let my body suffer its due and turn sallow" },
  { number: 1190, tamil: "பசப்பெனப் பேர்பெறுதல் நன்றே நயப்பித்தார்\nநல்காமை தூற்றார் எனின்.", transliteration: "Pasappenap Perperudhal Nandre Nayappiththaar / Nalkaamai Thootraar Enin", english: "It would be good to be said of me that I have turned sallow, if friends do not reproach with unkindness him who pleased me (then)" },
  { number: 1191, tamil: "தாம்வீழ்வார் தம்வீழப் பெற்றவர் பெற்றாரே\nகாமத்துக் காழில் கனி.", transliteration: "Thaamveezhvaar Thamveezhap Petravar Petraare / Kaamaththuk Kaazhil Kani", english: "The women who are beloved by those whom they love, have they have not got the stone-less fruit of sexual delight ?" },
  { number: 1192, tamil: "வாழ்வார்க்கு வானம் பயந்தற்றால் வீழ்வார்க்கு\nவீழ்வார் அள஧ க்கும் அளி.", transliteration: "Vaazhvaarkku Vaanam Payandhatraal Veezhvaarkku / Veezhvaar Ala� Kkum Ali", english: "The bestowal of love by the beloved on those who love them is like the rain raining (at the proper season) on those who live by it" },
  { number: 1193, tamil: "வீழுநர் வீழப் படுவார்க்கு அமையுமே\nவாழுநம் என்னும் செருக்கு.", transliteration: "Veezhunar Veezhap Patuvaarkku Amaiyume / Vaazhunam Ennum Serukku", english: "The pride that says \"we shall live\" suits only those who are loved by their beloved (husbands)" },
  { number: 1194, tamil: "வீழப் படுவார் கெழீஇயிலர் தாம்வீழ்வார்\nவீழப் படாஅர் எனின்.", transliteration: "Veezhap Patuvaar Kezheeiyilar Thaamveezhvaar / Veezhap Pataaar Enin", english: "Even those who are esteemed (by other women) are devoid of excellence, if they are not loved by their beloved" },
  { number: 1195, tamil: "நாம்காதல் கொண்டார் நமக்கெவன் செய்பவோ\nதாம்காதல் கொள்ளாக் கடை.", transliteration: "Naamkaadhal Kontaar Namakkevan Seypavo / Thaamkaadhal Kollaak Katai", english: "He who is beloved by me, what will he do to me, if I am not beloved by him ?" },
  { number: 1196, tamil: "ஒருதலையான் இன்னாது காமம்காப் போல\nஇருதலை யானும் இனிது.", transliteration: "Orudhalaiyaan Innaadhu Kaamamkaap Pola / Irudhalai Yaanum Inidhu", english: "Lust, like the weight of the KAVADI, pains if it lies in one end only but pleases if it is in both" },
  { number: 1197, tamil: "பருவரலும் பைதலும் காணான்கொல் காமன்\nஒருவர்கண் நின்றொழுகு வான்.", transliteration: "Paruvaralum Paidhalum Kaanaankol Kaaman / Oruvarkan Nindrozhuku Vaan", english: "Would not cupid who abides and contends in one party (only) witness the pain and sorrow (in that party)?" },
  { number: 1198, tamil: "வீழ்வாரின் இன்சொல் பெறாஅது உலகத்து\nவாழ்வாரின் வன்கணார் இல்.", transliteration: "Veezhvaarin Insol Peraaadhu Ulakaththu / Vaazhvaarin Vankanaar Il", english: "There is no one in the world so hard-hearted as those who can live without receiving (even) a kind word from their beloved" },
  { number: 1199, tamil: "நசைஇயார் நல்கார் எனினும் அவர்மாட்டு\nஇசையும் இனிய செவிக்கு.", transliteration: "Nasaiiyaar Nalkaar Eninum Avarmaattu / Isaiyum Iniya Sevikku", english: "Though my beloved bestows no love on one, still are his words sweet to my ears" },
  { number: 1200, tamil: "உறாஅர்க்கு உறுநோய் உரைப்பாய் கடலைச்\nசெறாஅஅய் வாழிய நெஞ்சு.", transliteration: "Uraaarkku Urunoi Uraippaai Katalaich / Cheraaaai Vaazhiya Nenju", english: "Live, O my soul, would you who relate your great sorrow to strangers, try rather to fill up your own sea (of sorrow)" },
  { number: 1201, tamil: "உள்ளினும் தீராப் பெருமகிழ் செய்தலால்\nகள்ளினும் காமம் இனிது.", transliteration: "Ullinum Theeraap Perumakizh Seydhalaal / Kallinum Kaamam Inidhu", english: "Sexuality is sweeter than liquor, because when remembered, it creates a most rapturous delight" },
  { number: 1202, tamil: "எனைத்தொனறு இனிதேகாண் காமம்தாம் வீழ்வார்\nநினைப்ப வருவதொன்று ஏல்.", transliteration: "Enaiththonaru Inidhekaan Kaamamdhaam Veezhvaar / Ninaippa Varuvadhondru El", english: "Even to think of one's beloved gives one no pain Sexuality, in any degree, is always delightful" },
  { number: 1203, tamil: "நினைப்பவர் போன்று நினையார்கொல் தும்மல்\nசினைப்பது போன்று கெடும்.", transliteration: "Ninaippavar Pondru Ninaiyaarkol Thummal / Sinaippadhu Pondru Ketum", english: "I feel as if I am going to sneeze but do not, and (therefore) my beloved is about to think (of me) but does not" },
  { number: 1204, tamil: "யாமும் உளேங்கொல் அவர்நெஞ்சத்து எந்நெஞ்சத்து\nஓஒ உளரே அவர்.", transliteration: "Yaamum Ulengol Avarnenjaththu Ennenjaththu / Oo Ulare Avar", english: "He continues to abide in my soul, do I likewise abide in his ?" },
  { number: 1205, tamil: "தம்நெஞ்சத்து எம்மைக் கடிகொண்டார் நாணார்கொல்\nஎம்நெஞ்சத்து ஓவா வரல்.", transliteration: "Thamnenjaththu Emmaik Katikontaar Naanaarkol / Emnenjaththu Ovaa Varal", english: "He who has imprisoned me in his soul, is he ashamed to enter incessantly into mine" },
  { number: 1206, tamil: "மற்றியான் என்னுளேன் மன்னோ அவரொடியான்\nஉற்றநாள் உள்ள உளேன்.", transliteration: "Matriyaan Ennulen Manno Avaroti / Yaan Utranaal Ulla Ulen", english: "I live by remembering my (former) intercourse with him; if it were not so, how could I live ?" },
  { number: 1207, tamil: "மறப்பின் எவனாவன் மற்கொல் மறப்பறியேன்\nஉள்ளினும் உள்ளம் சுடும்.", transliteration: "Marappin Evanaavan Markol Marappariyen / Ullinum Ullam Sutum", english: "I have never forgotten (the pleasure); even to think of it burns my soul; could I live, if I should ever forget it ?" },
  { number: 1208, tamil: "எனைத்து நினைப்பினும் காயார் அனைத்தன்றோ\nகாதலர் செய்யும் சிறப்பு.", transliteration: "Enaiththu Ninaippinum Kaayaar Anaiththandro / Kaadhalar Seyyum Sirappu", english: "He will not be angry however much I may think of him; is it not so much the delight my beloved" },
  { number: 1209, tamil: "விளியுமென் இன்னுயிர் வேறல்லம் என்பார்\nஅளியின்மை ஆற்ற நினைந்து.", transliteration: "Viliyumen Innuyir Verallam Enpaar / Aliyinmai Aatra Ninaindhu", english: "My precious life is wasting away by thinking too much on the cruelty of him who said we were not different" },
  { number: 1210, tamil: "விடாஅது சென்றாரைக் கண்ணினால் காணப்\nபடாஅதி வாழி மதி.", transliteration: "Vitaaadhu Sendraaraik Kanninaal Kaanap / Pataaadhi Vaazhi Madhi", english: "May you live, O Moon! Do not set, that I mine see him who has departed without quitting my soul" },
  { number: 1211, tamil: "காதலர் தூதொடு வந்த கனவினுக்கு\nயாதுசெய் வேன்கொல் விருந்து.", transliteration: "Kaadhalar Thoodhotu Vandha Kanavinukku / Yaadhusey Venkol Virundhu", english: "Where with shall I feast the dream which has brought me my dear one's messenger ?" },
  { number: 1212, tamil: "கயலுண்கண் யானிரப்பத் துஞ்சிற் கலந்தார்க்கு\nஉயலுண்மை சாற்றுவேன் மன்.", transliteration: "Kayalunkan Yaanirappath Thunjir Kalandhaarkku / Uyalunmai Saatruven Man", english: "If my fish-like painted eyes should, at my begging, close in sleep, I could fully relate my sufferings to my lord" },
  { number: 1213, tamil: "நனவினால் நல்கா தவரைக் கனவினால்\nகாண்டலின் உண்டென் உயிர்.", transliteration: "Nanavinaal Nalkaa Thavaraik Kanavinaal / Kaantalin Unten Uyir", english: "My life lasts because in my dream I behold him who does not favour me in my waking hours" },
  { number: 1214, tamil: "கனவினான் உண்டாகும் காமம் நனவினான்\nநல்காரை நாடித் தரற்கு.", transliteration: "Kanavinaan Untaakum Kaamam Nanavinaan / Nalkaarai Naatith Thararku", english: "There is pleasure in my dream, because in it I seek and obtain him who does not visit me in my wakefulness" },
  { number: 1215, tamil: "நனவினால் கண்டதூஉம் ஆங்கே கனவுந்தான்\nகண்ட பொழுதே இனிது.", transliteration: "Nanavinaal Kantadhooum Aange Kanavundhaan / Kanta Pozhudhe Inidhu", english: "I saw him in my waking hours, and then it was pleasant; I see him just now in my dream, and it is (equally) pleasant" },
  { number: 1216, tamil: "நனவென ஒன்றில்லை ஆயின் கனவினால்\nகாதலர் நீங்கலர் மன்.", transliteration: "Nanavena Ondrillai Aayin Kanavinaal / Kaadhalar Neengalar Man", english: "Were there no such thing as wakefulness, my beloved (who visited me) in my dream would not depart from me" },
  { number: 1217, tamil: "நனவினால் நல்காக் கொடியார் கனவனால்\nஎன்எம்மைப் பீழிப் பது.", transliteration: "Nanavinaal Nalkaak Kotiyaar Kanavanaal / Enemmaip Peezhip Padhu", english: "The cruel one who would not favour me in my wakefulness, what right has he to torture me in my dreams?" },
  { number: 1218, tamil: "துஞ்சுங்கால் தோள்மேலர் ஆகி விழிக்குங்கால்\nநெஞ்சத்தர் ஆவர் விரைந்து.", transliteration: "Thunjungaal Tholmelar Aaki Vizhikkungaal / Nenjaththar Aavar Viraindhu", english: "When I am asleep he rests on my shoulders, (but) when I awake he hastens into my soul" },
  { number: 1219, tamil: "நனவினால் நல்காரை நோவர் கனவினால்\nகாதலர்க் காணா தவர்.", transliteration: "Nanavinaal Nalkaarai Novar Kanavinaal / Kaadhalark Kaanaa Thavar", english: "They who have no dear ones to behold in their dreams blame him who visits me not in my waking hours" },
  { number: 1220, tamil: "நனவினால் நம்நீத்தார் என்பர் கனவினால்\nகாணார்கொல் இவ்வூ ரவர்.", transliteration: "Nanavinaal Namneeththaar Enpar Kanavinaal / Kaanaarkol Ivvoo Ravar", english: "The women of this place say he has forsaken me in my wakefulness I think they have not seen him visit me in my dreams" },
  { number: 1221, tamil: "மாலையோ அல்லை மணந்தார் உயிருண்ணும்\nவேலைநீ வாழி பொழுது.", transliteration: "Maalaiyo Allai Manandhaar Uyirunnum / Velainee Vaazhi Pozhudhu", english: "Live, O you evening are you (the former) evening? No, you are the season that slays (married) women" },
  { number: 1222, tamil: "புன்கண்ணை வாழி மருள்மாலை எம்கேள்போல்\nவன்கண்ண தோநின் துணை.", transliteration: "Punkannai Vaazhi Marulmaalai Emkelpol / Vankanna Thonin Thunai", english: "A long life to you, O dark evening! You are sightless Is your help-mate (also) as hard-hearted as mine" },
  { number: 1223, tamil: "பனிஅரும்பிப் பைதல்கொள் மாலை துனிஅரும்பித்\nதுன்பம் வளர வரும்.", transliteration: "Paniarumpip Paidhalkol Maalai Thuniarumpith / Thunpam Valara Varum", english: "The evening that (once) came in with trembling and dimness (now) brings me an aversion for life and increasing sorrow" },
  { number: 1224, tamil: "காதலர் இல்வழி மாலை கொலைக்களத்து\nஏதிலர் போல வரும்.", transliteration: "Kaadhalar Ilvazhi Maalai Kolaikkalaththu / Edhilar Pola Varum", english: "In the absence of my lover, evening comes in like slayers on the field of slaughter" },
  { number: 1225, tamil: "காலைக்குச் செய்தநன்று என்கொல் எவன்கொல்யான்\nமாலைக்குச் செய்த பகை?", transliteration: "Kaalaikkuch Cheydhanandru Enkol Evankolyaan / Maalaikkuch Cheydha Pakai?", english: "O eve, why art thou foe! thou dost renew my grief" },
  { number: 1226, tamil: "மாலைநோய் செய்தல் மணந்தார் அகலாத\nகாலை அறிந்த திலேன்.", transliteration: "Maalainoi Seydhal Manandhaar Akalaadha / Kaalai Arindha Thilen", english: "Previous to my husband's departure, I know not the painful nature of evening" },
  { number: 1227, tamil: "காலை அரும்பிப் பகலெல்லாம் போதாகி\nமாலை மலரும்இந் நோய்.", transliteration: "Kaalai Arumpip Pakalellaam Podhaaki / Maalai Malarumin Noi", english: "This malady buds forth in the morning, expands all day long and blossoms in the evening" },
  { number: 1228, tamil: "அழல்போலும் மாலைக்குத் தூதாகி ஆயன்\nகுழல்போலும் கொல்லும் படை.", transliteration: "Azhalpolum Maalaikkuth Thoodhaaki Aayan / Kuzhalpolum Kollum Patai", english: "The shepherd's flute now sounds as a fiery forerunner of night, and is become a weapon that slays (me)" },
  { number: 1229, tamil: "பதிமருண்டு பைதல் உழக்கும் மதிமருண்டு\nமாலை படர்தரும் போழ்து.", transliteration: "Padhimaruntu Paidhal Uzhakkum Madhimaruntu / Maalai Patardharum Pozhdhu", english: "When night comes on confusing (everyone's) mind, the (whole) town will lose its sense and be plunged in sorrow" },
  { number: 1230, tamil: "பொருள்மாலை யாளரை உள்ளி மருள்மாலை\nமாயும்என் மாயா உயிர்.", transliteration: "Porulmaalai Yaalarai Ulli Marulmaalai / Maayumen Maayaa Uyir", english: "My (hitherto) unextinguished life is now lost in this bewildering night at the thought of him who has the nature of wealth" },
  { number: 1231, tamil: "சிறுமை நமக்கொழியச் சேட்சென்றார் உள்ளி\nநறுமலர் நாணின கண்.", transliteration: "Sirumai Namakkozhiyach Chetchendraar Ulli / Narumalar Naanina Kan", english: "While we endure the unbearable sorrow, your eyes weep for him who is gone afar, and shun (the sight of) fragrant flowers" },
  { number: 1232, tamil: "நயந்தவர் நல்காமை சொல்லுவ போலும்\nபசந்து பனிவாரும் கண்.", transliteration: "Nayandhavar Nalkaamai Solluva Polum / Pasandhu Panivaarum Kan", english: "The discoloured eyes that shed tears profusely seem to betray the unkindness of our beloved" },
  { number: 1233, tamil: "தணந்தமை சால அறிவிப்ப போலும்\nமணந்தநாள் வீங்கிய தோள்.", transliteration: "Thanandhamai Saala Arivippa Polum / Manandhanaal Veengiya Thol", english: "The shoulders that swelled on the day of our union (now) seem to announce our separation clearly (to the public)" },
  { number: 1234, tamil: "பணைநீங்கிப் பைந்தொடி சோரும் துணைநீங்கித்\nதொல்கவின் வாடிய தோள்.", transliteration: "Panaineengip Paindhoti Sorum Thunaineengith / Tholkavin Vaatiya Thol", english: "In the absence of your consort, your shoulders having lost their former beauty and fulness, your bracelets of pure gold have become loose" },
  { number: 1235, tamil: "கொடியார் கொடுமை உரைக்கும் தொடியொடு\nதொல்கவின் வாடிய தோள்.", transliteration: "Kotiyaar Kotumai Uraikkum Thotiyotu / Tholkavin Vaatiya Thol", english: "The (loosened) bracelets, and the shoulders from which the old beauty has faded, relate the cruelty of the pitiless one" },
  { number: 1236, tamil: "தொடியொடு தோள்நெகிழ நோவல் அவரைக்\nகொடியர் எனக்கூறல் நொந்து.", transliteration: "Thotiyotu Tholnekizha Noval Avaraik / Kotiyar Enakkooral Nondhu", english: "I am greatly pained to hear you call him a cruel man, just because your shoulders are reduced and your bracelets loosened" },
  { number: 1237, tamil: "பாடு பெறுதியோ நெஞ்சே கொடியார்க்கென்\nவாடுதோட் பூசல் உரைத்து.", transliteration: "Paatu Perudhiyo Nenje Kotiyaarkken / Vaatudhot Poosal Uraiththu", english: "Can you O my soul! gain glory by relating to the (so-called) cruel one the clamour of my fading shoulders?" },
  { number: 1238, tamil: "முயங்கிய கைகளை ஊக்கப் பசந்தது\nபைந்தொடிப் பேதை நுதல்.", transliteration: "Muyangiya Kaikalai Ookkap Pasandhadhu / Paindhotip Pedhai Nudhal", english: "When I once loosened the arms that were in embrace, the forehead of the gold-braceleted women turned sallow" },
  { number: 1239, tamil: "முயக்கிடைத் தண்வளி போழப் பசப்புற்ற\nபேதை பெருமழைக் கண்.", transliteration: "Muyakkitaith Thanvali Pozhap Pasapputra / Pedhai Perumazhaik Kan", english: "When but a breath of breeze penetrated our embrace, her large cool eyes became sallow" },
  { number: 1240, tamil: "கண்ணின் பசப்போ பருவரல் எய்தின்றே\nஒண்ணுதல் செய்தது கண்டு.", transliteration: "Kannin Pasappo Paruvaral Eydhindre / Onnudhal Seydhadhu Kantu", english: "Was it at the sight of what the bright forehead had done that the sallowness of her eyes became sad?" },
  { number: 1241, tamil: "நினைத்தொன்று சொல்லாயோ நெஞ்சே எனைத்தொன்றும்\nஎவ்வநோய் தீர்க்கும் மருந்து.", transliteration: "Ninaiththondru Sollaayo Nenje Enaiththondrum / Evvanoi Theerkkum Marundhu", english: "O my soul, will you not think and tell me some medicine be it what it may, that can cure this incurable malady?" },
  { number: 1242, tamil: "காதல் அவரிலர் ஆகநீ நோவது\nபேதைமை வாழியென் நெஞ்சு.", transliteration: "Kaadhal Avarilar Aakanee Novadhu / Pedhaimai Vaazhiyen Nenju", english: "Is folly, fare thee well my heart!" },
  { number: 1243, tamil: "இருந்துள்ளி என்பரிதல் நெஞ்சே பரிந்துள்ளல்\nபைதல்நோய் செய்தார்கண் இல்.", transliteration: "Irundhulli Enparidhal Nenje Parindhullal / Paidhalnoi Seydhaarkan Il", english: "O my soul! why remain (here) and suffer thinking (of him)? There are no lewd thoughts (of you) in him who has caused you this disease of sorrow" },
  { number: 1244, tamil: "கண்ணும் கொளச்சேறி நெஞ்சே இவையென்னைத்\nதின்னும் அவர்க்காணல் உற்று.", transliteration: "Kannum Kolachcheri Nenje Ivaiyennaith / Thinnum Avarkkaanal Utru", english: "O my soul! take my eyes also with you, (if not), these would eat me up (in their desire) to see him" },
  { number: 1245, tamil: "செற்றார் எனக்கை விடல்உண்டோ நெஞ்சேயாம்\nஉற்றால் உறாஅ தவர்.", transliteration: "Setraar Enakkai Vitalunto Nenjeyaam / Utraal Uraaa Thavar", english: "O my soul! can he who loves not though he is beloved, be forsaken saying he hates me (now)?" },
  { number: 1246, tamil: "கலந்துணர்த்தும் காதலர்க் கண்டாற் புலந்துணராய்\nபொய்க்காய்வு காய்திஎன் நெஞ்சு.", transliteration: "Kalandhunarththum Kaadhalark Kantaar Pulandhunaraai / Poikkaaivu Kaaidhien Nenju", english: "O my soul! when you see the dear one who remove dislike by intercourse, you are displeased and continue to be so Nay, your displeasure is (simply) false" },
  { number: 1247, tamil: "காமம் விடுஒன்றோ நாண்விடு நன்னெஞ்சே\nயானோ பொறேன்இவ் விரண்டு.", transliteration: "Kaamam Vituondro Naanvitu Nannenje / Yaano Poreniv Virantu", english: "O my good soul, give up either lust or honour, as for me I can endure neither" },
  { number: 1248, tamil: "பரிந்தவர் நல்காரென்று ஏங்கிப் பிரிந்தவர்\nபின்செல்வாய் பேதைஎன் நெஞ்சு.", transliteration: "Parindhavar Nalkaarendru Engip Pirindhavar / Pinselvaai Pedhaien Nenju", english: "You are a fool, O my soul! to go after my departed one, while you mourn that he is not kind enough to favour you" },
  { number: 1249, tamil: "உள்ளத்தார் காத லவரால் உள்ளிநீ\nயாருழைச் சேறியென் நெஞ்சு.", transliteration: "Ullaththaar Kaadha Lavaraal Ullinee / Yaaruzhaich Cheriyen Nenju", english: "O my soul! to whom would you repair, while the dear one is within yourself?" },
  { number: 1250, tamil: "துன்னாத் துறந்தாரை நெஞ்சத்து உடையேமா\nஇன்னும் இழத்தும் கவின்.", transliteration: "Thunnaath Thurandhaarai Nenjaththu Utaiyemaa / Innum Izhaththum Kavin", english: "If I retain in my heart him who has left me without befriending me, I shall lose even the (inward) beauty that remains" },
  { number: 1251, tamil: "காமக் கணிச்சி உடைக்கும் நிறையென்னும்\nநாணுத்தாழ் வீழ்த்த கதவு.", transliteration: "Kaamak Kanichchi Utaikkum Niraiyennum / Naanuththaazh Veezhththa Kadhavu", english: "The axe of lust can break the door of chastity which is bolted with the bolt of modesty" },
  { number: 1252, tamil: "காமம் எனவொன்றோ கண்ணின்றென் நெஞ்சத்தை\nயாமத்தும் ஆளும் தொழில்.", transliteration: "Kaamam Enavondro Kannindren Nenjaththai / Yaamaththum Aalum Thozhil", english: "Even at midnight is my mind worried by lust, and this one thing, alas! is without mercy" },
  { number: 1253, tamil: "மறைப்பேன்மன் காமத்தை யானோ குறிப்பின்றித்\nதும்மல்போல் தோன்றி விடும்.", transliteration: "Maraippenman Kaamaththai Yaano Kurippindrith / Thummalpol Thondri Vitum", english: "I would conceal my lust, but alas, it yields not to my will but breaks out like a sneeze" },
  { number: 1254, tamil: "நிறையுடையேன் என்பேன்மன் யானோஎன் காமம்\nமறையிறந்து மன்று படும்.", transliteration: "Niraiyutaiyen Enpenman Yaanoen Kaamam / Maraiyirandhu Mandru Patum", english: "I say I would be firm, but alas, my malady breaks out from its concealment and appears in public" },
  { number: 1255, tamil: "செற்றார்பின் செல்லாப் பெருந்தகைமை காமநோய்\nஉற்றார் அறிவதொன்று அன்று.", transliteration: "Setraarpin Sellaap Perundhakaimai Kaamanoi / Utraar Arivadhondru Andru", english: "The dignity that would not go after an absent lover is not known to those who are sticken by love" },
  { number: 1256, tamil: "செற்றவர் பின்சேறல் வேண்டி அளித்தரோ\nஎற்றென்னை உற்ற துயர்.", transliteration: "Setravar Pinseral Venti Aliththaro / Etrennai Utra Thuyar", english: "The sorrow I have endured by desiring to go after my absent lover, in what way is it excellent?" },
  { number: 1257, tamil: "நாணென ஒன்றோ அறியலம் காமத்தால்\nபேணியார் பெட்ப செயின்.", transliteration: "Naanena Ondro Ariyalam Kaamaththaal / Peniyaar Petpa Seyin", english: "I know nothing like shame when my beloved does from love (just) what is desired (by me)" },
  { number: 1258, tamil: "பன்மாயக் கள்வன் பணிமொழி அன்றோநம்\nபெண்மை உடைக்கும் படை.", transliteration: "Panmaayak Kalvan Panimozhi Andronam / Penmai Utaikkum Patai", english: "Are not the enticing words of my trick-abounding roguish lover the weapon that breaks away my feminine firmness?" },
  { number: 1259, tamil: "புலப்பல் எனச்சென்றேன் புல்லினேன் நெஞ்சம்\nகலத்தல் உறுவது கண்டு.", transliteration: "Pulappal Enachchendren Pullinen Nenjam / Kalaththal Uruvadhu Kantu", english: "I said I would feign dislike and so went (away); (but) I embraced him the moment I say my mind began to unite with him!" },
  { number: 1260, tamil: "நிணந்தீயில் இட்டன்ன நெஞ்சினார்க்கு உண்டோ\nபுணர்ந்தூடி நிற்பேம் எனல்.", transliteration: "Ninandheeyil Ittanna Nenjinaarkku Unto / Punarndhooti Nirpem Enal", english: "Is it possible for those whose hearts melt like fat in the fire to say they can feign a strong dislike and remain so?" },
  { number: 1261, tamil: "வாளற்றுப் புற்கென்ற கண்ணும் அவர்சென்ற\nநாளொற்றித் தேய்ந்த விரல்.", transliteration: "Vaalatrup Purkendra Kannum Avarsendra / Naalotrith Theyndha Viral", english: "My finger has worn away by marking (on the wall) the days he has been absent while my eyes have lost their lustre and begin to fail" },
  { number: 1262, tamil: "இலங்கிழாய் இன்று மறப்பின்என் தோள்மேல்\nகலங்கழியும் காரிகை நீத்து.", transliteration: "Ilangizhaai Indru Marappinen Tholmel / Kalangazhiyum Kaarikai Neeththu", english: "O you bright-jewelled maid, if I forget (him) today, my shoulders will lose their beauty even in the other life and make my bracelets loose" },
  { number: 1263, tamil: "உரன்நசைஇ உள்ளம் துணையாகச் சென்றார்\nவரல்நசைஇ இன்னும் உளேன்.", transliteration: "Urannasaii Ullam Thunaiyaakach Chendraar / Varalnasaii Innum Ulen", english: "I still live by longing for the arrival of him who has gone out of love for victory and with valour as his guide" },
  { number: 1264, tamil: "கூடிய காமம் பிரிந்தார் வரவுள்ளிக்\nகோடுகொ டேறுமென் நெஞ்சு.", transliteration: "Kootiya Kaamam Pirindhaar Varavullik / Kotuko Terumen Nenju", english: "My heart is rid of its sorrow and swells with rapture to think of my absent lover returning with his love" },
  { number: 1265, tamil: "காண்கமன் கொண்கனைக் கண்ணாரக் கண்டபின்\nநீங்கும்என் மென்தோள் பசப்பு.", transliteration: "Kaankaman Konkanaik Kannaarak Kantapin / Neengumen Mendhol Pasappu", english: "May I look on my lover till I am satisfied and thereafter will vanish the sallowness of my slender shoulders" },
  { number: 1266, tamil: "வருகமன் கொண்கன் ஒருநாள் பருகுவன்\nபைதல்நோய் எல்லாம் கெட.", transliteration: "Varukaman Konkan Orunaal Parukuvan / Paidhalnoi Ellaam Keta", english: "May my husband return some day; and then will I enjoy (him) so as to destroy all this agonizing sorrow" },
  { number: 1267, tamil: "புலப்பேன்கொல் புல்லுவேன் கொல்லோ கலப்பேன்கொல்\nகண்அன்ன கேளிர் விரன்.", transliteration: "Pulappenkol Pulluven Kollo Kalappenkol / Kananna Kelir Viran", english: "On the return of him who is as dear as my eyes, am I displeased or am I to embrace (him); or am I to do both?" },
  { number: 1268, tamil: "வினைகலந்து வென்றீக வேந்தன் மனைகலந்து\nமாலை அயர்கம் விருந்து.", transliteration: "Vinaikalandhu Vendreeka Vendhan Manaikalandhu / Maalai Ayarkam Virundhu", english: "Let the king fight and gain (victories); (but) let me be united to my wife and feast the evening" },
  { number: 1269, tamil: "ஒருநாள் எழுநாள்போல் செல்லும்சேண் சென்றார்\nவருநாள்வைத்து ஏங்கு பவர்க்கு.", transliteration: "Orunaal Ezhunaalpol Sellumsen Sendraar / Varunaalvaiththu Engu Pavarkku", english: "To those who suffer waiting for the day of return of their distant lovers one day is as long as seven days" },
  { number: 1270, tamil: "பெறின்என்னாம் பெற்றக்கால் என்னாம் உறினென்னாம்\nஉள்ளம் உடைந்துக்கக் கால்.", transliteration: "Perinennaam Petrakkaal Ennaam Urinennaam / Ullam Utaindhukkak Kaal", english: "After (my wife) has died of a broken heart, what good will there be if she is to receive me, has received me, or has even embraced me?" },
  { number: 1271, tamil: "கரப்பினுங் கையிகந் தொல்லாநின் உண்கண்\nஉரைக்கல் உறுவதொன் றுண்டு.", transliteration: "Karappinung Kaiyikan Thollaanin Unkan / Uraikkal Uruvadhon Runtu", english: "Though you would conceal (your feelings), your painted eyes would not, for, transgressing (their bounds), they tell (me) something" },
  { number: 1272, tamil: "கண்ணிறைந்த காரிகைக் காம்பேர்தோட் பேதைக்குப்\nபெண்நிறைந்த நீர்மை பெரிது.", transliteration: "Kanniraindha Kaarikaik Kaamperdhot Pedhaikkup / Penniraindha Neermai Peridhu", english: "Unusually great is the female simplicity of your maid whose beauty fills my eyes and whose shoulders resemble the bamboo" },
  { number: 1273, tamil: "மணியில் திகழ்தரு நூல்போல் மடந்தை\nஅணியில் திகழ்வதொன்று உண்டு.", transliteration: "Maniyil Thikazhdharu Noolpol Matandhai / Aniyil Thikazhvadhondru Untu", english: "There is something that is implied in the beauty of this woman, like the thread that is visible in a garland of gems" },
  { number: 1274, tamil: "முகைமொக்குள் உள்ளது நாற்றம்போல் பேதை\nநகைமொக்குள் உள்ளதொன் றுண்டு.", transliteration: "Mukaimokkul Ulladhu Naatrampol Pedhai / Nakaimokkul Ulladhon Runtu", english: "There is something in the unmatured smile of this maid like the fragrance that is contained in an unblossomed bud" },
  { number: 1275, tamil: "செறிதொடி செய்திறந்த கள்ளம் உறுதுயர்\nதீர்க்கும் மருந்தொன்று உடைத்து.", transliteration: "Seridhoti Seydhirandha Kallam Urudhuyar / Theerkkum Marundhondru Utaiththu", english: "The well-meant departure of her whose bangles are tight-fitting contains a remedy that can cure my great sorrow" },
  { number: 1276, tamil: "பெரிதாற்றிப் பெட்பக் கலத்தல் அரிதாற்றி\nஅன்பின்மை சூழ்வ துடைத்து.", transliteration: "Peridhaatrip Petpak Kalaththal Aridhaatri / Anpinmai Soozhva Thutaiththu", english: "The embrace that fills me with comfort and gladness is capable of enduring (my former) sorrow and meditating on his want of love" },
  { number: 1277, tamil: "தண்ணந் துறைவன் தணந்தமை நம்மினும்\nமுன்னம் உணர்ந்த வளை.", transliteration: "Thannan Thuraivan Thanandhamai Namminum / Munnam Unarndha Valai", english: "My bracelets have understood before me the (mental) separation of him who rules the cool seashore" },
  { number: 1278, tamil: "நெருநற்றுச் சென்றார்எம் காதலர் யாமும்\nஎழுநாளேம் மேனி பசந்து.", transliteration: "Nerunatruch Chendraarem Kaadhalar Yaamum / Ezhunaalem Meni Pasandhu", english: "It was but yesterday my lover departed (from me); and it is seven days since my complexion turned sallow" },
  { number: 1279, tamil: "தொடிநோக்கி மென்தோளும் நோக்கி அடிநோக்கி\nஅஃதாண் டவள்செய் தது.", transliteration: "Thotinokki Mendholum Nokki Atinokki / Aqdhaan Tavalsey Thadhu", english: "She looked at her bracelets, her tender shoulders, and her feet; this was what she did there (significantly)" },
  { number: 1280, tamil: "பெண்ணினால் பெண்மை உடைத்தென்ப கண்ணினால்\nகாமநோய் சொல்லி இரவு.", transliteration: "Penninaal Penmai Utaiththenpa Kanninaal / Kaamanoi Solli Iravu", english: "To express their love-sickness by their eyes and resort to begging bespeaks more than ordinary female excellence" },
  { number: 1281, tamil: "உள்ளக் களித்தலும் காண மகிழ்தலும்\nகள்ளுக்கில் காமத்திற் குண்டு.", transliteration: "Ullak Kaliththalum Kaana Makizhdhalum / Kallukkil Kaamaththir Kuntu", english: "To please by thought and cheer by sight is peculiar, not to liquor but lust" },
  { number: 1282, tamil: "தினைத்துணையும் ஊடாமை வேண்டும் பனைத்துணையும்\nகாமம் நிறைய வரின்.", transliteration: "Thinaiththunaiyum Ootaamai Ventum Panaith / Thunaiyum Kaamam Niraiya Varin", english: "If women have a lust that exceeds even the measure of the palmyra fruit, they will not desire (to feign) dislike even as much as the millet" },
  { number: 1283, tamil: "பேணாது பெட்பவே செய்யினும் கொண்கனைக்\nகாணா தமையல கண்.", transliteration: "Penaadhu Petpave Seyyinum Konkanaik / Kaanaa Thamaiyala Kan", english: "Though my eyes disregard me and do what is pleasing to my husband, still will they not be satisfied unless they see him" },
  { number: 1284, tamil: "ஊடற்கண் சென்றேன்மன் தோழி அதுமறந்து\nகூடற்கண் சென்றது என் னெஞ்சு.", transliteration: "Ootarkan Sendrenman Thozhi Adhumarandhu / Kootarkan Sendradhu En Nenju", english: "My heart, forgetting all, could not its love restrain" },
  { number: 1285, tamil: "எழுதுங்கால் கோல்காணாக் கண்ணேபோல் கொண்கன்\nபழிகாணேன் கண்ட இடத்து.", transliteration: "Ezhudhungaal Kolkaanaak Kannepol Konkan / Pazhikaanen Kanta Itaththu", english: "Like the eyes which see not the pencil that paints it, I cannot see my husband's fault (just) when I meet him" },
  { number: 1286, tamil: "காணுங்கால் காணேன் தவறாய காணாக்கால்\nகாணேன் தவறல் லவை.", transliteration: "Kaanungaal Kaanen Thavaraaya Kaanaakkaal / Kaanen Thavaral Lavai", english: "When I see my husband, I do not see any faults; but when I do not see him, I do not see anything but faults" },
  { number: 1287, tamil: "உய்த்தல் அறிந்து புனல்பாய் பவரேபோல்\nபொய்த்தல் அறிந்தென் புலந்து.", transliteration: "Uyththal Arindhu Punalpaai Pavarepol / Poiththal Arindhen Pulandhu", english: "Like those who leap into a stream which they know will carry them off, why should a wife feign dislike which she knows cannot hold out long?" },
  { number: 1288, tamil: "இளித்தக்க இன்னா செயினும் களித்தார்க்குக்\nகள்ளற்றே கள்வநின் மார்பு.", transliteration: "Iliththakka Innaa Seyinum Kaliththaarkkuk / Kallatre Kalvanin Maarpu", english: "O you rogue! your breast is to me what liquor is to those who rejoice in it, though it only gives them an unpleasant disgrace" },
  { number: 1289, tamil: "மலரினும் மெல்லிது காமம் சிலர்அதன்\nசெவ்வி தலைப்படு வார்.", transliteration: "Malarinum Mellidhu Kaamam Silaradhan / Sevvi Thalaippatu Vaar", english: "Sexual delight is more delicate than a flower, and few are those who understand its real nature" },
  { number: 1290, tamil: "கண்ணின் துனித்தே கலங்கினாள் புல்லுதல்\nஎன்னினும் தான்விதுப் புற்று.", transliteration: "Kannin Thuniththe Kalanginaal Pulludhal / Enninum Thaanvidhup Putru", english: "She once feigned dislike in her eyes, but the warmth of her embrace exceeded my own" },
  { number: 1291, tamil: "அவர்நெஞ்சு அவர்க்காதல் கண்டும் எவன்நெஞ்சே\nநீஎமக்கு ஆகா தது.", transliteration: "Avarnenju Avarkkaadhal Kantum Evannenje / Neeemakku Aakaa Thadhu", english: "O my soul! although you have seen how his soul stands by him, how is it you do not stand by me?" },
  { number: 1292, tamil: "உறாஅ தவர்க்கண்ட கண்ணும் அவரைச்\nசெறாஅரெனச் சேறியென் நெஞ்சு.", transliteration: "Uraaa Thavarkkanta Kannum Avaraich / Cheraaarenach Cheriyen Nenju", english: "O my soul! although you have known him who does not love me, still do you go to him, saying \"he will not be displeased.\"" },
  { number: 1293, tamil: "கெட்டார்க்கு நட்டார்இல் என்பதோ நெஞ்சேநீ\nபெட்டாங்கு அவர்பின் செலல்.", transliteration: "Kettaarkku Nattaaril Enpadho Nenjenee / Pettaangu Avarpin Selal", english: "O my soul! do you follow him at pleasure under the belief that the ruined have no friends?" },
  { number: 1294, tamil: "இனிஅன்ன நின்னொடு சூழ்வார்யார் நெஞ்சே\nதுனிசெய்து துவ்வாய்காண் மற்று.", transliteration: "Inianna Ninnotu Soozhvaaryaar Nenje / Thuniseydhu Thuvvaaikaan Matru", english: "O my soul! you would not first seem sulky and then enjoy (him); who then would in future consult you about such things?" },
  { number: 1295, tamil: "பெறாஅமை அஞ்சும் பெறின்பிரிவு அஞ்சும்\nஅறாஅ இடும்பைத்தென் நெஞ்சு.", transliteration: "Peraaamai Anjum Perinpirivu Anjum / Araaa Itumpaiththen Nenju", english: "My soul fears when it is without him; it also fears when it is with him; it is subject to incessant sorrow" },
  { number: 1296, tamil: "தனியே இருந்து நினைத்தக்கால் என்னைத்\nதினிய இருந்ததென் நெஞ்சு.", transliteration: "Thaniye Irundhu Ninaiththakkaal Ennaith / Thiniya Irundhadhen Nenju", english: "My mind has been (here) in order to eat me up (as it were) whenever I think of him in my solitude" },
  { number: 1297, tamil: "நாணும் மறந்தேன் அவர்மறக் கல்லாஎன்\nமாணா மடநெஞ்சிற் பட்டு.", transliteration: "Naanum Marandhen Avarmarak Kallaaen / Maanaa Matanenjir Pattu", english: "I have even forgotten my modesty, having been caught in my foolish mind which is not dignified enough to forget him" },
  { number: 1298, tamil: "எள்ளின் இளிவாம்என்று எண்ணி அவர்திறம்\nஉள்ளும் உயிர்க்காதல் நெஞ்சு.", transliteration: "Ellin Ilivaamendru Enni Avardhiram / Ullum Uyirkkaadhal Nenju", english: "My soul which clings to life thinks only of his (own) gain in the belief that it would be disgraceful for it to despise him" },
  { number: 1299, tamil: "துன்பத்திற்கு யாரே துணையாவார் தாமுடைய\nநெஞ்சந் துணையல் வழி.", transliteration: "Thunpaththirku Yaare Thunaiyaavaar Thaamutaiya / Nenjan Thunaiyal Vazhi", english: "Who would help me out of one's distress, when one's own soul refuses help to one?" },
  { number: 1300, tamil: "தஞ்சம் தமரல்லர் ஏதிலார் தாமுடைய\nநெஞ்சம் தமரல் வழி.", transliteration: "Thanjam Thamarallar Edhilaar Thaamutaiya / Nenjam Thamaral Vazhi", english: "It is hardly possible for strangers to behave like relations, when one's own soul acts like a stranger" },
  { number: 1301, tamil: "புல்லா திராஅப் புலத்தை அவர்உறும்\nஅல்லல்நோய் காண்கம் சிறிது.", transliteration: "Pullaa Thiraaap Pulaththai Avar / Urum Allalnoi Kaankam Siridhu", english: "Let us witness awhile his keen suffering; just feign dislike and embrace him not" },
  { number: 1302, tamil: "உப்பமைந் தற்றால் புலவி அதுசிறிது\nமிக்கற்றால் நீள விடல்.", transliteration: "Uppamain Thatraal Pulavi Adhusiridhu / Mikkatraal Neela Vital", english: "A little dislike is like salt in proportion; to prolong it a little is like salt a little too much" },
  { number: 1303, tamil: "அலந்தாரை அல்லல்நோய் செய்தற்றால் தம்மைப்\nபுலந்தாரைப் புல்லா விடல்.", transliteration: "Alandhaarai Allalnoi Seydhatraal Thammaip / Pulandhaaraip Pullaa Vital", english: "For men not to embrace those who have feigned dislike is like torturing those already in agony" },
  { number: 1304, tamil: "ஊடி யவரை உணராமை வாடிய\nவள்ளி முதலரிந் தற்று.", transliteration: "Ooti Yavarai Unaraamai Vaatiya / Valli Mudhalarin Thatru", english: "Not to reconcile those who have feigned dislike is like cutting a faded creeper at its root" },
  { number: 1305, tamil: "நலத்தகை நல்லவர்க்கு ஏஎர் புலத்தகை\nபூஅன்ன கண்ணார் அகத்து.", transliteration: "Nalaththakai Nallavarkku Eer Pulaththakai / Pooanna Kannaar Akaththu", english: "An increased shyness in those whose eyes are like flowers is beautiful even to good and virtuous husbands" },
  { number: 1306, tamil: "துனியும் புலவியும் இல்லாயின் காமம்\nகனியும் கருக்காயும் அற்று.", transliteration: "Thuniyum Pulaviyum Illaayin Kaamam / Kaniyum Karukkaayum Atru", english: "Sexual pleasure, without prolonged and short-lived dislike, is like too ripe, and unripe fruit" },
  { number: 1307, tamil: "ஊடலின் உண்டாங்கோர் துன்பம் புணர்வது\nநீடுவ தன்று கொல் என்று.", transliteration: "Ootalin Untaangor Thunpam Punarvadhu / Neetuva Thandru Kol Endru", english: "The doubt as to whether intercourse would take place soon or not, creates a sorrow (even) in feigned dislike" },
  { number: 1308, tamil: "நோதல் எவன்மற்று நொந்தாரென்று அஃதறியும்\nகாதலர் இல்லா வழி.", transliteration: "Nodhal Evanmatru Nondhaarendru Aqdhariyum / Kaadhalar Illaa Vazhi", english: "What avails sorrow when I am without a wife who can understand the cause of my sorrow?" },
  { number: 1309, tamil: "நீரும் நிழலது இனிதே புலவியும்\nவீழுநர் கண்ணே இனிது.", transliteration: "Neerum Nizhaladhu Inidhe Pulaviyum / Veezhunar Kanne Inidhu", english: "Like water in the shade, dislike is delicious only in those who love" },
  { number: 1310, tamil: "ஊடல் உணங்க விடுவாரோடு என்நெஞ்சம்\nகூடுவேம் என்பது அவா.", transliteration: "Ootal Unanga Vituvaarotu Ennenjam / Kootuvem Enpadhu Avaa", english: "It is nothing but strong desire that makes her mind unite with me who can leave her to her own dislike" },
  { number: 1311, tamil: "பெண்ணியலார் எல்லாரும் கண்ணின் பொதுஉண்பர்\nநண்ணேன் பரத்தநின் மார்பு.", transliteration: "Penniyalaar Ellaarum Kannin Podhuunpar / Nannen Paraththanin Maarpu", english: "You are given to prostitution; all those who are born as womankind enjoy you with their eyes in an ordinary way I will not embrace you" },
  { number: 1312, tamil: "ஊடி இருந்தேமாத் தும்மினார் யாம்தம்மை\nநீடுவாழ் கென்பாக் கறிந்து.", transliteration: "Ooti Irundhemaath Thumminaar Yaamdhammai / Neetuvaazh Kenpaak Karindhu", english: "When I continued to be sulky he sneezed and thought I would (then) wish him a long life" },
  { number: 1313, tamil: "கோட்டுப்பூச் சூடினும் காயும் ஒருத்தியைக்\nகாட்டிய சூடினீர் என்று.", transliteration: "Kottup Pooch Chootinum Kaayum / Oruththiyaik Kaattiya Sootineer Endru", english: "Even if I were adorned with a garland of branch-flowers, she would say I did so to show it to another woman" },
  { number: 1314, tamil: "யாரினும் காதலம் என்றேனா ஊடினாள்\nயாரினும் யாரினும் என்று.", transliteration: "Yaarinum Kaadhalam Endrenaa Ootinaal / Yaarinum Yaarinum Endru", english: "When I said I loved her more than any other woman, she said \"more than others, yes, more than others,\" and remained sulky" },
  { number: 1315, tamil: "இம்மைப் பிறப்பில் பிரியலம் என்றேனாக்\nகண்நிறை நீர்கொண் டனள்.", transliteration: "Immaip Pirappil Piriyalam Endrenaak / Kannirai Neerkon Tanal", english: "When I said I would never part from her in this life her eyes were filled with tears" },
  { number: 1316, tamil: "உள்ளினேன் என்றேன்மற் றென்மறந்தீர் என்றென்னைப்\nபுல்லாள் புலத்தக் கனள்.", transliteration: "Ullinen Endrenmar Renmarandheer Endrennaip / Pullaal Pulaththak Kanal", english: "When I said I had remembered her, she said I had forgotten her and relaxing her embrace, began to feign dislike" },
  { number: 1317, tamil: "வழுத்தினாள் தும்மினேன் ஆக அழித்தழுதாள்\nயாருள்ளித் தும்மினீர் என்று.", transliteration: "Vazhuththinaal Thumminen Aaka Azhiththazhudhaal / Yaarullith Thummineer Endru", english: "When I sneezed she blessed me, but at once changed (her mind) and wept, asking, \"At the thought of whom did you sneeze?\"" },
  { number: 1318, tamil: "தும்முச் செறுப்ப அழுதாள் நுமர்உள்ளல்\nஎம்மை மறைத்திரோ என்று.", transliteration: "Thummuch Cheruppa Azhudhaal Numarullal / Emmai Maraiththiro Endru", english: "When I suppressed my sneezing, she wept saying, \"I suppose you (did so) to hide from me your own people's remembrance of you\"" },
  { number: 1319, tamil: "தன்னை உணர்த்தினும் காயும் பிறர்க்கும்நீர்\nஇந்நீரர் ஆகுதிர் என்று.", transliteration: "Thannai Unarththinum Kaayum Pirarkkumneer / Inneerar Aakudhir Endru", english: "'I see', quoth she, 'to other folks How you are wondrous kind' Even when I try to remove her dislike, she is displeased and says, \"This is the way you behave" },
  { number: 1320, tamil: "நினைத்திருந்து நோக்கினும் காயும் அனைத்துநீர்\nயாருள்ளி நோக்கினீர் என்று.", transliteration: "Ninaiththirundhu Nokkinum Kaayum Anaiththuneer / Yaarulli Nokkineer Endru", english: "Even when I look on her contemplating (her beauty), she is displeased and says, \"With whose thought have you (thus) looked on my person?\"" },
  { number: 1321, tamil: "இல்லை தவறவர்க்கு ஆயினும் ஊடுதல்\nவல்லது அவர்அள஧க்கு மாறு.", transliteration: "Illai Thavaravarkku Aayinum Ootudhal / Valladhu Avaralikku Maaru", english: "Although my husband is free from defects, the way in which he embraces me is such as to make me feign dislike" },
  { number: 1322, tamil: "ஊடலின் தோன்றும் சிறுதுனி நல்லளி\nவாடினும் பாடு பெறும்.", transliteration: "Ootalin Thondrum Sirudhuni Nallali / Vaatinum Paatu Perum", english: "His love will increase though it may (at first seem to) fade through the short-lived distress caused by (my) dislike" },
  { number: 1323, tamil: "புலத்தலின் புத்தேள்நாடு உண்டோ நிலத்தொடு\nநீரியைந் தன்னார் அகத்து.", transliteration: "Pulaththalin Puththelnaatu Unto Nilaththotu / Neeriyain Thannaar Akaththu", english: "Is there a celestial land that can please like the feigned dislike of those whose union resembles that of earth and water?" },
  { number: 1324, tamil: "புல்லி விடாஅப் புலவியுள் தோன்றுமென்\nஉள்ளம் உடைக்கும் படை.", transliteration: "Pulli Vitaaap Pulaviyul Thondrumen / Ullam Utaikkum Patai", english: "In prolonged dislike after an embrace there is a weapon that can break my heart" },
  { number: 1325, tamil: "தவறிலர் ஆயினும் தாம்வீழ்வார் மென்றோள்\nஅகறலின் ஆங்கொன் றுடைத்து.", transliteration: "Thavarilar Aayinum Thaamveezhvaar Mendrol / Akaralin Aangon Rutaiththu", english: "Though free from defects, men feel pleased when they cannot embrace the delicate shoulders of those whom they love" },
  { number: 1326, tamil: "உணலினும் உண்டது அறல்இனிது காமம்\nபுணர்தலின் ஊடல் இனிது.", transliteration: "Unalinum Untadhu Aralinidhu Kaamam / Punardhalin Ootal Inidhu", english: "To digest what has been eaten is more delightful than to eat more; likewise love is more delightful in dislike than intercourse" },
  { number: 1327, tamil: "ஊடலில் தோற்றவர் வென்றார் அதுமன்னும்\nகூடலிற் காணப் படும்.", transliteration: "Ootalil Thotravar Vendraar Adhumannum / Kootalir Kaanap Patum", english: "Those are conquerors whose dislike has been defeated and that is proved by the love (which" },
  { number: 1328, tamil: "ஊடிப் பெறுகுவம் கொல்லோ நுதல்வெயர்ப்பக்\nகூடலில் தோன்றிய உப்பு.", transliteration: "Ootip Perukuvam Kollo Nudhalveyarppak / Kootalil Thondriya Uppu", english: "Will I enjoy once more through her dislike, the pleasure of that love that makes her forehead perspire?" },
  { number: 1329, tamil: "ஊடுக மன்னோ ஒளியிழை யாமிரப்ப\nநீடுக மன்னோ இரா.", transliteration: "Ootuka Manno Oliyizhai Yaamirappa / Neetuka Manno Iraa", english: "May the bright-jewelled one feign dislike, and may the night be prolonged for me to implore her!" },
  { number: 1330, tamil: "ஊடுதல் காமத்திற்கு இன்பம் அதற்கின்பம்\nகூடி முயங்கப் பெறின்.", transliteration: "Ootudhal Kaamaththirku Inpam Adharkinpam / Kooti Muyangap Perin", english: "Dislike adds delight to love; and a hearty embrace (thereafter) will add delight to dislike" },
]

// Returns today's kural — rotates daily through all 1330
export function getTodaysKural() {
  const start = new Date(new Date().getFullYear(), 0, 0)
  const dayOfYear = Math.floor((Date.now() - start.getTime()) / 86400000)
  return kurals[dayOfYear % kurals.length]
}
